            internal static MovementResult Arrival(TrafficIntentKey key,TrafficNativeStamp stamp,Vector3 at)=>new MovementResult(stamp.RequestId,key.ActorId,MovementStatus.Arrived,NavigationFailure.None,NavigationFailure.None,NavigationFailure.None,at,0);
            internal TrafficParkingFact Claim(TrafficIntentKey owner,CounterQueueService.AssignmentClaim claim)=>new TrafficParkingFact(owner,Counter,Counter.Version,"counter/"+owner.ActorId,claim.Assignment.Position,.4f,
                businessOwner:owner.ActorId==Follower.ActorId?FollowerBusiness:Business,releaseObligation:owner.ActorId==Follower.ActorId?FollowerRelease:Release,semanticCheckpoint:claim);
            private void Refresh(bool install=true)
            {
                var bodies=new List<TrafficBodyFact>{new TrafficBodyFact(bodyOwner,priorPose,.4f,true,progress,progress?30:0,actorLife:Actor),new TrafficBodyFact(followerBody,FollowerStart,.4f,actorLife:FollowerLife)};
                if(headPresent)bodies.Add(new TrafficBodyFact(head,NextEnd,.4f,actorLife:HeadLife));
                var parking=new List<TrafficParkingFact>();foreach(var id in new[]{Old.ActorId,Follower.ActorId,head.ActorId})if(Counter.TryCaptureAssignment(id,out var claim))parking.Add(Claim(id==Old.ActorId?bodyOwner:id==Follower.ActorId?followerBody:head,claim));
                World=ServiceTrafficCoordinatorTests.World(++worldVersion,worldVersion,bodies.ToArray(),parking.ToArray());if(install)Core.SetSnapshot(World);
            }
            private void Attach()
            {
                var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficCounterAdvanceReadiness");
                var descriptor=Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,null,
                    new object[]{Follower,(Func<bool>)(()=>ProducerCurrent && OriginalFollowerClaim.IsCurrent),(Func<TrafficIntentKey,float>)(owner=>ProducerCurrent && Receipt!=null && Receipt.IsCurrent && NextSource!=null && (owner.Equals(Old)||owner.Equals(Next))?1:0)},null);
                var port=typeof(ServiceTrafficCoordinator).GetMethod("TrySetCounterAdvanceReadiness",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That((bool)port.Invoke(Core,new[]{(object)Core.GetDecision(Follower),descriptor}),Is.True);
            }
            internal void TransferAndActuallyArriveNext()
            {
                var ready=Core.GetDecision(Next);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
                var state=D1Read(Core,Old,"PendingHandoff");var table=(System.Collections.IDictionary)D3ReadField(Core,"entries");
                var originalCaptured=((HashSet<string>)((System.Collections.IDictionary)D3ReadField(state,"Dependencies"))[table[Follower]]).ToArray();
                var originalFrozen=((Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(Core,Follower,"FrozenResources"))[Old].ToArray();
                Assert.That(Core.TryCommitPhaseHandoff(Handoff,ready,Receipt,publish:()=>{bodyOwner=Next;Refresh();}),Is.True);
                var successorResources=((Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(Core,Follower,"FrozenResources"))[Next];
                CollectionAssert.AreEquivalent(originalCaptured.Where(originalFrozen.Contains),successorResources,
                    "Sole real strict handoff migrates exactly the original captured AND frozen pool");
                Assert.That(successorResources.Contains("body"),Is.EqualTo(originalCaptured.Contains("body") && originalFrozen.Contains("body")),
                    "A Counter-only predecessor cannot give the successor new body WAIT authority");
                Assert.That(World.Bodies.Single(b=>b.Owner.Equals(Next)).IndependentlyProgressing,Is.False,"Owner-tag transfer itself does not create independent body motion");
                Assert.That(Core.BindLeg(Next,Actor,NextStamp),Is.True);progress=true;Refresh();
                Assert.That(D1Read(Core,Old,"Retired"),Is.EqualTo(true));Assert.That(((HashSet<TrafficIntentKey>)D1Read(Core,Follower,"FrozenOwners")),Is.EquivalentTo(new[]{Next}));
                FollowerRequest=D2FreshRequest(FollowerRequest,World);Assert.That(CfcReprepare(Core,Core.GetDecision(Follower),FollowerRequest,out _),Is.True);Core.ProcessReady(6);
                Assert.That(Core.GetDecision(Follower).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"Only the new genuinely Bound Native now owns ordinary finite WAIT");
                var saved=((TrafficRequest)D1Read(Core,Next,"Request")).Snapshot.Parking.Single(p=>p.Owner.Equals(Next)&&p.ResourceId=="counter/"+Next.ActorId);
                priorPose=NextEnd;progress=false;Refresh();Assert.That(Counter.TryCaptureAssignment(Old.ActorId,out var current),Is.True);
                Assert.That(Core.CompleteLegAndBeginHandoff(Next,Actor,NextStamp,Arrival(Next,NextStamp,NextEnd),()=>
                {Assert.That(Counter.Complete(Old.ActorId,current.Assignment.Generation),Is.True);return new CounterReadinessArrival(this,Next,NextSource,saved);},out _),Is.True);Refresh();
                Core.NotifyChanged(Next,"body");FollowerRequest=D2FreshRequest(FollowerRequest,World);Assert.That(CfcReprepare(Core,Core.GetDecision(Follower),FollowerRequest,out _),Is.True);Core.ProcessReady(7);
            }
            internal sealed class CounterReadinessArrival:ITrafficPhaseMilestone
            {
                private readonly CapturedCounterAdvanceReadinessFixture f;private readonly TrafficIntentKey owner;
                internal CounterReadinessArrival(CapturedCounterAdvanceReadinessFixture fixture,TrafficIntentKey key,TrafficDecision source,TrafficParkingFact original){f=fixture;owner=key;SourcePermit=source;OriginalClaim=original;}
                public TrafficDecision SourcePermit{get;} public TrafficParkingFact OriginalClaim{get;}
                public TrafficParkingFact CurrentClaim{get{f.Counter.TryCaptureAssignment(owner.ActorId,out var claim);return claim==null?null:f.Claim(owner,claim);}}
                public object ActorLife=>f.Actor;public object BusinessOwner=>f.Business;public object ReleaseObligation=>f.Release;public TrafficPhaseMilestoneKind Kind=>TrafficPhaseMilestoneKind.Arrived;
                public bool IsCurrent=>f.Counter.TryCaptureAssignment(owner.ActorId,out var claim) && ((CounterQueueService.AssignmentClaim)OriginalClaim.SemanticCheckpoint).IsSameReservation(claim);
                public TrafficPhaseClaimState ReadClaim(TrafficParkingFact original,out TrafficParkingFact current){current=null;if(!ReferenceEquals(original,OriginalClaim)||!IsCurrent)return TrafficPhaseClaimState.Invalid;current=CurrentClaim;return TrafficPhaseClaimState.Held;}
                public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision source,int firstFrame)=>owner.Equals(f.Old) && IsCurrent && successor.Equals(f.Next) && ReferenceEquals(source,f.NextSource) && firstFrame==4;
            }
        }
        [Test]
        public void CapturedCounterReadinessWithholdsOnlyUntilOriginalStrictHandoffThenReprovesSameFollower()
            =>AssertCapturedCounterReadinessContinuation(false);
        [Test]
        public void CapturedCounterReadinessSurvivesPreparedGrantClearingTransientBlockerCache()
            =>AssertCapturedCounterReadinessContinuation(true);
        [Test]
        public void OriginalCapturedBodyCounterReadinessPreservesItsPoolAcrossTheSameStrictDeadline()
            =>AssertCapturedCounterReadinessContinuation(true,true);
        private void AssertCapturedCounterReadinessContinuation(bool clearWaiterCache,bool captureBody=false)
        {
            var f=new CapturedCounterAdvanceReadinessFixture(clearWaiterCache,captureBody);var entry=((System.Collections.IDictionary)D3ReadField(f.Core,"entries"))[f.Follower];
            var accounting=D3CaptureAccounting(f.Core,f.Follower);var frozen=D1Read(f.Core,f.Follower,"FrozenOwners");var resources=D1Read(f.Core,f.Follower,"FrozenResources");var calls=f.Calls;
            Assert.That(f.Core.GetDecision(f.Follower).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));f.Core.ProcessReady(5);var held=f.Core.GetDecision(f.Follower);
            Assert.That(held.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"FEATURE RED: an actually captured Counter-only Arrived handoff must withhold its unchanged follower across the same owner's next unissued first Native leg");
            Assert.That(held.Reason,Is.EqualTo("counter-advance-handoff-readiness-held"));Assert.That(held.AcquiredSequence,Is.Zero);
            Assert.That(((System.Collections.IDictionary)D3ReadField(f.Core,"entries"))[f.Follower],Is.SameAs(entry));D3AssertAccounting(f.Core,f.Follower,accounting);
            Assert.That(D1Read(f.Core,f.Follower,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,f.Follower,"FrozenResources"),Is.SameAs(resources));
            Assert.That(f.Core.QueriesConsumed(f.Follower),Is.EqualTo((int)accounting["Queries"]));Assert.That(f.Core.TryCommit(held),Is.False);Assert.That(f.Core.CanIssueLeg(f.Follower,f.FollowerLife,1),Is.False);
            Assert.That(f.Calls,Is.GreaterThan(calls),"The earlier original next leg continues its own real query while follower is withheld");
            f.Core.Tick(100,true);D3AssertAccounting(f.Core,f.Follower,accounting);f.Core.Tick(.25f,false);var spent=(float)D1Read(f.Core,f.Follower,"WaitRemaining");
            Assert.That(spent,Is.EqualTo((float)accounting["WaitRemaining"]-.25f).Within(.0001));
            f.TransferAndActuallyArriveNext();var ready=f.Core.GetDecision(f.Follower);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(ready.RequestSequence,Is.EqualTo((long)accounting["RequestSequence"]));Assert.That(D1Read(f.Core,f.Follower,"FirstFrame"),Is.EqualTo(accounting["FirstFrame"]));
            Assert.That((float)D1Read(f.Core,f.Follower,"WaitRemaining"),Is.LessThanOrEqualTo(spent));Assert.That(ready.AcquiredSequence,Is.Zero);
            Assert.That(f.Core.QueriesConsumed(f.Follower),Is.GreaterThan((int)accounting["Queries"]));Assert.That(ready.ProofRoutes.Single(p=>p.ResourceId=="counter/"+f.Follower.ActorId).Waypoints.Last(),Is.EqualTo(f.End));
        }
        // Analytic Core + actual Counter claim; the Native fixture owns real cashier/body/Due proof.
        // 不写Core私有Entry；typed API尚不存在时仍走原公开Evaluate，RED落在实际Terminal行为。
        // Normal Core operations establish both genuine Bound owners; snapshots move only along those paths.
        // 真正的原Frozen owner离开后，新Bound owner进入当前路线；不手写Entry/permit/Native状态。
        private sealed class DeliveryNewFrozenOwnerModel
        {
            internal readonly TrafficIntentKey Key,Body=ServiceTrafficCoordinatorTests.Key("alternate-barista","body"),
                Old=ServiceTrafficCoordinatorTests.Key("alternate-old","counter-admission",1),New=ServiceTrafficCoordinatorTests.Key("alternate-new","counter-admission",2);
            internal readonly object Actor=new object(),OldLife=new object(),NewLife=new object();
            internal readonly TrafficNativeStamp OldStamp=new TrafficNativeStamp(801,1),NewStamp=new TrafficNativeStamp(802,2);
            internal readonly ServiceTrafficCoordinator Core;internal TrafficWorldSnapshot Snapshot;
            internal readonly bool BoundNew,MixedCanonical,ExtraSelected;internal readonly int Count;
            internal readonly CanonicalOwner NewParking=new CanonicalOwner{Version=1};
            internal readonly Vector3 OldStart=P(2),OldEnd=P(2,4),NewStart=P(3,-4),NewEnd=P(3,4);
            internal TrafficDecision OriginalWait,Refused;
            internal DeliveryNewFrozenOwnerModel(string intent="employee-pickup-journey",int count=2,bool boundNew=true,bool mixedCanonical=false,bool extraSelected=false)
            {
                Key=ServiceTrafficCoordinatorTests.Key("alternate-barista",intent,20);Count=count;BoundNew=boundNew;MixedCanonical=mixedCanonical;ExtraSelected=extraSelected;
                if(mixedCanonical)NewEnd=P(3,1);
                Snapshot=MakeWorld(1,OldStart,NewStart,true);Core=Coordinator(Snapshot,waitSeconds:30,query:(from,to)=>mixedCanonical && from==Origin && to==P(4)
                    ?new[]{Origin,P(0,2),P(4,2),P(4)}:new[]{from,to});
                Bind(Old,OldLife,OldStart,OldEnd,OldStamp,1);
                Core.EvaluateParking(Request(P(4),5),0,count);Core.ProcessReady(5);OriginalWait=Core.GetDecision(Key);
                Assert.That(OriginalWait.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                Assert.That((IEnumerable<TrafficIntentKey>)D1Read(Core,Key,"FrozenOwners"),Is.EquivalentTo(new[]{Old}));
                Assert.That((float)D1Read(Core,Key,"WaitRemaining"),Is.EqualTo(13f));Core.Tick(2,false);
                if(boundNew)Bind(New,NewLife,NewStart,NewEnd,NewStamp,6);
                Snapshot=MakeWorld(2,OldEnd,P(3),false);Core.SetSnapshot(Snapshot);
                // The negative owner is born here and only has an unissued public proposal; no fake Native movement.
                if(!boundNew)Core.EvaluateMovement(ServiceTrafficCoordinatorTests.Request(New,P(3),NewEnd,Snapshot,frame:7,resource:"counter/"+New.ActorId,seconds:13));
                Assert.That(Core.CompleteLeg(Old,OldLife,OldStamp,OldEnd),Is.True);
                Core.ProcessReady(8);Refused=Core.GetDecision(Key);
                Assert.That(Refused.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
                Assert.That(Refused.Reason,Is.EqualTo("no-independent-finite-release-or-cycle"));
                Assert.That(Refused.Blockers.Any(b=>b.Owner.Equals(New) && b.ResourceId=="body" && b.Proof=="live-body-checkpoint"),Is.True);
                if(boundNew){Assert.That(D3ReadField(D1Read(Core,New,"Leg"),"Bound"),Is.EqualTo(true));Assert.That(Core.HasActiveGrant(New),Is.True);}
            }
            private TrafficWorldSnapshot MakeWorld(int version,Vector3 oldPose,Vector3 newPose,bool oldMoving)=>World(version,version,new[]{
                new TrafficBodyFact(Body,Origin,.4f,actorLife:Actor),
                new TrafficBodyFact(Old,oldPose,.4f,independentlyProgressing:oldMoving,remainingSeconds:oldMoving?13:0,actorLife:OldLife)}.Concat(
                BoundNew || version>=2?new[]{new TrafficBodyFact(New,newPose,.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:NewLife)}:
                    Array.Empty<TrafficBodyFact>()).ToArray(),
                MixedCanonical && version>=2?new[]{new TrafficParkingFact(New,NewParking,NewParking.Version,"canonical/"+New.ActorId,P(3),.4f)}:null);
            private void Bind(TrafficIntentKey key,object actor,Vector3 start,Vector3 end,TrafficNativeStamp stamp,int frame)
            {
                var resource="counter/"+key.ActorId;
                var source=Grant(Core,ServiceTrafficCoordinatorTests.Request(key,start,end,Snapshot,frame:frame,resource:resource,seconds:13));
                Core.PrepareLeg(source,resource,0,actor,stamp.LegGeneration,Snapshot,start,.08f,frame+1);Core.ProcessReady(frame+1);
                Assert.That(Core.TryCommit(Core.GetDecision(key)),Is.True);Assert.That(Core.BindLeg(key,actor,stamp),Is.True);
            }
            internal TrafficRequest Request(Vector3 target,int frame)=>new TrafficRequest(Key,frame,Snapshot,Origin,target,.4f,"pickup/"+Key.ActorId,
                requirements:ExtraSelected?new[]{new TrafficRouteRequirement("selected-home",target,Origin,.8f,selectedJourney:true,avoidProposedParking:false),
                    new TrafficRouteRequirement("extra-selected",P(-4,6),P(-2,6),.8f,selectedJourney:true,avoidProposedParking:false)}:
                    new[]{new TrafficRouteRequirement("selected-home",target,Origin,.8f,selectedJourney:true,avoidProposedParking:false)},
                independentlyProgressing:true,finiteSeconds:20,planPrimaryRoute:true);
        }
        [TestCase(false)][TestCase(true)]
        public void DeliveryNewFrozenBodyAllowsOnlyOriginalUnusedSideAndSpendsItsExistingDebtWhileChoosing(bool expireInGap)
        {
            var f=new DeliveryNewFrozenOwnerModel();var core=f.Core;var failed=f.Refused;
            Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.AlternateAllowed),
                "RED: this original side cannot add a new owner; unused original sides still owe full current proof");
            var queries=core.QueriesConsumed(f.Key);var age=D1Read(core,f.Key,"FirstFrame");var sequence=failed.RequestSequence;
            var frozen=(IEnumerable<TrafficIntentKey>)D1Read(core,f.Key,"FrozenOwners");Assert.That(frozen,Is.EquivalentTo(new[]{f.Old}));
            Assert.That(failed.AcquiredSequence,Is.Zero);Assert.That(core.HasActiveGrant(f.Key),Is.False);Assert.That(core.TryCommit(failed),Is.False);
            Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(11f));
            var entry=((System.Collections.IDictionary)D3ReadField(core,"entries"))[f.Key];
            Assert.That(((System.Collections.IEnumerable)D3ReadField(core,"workEntries")).Cast<object>().Any(e=>ReferenceEquals(e,entry)),Is.True,
                "A nonqueued alternate gap must remain in Tick's real work set");
            core.Tick(100,true);Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(11f));core.Tick(expireInGap?11:3,false);
            if(expireInGap)
            {
                var terminal=core.GetDecision(f.Key);Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                Assert.That(terminal.Reason,Is.EqualTo("wait-budget-exhausted"));Assert.That(core.TryAdvanceCandidate(terminal,1,f.Request(P(-4),9),out _),Is.False);
                Assert.That(core.QueriesConsumed(f.Key),Is.EqualTo(queries));Assert.That(core.TryCommit(terminal),Is.False);return;
            }
            Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(8f));
            Assert.That(core.TryAdvanceCandidate(failed,0,f.Request(P(-4),9),out _),Is.False,"Original attempted index cannot retry");
            Assert.That(core.TryAdvanceCandidate(failed,2,f.Request(P(-4),9),out _),Is.False,"Original finite count cannot expand");
            Assert.That(core.TryAdvanceCandidate(failed,1,f.Request(P(-4),9),out _),Is.True);
            core.Tick(1,false);core.ProcessReady(9);var ready=core.GetDecision(f.Key);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(7f));
            Assert.That(ready.RequestSequence,Is.EqualTo(sequence));Assert.That(D1Read(core,f.Key,"FirstFrame"),Is.EqualTo(age));
            Assert.That(core.QueriesConsumed(f.Key),Is.GreaterThan(queries));Assert.That((IEnumerable<TrafficIntentKey>)D1Read(core,f.Key,"FrozenOwners"),Is.EquivalentTo(new[]{f.Old}));
            Assert.That(core.TryCommit(ready),Is.True);Assert.That(core.TryAdvanceCandidate(failed,1,f.Request(P(-4),10),out _),Is.False);
        }
