        private sealed class UnpaidEligibilityModel
        {
            internal readonly TrafficIntentKey Key=new TrafficIntentKey("scene",1,"eligibility-head","pickup-wait",1,7,"eligibility-head/0");
            internal readonly TrafficIntentKey BodyKey=new TrafficIntentKey("scene",1,"eligibility-head","counter-arrival",1,7,"head");
            internal readonly object Life=new object(),Business=new object(),Admission=new object(),OlderOwner=new object();
            internal readonly CounterQueueService Queue=new CounterQueueService(new[]{Origin,P(-2)});
            internal readonly ServiceTrafficCoordinator Core;internal TrafficWorldSnapshot Snapshot;internal object Descriptor;
            internal bool Current=true,Capability,Blocked=true;internal int Calls;internal TrafficRequest Original;
            internal UnpaidEligibilityModel(bool capability=false,int budget=16384,bool attach=true,Func<Vector3,Vector3,IReadOnlyList<Vector3>> queryFault=null,int frameBudget=128,Func<object> nativeContext=null)
            {
                Capability=capability;Assert.That(Queue.TryJoin(Key.ActorId),Is.True);Assert.That(Queue.Complete(Key.ActorId,1),Is.True);
                Snapshot=MakeWorld(1);Func<Vector3,Vector3,IReadOnlyList<Vector3>> query=(from,to)=>
                {Calls++;if(queryFault!=null)return queryFault(from,to);return Capability && Blocked && from==P(0,2)?null:new[]{from,to};};
                Core=nativeContext==null?Coordinator(Snapshot,query:query,intentBudget:budget,frameBudget:frameBudget):
                    NativeContextCoordinator(Snapshot,query,frameBudget,budget,nativeContext);
                Original=RequestNow();var initial=Core.EvaluateParking(Original);
                if(attach)Attach(initial);
            }
            internal TrafficWorldSnapshot MakeWorld(int version,bool replaceLife=false)
            {
                Assert.That(Queue.TryCaptureAssignment(Key.ActorId,out var claim),Is.True);
                var bodies=new List<TrafficBodyFact>{new TrafficBodyFact(BodyKey,Origin,.4f,actorLife:replaceLife?new object():Life)};
                var parking=new List<TrafficParkingFact>{new TrafficParkingFact(BodyKey,Queue,Queue.Version,"counter/"+Key.ActorId,Origin,.4f,
                    businessOwner:Business,releaseObligation:Admission,semanticCheckpoint:claim)};
                if(Blocked && !Capability)bodies.Add(new TrafficBodyFact(ServiceTrafficCoordinatorTests.Key("eligibility-blocker"),P(2),.4f,actorLife:OlderOwner));
                if(Blocked && Capability)parking.Add(new TrafficParkingFact(ServiceTrafficCoordinatorTests.Key("eligibility-older"),OlderOwner,0,"pickup/eligibility-older",P(0,2),.4f));
                return World(version,version,bodies.ToArray(),parking.ToArray());
            }
            internal TrafficRequest RequestNow()=>new TrafficRequest(Key,11,Snapshot,Origin,P(2),.4f,"pickup/"+Key.ActorId,
                requirements:Capability && Blocked?new[]{new TrafficRouteRequirement("existing-goal/eligibility-older/exit-capability",P(0,2),P(4,2),.8f)}:null,
                finiteSeconds:20,planPrimaryRoute:true);
            internal void Attach(TrafficDecision initial)
            {
                var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficUnpaidParkingEligibility");
                if(type==null)return; // Baseline still executes the original behavior, rather than faking eligibility.
                Descriptor=Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                    null,new object[]{Key,Life,Queue,Business,Admission,(Func<bool>)(()=>Current)},null);
                Assert.That(D3InvokeBool(Core,"TrySetUnpaidParkingEligibility",initial,Descriptor),Is.True);
            }
            internal TrafficDecision Run(int frame=11){Core.ProcessReady(frame);return Core.GetDecision(Key);}
            internal void Clear()
            {Blocked=false;Snapshot=MakeWorld(2);Core.SetSnapshot(Snapshot);}
            internal bool Refresh(out TrafficDecision next)=>CfcReprepare(Core,Core.GetDecision(Key),RequestNow(),out next);
        }

        [Test] public void UnpaidQueuedDeferredMissingPreviewHoldsOriginalSourceAcrossCanonicalMetadataUntilFreshProof()
        {
            var m=new UnpaidEligibilityModel(capability:true,frameBudget:1);
            Assert.That(m.Run(11).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));m.Run(12);
            AssertUnpaidEligibilityHold(m,"unpaid-eligibility/route-capability-unavailable");
            Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var claim),Is.True);
            m.Clear();Assert.That(m.Refresh(out var queued),Is.True);
            Assert.That(queued.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(queued.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(D1Read(m.Core,m.Key,"Queued"),Is.EqualTo(true));Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilityHeld"),Is.EqualTo(false));
            Assert.That(D1Read(m.Core,m.Key,"FrozenOwners"),Is.Null);Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilityQueryFault"),Is.EqualTo(false));
            var entry=((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key];var descriptor=D1Read(m.Core,m.Key,"UnpaidEligibility");
            var first=D1Read(m.Core,m.Key,"FirstFrame");var sequence=queued.RequestSequence;var finite=D1Read(m.Core,m.Key,"FiniteLimit");
            var count=D1Read(m.Core,m.Key,"CandidateCount");var index=D1Read(m.Core,m.Key,"CurrentIndex");
            var attempts=((IEnumerable<int>)D1Read(m.Core,m.Key,"AttemptedIndices")).ToArray();var queries=m.Core.QueriesConsumed(m.Key);var calls=m.Calls;
            // A public unused-slot update changes real Counter metadata while the arrived head Entry/pose remains exact.
            m.Queue.UpdateSlots(new[]{Origin,P(-3)});Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var sameClaim),Is.True);
            Assert.That(claim.IsSameReservation(sameClaim),Is.True);Assert.That(claim.IsSameCurrentClaim(sameClaim),Is.True);
            var basis=m.MakeWorld(3);m.Snapshot=new TrafficWorldSnapshot(3,m.Snapshot.BodyVersion,basis.Bodies,basis.Parking);m.Core.SetSnapshot(m.Snapshot);
            var held=HoldProducerPreview(m.Core,queued); // This is the original real producer's missing-preview port, not a Core state write.

            m.Core.ProcessReady(13);var observed=m.Core.GetDecision(m.Key);
            Assert.That(observed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None),
                "RED: a missing canonical preview must not let the original queued unpaid request execute its stale snapshot; holdAccepted="+held+" result="+observed.Kind+"/"+observed.Reason);
            Assert.That(held,Is.True);Assert.That(observed,Is.SameAs(queued));Assert.That(D1Read(m.Core,m.Key,"ProducerPreviewHeld"),Is.EqualTo(true));
            Assert.That(D1Read(m.Core,m.Key,"Queued"),Is.EqualTo(false));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries));Assert.That(m.Calls,Is.EqualTo(calls));
            Assert.That(m.Core.HasActiveGrant(m.Key),Is.False);Assert.That(m.Core.TryCommit(observed),Is.False);Assert.That(observed.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(m.Core,m.Key,"FrozenOwners"),Is.Null);Assert.That(D1Read(m.Core,m.Key,"Leg"),Is.Null);
            Assert.That(m.Refresh(out var resumed),Is.True,"The same actual front Counter claim and restored real preview must admit current full reproof");
            Assert.That(resumed.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(D1Read(m.Core,m.Key,"ProducerPreviewHeld"),Is.EqualTo(false));
            Assert.That(((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key],Is.SameAs(entry));Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibility"),Is.SameAs(descriptor));
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(first));Assert.That(resumed.RequestSequence,Is.EqualTo(sequence));
            Assert.That(D1Read(m.Core,m.Key,"FiniteLimit"),Is.EqualTo(finite));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries));
            Assert.That(D1Read(m.Core,m.Key,"CandidateCount"),Is.EqualTo(count));Assert.That(D1Read(m.Core,m.Key,"CurrentIndex"),Is.EqualTo(index));
            Assert.That((IEnumerable<int>)D1Read(m.Core,m.Key,"AttemptedIndices"),Is.EquivalentTo(attempts));
            var ready=m.Run(14);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.GreaterThan(queries),"Only complete current-world proof may prepare the original unacquired source");
            Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var finalClaim),Is.True);Assert.That(claim.IsSameReservation(finalClaim),Is.True);
            Assert.That(m.Queue.Snapshot.Single().VisitId,Is.EqualTo(m.Key.ActorId));Assert.That(m.Queue.Snapshot.Single().SlotIndex,Is.Zero);
            Assert.That(m.Core.TryCommit(ready),Is.True);
        }

        // The old constructor executes the same scenario during RED; no private Entry or budget mutation.
        // RED在旧公开构造入口跑相同业务；新入口只显式认证Native查询上下文。
        private static ServiceTrafficCoordinator NativeContextCoordinator(TrafficWorldSnapshot snapshot,
            Func<Vector3,Vector3,IReadOnlyList<Vector3>> query,int frameBudget,int budget,Func<object> context)
        {
            var constructor=typeof(ServiceTrafficCoordinator).GetConstructors().Single();
            var args=new object[]{"scene",1L,7,snapshot,query,frameBudget,budget,30f};
            if(constructor.GetParameters().Length==9)args=args.Concat(new object[]{context}).ToArray();
            return (ServiceTrafficCoordinator)constructor.Invoke(args);
        }
        private sealed class NativeChunkMemoModel
        {
            internal readonly UnpaidEligibilityModel M;internal object Token=new object();
            internal int Frame=10,Version=1,PrimaryCalls,NullCalls;internal bool NullPrimary,ThrowPrimary,RotateDuringPrimary,AllowCapability,ThrowContext,InvalidateProducer;
            internal Vector3[] ReturnedPrimary;
            internal NativeChunkMemoModel(bool disableContext=false)
            {
                M=new UnpaidEligibilityModel(capability:true,budget:10,frameBudget:1,nativeContext:()=>
                    {if(ThrowContext)throw new InvalidOperationException("Native context unavailable");if(InvalidateProducer)M.Current=false;return disableContext?null:Token;},
                    queryFault:(from,to)=>
                    {
                        if(from==Origin)
                        {
                            PrimaryCalls++;if(ThrowPrimary)throw new InvalidOperationException("Original current provider fault");
                            if(RotateDuringPrimary)Token=new object();if(NullPrimary)return null;
                            return ReturnedPrimary=new[]{from,to};
                        }
                        if(AllowCapability)return new[]{from,to};NullCalls++;return null;
                    });
            }
            internal TrafficDecision RunToBoundary()
            {
                for(var i=0;i<8;i++)
                {
                    var result=M.Run(++Frame);
                    if(result.FailureDisposition!=TrafficFailureDisposition.None ||
                        (bool)D1Read(M.Core,M.Key,"UnpaidEligibilityHeld") || result.Kind==TrafficDecisionKind.Granted)return result;
                }
                return M.Core.GetDecision(M.Key);
            }
            internal bool Refresh(bool clear=false)
            {
                if(clear)M.Blocked=false;M.Snapshot=M.MakeWorld(++Version);M.Core.SetSnapshot(M.Snapshot);
                var roles=clear?Array.Empty<TrafficRouteRequirement>():new[]{new TrafficRouteRequirement(
                    "existing-goal/changed-opportunity/"+Version,P(0,2),P(4,2),.8f)};
                var request=new TrafficRequest(M.Key,11,M.Snapshot,Origin,P(2),.4f,"pickup/"+M.Key.ActorId,
                    requirements:roles,finiteSeconds:20,planPrimaryRoute:true);
                return CfcReprepare(M.Core,M.Core.GetDecision(M.Key),request,out _);
            }
            internal bool RefreshIdenticalSpace()
            {
                var old=(TrafficRequest)D1Read(M.Core,M.Key,"Request");M.Snapshot=M.MakeWorld(++Version);M.Core.SetSnapshot(M.Snapshot);
                var request=new TrafficRequest(M.Key,11,M.Snapshot,old.Start,old.Target,old.Radius,old.ResourceId,
                    requirements:old.Requirements,finiteSeconds:old.FiniteSeconds,planPrimaryRoute:true);
                return CfcReprepare(M.Core,M.Core.GetDecision(M.Key),request,out _);
            }
            internal void AssertHeld()
            {
                var d=RunToBoundary();Assert.That(d.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None),d.Reason);
                Assert.That(D1Read(M.Core,M.Key,"UnpaidEligibilityHeld"),Is.EqualTo(true),d.Reason);
                Assert.That(M.Core.HasActiveGrant(M.Key),Is.False);Assert.That(M.Core.TryCommit(d),Is.False);
            }
        }
        [Test] public void NativePositiveChunksSurviveRepeatedRealSpatialReproofWithinOriginalQueryAccount()
        {
            var f=new NativeChunkMemoModel();var m=f.M;f.AssertHeld();var sequence=m.Core.GetDecision(m.Key).RequestSequence;
            var age=D1Read(m.Core,m.Key,"FirstFrame");var entry=((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key];
            for(var n=1;n<8;n++){Assert.That(f.Refresh(),Is.True);f.AssertHeld();}
            Assert.That(f.PrimaryCalls,Is.EqualTo(1),"Same exact positive Native query is reused; failed null proof is always queried again");
            Assert.That(f.NullCalls,Is.EqualTo(8));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(9));
            Assert.That(f.Refresh(clear:true),Is.True);var ready=f.RunToBoundary();Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(9));Assert.That(ready.RequestSequence,Is.EqualTo(sequence));
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(age));
            Assert.That(((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key],Is.SameAs(entry));Assert.That(m.Core.TryCommit(ready),Is.True);
        }
