        [Test] public void NativeContextChangeWhilePausedRetainsReproofEvidenceUntilResume()
        {
            var f=new NativeChunkMemoModel();f.AssertHeld();var m=f.M;var held=m.Core.GetDecision(m.Key);var queries=m.Core.QueriesConsumed(m.Key);
            var age=D1Read(m.Core,m.Key,"FirstFrame");m.Core.Tick(0,true);f.Token=new object();f.AllowCapability=true;
            Assert.That(f.RefreshIdenticalSpace(),Is.False);Assert.That(m.Core.GetDecision(m.Key),Is.SameAs(held));
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries));Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilityHeld"),Is.EqualTo(true));
            m.Core.Tick(0,false);Assert.That(f.RefreshIdenticalSpace(),Is.True);Assert.That(f.RunToBoundary().Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries+2));Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(age));
        }

        // Derived from Main g54: primary and work routes finish before a later capability changes.
        // 真实Counter claim；只经公开准备入口刷新，不写Entry或重置查询账本。
        private sealed class QueuedUnpaidRolesModel
        {
            internal readonly UnpaidEligibilityModel M;
            internal readonly List<Vector3[]> Calls=new List<Vector3[]>();
            internal readonly Vector3 AStart=P(4,4),AGoal=P(6,4),BStart=P(4,6);
            internal TrafficRouteRequirement A;
            internal QueuedUnpaidRolesModel(int budget=4)
            {
                M=new UnpaidEligibilityModel(budget:budget,frameBudget:1,queryFault:(from,to)=>{Calls.Add(new[]{from,to});return new[]{from,to};});
                M.Blocked=false;M.Snapshot=M.MakeWorld(2);M.Core.SetSnapshot(M.Snapshot);
                A=new TrafficRouteRequirement("work-outward",AStart,AGoal,.8f);
                Assert.That(CfcReprepare(M.Core,M.Core.GetDecision(M.Key),Request(new[]{A,new TrafficRouteRequirement("work-home",BStart,P(6,6),.8f)}),out _),Is.True);
                M.Run(11);M.Run(12);
                Assert.That(M.Core.GetDecision(M.Key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Assert.That(M.Core.QueriesConsumed(M.Key),Is.EqualTo(2));Assert.That(D1Read(M.Core,M.Key,"JobIndex"),Is.EqualTo(2));
            }
            internal TrafficRequest Request(IEnumerable<TrafficRouteRequirement> roles)=>new TrafficRequest(M.Key,11,M.Snapshot,Origin,P(2),.4f,"pickup/"+M.Key.ActorId,
                requirements:roles.ToArray(),finiteSeconds:20,planPrimaryRoute:true);
            internal TrafficRouteRequirement[] Changed(TrafficRouteRequirement a=null)=>new[]{
                new TrafficRouteRequirement("work-home",BStart,P(7,6),.8f),a??A,new TrafficRouteRequirement("waiting-exit-capability",P(4,8),P(6,8),.8f,avoidProposedParking:false)};
            internal TrafficDecision Finish(int first=13)
            {
                for(var frame=first;frame<first+90 && M.Core.GetDecision(M.Key).Kind==TrafficDecisionKind.DeferredByBudget;frame++)M.Run(frame);
                return M.Core.GetDecision(M.Key);
            }
            internal int AQueries=>Calls.Count(p=>p[0]==AStart && p[1]==AGoal);
        }
        [Test] public void QueuedUnpaidRoleRefreshRetainsRevalidatedCompletedRoutesWithinOriginalLifetimeBudget()
        {
            var f=new QueuedUnpaidRolesModel();var m=f.M;var old=m.Core.GetDecision(m.Key);var age=D1Read(m.Core,m.Key,"FirstFrame");
            var entry=((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key];
            Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var claim),Is.True);
            // A new distant body changes current obstacle facts but does not cut either completed route.
            var basis=m.MakeWorld(3);var far=P(-8,-8);m.Snapshot=World(3,3,basis.Bodies.Concat(new[]{new TrafficBodyFact(Key("new-far-body"),far,.4f,actorLife:new object())}).ToArray(),basis.Parking.ToArray());m.Core.SetSnapshot(m.Snapshot);
            var a=new TrafficRouteRequirement("work-outward",f.AStart,f.AGoal,.8f,new[]{far});
            Assert.That(CfcReprepare(m.Core,old,f.Request(f.Changed(a)),out var pending),Is.True);Assert.That(pending.AcquiredSequence,Is.Zero);
            var ready=f.Finish();Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),
                "RED: changed B and new C need only their own Native queries; completed current-safe primary/A must not be discarded: "+ready.Reason);
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(4));Assert.That(f.AQueries,Is.EqualTo(1));
            Assert.That(f.Calls.Count(p=>p[0]==Origin&&p[1]==P(2)),Is.EqualTo(1));
            CollectionAssert.AreEqual(new[]{"pickup/"+m.Key.ActorId,"work-home","work-outward","waiting-exit-capability"},ready.ProofRoutes.Select(p=>p.ResourceId));
            Assert.That(ready.ProofRoutes[1].Waypoints.Last(),Is.EqualTo(P(7,6)));Assert.That(ready.AcquiredSequence,Is.Zero);
            Assert.That(((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key],Is.SameAs(entry));Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(age));
            Assert.That(ready.RequestSequence,Is.EqualTo(old.RequestSequence));Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var current),Is.True);Assert.That(claim.IsSameCurrentClaim(current),Is.True);
            Assert.That(m.Core.TryCommit(ready),Is.True);
        }
