        [Test] public void WildcardWaitFailureRecordsEachOriginalPhaseWithoutChangingOutcomeOrCallingNative()
        {
            var stopped=Key("wildcard-stopped");var world=World(1,1,new[]{new TrafficBodyFact(stopped,P(2),.4f,actorLife:new object())});
            var calls=0;var core=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            typeof(ServiceTrafficCoordinator).GetField("WaitFailureDiagnosticIntent",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(core,"*");
            var paid=Key("wildcard-paid","pickup-paid-movement",1);var exiting=Key("wildcard-exit","actual-exit",2);
            foreach(var key in new[]{paid,exiting})core.EvaluateParking(Request(key,Origin,P(2),world));core.ProcessReady(11);
            foreach(var key in new[]{paid,exiting})
            {
                var failed=core.GetDecision(key);Assert.That(failed.Reason,Is.EqualTo("no-independent-finite-release-or-cycle"));
                Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(core.TryCommit(failed),Is.False);
                Assert.That(core.QueriesConsumed(key),Is.Zero);
            }
            Assert.That(calls,Is.Zero);Assert.That(core.QueriesThisFrame,Is.Zero);
            var records=(System.Collections.IDictionary)D3ReadField(core,"WaitFailureDiagnostics");
            Assert.That(records.Count,Is.EqualTo(2));Assert.That(records.Contains(paid),Is.True);Assert.That(records.Contains(exiting),Is.True);
            Assert.That(D3ReadField(core,"WaitFailureDiagnosticDropped"),Is.EqualTo(0));
            var text=(string)D3ReadField(core,"WaitFailureDiagnostic");Assert.That(text,Does.Contain("intent=wildcard-paid/pickup-paid-movement"));
            Assert.That(text,Does.Contain("intent=wildcard-exit/actual-exit"));Assert.That(text,Does.Contain("condition=owner-not-independent"));
        }

        private sealed class UnpaidCounterIdleMilestone:ITrafficPhaseMilestone
        {
            private readonly UnpaidEligibilityModel model;
            public TrafficDecision SourcePermit{get;}
            public TrafficParkingFact OriginalClaim{get;}
            public TrafficParkingFact CurrentClaim
            {
                get
                {
                    if(!model.Queue.TryCaptureAssignment(model.Key.ActorId,out var claim))return null;
                    return new TrafficParkingFact(model.BodyKey,model.Queue,model.Queue.Version,"counter/"+model.Key.ActorId,Origin,.4f,
                        businessOwner:model.Business,releaseObligation:model.Admission,semanticCheckpoint:claim);
                }
            }
            public object ActorLife=>model.Life;
            public object BusinessOwner=>model.Business;
            public object ReleaseObligation=>model.Admission;
            public TrafficPhaseMilestoneKind Kind=>TrafficPhaseMilestoneKind.Arrived;
            public bool IsCurrent=>model.Queue.Snapshot.Count==1 && model.Queue.Snapshot[0].Arrived &&
                model.Queue.Snapshot[0].SlotIndex==0 && model.Queue.Snapshot[0].VisitId==model.Key.ActorId;
            internal UnpaidCounterIdleMilestone(UnpaidEligibilityModel model,TrafficDecision source)
            {this.model=model;SourcePermit=source;OriginalClaim=model.Snapshot.Parking.Single(p=>p.Owner.ActorId==model.Key.ActorId);}
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)
            {
                current=CurrentClaim;return IsCurrent && ReferenceEquals(captured,OriginalClaim) &&
                    TrafficClaimCheckpoints.AreSame(captured,current)?TrafficPhaseClaimState.Held:TrafficPhaseClaimState.Invalid;
            }
            public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision source,int firstFrame)=>false;
        }
        [Test] public void UnpaidEligibilityHoldKeepsActualArrivedCounterIdleAndStartsNoNewTransactionBudget()
        {
            var m=new UnpaidEligibilityModel();var resource="counter/"+m.Key.ActorId;
            var movement=new TrafficRequest(m.BodyKey,1,m.Snapshot,Origin,Origin,.4f,resource,finiteSeconds:20);
            m.Core.EvaluateMovement(movement);m.Core.ProcessReady(1);var source=m.Core.GetDecision(m.BodyKey);
            Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(m.Core.TryCommit(source),Is.True);
            var leg=m.Core.PrepareLeg(source,resource,0,m.Life,1,m.Snapshot,Origin,.08f,2);
            m.Core.ProcessReady(2);leg=m.Core.GetDecision(m.BodyKey);Assert.That(leg.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(m.Core.TryCommit(leg),Is.True);var stamp=new TrafficNativeStamp(901,1);Assert.That(m.Core.BindLeg(m.BodyKey,m.Life,stamp),Is.True);
            var milestone=new UnpaidCounterIdleMilestone(m,source);
            var arrived=new MovementResult(901,m.Key.ActorId,MovementStatus.Arrived,NavigationFailure.None,NavigationFailure.None,NavigationFailure.None,Origin,0);
            Assert.That(m.Core.CompleteLegAndBeginHandoff(m.BodyKey,m.Life,stamp,arrived,()=>milestone,out var handle),Is.True);
            Assert.That(handle,Is.Not.Null);var state=D1Read(m.Core,m.BodyKey,"PendingHandoff");
            m.Run(11);AssertUnpaidEligibilityHold(m,"unpaid-eligibility/endpoint-occupied");var queries=m.Core.QueriesConsumed(m.Key);
            m.Core.Tick(61,false);
            Assert.That(D1Read(m.Core,m.BodyKey,"PendingHandoff"),Is.SameAs(state),"Business ineligibility owns no active handoff work or finite waiter");
            Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(20f));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries));
            Assert.That(((System.Collections.IDictionary)D3ReadField(state,"Dependencies")).Count,Is.Zero);
            m.Clear();Assert.That(m.Refresh(out _),Is.True);m.Core.Tick(1,false);
            Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(19f),"A genuinely queued full reproof resumes the unspent original transaction deadline");
            var ready=m.Run(12);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(m.Core,m.Key,"FiniteLimit"),Is.EqualTo(20f));
        }

        [TestCase("throw")][TestCase("empty")][TestCase("nonfinite")]
        public void UnpaidEligibilityQueryProviderFaultRemainsTerminalAfterRealSpatialChange(string fault)
        {
            IReadOnlyList<Vector3> QueryFault(Vector3 from,Vector3 to)
            {
                if(fault=="throw")throw new InvalidOperationException("actual provider failure");
                if(fault=="empty")return Array.Empty<Vector3>();
                return new[]{from,new Vector3(float.NaN,0,0),to};
            }
            var m=new UnpaidEligibilityModel(queryFault:QueryFault);
            // Clear endpoint occupancy before the first actual batch, so this reaches the provider itself.
            // 不伪造Core结果；真实委托分别抛出异常/返回empty/NaN，原查询计数照常消费。
            m.Clear();Assert.That(m.Refresh(out _),Is.True);var failed=m.Run(12);
            Assert.That(m.Calls,Is.EqualTo(1));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(1));
            Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(failed.Reason,Is.EqualTo("bounded-route-proof-failed"),"Keep the existing fault result; it is not spatial eligibility evidence");
            Assert.That(failed.AcquiredSequence,Is.Zero);Assert.That(m.Core.HasActiveGrant(m.Key),Is.False);
            Assert.That(m.Core.TryCommit(failed),Is.False);
            var spent=m.Core.QueriesConsumed(m.Key);var first=D1Read(m.Core,m.Key,"FirstFrame");var limit=D1Read(m.Core,m.Key,"FiniteLimit");
            m.Blocked=true;m.Snapshot=m.MakeWorld(3);m.Core.SetSnapshot(m.Snapshot);
            Assert.That(m.Refresh(out _),Is.False,"Real external spatial change cannot resurrect a provider fault");m.Run(13);
            Assert.That(m.Core.GetDecision(m.Key),Is.SameAs(failed));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(spent));
            Assert.That(m.Calls,Is.EqualTo(1));Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(first));
            Assert.That(D1Read(m.Core,m.Key,"FiniteLimit"),Is.EqualTo(limit));
        }


        // Reuse the actual Counter-claim model. All moving ownership below comes from public Core prepare/commit/bind.
        // 只更新模型真实世界输入；不写Entry/Route/State，不把Independent hint当Native来源。
        private sealed class UnpaidNativeMotionModel
        {
            internal readonly UnpaidEligibilityModel Candidate=new UnpaidEligibilityModel(capability:true,budget:64,frameBudget:2);
            internal readonly TrafficIntentKey Moving;
            internal readonly bool Unrelated;
            internal readonly TrafficNativeStamp Stamp=new TrafficNativeStamp(971,7);
            internal object Life=>Unrelated?StaticLife:Candidate.OlderOwner;
            internal readonly object StaticLife=new object();
            internal TrafficDecision Source;internal Vector3 Pose;internal bool Enabled=true,Progress,StaticTarget;
            internal readonly float X;internal int Version=20;
            internal Vector3 Start=>Unrelated?P(-6,4):X==2?P(2,-3):P(0,2);internal Vector3 End=>Unrelated?P(-3,4):X==2?P(2,3):P(2,-2);
            internal UnpaidNativeMotionModel(float x=1,bool unrelated=false)
            {
                Unrelated=unrelated;Moving=ServiceTrafficCoordinatorTests.Key(unrelated?"eligibility-moving-barista":"eligibility-older","pickup-service",90);
                X=x;Pose=Start;Publish();Assert.That(Candidate.Refresh(out _),Is.True);Candidate.Run(11);
                AssertUnpaidEligibilityHold(Candidate,"unpaid-eligibility/route-capability-unavailable");
            }
            internal void Publish()
            {
                var m=Candidate;var basis=m.MakeWorld(++Version);
                var bodies=basis.Bodies.Concat(new[]{new TrafficBodyFact(Moving,Pose,.4f,enabled:Enabled,
                    independentlyProgressing:Progress,remainingSeconds:Progress?20:0,actorLife:Life,actorActive:Enabled)}).ToList();
                if(StaticTarget)bodies.Add(new TrafficBodyFact(ServiceTrafficCoordinatorTests.Key("eligibility-checkpoint-static"),P(2),.4f,actorLife:StaticLife));
                m.Snapshot=World(Version,Version,bodies.ToArray(),basis.Parking.ToArray());m.Core.SetSnapshot(m.Snapshot);
            }
            internal void Begin(bool bind=true,bool source=true)
            {
                // The prior real refusal is retained; remove its test body before creating the independent Native route.
                if(!Unrelated)Candidate.Blocked=false;Progress=true;Publish();if(!source)return;
                var c=Candidate.Core;var request=new TrafficRequest(Moving,12,Candidate.Snapshot,Start,End,.4f,"native-route",finiteSeconds:20,planPrimaryRoute:true);
                c.EvaluateParking(request);c.ProcessReady(12);Source=c.GetDecision(Moving);
                Assert.That(Source.Kind,Is.EqualTo(TrafficDecisionKind.Granted),Source.Reason);Assert.That(c.TryCommit(Source),Is.True);
                c.PrepareLeg(Source,"native-route",0,Life,7,Candidate.Snapshot,Start,.08f,12);c.ProcessReady(12);
                var leg=c.GetDecision(Moving);Assert.That(leg.Kind,Is.EqualTo(TrafficDecisionKind.Granted),leg.Reason);Assert.That(c.TryCommit(leg),Is.True);
                if(bind)Assert.That(c.BindLeg(Moving,Life,Stamp),Is.True);
                Assert.That(D1Read(c,Moving,"JourneyParking"),Is.EqualTo(true),"Actual pickup-service family starts as parking permission");
                Assert.That(D1Read(c,Moving,"Parking"),Is.EqualTo(false),"The same family has a real strict movement leg now");
            }
            internal void Checkpoint()
            {Pose=End;Progress=false;Publish();Assert.That(Candidate.Core.CompleteLeg(Moving,Life,Stamp,End),Is.True);}
        }
        [Test] public void UnpaidPreviewRestoreFinishesFreshMultiFrameProofWithoutReusingTheOldNativeRefusal()
        {
            var f=new UnpaidNativeMotionModel();f.Begin();var m=f.Candidate;
            var original=m.Core.GetDecision(m.Key);Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilitySpatialRefusal"),Is.Not.Null,"PREMISE: actual older refusal exists before preview interruption");
            var nativeLeg=D1Read(m.Core,f.Moving,"Leg");Assert.That(D3ReadField(nativeLeg,"Bound"),Is.EqualTo(true));
            var entry=((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key];var age=D1Read(m.Core,m.Key,"FirstFrame");
            var queries=m.Core.QueriesConsumed(m.Key);var sequence=original.RequestSequence;
            Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var claim),Is.True);
            Assert.That(HoldProducerPreview(m.Core,original),Is.True);
            // The restored real preview moves to a current safe target; three ordinary roles force proof across two batches.
            TrafficRequest Fresh()=>new TrafficRequest(m.Key,11,m.Snapshot,Origin,P(-4),.4f,"pickup/"+m.Key.ActorId,
                requirements:new[]{new TrafficRouteRequirement("work-outward",P(-6,3),P(-4,3),.8f),
                    new TrafficRouteRequirement("work-home",P(-4,3),P(-6,3),.8f),
                    new TrafficRouteRequirement("waiting-exit-capability",P(-4),P(-6,-3),.8f,avoidProposedParking:false)},finiteSeconds:20,planPrimaryRoute:true);
            Assert.That(CfcReprepare(m.Core,m.Core.GetDecision(m.Key),Fresh(),out _),Is.True);Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries));
            var partial=m.Run(13);Assert.That(partial.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),partial.Reason);
            var jobs=D1Read(m.Core,m.Key,"Jobs");var count=((System.Collections.IList)jobs).Count;var jobIndex=(int)D1Read(m.Core,m.Key,"JobIndex");
            Assert.That(count,Is.GreaterThan(2));Assert.That(jobIndex,Is.LessThan(count));var spent=m.Core.QueriesConsumed(m.Key);
            Assert.That(spent,Is.GreaterThan(queries));Assert.That(D1Read(m.Core,f.Moving,"Leg"),Is.SameAs(nativeLeg));Assert.That(D3ReadField(nativeLeg,"Bound"),Is.EqualTo(true));
            Assert.That(CfcReprepare(m.Core,m.Core.GetDecision(m.Key),Fresh(),out _),Is.True);
            Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilityHeld"),Is.EqualTo(false),"The old refusal cannot coalesce a new incomplete proof just because the old actor is still Bound");
            Assert.That(D1Read(m.Core,m.Key,"Jobs"),Is.SameAs(jobs));Assert.That(((System.Collections.IList)jobs).Count,Is.EqualTo(count));
            Assert.That(D1Read(m.Core,m.Key,"JobIndex"),Is.EqualTo(jobIndex));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(spent));
            var ready=m.Run(14);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.GreaterThan(spent));Assert.That(ready.AcquiredSequence,Is.Zero);
            Assert.That(((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key],Is.SameAs(entry));Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(age));
            Assert.That(ready.RequestSequence,Is.EqualTo(sequence));Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var same),Is.True);Assert.That(claim.IsSameReservation(same),Is.True);
            Assert.That(D1Read(m.Core,f.Moving,"Leg"),Is.SameAs(nativeLeg));Assert.That(D3ReadField(nativeLeg,"Bound"),Is.EqualTo(true));
            Assert.That(m.Core.HasActiveGrant(m.Key),Is.False);Assert.That(m.Core.TryCommit(ready),Is.True);
        }

        [Test] public void UnpaidEligibilityCoalescesSameBoundNativeMotionWithoutSpendingItsOriginalQueryBudget()
        {
            var f=new UnpaidNativeMotionModel();f.Begin();var m=f.Candidate;
            var first=D1Read(m.Core,m.Key,"FirstFrame");var limit=D1Read(m.Core,m.Key,"FiniteLimit");
            var sequence=m.Core.GetDecision(m.Key).RequestSequence;var queries=m.Core.QueriesConsumed(m.Key);
            m.Blocked=false;TrafficDecision observed=null;var frames=0;
            for(var frame=13;frame<109;frame++)
            {
                var progress=.8f+(frame-13)*.006f;f.Pose=P(progress,2-2*progress);f.Publish();
                if(m.Core.GetDecision(m.Key).FailureDisposition==TrafficFailureDisposition.Terminal)break;
                Assert.That(m.Refresh(out _),Is.True,"PREMISE: same original unpaid source must remain refreshable before any genuine terminal");
                observed=m.Run(frame);m.Core.Tick(1f/60,false);frames++;
                if(observed.FailureDisposition==TrafficFailureDisposition.Terminal)break;
            }
            TestContext.WriteLine("UNPAID_MOTION_COALESCE frames="+frames+" queries="+queries+"->"+m.Core.QueriesConsumed(m.Key)+
                " kind="+observed?.Kind+" reason="+observed?.Reason+" first="+D1Read(m.Core,m.Key,"FirstFrame"));
            Assert.That(m.Core.GetDecision(m.Key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None),
                "RED: the same real finite Bound leg's position updates must not exhaust an unpaid business proposal before its checkpoint");
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries),"Coalescing is scheduling only; no re-query on each continuous Native position");
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(first));Assert.That(D1Read(m.Core,m.Key,"FiniteLimit"),Is.EqualTo(limit));
            Assert.That(m.Core.GetDecision(m.Key).RequestSequence,Is.EqualTo(sequence));Assert.That(m.Core.GetDecision(m.Key).AcquiredSequence,Is.Zero);
            Assert.That(m.Core.HasActiveGrant(m.Key),Is.False);Assert.That(m.Core.TryCommit(m.Core.GetDecision(m.Key)),Is.False);
            Assert.That(D1Read(m.Core,m.Key,"FrozenOwners"),Is.Null);Assert.That(D1Read(m.Core,m.Key,"Leg"),Is.Null);
            f.Checkpoint();Assert.That(m.Refresh(out _),Is.True);var ready=m.Run(109);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.GreaterThan(queries),"Only a complete actual-current-world proof may prepare permission after the checkpoint");
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(first));Assert.That(D1Read(m.Core,m.Key,"FiniteLimit"),Is.EqualTo(limit));
            Assert.That(m.Core.TryCommit(ready),Is.True);
        }
        // Same original unpaid claim and failed capability; a different real moving body only changes world geometry.
        // 复现旧Main短时重复重证；没有修改Entry、预算、失败状态或Native stamp。
        [TestCase(false)][TestCase(true)]
        public void UnpaidEligibilityUncapturedBoundMotionCannotRepeatedlySpendTheSameLifetimeBudget(bool staticAtCheckpoint)
        {
            var f=new UnpaidNativeMotionModel(unrelated:true);f.Begin();var m=f.Candidate;
            // Creating the real Native right is a genuine world change: prove once before position-only samples.
            Assert.That(m.Refresh(out _),Is.True);m.Run(13);AssertUnpaidEligibilityHold(m,"unpaid-eligibility/route-capability-unavailable");
            var causal=(IEnumerable<string>)D1Read(m.Core,m.Key,"UnpaidEligibilitySpatialActors");
            Assert.That(causal,Does.Not.Contain(f.Moving.ActorId),"PREMISE: the moving actor was not the failed role owner or one of its obstacles");
            var source=m.Core.GetDecision(m.Key);var queries=m.Core.QueriesConsumed(m.Key);var age=D1Read(m.Core,m.Key,"FirstFrame");
            var entry=((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key];var native=D1Read(m.Core,f.Moving,"Leg");
            Assert.That(D3ReadField(native,"Bound"),Is.EqualTo(true));Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var originalClaim),Is.True);
            var frames=0;
            for(var frame=14;frame<110;frame++)
            {
                f.Pose=P(-6+(frame-13)*.02f,4);f.Publish();
                if(m.Core.GetDecision(m.Key).FailureDisposition==TrafficFailureDisposition.Terminal)break;
                Assert.That(m.Refresh(out _),Is.True);m.Run(frame);m.Core.Tick(.01f,false);frames++;
                if(m.Core.GetDecision(m.Key).FailureDisposition==TrafficFailureDisposition.Terminal)break;
            }
            var held=m.Core.GetDecision(m.Key);
            Assert.That(held.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None),
                "RED: unrelated real body position samples must not turn one unchanged unpaid proposal into "+held.Reason+"; frames="+frames+" queries="+m.Core.QueriesConsumed(m.Key));
            Assert.That(frames,Is.EqualTo(96));Assert.That(m.Core.QueriesConsumed(m.Key),Is.EqualTo(queries));Assert.That(held.AcquiredSequence,Is.Zero);
            Assert.That(m.Core.TryCommit(held),Is.False);Assert.That(m.Core.HasActiveGrant(m.Key),Is.False);
            Assert.That(((System.Collections.IDictionary)D3ReadField(m.Core,"entries"))[m.Key],Is.SameAs(entry));
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(age));Assert.That(held.RequestSequence,Is.EqualTo(source.RequestSequence));
            Assert.That(D1Read(m.Core,f.Moving,"Leg"),Is.SameAs(native));Assert.That(D3ReadField(native,"Stamp"),Is.EqualTo(f.Stamp));
            f.StaticTarget=staticAtCheckpoint;f.Checkpoint();Assert.That(m.Refresh(out _),Is.True);
            Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilitySpatialRefusal"),Is.Null,"The completed discovery cannot let an old causal leg take over fresh partial proof");
            Assert.That((IEnumerable<string>)D1Read(m.Core,m.Key,"UnpaidEligibilitySpatialActors"),Is.Empty);
            var checkedNow=m.Run(110);
            Assert.That(checkedNow.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(m.Core.TryCommit(checkedNow),Is.False);
            if(staticAtCheckpoint)Assert.That(checkedNow.Blockers.Any(b=>b.Owner.ActorId=="eligibility-checkpoint-static"),Is.True,"New actual body must survive coalescing");
            else Assert.That(m.Core.QueriesConsumed(m.Key),Is.GreaterThan(queries),"Real checkpoint still owes current full capability proof");
            f.StaticTarget=false;m.Blocked=false;f.Publish();Assert.That(m.Refresh(out _),Is.True);var ready=m.Run(111);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);Assert.That(ready.AcquiredSequence,Is.Zero);
            Assert.That(m.Core.QueriesConsumed(m.Key),Is.GreaterThan(queries));Assert.That(m.Core.QueriesConsumed(m.Key),Is.LessThan(64));
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(age));Assert.That(ready.RequestSequence,Is.EqualTo(source.RequestSequence));
            Assert.That(m.Queue.TryCaptureAssignment(m.Key.ActorId,out var currentClaim),Is.True);Assert.That(originalClaim.IsSameCurrentClaim(currentClaim),Is.True);
            Assert.That(m.Core.TryCommit(ready),Is.True);
        }
        [TestCase("target",false)][TestCase("target",true)][TestCase("roles",false)][TestCase("roles",true)]
        [TestCase("static-body",false)][TestCase("static-body",true)][TestCase("parking",false)][TestCase("parking",true)]
        public void UnpaidEligibilityDiscoveredMotionCannotHideOtherCurrentSpaceChanges(string change,bool alreadyCoalesced)
        {
            var f=new UnpaidNativeMotionModel(unrelated:true);f.Begin();var m=f.Candidate;
            Assert.That(m.Refresh(out _),Is.True);m.Run(13);AssertUnpaidEligibilityHold(m,"unpaid-eligibility/route-capability-unavailable");
            if(alreadyCoalesced){f.Pose=P(-5.9f,4);f.Publish();Assert.That(m.Refresh(out _),Is.True);m.Run(14);}
            var held=m.Core.GetDecision(m.Key);var queries=m.Core.QueriesConsumed(m.Key);var native=D1Read(m.Core,f.Moving,"Leg");
            f.StaticTarget=change=="static-body";f.Pose=P(-5.8f,4);f.Publish();
            if(change=="parking")
            {
                var old=m.Snapshot;m.Snapshot=World(++f.Version,f.Version,old.Bodies.ToArray(),old.Parking.Concat(new[]{
                    new TrafficParkingFact(Key("eligibility-new-parking"),f.StaticLife,0,"pickup/new-parking",P(-9,-9),.4f)}).ToArray());m.Core.SetSnapshot(m.Snapshot);
            }
            var basis=m.RequestNow();var roles=basis.Requirements.ToList();
            if(change=="roles")roles.Add(new TrafficRouteRequirement("work-home",P(-4,6),P(-3,6),.8f));
            var request=new TrafficRequest(m.Key,11,m.Snapshot,Origin,change=="target"?P(-4):basis.Target,.4f,basis.ResourceId,
                requirements:roles,finiteSeconds:20,planPrimaryRoute:true);
            Assert.That(CfcReprepare(m.Core,held,request,out var pending),Is.True);
            Assert.That(pending,Is.Not.SameAs(held),"Only Native position samples may retain the old hold; "+change);
            Assert.That(pending.Reason,Is.EqualTo("unpaid-eligibility/spatial-change"));Assert.That(D1Read(m.Core,m.Key,"Queued"),Is.EqualTo(true));
            Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilitySpatialRefusal"),Is.Null,"No old cause may recapture this current full proof");
            var checkedNow=m.Run(15);Assert.That(checkedNow.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(m.Core.TryCommit(checkedNow),Is.False);
            if(change=="static-body")Assert.That(checkedNow.Blockers.Any(b=>b.Owner.ActorId=="eligibility-checkpoint-static"),Is.True);
            else Assert.That(m.Core.QueriesConsumed(m.Key),Is.GreaterThan(queries));
            Assert.That(D1Read(m.Core,f.Moving,"Leg"),Is.SameAs(native));Assert.That(D3ReadField(native,"Bound"),Is.EqualTo(true));
        }
