        private static void AssertUnpaidEligibilityHold(UnpaidEligibilityModel m,string reason)
        {
            var d=m.Core.GetDecision(m.Key);
            Assert.That(d.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"prepayment business eligibility is not Terminal or finite traffic WAIT");
            Assert.That(d.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));Assert.That(d.Reason,Is.EqualTo(reason));
            Assert.That(d.AcquiredSequence,Is.Zero);Assert.That(d.Permit,Is.Zero);Assert.That(m.Core.HasActiveGrant(m.Key),Is.False);
            Assert.That(m.Core.TryGetCommittedJourney(m.Key,out _),Is.False);Assert.That(m.Core.TryCommit(d),Is.False);
            Assert.That(D1Read(m.Core,m.Key,"UnpaidEligibilityHeld"),Is.EqualTo(true));
            Assert.That(D1Read(m.Core,m.Key,"FrozenOwners"),Is.Null);Assert.That(D1Read(m.Core,m.Key,"Leg"),Is.Null);
            Assert.That(D1Read(m.Core,m.Key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(m.Core,m.Key,"FiniteLimit"),Is.EqualTo(20f));
        }
        [Test] public void UnpaidEligibilityEndpointHoldRetainsOriginalSourceAndActuallyClears()
        {
