        [Test] public void UnpaidEligibilityCannotInstallAfterOriginalTerminalOrAcquiredPermission()
        {
            var failed=new UnpaidEligibilityModel(attach:false);var terminal=failed.Run();Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficUnpaidParkingEligibility");
            if(type==null)return; // This negative already holds on the baseline; positive controls fail naturally.
            var descriptor=Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                null,new object[]{failed.Key,failed.Life,failed.Queue,failed.Business,failed.Admission,(Func<bool>)(()=>true)},null);
            Assert.That(D3InvokeBool(failed.Core,"TrySetUnpaidParkingEligibility",terminal,descriptor),Is.False);
            failed.Clear();Assert.That(failed.Refresh(out _),Is.False);Assert.That(failed.Core.GetDecision(failed.Key),Is.SameAs(terminal));
            var granted=new UnpaidEligibilityModel();granted.Blocked=false;granted.Snapshot=granted.MakeWorld(2);granted.Core.SetSnapshot(granted.Snapshot);
            Assert.That(granted.Refresh(out _),Is.True);var permission=granted.Run(12);Assert.That(permission.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(granted.Core.TryCommit(permission),Is.True);
            Assert.That(D3InvokeBool(granted.Core,"TrySetUnpaidParkingEligibility",permission,granted.Descriptor),Is.False);
        }
