        // Analytic Core inputs + real CounterQueueService checkpoints; Native owns real Cashier/Actor proof.
        private sealed class CounterAdvanceReadinessModel
        {
            internal readonly TrafficIntentKey Incoming=new TrafficIntentKey("scene",1,"counter-follower","counter-advance",1,7,"counter-follower/assignment/1");
            internal readonly TrafficIntentKey HeadBody=Key("counter-head","counter-advance");
            internal readonly TrafficIntentKey HeadPickup=Key("counter-head","pickup-wait");
            internal readonly TrafficIntentKey FollowerBody=Key("counter-follower","body");
            internal readonly object HeadLife=new object(),FollowerLife=new object(),HeadBusiness=new object(),FollowerBusiness=new object();
            internal readonly object HeadAdmission=new object(),FollowerAdmission=new object();
            internal readonly CounterQueueService Queue;
            internal readonly ServiceTrafficCoordinator Core;
            internal TrafficWorldSnapshot Snapshot;
            internal readonly TrafficRequest Request;
            internal object Descriptor;internal bool Current=true;internal float WorkingSeconds=1;
            internal int Calls;
            internal CounterAdvanceReadinessModel(bool ownerBeforeIncoming=true,Vector3? candidate=null)
            {
                // Head already at slot0; a removed middle reservation leaves follower's real Advance gap.
                Queue=new CounterQueueService(new[]{P(0,1),candidate??P(0,0),P(0,-1)});
                Assert.That(Queue.TryJoin("counter-head"),Is.True);Assert.That(Queue.Complete("counter-head",1),Is.True);
                Assert.That(Queue.TryJoin("removed"),Is.True);Assert.That(Queue.Complete("removed",1),Is.True);
                Assert.That(Queue.TryJoin("counter-follower"),Is.True);Assert.That(Queue.Complete("counter-follower",1),Is.True);
                Assert.That(Queue.Remove("removed"),Is.True);
                Assert.That(Queue.TryCaptureAssignment("counter-head",out var head),Is.True);
                Assert.That(Queue.TryCaptureAssignment("counter-follower",out var follower),Is.True);
                Snapshot=World(actors:new[]{
                    new TrafficBodyFact(HeadBody,P(0,1),.45f,actorLife:HeadLife),
                    new TrafficBodyFact(FollowerBody,P(0,-1),.45f,actorLife:FollowerLife)},parking:new[]{
                    new TrafficParkingFact(HeadBody,Queue,Queue.Version,"counter/counter-head",P(0,1),.45f,.011f,HeadBusiness,HeadAdmission,head),
                    new TrafficParkingFact(FollowerBody,Queue,Queue.Version,"counter/counter-follower",P(0,-1),.45f,.011f,FollowerBusiness,FollowerAdmission,follower)});
                Core=Coordinator(Snapshot,query:(a,b)=>{Calls++;return new[]{a,b};},waitSeconds:10);
                if(ownerBeforeIncoming)CommitHeadParking();
                Request=new TrafficRequest(Incoming,1,Snapshot,P(0,-1),candidate??P(0,0),.45f,"counter/counter-follower",safetyMargin:.011f,planPrimaryRoute:true);
                Core.EvaluateParking(Request);
            }
            internal void CommitHeadParking()
            {
                // Exact future route intersects follower target; its physical Counter body remains elsewhere.
                var request=new TrafficRequest(HeadPickup,0,Snapshot,P(0,1),P(2,0),.45f,"pickup/counter-head",safetyMargin:.011f,planPrimaryRoute:true);
                Core.EvaluateParking(request);Core.ProcessReady(0);
                var prepared=Core.GetDecision(HeadPickup);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(Core.TryCommit(prepared),Is.True);Assert.That(Core.HasActiveGrant(HeadPickup),Is.True);
                Assert.That(Core.TryGetCommittedJourney(HeadPickup,out var source),Is.True);Assert.That(source,Is.SameAs(prepared));
            }
            internal object MakeDescriptor(TrafficIntentKey? key=null)
            {
                var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficCounterAdvanceReadiness");
                Assert.That(type,Is.Not.Null,"FEATURE: typed existing-Counter readiness is missing; unborn admission identity cannot substitute");
                return Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                    null,new object[]{key??Incoming,(Func<bool>)(()=>Current),(Func<TrafficIntentKey,float>)(owner=>owner.Equals(HeadPickup)?WorkingSeconds:0)},null);
            }
            internal bool Attach(object descriptor=null)
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod("TrySetCounterAdvanceReadiness",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That(method,Is.Not.Null,"FEATURE: existing Counter preparation requires its own readonly readiness port");
                Descriptor=descriptor??MakeDescriptor();return (bool)method.Invoke(Core,new[]{(object)Core.GetDecision(Incoming),Descriptor});
            }
            internal TrafficDecision Run(int frame=1){Core.ProcessReady(frame);return Core.GetDecision(Incoming);}
            internal void AssertHeld()
            {
                var d=Core.GetDecision(Incoming);Assert.That(d.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Assert.That(d.Reason,Is.EqualTo("counter-advance-working-readiness-held"));Assert.That(d.AcquiredSequence,Is.Zero);
                Assert.That(Core.HasActiveGrant(Incoming),Is.False);Assert.That(Core.TryGetCommittedJourney(Incoming,out _),Is.False);
                Assert.That((bool)D1Read(Core,Incoming,"Prepared"),Is.False);Assert.That((bool)D1Read(Core,Incoming,"Active"),Is.False);
                Assert.That((bool)D1Read(Core,Incoming,"Queued"),Is.True,"Original ready pump owns bounded rechecks; no parallel hold queue");
                Assert.That(D1Read(Core,Incoming,"FrozenOwners"),Is.Null,"Readiness creates no finite-WAIT dependency or authority");
                Assert.That((Vector3[])D1Read(Core,Incoming,"CurrentPath"),Is.Empty);Assert.That(Core.HasPendingWork,Is.True);
            }
            internal void CancelUnusedParking()
            {WorkingSeconds=0;Core.Retire(HeadPickup);} // Does not remove/move the real declared Counter body or claim.
        }

        [TestCase(true)][TestCase(false)]
        public void CounterAdvanceReadinessDefersBothOriginalBirthOrdersWithoutNewRightsOrQueries(bool predecessorFirst)
        {
            var f=new CounterAdvanceReadinessModel(predecessorFirst);Assert.That(f.Attach(),Is.True);
            if(!predecessorFirst)f.CommitHeadParking(); // follower is already submitted/queued before the actual owner commit.
            var before=f.Calls;var entry=D1Read(f.Core,f.Incoming,"Key");var first=D1Read(f.Core,f.Incoming,"FirstFrame");
            f.Run();f.AssertHeld();var sequence=f.Core.GetDecision(f.Incoming).RequestSequence;
            var consumed=f.Core.QueriesConsumed(f.Incoming);var remaining=(float)D1Read(f.Core,f.Incoming,"WaitRemaining");
            f.Core.Tick(.25f,false);for(var frame=2;frame<=4;frame++){f.Run(frame);f.AssertHeld();}
            Assert.That(f.Calls,Is.EqualTo(before),"No unchanged readiness polling may call Native");
            Assert.That(f.Core.QueriesConsumed(f.Incoming),Is.EqualTo(consumed));Assert.That(consumed,Is.Zero);
            Assert.That(D1Read(f.Core,f.Incoming,"FirstFrame"),Is.EqualTo(first));Assert.That(D1Read(f.Core,f.Incoming,"Key"),Is.EqualTo(entry));
            Assert.That(f.Core.GetDecision(f.Incoming).RequestSequence,Is.EqualTo(sequence));
            Assert.That((float)D1Read(f.Core,f.Incoming,"WaitRemaining"),Is.EqualTo(remaining-.25f).Within(.0001));
            f.CancelUnusedParking();Assert.That(f.Run(5).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Core.GetDecision(f.Incoming).RequestSequence,Is.EqualTo(sequence));Assert.That(D1Read(f.Core,f.Incoming,"FirstFrame"),Is.EqualTo(first));
        }
