                new TrafficParkingFact(f.FollowerBody,f.Queue,f.Queue.Version,"counter/counter-follower",P(0,-1),.45f,.011f,f.FollowerBusiness,f.FollowerAdmission,follower)});
            f.Core.SetSnapshot(f.Snapshot);
