            var port=typeof(ServiceTrafficCoordinator).GetMethod("TryReprepareCanonicalAnchor",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            var args=new object[]{prepared,refreshed,null};Assert.That((bool)port.Invoke(f.Core,args),Is.True);
            Assert.That(f.Core.GetDecision(f.Incoming).Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
