            Assert.That(D1Read(f.Core,f.Incoming,"FirstFrame"),Is.EqualTo(first));Assert.That(f.Core.GetDecision(f.Incoming).RequestSequence,Is.EqualTo(sequence));
            Assert.That(f.Core.QueriesConsumed(f.Incoming),Is.EqualTo(consumed));Assert.That(f.Core.HasActiveGrant(f.Incoming),Is.False);
        }
        // Public analytic traffic inputs; only reflection calls the internal readonly producer port.
        // 真实业务身份由Native覆盖；模型不私改Entry、身体、许可或预算。
        // A not-yet-born opportunity cannot become a finite waiter that constrains an already real actor.
        // 已有角色继续走原流程；未出生来客仅等待业务资格，没有Native/容量/交接权利。
        private sealed class UnbornSpaceEligibilityModel
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("prospective","counter-admission");
            internal readonly TrafficIntentKey Owner=ServiceTrafficCoordinatorTests.Key("real-queue-owner","counter-arrival",7);
            internal readonly object Life=new object();internal readonly ServiceTrafficCoordinator Core;
            internal TrafficWorldSnapshot WorldNow;internal bool Occupied=true,Current=true,NoPath;internal int Calls;
            internal UnbornSpaceEligibilityModel(bool attach=true,string queryFault=null,int budget=32)
            {
                WorldNow=Snapshot(1);Core=Coordinator(WorldNow,waitSeconds:2,intentBudget:budget,query:(from,to)=>
                {Calls++;if(queryFault=="throw")throw new InvalidOperationException("Modeled original provider fault");if(queryFault=="empty")return Array.Empty<Vector3>();
                    if(queryFault=="nonfinite")return new[]{from,new Vector3(float.NaN,0,0)};return NoPath?null:new[]{from,to};});
                Core.EvaluateParking(Request());
                if(attach)
                {
                    var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficAdmissionReadiness");
                    var descriptor=Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                        null,new object[]{Key,(Func<bool>)(()=>Current),(Func<IReadOnlyList<TrafficIntentKey>>)(()=>Array.Empty<TrafficIntentKey>())},null);
                    Assert.That(D3InvokeBool(Core,"TrySetAdmissionReadiness",Core.GetDecision(Key),descriptor),Is.True);
                }
            }
            internal TrafficWorldSnapshot Snapshot(int version)=>ServiceTrafficCoordinatorTests.World(version,version,Occupied?
                new[]{new TrafficBodyFact(Owner,P(2),.4f,independentlyProgressing:true,remainingSeconds:20,actorLife:Life)}:Array.Empty<TrafficBodyFact>());
            internal TrafficRequest Request()=>new TrafficRequest(Key,1,WorldNow,Origin,P(2),.4f,"counter/prospective",planPrimaryRoute:true);
            internal TrafficDecision Run(int frame=1){Core.ProcessReady(frame);return Core.GetDecision(Key);}
            internal bool Refresh(int version,out TrafficDecision next)
            {WorldNow=Snapshot(version);Core.SetSnapshot(WorldNow);return CfcReprepare(Core,Core.GetDecision(Key),Request(),out next);}
        }
        [Test] public void UnbornSpaceIneligibilityDoesNotCreateFiniteWaitDebtOrBurnQueries()
        {
            var f=new UnbornSpaceEligibilityModel();var held=f.Run();var queries=f.Core.QueriesConsumed(f.Key);var sequence=held.RequestSequence;
            Assert.That(held.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"RED: unborn business eligibility must not become a finite WAIT on the real queue actor");
            Assert.That(D1Read(f.Core,f.Key,"FrozenOwners"),Is.Null);Assert.That(held.Blockers.All(b=>b.Owner.Equals(f.Owner)),Is.True);
            Assert.That(f.Core.HasActiveGrant(f.Key),Is.False);Assert.That(f.Core.TryCommit(held),Is.False);Assert.That(held.AcquiredSequence,Is.Zero);
            var age=D1Read(f.Core,f.Key,"FirstFrame");var entry=((System.Collections.IDictionary)D3ReadField(f.Core,"entries"))[f.Key];
            for(var frame=2;frame<=42;frame++){Assert.That(f.Refresh(frame,out _),Is.True);f.Core.Tick(1,false);f.Run(frame);}
            held=f.Core.GetDecision(f.Key);Assert.That(held.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));Assert.That(f.Core.QueriesConsumed(f.Key),Is.EqualTo(queries));
            Assert.That(D1Read(f.Core,f.Key,"FrozenOwners"),Is.Null);Assert.That((float)D1Read(f.Core,f.Key,"WaitRemaining"),Is.Zero);
            f.Occupied=false;Assert.That(f.Refresh(43,out _),Is.True);var ready=f.Run(43);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);Assert.That(f.Core.QueriesConsumed(f.Key),Is.GreaterThan(queries));
            Assert.That(D1Read(f.Core,f.Key,"FirstFrame"),Is.EqualTo(age));Assert.That(ready.RequestSequence,Is.EqualTo(sequence));
            Assert.That(((System.Collections.IDictionary)D3ReadField(f.Core,"entries"))[f.Key],Is.SameAs(entry));Assert.That(f.Core.TryCommit(ready),Is.True);
        }
