        // Add inside the existing ServiceTrafficCoordinatorTests class. Uses the existing HandoffFixture;
        // only normal Core operations create/commit/bind/arrive the owner. Reflection below is read-only.
        // 真实已Bound owner完成Arrived交接；不写Entry、permit、Native stamp或角色状态。
        [Test]
        public void UnbornBusinessHoldCannotJoinActualBoundOwnerHandoffOrShortenItsOriginalDeadline()
        {
            var f=new HandoffFixture();var core=f.Coordinator;
            // Remove the fixture's separate genuine waiter via its real lifecycle operation. This case
            // isolates the unborn opportunity; the owner retains its already committed/bound leg.
            core.Retire(f.Waiter);
            Assert.That(core.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            Assert.That(f.ReadLeg(f.Owner,"Committed"),Is.EqualTo(true));
            Assert.That(f.ReadLeg(f.Owner,"Bound"),Is.EqualTo(true));
            Assert.That(f.ReadLeg(f.Owner,"Completed"),Is.EqualTo(false));
            Assert.That(f.ReadLeg(f.Owner,"Stamp"),Is.EqualTo(f.Stamp));
            Assert.That(f.Read(f.Owner,"JourneyPermit"),Is.SameAs(f.Source));

            var incoming=Key("unborn-real-handoff-opportunity","counter-admission",30);
            var request=new TrafficRequest(incoming,f.Frame,f.World,P(2,-3),f.End,.4f,
                "counter/"+incoming.ActorId,finiteSeconds:2,planPrimaryRoute:true);
            core.EvaluateParking(request);
            var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficAdmissionReadiness");
            Assert.That(type,Is.Not.Null);
            var descriptor=Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                null,new object[]{incoming,(Func<bool>)(()=>true),(Func<IReadOnlyList<TrafficIntentKey>>)(()=>Array.Empty<TrafficIntentKey>())},null);
            Assert.That(D3InvokeBool(core,"TrySetAdmissionReadiness",core.GetDecision(incoming),descriptor),Is.True);
            core.ProcessReady(f.Frame++);var held=core.GetDecision(incoming);
            Assert.That(held.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(held.Reason,Is.EqualTo("admission-eligibility/endpoint-occupied"));
            Assert.That(held.AcquiredSequence,Is.Zero);Assert.That(core.HasActiveGrant(incoming),Is.False);
            Assert.That(D1Read(core,incoming,"FrozenOwners"),Is.Null);
            Assert.That(D1Read(core,incoming,"FrozenResources"),Is.Null);
            Assert.That(D1Read(core,incoming,"AdmissionWaitStarted"),Is.EqualTo(false));
            var queries=core.QueriesConsumed(incoming);var age=D1Read(core,incoming,"FirstFrame");
            var sequence=held.RequestSequence;core.Tick(1,false);
            Assert.That(core.GetDecision(incoming),Is.SameAs(held));
            Assert.That(D1Read(core,incoming,"WaitRemaining"),Is.EqualTo(0f));

            // Begin uses actual PrepareLeg/TryCommit/Bind established by HandoffFixture, then the
            // exact stamped Arrived + canonical receipt through CompleteLegAndBeginHandoff.
            var handle=f.Begin();Assert.That(handle,Is.Not.Null);
            var state=f.Read(f.Owner,"PendingHandoff");
            var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");
            var incomingEntry=((System.Collections.IDictionary)D3ReadField(core,"entries"))[incoming];
            Assert.That(dependencies.Contains(incomingEntry),Is.False);
            Assert.That(dependencies.Count,Is.Zero,"Neither retired historical waiter nor unborn business hold owns a dependency");
            Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(8f),
                "Owner keeps its original 8s transaction deadline; unborn 2s opportunity cannot cap it to 1s");
            Assert.That(f.ReadLeg(f.Owner,"Committed"),Is.EqualTo(true));
            Assert.That(f.ReadLeg(f.Owner,"Bound"),Is.EqualTo(true));
            Assert.That(f.ReadLeg(f.Owner,"Completed"),Is.EqualTo(true));
            Assert.That(f.ReadLeg(f.Owner,"Stamp"),Is.EqualTo(f.Stamp));
            Assert.That(f.Read(f.Owner,"JourneyPermit"),Is.SameAs(f.Source));
            Assert.That(core.QueriesConsumed(incoming),Is.EqualTo(queries));
            Assert.That(D1Read(core,incoming,"FirstFrame"),Is.EqualTo(age));
            Assert.That(core.GetDecision(incoming).RequestSequence,Is.EqualTo(sequence));
            Assert.That(core.TryCommit(core.GetDecision(incoming)),Is.False);
        }

        private sealed class AdmissionExitReadinessModel
        {
            internal readonly TrafficIntentKey Incoming=Key("unborn", "counter-admission"), Leaving=Key("leaving", "actual-exit");
            internal readonly object Life=new object();internal readonly ServiceTrafficCoordinator Core;
            internal TrafficWorldSnapshot Snapshot;internal TrafficRequest Request;internal bool Pending=true,Current=true;
            internal int Calls;internal object Descriptor;
            internal AdmissionExitReadinessModel(bool conflict=true,bool born=false)
            {
                var bodies=new List<TrafficBodyFact>{new TrafficBodyFact(Leaving,P(8,8),.45f,actorLife:Life)};
                if(born)bodies.Add(new TrafficBodyFact(Incoming,new Vector3(-.5f,0,-3.35f),.45f,actorLife:new object()));
                Snapshot=World(actors:bodies.ToArray());Core=Coordinator(Snapshot,query:(a,b)=>{Calls++;return new[]{a,b};},waitSeconds:10);
                Core.EvaluateMovement(new TrafficRequest(Leaving,100,Snapshot,P(8,8),conflict?new Vector3(.5f,0,-3.35f):P(12,12),.45f,"pickup/leaving",safetyMargin:.011f));
                Request=new TrafficRequest(Incoming,1,Snapshot,new Vector3(-.5f,0,-3.35f),new Vector3(.2397f,0,-2.2397f),.45f,
                    "counter/unborn",safetyMargin:.011f,planPrimaryRoute:true);
                Core.EvaluateParking(Request);
            }
            internal object MakeDescriptor(TrafficIntentKey? key=null,Func<bool> current=null,Func<IReadOnlyList<TrafficIntentKey>> read=null)
            {
                var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficAdmissionReadiness");
                Assert.That(type,Is.Not.Null,"FEATURE: narrowly typed unborn readiness descriptor is missing");
                return Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                    null,new object[]{key??Incoming,current??(()=>Current),read??(Func<IReadOnlyList<TrafficIntentKey>>)(()=>Pending?new[]{Leaving}:Array.Empty<TrafficIntentKey>())},null);
            }
            internal bool Attach(object descriptor=null)
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod("TrySetAdmissionReadiness",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That(method,Is.Not.Null,"FEATURE: original unborn proposal has no readiness binding port");
                Descriptor=descriptor??MakeDescriptor();return (bool)method.Invoke(Core,new[]{(object)Core.GetDecision(Incoming),Descriptor});
            }
            internal TrafficDecision Run(int frame=1){Core.ProcessReady(frame);return Core.GetDecision(Incoming);}
            internal void AssertHeld()
            {
                var d=Core.GetDecision(Incoming);Assert.That(d.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Assert.That(d.Reason,Is.EqualTo("admission-exit-readiness-held"));Assert.That(d.AcquiredSequence,Is.Zero);
                Assert.That((bool)D1Read(Core,Incoming,"Prepared"),Is.False);Assert.That(Core.HasActiveGrant(Incoming),Is.False);
                Assert.That((Vector3[])D1Read(Core,Incoming,"CurrentPath"),Is.Empty);Assert.That(Core.HasPendingWork,Is.True);
            }
            internal void Release()
            {
                Pending=false;Core.Retire(Leaving);Snapshot=World(2,2);Core.SetSnapshot(Snapshot);
                Request=new TrafficRequest(Incoming,1,Snapshot,Request.Start,Request.Target,.45f,"counter/unborn",safetyMargin:.011f,planPrimaryRoute:true);
                var method=typeof(ServiceTrafficCoordinator).GetMethod("TryReprepareCanonicalAnchor",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                var args=new object[]{Core.GetDecision(Incoming),Request,null};Assert.That((bool)method.Invoke(Core,args),Is.True);
            }
        }
        [Test] public void AdmissionReadinessHoldsOnlyOriginalUnbornProposalAndResumesWithoutRightsOrBudgetReset()
        {
            var f=new AdmissionExitReadinessModel();Assert.That(f.Attach(),Is.True);f.Run();f.AssertHeld();
            var seq=f.Core.GetDecision(f.Incoming).RequestSequence;var queries=f.Core.QueriesConsumed(f.Incoming);var calls=f.Calls;
            Assert.That(D1Read(f.Core,f.Incoming,"FrozenOwners"),Is.Null,"readiness does not invent a WAIT dependency");
            f.Core.Tick(2,false);for(var n=2;n<8;n++)f.Run(n);f.AssertHeld();
            Assert.That(f.Calls,Is.EqualTo(calls),"held producer does no planner polling");Assert.That((float)D1Read(f.Core,f.Incoming,"WaitRemaining"),Is.EqualTo(8).Within(.0001));
            f.Release();var granted=f.Run(8);Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(granted.RequestSequence,Is.EqualTo(seq));Assert.That(f.Core.QueriesConsumed(f.Incoming),Is.GreaterThanOrEqualTo(queries));
            Assert.That((float)D1Read(f.Core,f.Incoming,"WaitRemaining"),Is.EqualTo(8).Within(.0001));
        }
