        [Test]
        public void AdmissionReadinessHoldsBeforeWaitingOnAnAlreadyBoundExitCurrentLeg()
        {
            // Public Core operations establish the current Native authority; no Entry fields are written.
            // 先真实Commit/Bind离店当前腿；未出生候选必须先进入readiness hold，不能先安装新的WAIT依赖。
            var leaving=Key("readiness-bound-exit","actual-exit");var incoming=Key("readiness-bound-incoming","counter-admission");
            var life=new object();var queries=0;var goal=P(4);var start=P(3.5f,-2);var target=P(3.5f,2);
            var world=World(actors:new[]{new TrafficBodyFact(leaving,Origin,.45f,actorLife:life)});
            var core=Coordinator(world,query:(from,to)=>{queries++;return new[]{from,to};},waitSeconds:10);
            var source=Grant(core,new TrafficRequest(leaving,1,world,Origin,goal,.45f,"pickup/bound-exit",safetyMargin:.011f));
            Assert.That(core.PrepareLeg(source,"pickup/bound-exit",0,life,1,world,Origin,.08f,2).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            core.ProcessReady(2);var strict=core.GetDecision(leaving);
            Assert.That(strict.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(core.TryCommit(strict),Is.True);
            Assert.That(core.BindLeg(leaving,life,new TrafficNativeStamp(7701,1)),Is.True);
            Assert.That(core.HasActiveGrant(leaving),Is.True);
            var current=(Vector3[])D1Read(core,leaving,"CurrentPath");
            Assert.That(CustomerRoutePlanner.IsClear(current,new[]{target},.911f),Is.True,
                "PREMISE: the new parking endpoint does not itself trigger the earlier endpoint guard");
            Assert.That(CustomerRoutePlanner.IsClear(new[]{start,target},new[]{goal},.911f),Is.False,
                "PREMISE: the actual admission first leg crosses the fixed exit endpoint clearance");
            core.EvaluateParking(new TrafficRequest(incoming,3,world,start,target,.45f,"counter/bound-incoming",
                safetyMargin:.011f,planPrimaryRoute:true));
            var type=typeof(ServiceTrafficCoordinator).Assembly.GetType("AnimalCafe.Navigation.TrafficAdmissionReadiness");
            Assert.That(type,Is.Not.Null);
            var descriptor=Activator.CreateInstance(type,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,
                null,new object[]{incoming,(Func<bool>)(()=>true),(Func<IReadOnlyList<TrafficIntentKey>>)(()=>new[]{leaving})},null);
            Assert.That(D3InvokeBool(core,"TrySetAdmissionReadiness",core.GetDecision(incoming),descriptor),Is.True);
            core.ProcessReady(3);var held=core.GetDecision(incoming);
            Assert.That(held.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),
                "FEATURE RED: readiness must hold before SelectedPathBlockers installs an ordinary WAIT on the bound exit");
            Assert.That(held.Reason,Is.EqualTo("admission-exit-readiness-held"));Assert.That(held.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(core,incoming,"FrozenOwners"),Is.Null);Assert.That(D1Read(core,incoming,"FrozenResources"),Is.Null);
            Assert.That(D1Read(core,incoming,"Prepared"),Is.False);Assert.That(core.HasActiveGrant(incoming),Is.False);
            var beforeQueries=queries;core.Tick(.25f,false);core.ProcessReady(4);
            Assert.That(queries,Is.EqualTo(beforeQueries),"A held original first leg is checked without another planning query");
            Assert.That(D1Read(core,incoming,"WaitRemaining"),Is.EqualTo(9.75f));
        }

