        // Analytic open-plane/narrow-line Core models; the real Native RED is separately recorded as 4E5ADA...
        // 只用公开Core输入/操作；不伪造真实Native回执，不写Entry或任务状态。
        private sealed class FiniteBusinessGeometryModel
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("detour-waiter");
            internal readonly TrafficIntentKey Worker=ServiceTrafficCoordinatorTests.Key("detour-worker","body");
            internal readonly object Actor=new object(),WorkerLife=new object();
            internal readonly ServiceTrafficCoordinator Core;
            internal TrafficWorldSnapshot World;
            internal readonly TrafficRequest Request;
            internal int Calls;
            internal Action<int> DuringQuery;
            internal FiniteBusinessGeometryModel(int frameBudget=128,int intentBudget=16384,bool narrow=false,bool endpoint=false,bool disabled=false,bool submit=true)
            {
                World=Snapshot(1,8,P(endpoint?4:2),WorkerLife,Worker,disabled);
                Core=Coordinator(World,frameBudget,intentBudget,(a,b)=>
                {
                    Calls++;DuringQuery?.Invoke(Calls);
                    return !narrow || (a.z.Equals(0f) && b.z.Equals(0f))?new[]{a,b}:null;
                });
                Request=ServiceTrafficCoordinatorTests.Request(Key,Origin,P(4),World);
                if(submit)Core.EvaluateMovement(Request);
            }
            internal TrafficWorldSnapshot Snapshot(long version,float seconds,Vector3 position,object life,TrafficIntentKey owner,bool disabled=false)
                =>ServiceTrafficCoordinatorTests.World(1,version,actors:new[]{
                    new TrafficBodyFact(Key,Origin,.4f,actorLife:Actor),
                    new TrafficBodyFact(owner,position,.4f,!disabled,true,seconds,actorLife:life,actorActive:true)});
            internal TrafficDecision Finish(int start=1)
            {
                for(var frame=start;frame<start+512;frame++)
                {
                    Core.ProcessReady(frame);var result=Core.GetDecision(Key);
                    if(result.Kind!=TrafficDecisionKind.DeferredByBudget)return result;
                }
                Assert.Fail("MODELED finite query search did not finish within 512 original public batches");return null;
            }
            internal void AssertClear(TrafficDecision result)
            {
                var path=result.ProofRoutes.Single(p=>p.ResourceId==Request.ResourceId).ExpandedPath.Concat(new[]{Request.Target}).ToArray();
                Assert.That(CustomerRoutePlanner.IsClear(path,World.Bodies.Where(b=>b.Owner.ActorId!=Key.ActorId).Select(b=>b.Position).ToArray(),.8f),Is.True);
            }
        }
        // Public analytic graph models, not Main Native receipts; only public APIs mutate the lifecycle.
        // 固定路径拓扑与身体snapshot分离；只读Jobs核对缓存，不私改Entry。
        private sealed class SelectedParkingGuardModel
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("home-guard-candidate");
            internal readonly TrafficIntentKey Worker=ServiceTrafficCoordinatorTests.Key("home-guard-worker","body");
            internal readonly object ActorLife=new object(),WorkerLife=new object();
            internal readonly ServiceTrafficCoordinator Core;internal readonly TrafficRequest Original;
            internal readonly TrafficRouteRequirement[] Requirements;
            internal TrafficWorldSnapshot World;internal Vector3 BodyPosition;
            internal int Calls,HomeQueries,LastFrame=10;internal readonly int[] CapabilityCalls=new int[2];
            internal SelectedParkingGuardModel(int frameBudget=128,int intentBudget=16384,bool noAlternative=false,bool endpoint=false,
                string fault=null,int faultQuery=2,bool disabled=false,float homeClearance=.8f,bool primary=true)
            {
                BodyPosition=endpoint?P(4):homeClearance>.8f?P(2,1):P(2,2);World=Snapshot(1,8,BodyPosition,WorkerLife,Worker,disabled);
                Requirements=new[]{new TrafficRouteRequirement("home-guard-cap-one",P(10,1),P(12,1),.8f),
                    new TrafficRouteRequirement("home-guard-cap-two",P(10,3),P(12,3),.8f),
                    new TrafficRouteRequirement("selected-home",P(4),Origin,homeClearance,obstacles:disabled?new[]{BodyPosition}:null,
                        selectedJourney:true,avoidProposedParking:false)};
                Core=Coordinator(World,frameBudget,intentBudget,(a,b)=>
                {
                    Calls++;for(var i=0;i<2;i++)if(a.Equals(Requirements[i].Start) && b.Equals(Requirements[i].Goal))CapabilityCalls[i]++;
                    if(a.Equals(P(4)) && b.Equals(Origin) && ++HomeQueries==faultQuery && fault!=null)
                    {if(fault=="throw")throw new InvalidOperationException("Modeled selected-home query fault");return new[]{a,new Vector3(float.NaN,0,0),b};}
                    if(a.Equals(Origin) && b.Equals(P(4)) || Requirements.Take(2).Any(q=>a.Equals(q.Start) && b.Equals(q.Goal)))return new[]{a,b};
                    if(homeClearance>.8f)return new[]{a,b};
                    return noAlternative || a.Equals(P(4)) && b.Equals(Origin)?new[]{a,P(2,2),b}:new[]{a,b};
                });
                Original=new TrafficRequest(Key,11,World,Origin,P(4),.4f,"home-guard-delivery",requirements:Requirements,planPrimaryRoute:primary);
                Core.EvaluateParking(Original);
            }
            internal TrafficWorldSnapshot Snapshot(long version,float seconds,Vector3 point,object life,TrafficIntentKey owner,bool disabled=false)
                =>ServiceTrafficCoordinatorTests.World(1,version,actors:new[]{new TrafficBodyFact(Key,Origin,.4f,actorLife:ActorLife),
                    new TrafficBodyFact(owner,point,.4f,!disabled,true,seconds,actorLife:life,actorActive:true)});
            internal TrafficRequest FreshRequest()=>new TrafficRequest(Key,11,World,Original.Start,Original.Target,Original.Radius,
                Original.ResourceId,requirements:Requirements,planPrimaryRoute:Original.PlanPrimaryRoute);
            internal TrafficDecision Finish()
            {
                for(var count=0;count<512;count++)
                {Core.ProcessReady(++LastFrame);var d=Core.GetDecision(Key);if(d.Kind!=TrafficDecisionKind.DeferredByBudget)return d;}
                Assert.Fail("MODELED selected-home bounded search did not finish");return null;
            }
            internal object PendingHome()
            {
                for(var count=0;count<20;count++)
                {
                    Core.ProcessReady(++LastFrame);var d=Core.GetDecision(Key);
                    if(d.Kind==TrafficDecisionKind.DeferredByBudget && Calls==4 && HomeQueries==1 && (int)D1Read(Core,Key,"JobIndex")==3)
                    {Assert.That(CapabilityCalls,Is.EqualTo(new[]{1,1}));return ((System.Collections.IList)D1Read(Core,Key,"Jobs"))[3];}
                    if(d.Kind!=TrafficDecisionKind.DeferredByBudget)break;
                }
                Assert.Fail("FEATURE: home-only child must be pending after the same base/capability jobs");return null;
            }
            internal void AssertHomeClear(TrafficDecision d)
            {
                var home=d.ProofRoutes.Single(p=>p.ResourceId=="selected-home");
                Assert.That(CustomerRoutePlanner.IsClear(new[]{P(4)}.Concat(home.ExpandedPath).Concat(new[]{Origin}).ToArray(),
                    new[]{BodyPosition},Requirements[2].Clearance),Is.True);
                Assert.That((Vector3[])D1Read(Core,Key,"CurrentPath"),Is.EqualTo(d.ProofRoutes[0].ExpandedPath));
                Assert.That(Core.HasActiveGrant(Key),Is.False);
            }
        }
        private static bool HoldProducerPreview(ServiceTrafficCoordinator core,TrafficDecision expected)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryHoldCanonicalAnchorPreparation",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"TEST-FIRST inert port must exist; a missing API is not the intended RED");
            return (bool)method.Invoke(core,new object[]{expected});
        }
        private sealed class ProducerPreviewHoldModel
        {
            internal readonly TrafficIntentKey Waiter=Key("preview-waiter","pickup-wait"),A=Key("queue-a","paid-move"),B=Key("later-staff","selected-delivery");
            internal readonly object WaiterLife=new object(),ALife=new object(),BLife=new object(),Business=new object(),Obligation=new object();
            internal readonly CounterQueueService Counter=new CounterQueueService(new[]{Origin});
            internal readonly PickupQueueService Pickup=new PickupQueueService(new[]{P(0,4),P(2,4),P(4,4)},new[]{P(6,4)});
            internal readonly ServiceTrafficCoordinator Core;internal readonly TrafficRequest Original;
            internal readonly PickupQueueService.PreparedMutation OriginalPreview;
            internal TrafficWorldSnapshot World;internal Vector3 APosition;internal long Version=1;
            internal int Calls;internal TrafficDecision Waiting;
            internal ProducerPreviewHoldModel(bool block=true)
            {
                Assert.That(Counter.TryJoin(Waiter.ActorId),Is.True);var counter=Counter.Snapshot.Single();Assert.That(Counter.Complete(Waiter.ActorId,counter.Generation),Is.True);
                Assert.That(Pickup.TryReserve("older-queue",out _),Is.True);Assert.That(Pickup.TryReserve(A.ActorId,out _),Is.True);
                Assert.That(Pickup.TryBeginTransfer(A.ActorId,out _),Is.True);APosition=block?P(4,4):P(2,4);World=Snapshot();
                Core=Coordinator(World,query:(a,b)=>{Calls++;return a.Equals(P(6,3)) && b.Equals(P(6,5))?new[]{a,P(4,4),b}:new[]{a,b};});
                Grant(Core,Request(A,APosition,P(2,4),World,frame:1,resource:"queue-a-route"));
                Assert.That(Pickup.TryPrepareMutation(PickupQueueService.MutationKind.Reserve,Waiter.ActorId,Pickup.Version,out var preview),Is.True);
                OriginalPreview=preview;Original=new TrafficRequest(Waiter,2,World,Origin,preview.Assignment.Position,.4f,"pickup/"+Waiter.ActorId,planPrimaryRoute:true);
                Core.EvaluateParking(Original);Core.ProcessReady(2);Waiting=Core.GetDecision(Waiter);
                Assert.That(Waiting.Kind,Is.EqualTo(block?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.Granted),"MODEL original public source premise");
                if(block){Assert.That(Waiting.Blockers.Count,Is.GreaterThan(0));Assert.That(Waiting.Blockers.All(blocker=>blocker.Owner.Equals(A)),Is.True);Assert.That(Waiting.Blockers.Any(blocker=>blocker.ResourceId=="body"),Is.True);}
            }
            internal TrafficWorldSnapshot Snapshot(object ownLife=null,bool omitClaim=false,bool unknownClaim=false)
            {
                var parking=new List<TrafficParkingFact>();
                if(!omitClaim){Assert.That(Counter.TryCaptureAssignment(Waiter.ActorId,out var own),Is.True);parking.Add(new TrafficParkingFact(Waiter,Counter,Counter.Version,
                    "counter/"+Waiter.ActorId,own.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:unknownClaim?null:own));}
                foreach(var id in new[]{"older-queue",A.ActorId,"replacement"})if(Pickup.TryCaptureReservation(id,out var held))parking.Add(new TrafficParkingFact(
                    id==A.ActorId?A:Key(id,"queue-parking"),Pickup,Pickup.Version,"pickup/"+id,held.Assignment.Position,.4f,semanticCheckpoint:held));
                return new TrafficWorldSnapshot(Version,Version,new[]{new TrafficBodyFact(Waiter,Origin,.4f,actorLife:ownLife??WaiterLife),
                    new TrafficBodyFact(A,APosition,.4f,true,true,13,actorLife:ALife),new TrafficBodyFact(B,P(6,5),.4f,actorLife:BLife)},parking);
            }
            internal void MakePreviewUnavailable()
            {
                APosition=P(2,4);Assert.That(Pickup.TryGetReservation(A.ActorId,out var arrived),Is.True);Assert.That(Pickup.MarkArrived(A.ActorId,arrived.Generation),Is.True);
                Assert.That(Pickup.Remove("older-queue"),Is.True);Assert.That(Pickup.TryGetNextAdvance(out var advancing),Is.True);Assert.That(advancing.VisitId,Is.EqualTo(A.ActorId));
                Assert.That(Pickup.CanReserve,Is.False);Assert.That(Pickup.TryPrepareMutation(PickupQueueService.MutationKind.Reserve,Waiter.ActorId,Pickup.Version,out _),Is.False);
                World=SnapshotAfterChange();Core.SetSnapshot(World);Core.Retire(A);
                Assert.That(Core.GetDecision(Waiter),Is.SameAs(Waiting));Assert.That(D1Read(Core,Waiter,"Queued"),Is.True,"Real owner release queued the original waiter");
            }
            internal TrafficWorldSnapshot SnapshotAfterChange(){Version++;return Snapshot();}
            internal TrafficDecision CommitLaterSelectedHome()
            {
                var home=new[]{new TrafficRouteRequirement("selected-home",P(6,3),P(6,5),.8f,selectedJourney:true,avoidProposedParking:false)};
                var source=Grant(Core,Request(B,P(6,5),P(6,3),World,frame:3,resource:"staff-primary",requirements:home));
                Assert.That(source.RequestSequence,Is.GreaterThan(Waiting.RequestSequence));Assert.That(source.ProofRoutes.Single(p=>p.ResourceId=="selected-home").ExpandedPath.Contains(P(4,4)),Is.True);
                return source;
            }
            internal PickupQueueService.PreparedMutation RestorePreview(bool identical=false)
            {
                APosition=P(0,4);Assert.That(Pickup.TryGetReservation(A.ActorId,out var current),Is.True);Assert.That(Pickup.MarkArrived(A.ActorId,current.Generation),Is.True);
                if(identical)Assert.That(Pickup.TryReserve("replacement",out _),Is.True);
                World=SnapshotAfterChange();Core.SetSnapshot(World);
                Assert.That(Pickup.CanReserve,Is.True);Assert.That(Pickup.TryPrepareMutation(PickupQueueService.MutationKind.Reserve,Waiter.ActorId,Pickup.Version,out var preview),Is.True);return preview;
            }
            internal TrafficRequest Fresh(PickupQueueService.PreparedMutation preview)=>new TrafficRequest(Waiter,2,World,Origin,preview.Assignment.Position,.4f,Original.ResourceId,planPrimaryRoute:true);
        }
        [Test] public void MissingRealReservePreviewHoldsOnlyOriginalWaitingUntilFreshTargetProofReturns()
        {
