            var frozen=D1Read(f.Core,f.Waiter,"FrozenOwners");var resources=D1Read(f.Core,f.Waiter,"FrozenResources");var spent=f.Core.QueriesConsumed(f.Waiter);var budget=(float)D1Read(f.Core,f.Waiter,"WaitRemaining");
