            Assert.That(f.Core.GetDecision(f.Waiter),Is.SameAs(waiting));Assert.That(D1Read(f.Core,f.Waiter,"Queued"),Is.False);
            Assert.That(f.Core.QueriesConsumed(f.Waiter),Is.EqualTo(spent));Assert.That(D1Read(f.Core,f.Waiter,"WaitRemaining"),Is.EqualTo(budget-1));
            Assert.That(D1Read(f.Core,f.Waiter,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,f.Waiter,"FrozenResources"),Is.SameAs(resources));
            var preview=f.RestorePreview();Assert.That(preview.Assignment.Position,Is.EqualTo(P(2,4)));Assert.That(preview.Assignment.Position,Is.Not.EqualTo(f.Original.Target));
            Assert.That(CfcReprepare(f.Core,waiting,f.Fresh(preview),out var queued),Is.True);Assert.That(queued.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(D1Read(f.Core,f.Waiter,"Queued"),Is.True);f.Core.ProcessReady(5);var prepared=f.Core.GetDecision(f.Waiter);
            Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(prepared.RequestSequence,Is.EqualTo(waiting.RequestSequence));Assert.That(D1Read(f.Core,f.Waiter,"FirstFrame"),Is.EqualTo(2));
            Assert.That(D1Read(f.Core,f.Waiter,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,f.Waiter,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(f.Core,f.Waiter,"WaitRemaining"),Is.EqualTo(budget-1));Assert.That(f.Core.GetDecision(f.B),Is.SameAs(later));
            Assert.That(CustomerRoutePlanner.IsClear(prepared.ProofRoutes.Single().ExpandedPath,new[]{f.APosition},.8f),Is.True);Assert.That(f.Core.HasActiveGrant(f.Waiter),Is.False);
        }
