        [Test] public void UnacquiredParkingPrefersBodyClearOutwardAndSelectedHomeWithoutReroutingCapabilities()
            =>ObserveUnacquiredParkingSelectedRoundTrip(false);
        [Test] public void UnacquiredParkingWithClearPrimaryStillPrefersBodyClearSelectedHome()
            =>ObserveUnacquiredParkingSelectedRoundTrip(true);
        private void ObserveUnacquiredParkingSelectedRoundTrip(bool homeOnly)
        {
            // Explicit analytic complete-path provider; this is a public Core model, not proof of Main Native topology.
            // 两个nonselected能力不是可移动路线；只验证同一未获权proposal已选的outward和home。
            var key=Key("parking-roundtrip");var worker=Key("parking-working-body","body");
            var work=Origin;var service=P(4);var occupied=homeOnly?P(2,2):P(2);var capCalls=new int[2];var calls=0;
            IReadOnlyList<Vector3> Geometry(Vector3 a,Vector3 b)
                =>homeOnly && a.Equals(service) && b.Equals(work)?new[]{a,occupied,b}:new[]{a,b};
            Vector3[] IndependentBodyClearWitness(Vector3 from,Vector3 to)
            {
                var waypoints=new CustomerRoutePlanner().Build(from,to,new[]{occupied},.8f,Geometry);
                Assert.That(waypoints,Is.Not.Null,"MODELED premise: a complete independent body-aware alternative must exist");
                Assert.That(waypoints.Count,Is.LessThanOrEqualTo(24));
                var path=new List<Vector3>{from};var previous=from;
                foreach(var target in waypoints){var leg=Geometry(previous,target);Assert.That(leg,Is.Not.Null.And.Not.Empty);path.AddRange(leg);previous=leg[leg.Count-1];}
                path.Add(to);Assert.That(CustomerRoutePlanner.IsClear(path,new[]{occupied},.8f),Is.True,"MODELED full polyline includes all connectors and exact endpoints");
                return path.ToArray();
            }
            Assert.That(CustomerRoutePlanner.IsClear(Geometry(work,service),new[]{occupied},.8f),Is.EqualTo(homeOnly));
            Assert.That(CustomerRoutePlanner.IsClear(Geometry(service,work),new[]{occupied},.8f),Is.False);
            var outboundWitness=IndependentBodyClearWitness(work,service);var homeWitness=IndependentBodyClearWitness(service,work);
            Assert.That(CustomerRoutePlanner.IsClear(outboundWitness.Concat(homeWitness).ToArray(),new[]{occupied},.8f),Is.True);
            var world=World(actors:new[]{new TrafficBodyFact(key,work,.4f,actorLife:new object()),
                new TrafficBodyFact(worker,occupied,.4f,true,true,8,actorLife:new object())});
            var requirements=new[]{
                new TrafficRouteRequirement("capability-one",P(10,1),P(12,1),.8f,selectedJourney:false,avoidProposedParking:true),
                new TrafficRouteRequirement("capability-two",P(10,3),P(12,3),.8f,selectedJourney:false,avoidProposedParking:true),
                new TrafficRouteRequirement("selected-home",service,work,.8f,selectedJourney:true,avoidProposedParking:false)};
            var core=Coordinator(world,query:(a,b)=>
            {
                calls++;
                for(var index=0;index<2;index++)if(a.Equals(requirements[index].Start) && b.Equals(requirements[index].Goal))capCalls[index]++;
                return Geometry(a,b);
            });
            var request=new TrafficRequest(key,11,world,work,service,.4f,"selected-delivery",requirements:requirements,planPrimaryRoute:true);
            var queued=core.EvaluateParking(request);Assert.That(queued.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            TrafficDecision result=null;
            for(var frame=11;frame<267;frame++)
            {core.ProcessReady(frame);result=core.GetDecision(key);if(result.Kind!=TrafficDecisionKind.DeferredByBudget)break;}
            Assert.That(D1Read(core,key,"Parking"),Is.True);Assert.That(D1Read(core,key,"AcquiredSequence"),Is.EqualTo(0L));
            Assert.That(D1Read(core,key,"Leg"),Is.Null);Assert.That(D1Read(core,key,"JourneyPermit"),Is.Null);Assert.That(D1Read(core,key,"JourneyRequest"),Is.Null);
            Assert.That(capCalls,Is.EqualTo(new[]{1,1}),"Nonselected capability proofs use their original single direct query, never a physical detour");
            Assert.That(core.QueriesConsumed(key),Is.EqualTo(calls));Assert.That(core.QueriesThisFrame,Is.LessThanOrEqualTo(128));
            Assert.That(D1Read(core,key,"FirstFrame"),Is.EqualTo(11));Assert.That(result.RequestSequence,Is.GreaterThan(0));
            TestContext.WriteLine("PARKING_SELECTED_ROUNDTRIP homeOnly="+homeOnly+" decision="+result.Kind+"/"+result.Reason+
                " queries="+calls+" capabilities="+string.Join(",",capCalls)+" independentSafeOutward="+outboundWitness.Length+" independentSafeHome="+homeWitness.Length);
            Assert.That(result.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FEATURE: the unacquired parking proposal must prefer a complete safe selected roundtrip");
            Assert.That(result.ProofRoutes.Select(p=>p.ResourceId),Is.EqualTo(new[]{"selected-delivery","capability-one","capability-two","selected-home"}));
            for(var index=0;index<2;index++)
            {
                var requirement=requirements[index];var proof=result.ProofRoutes[index+1];
                Assert.That(proof.Waypoints,Is.EqualTo(new[]{requirement.Goal}));
                Assert.That(proof.ExpandedPath,Is.EqualTo(new[]{requirement.Start,requirement.Goal}),"Nonselected completed proof geometry is unchanged");
            }
            var outward=result.ProofRoutes[0];var home=result.ProofRoutes[3];
            Assert.That(CustomerRoutePlanner.IsClear(new[]{work}.Concat(outward.ExpandedPath).Concat(new[]{service}).ToArray(),new[]{occupied},.8f),Is.True,
                "FEATURE: selected outward remains physically clear, without modifying Working progress");
            Assert.That(CustomerRoutePlanner.IsClear(new[]{service}.Concat(home.ExpandedPath).Concat(new[]{work}).ToArray(),new[]{occupied},.8f),Is.True,
                "FEATURE: home-only conflict also needs a body-aware selected proof; primary-only coverage is insufficient");
            var combined=outward.ExpandedPath.Concat(home.ExpandedPath).ToArray();
            Assert.That(CustomerRoutePlanner.IsClear(new[]{work}.Concat(combined).Concat(new[]{work}).ToArray(),new[]{occupied},.8f),Is.True);
            Assert.That((Vector3[])D1Read(core,key,"CurrentPath"),Is.EqualTo(outward.ExpandedPath),"Home is not the current owned movement segment");
            Assert.That((Vector3[])D1Read(core,key,"Journey"),Is.EqualTo(combined),"Selected proof order is preserved in the same combined journey");
            Assert.That(core.HasActiveGrant(key),Is.False,"A prepared candidate is not canonical acquisition or issued movement");
            Assert.That(world.Bodies.Single(b=>b.Owner.Equals(worker)).IndependentlyProgressing,Is.True);
        }

        [Test] public void FiniteBusinessBodyChildStartsFromCurrentGeometryAfterAnUnchangedBaseAndSecondaryCursor()
        {
            var key=Key("lazy-detour-waiter");var worker=Key("lazy-detour-worker","body");
            var actor=new object();var workerLife=new object();var calls=0;var secondaryCalls=0;
            TrafficWorldSnapshot Snapshot(long bodyVersion,Vector3 position)=>World(1,bodyVersion,actors:new[]{
                new TrafficBodyFact(key,Origin,.4f,actorLife:actor),
                new TrafficBodyFact(worker,position,.4f,true,true,8,actorLife:workerLife)});
            var world=Snapshot(1,P(20));var core=Coordinator(world,frameBudget:1,query:(a,b)=>
            {calls++;if(a.Equals(P(10)) && b.Equals(P(12)))secondaryCalls++;return new[]{a,b};});
            var extra=new[]{new TrafficRouteRequirement("lazy-secondary",P(10),P(12),.8f)};
            core.EvaluateMovement(Request(key,Origin,P(4),world,requirements:extra));core.ProcessReady(1);
            var expected=core.GetDecision(key);Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(D1Read(core,key,"JobIndex"),Is.EqualTo(1),"PREMISE: base primary is complete; no conflicting business body or child exists yet");
            var jobs=(System.Collections.IList)D1Read(core,key,"Jobs");var primary=jobs[0];var secondary=jobs[1];
            Assert.That(calls,Is.EqualTo(1));Assert.That(secondaryCalls,Is.Zero);
            world=Snapshot(2,P(2));core.SetSnapshot(world);
            jobs=(System.Collections.IList)D1Read(core,key,"Jobs");
            Assert.That(jobs.Count,Is.EqualTo(2),"FEATURE_R6: potential business-body geometry must not discard the unchanged base cursor");
            Assert.That(jobs[0],Is.SameAs(primary));Assert.That(jobs[1],Is.SameAs(secondary));
            Assert.That(D1Read(core,key,"JobIndex"),Is.EqualTo(1));Assert.That(core.GetDecision(key),Is.SameAs(expected));Assert.That(calls,Is.EqualTo(1));
            core.ProcessReady(2);Assert.That(core.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(secondaryCalls,Is.EqualTo(1));Assert.That(calls,Is.EqualTo(2));
            Assert.That(D1Read(core,key,"JobIndex"),Is.EqualTo(0),"The new CURRENT body conflict may now start a child under the same primary");
            TrafficDecision result=null;
            for(var frame=3;frame<515;frame++)
            {core.ProcessReady(frame);result=core.GetDecision(key);if(result.Kind!=TrafficDecisionKind.DeferredByBudget)break;}
            Assert.That(result.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FEATURE_R6: first child must capture current P(2), not constructor-time P(20)");
            var proof=result.ProofRoutes.Single(p=>p.ResourceId=="lane");
            Assert.That(CustomerRoutePlanner.IsClear(new[]{Origin}.Concat(proof.ExpandedPath).Concat(new[]{P(4)}).ToArray(),new[]{P(2)},.8f),Is.True);
            Assert.That(secondaryCalls,Is.EqualTo(1),"The already completed secondary proof is never queried again");
            Assert.That(((System.Collections.IList)D1Read(core,key,"Jobs"))[0],Is.SameAs(primary));
            Assert.That(((System.Collections.IList)D1Read(core,key,"Jobs"))[1],Is.SameAs(secondary));
            Assert.That(result.RequestSequence,Is.EqualTo(expected.RequestSequence));Assert.That(D1Read(core,key,"FirstFrame"),Is.EqualTo(1));
            Assert.That(core.QueriesConsumed(key),Is.EqualTo(calls));Assert.That(core.QueriesThisFrame,Is.LessThanOrEqualTo(1));
        }
