        // Legal public-Core models; no real Native result or private Entry mutation is supplied.
        // 原 decision 前提先成立，再检查只读显示；模型不声称实际 Native 运动。
        [Test] public void PresentationReportsActualQueuedPlanningWithoutMutatingPermission()
        {
            var calls=0;var world=World();var core=Coordinator(world,query:(a,b)=>{calls++;return new[]{a,b};});
            var key=Key("ui-queued");var request=Request(key,Origin,P(2),world,frame:11);
            var queued=core.EvaluateMovement(request);
            Assert.That(queued.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"FIXTURE: actual original public-Core queue");
            Assert.That(queued.AcquiredSequence,Is.Zero);Assert.That(core.HasPendingWork,Is.True);
            var accounting=D3CaptureAccounting(core,key);var beforeCalls=calls;var beforeQueries=core.QueriesThisFrame;
            var presentation=core.CurrentWorkPresentation;
            Assert.That(core.GetDecision(key),Is.SameAs(queued));D3AssertAccounting(core,key,accounting);
            Assert.That(core.HasActiveGrant(key),Is.False);Assert.That(calls,Is.EqualTo(beforeCalls));Assert.That(core.QueriesThisFrame,Is.EqualTo(beforeQueries));
            Assert.That(presentation,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"PRODUCT: real unissued planning must be presentable without creating authority");
        }

        [Test] public void PresentationUsesActualWaitingBeforeConcurrentPlanningAndDropsRetiredWork()
        {
            var owner=Key("ui-finite-owner");var waitKey=Key("ui-waiter");var planKey=Key("ui-planner");
            var world=World(actors:new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,8)});var core=Coordinator(world);
            core.EvaluateMovement(Request(waitKey,Origin,P(4),world));core.ProcessReady(1); // Explicit public model processing only.
            var waiting=core.GetDecision(waitKey);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: real finite-progress body dependency");
            Assert.That(waiting.Blockers.Single().Owner,Is.EqualTo(owner));Assert.That(waiting.Blockers.Single().ResourceId,Is.EqualTo("body"));
            var planning=core.EvaluateMovement(Request(planKey,P(20),P(21),world,frame:2));
            Assert.That(planning.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            var waitAccounting=D3CaptureAccounting(core,waitKey);var planAccounting=D3CaptureAccounting(core,planKey);
            var presentation=core.CurrentWorkPresentation;
            Assert.That(core.GetDecision(waitKey),Is.SameAs(waiting));Assert.That(core.GetDecision(planKey),Is.SameAs(planning));
            D3AssertAccounting(core,waitKey,waitAccounting);D3AssertAccounting(core,planKey,planAccounting);
            Assert.That(presentation,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"PRODUCT: actual finite traffic wait outranks concurrent planning for display only");
            core.Retire(waitKey);
            Assert.That(core.GetDecision(waitKey).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(core.CurrentWorkPresentation,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            core.Retire(planKey);Assert.That(D3ContainsIntent(core,waitKey) && D3ContainsIntent(core,planKey),Is.True);
            Assert.That(core.HasPendingWork,Is.False);Assert.That(core.CurrentWorkPresentation,Is.Null);
        }

        [Test] public void PresentationIgnoresIdlePreparedAndRetiredHistoryAndClosedScope()
        {
            var world=World();var core=Coordinator(world);var key=Key("ui-history");
            Assert.That(core.HasPendingWork,Is.False);Assert.That(core.CurrentWorkPresentation,Is.Null);
            core.EvaluateMovement(Request(key,Origin,P(2),world));core.ProcessReady(1);
