            Assert.That(core.HasPendingWork,Is.True);Assert.That(core.CurrentWorkPresentation,Is.Null,"Prepared permission is not a waiting/planning display fact");
            core.Retire(key);Assert.That(D3ContainsIntent(core,key),Is.True);Assert.That(core.HasPendingWork,Is.False);
            Assert.That(core.GetDecision(key).Reason,Is.EqualTo("intent-retired"));Assert.That(core.CurrentWorkPresentation,Is.Null);
            var other=Key("ui-closed");Assert.That(core.EvaluateMovement(Request(other,P(20),P(21),world,frame:2)).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            core.Close();Assert.That(core.HasPendingWork,Is.False);Assert.That(core.CurrentWorkPresentation,Is.Null);
        }

        private static readonly Vector3 Origin = Vector3.zero;
        private static Vector3 P(float x, float z = 0) => new Vector3(x, 0, z);
        private static TrafficIntentKey Key(string actor, string phase = "journey", int generation = 1,
            int layout = 7, long epoch = 1, string session = "scene")
            => new TrafficIntentKey(session, epoch, actor, phase, generation, layout, "order.1");
        private static TrafficWorldSnapshot World(long version = 1, long bodies = 1,
            TrafficBodyFact[] actors = null, TrafficParkingFact[] parking = null)
            => new TrafficWorldSnapshot(version, bodies, actors, parking);
        private static ServiceTrafficCoordinator Coordinator(TrafficWorldSnapshot world = null,
            int frameBudget = 128, int intentBudget = 16384,
            Func<Vector3, Vector3, IReadOnlyList<Vector3>> query = null, float waitSeconds = 10)
            => new ServiceTrafficCoordinator("scene", 1, 7, world ?? World(),
                query ?? ((from, to) => new[] { from, to }), frameBudget, intentBudget, waitSeconds);
        private static TrafficRequest Request(TrafficIntentKey key, Vector3 start, Vector3 goal,
            TrafficWorldSnapshot world = null, int frame = 1, Vector3[] journey = null,
            TrafficRouteRequirement[] requirements = null, TrafficNativeStamp stamp = default,
            string resource = "lane", bool independent = true, float seconds = 20,
            TrafficDecisionKind? provenFailure = null)
            => new TrafficRequest(key, frame, world ?? World(), start, goal, .4f, resource,
                journey, requirements, stamp, independent, seconds, provenFailure);
        private static TrafficDecision Grant(ServiceTrafficCoordinator coordinator, TrafficRequest request, bool parking = false)
        {
            if (parking) coordinator.EvaluateParking(request); else coordinator.EvaluateMovement(request);
            coordinator.ProcessReady(request.RequestedFrame);
            var decision = coordinator.GetDecision(request.Intent);
            Assert.That(decision.Kind, Is.EqualTo(TrafficDecisionKind.Granted), decision.Reason);
            Assert.That(coordinator.TryCommit(decision), Is.True, "prepared permission must become committed");
            return decision;
        }

        // A hint only filters current endpoints before Submit; the normal Core decision remains authoritative.
        // 模型通过真实 Evaluate/Commit/CompleteLeg 形成占位，不写 private Entry 或伪造 permission。
        private static bool ParkingEndpointHint(ServiceTrafficCoordinator coordinator,TrafficRequest request)
            =>D3InvokeBool(coordinator,"IsParkingEndpointAvailable",request);

        [TestCase("body")]
        [TestCase("disabled-body")]
        [TestCase("canonical-parking")]
        public void ParkingEndpointHintRejectsActualOccupancyWithoutSubmitting(string kind)
        {
            var owner=Key("endpoint-owner");var key=Key("endpoint-candidate");var canonical=new CanonicalOwner();
            var bodies=kind=="canonical-parking"?null:new[]{new TrafficBodyFact(owner,P(2),.4f,enabled:kind=="body")};
            var parking=kind=="canonical-parking"?new[]{new TrafficParkingFact(owner,canonical,0,"actual-slot",P(2),.4f)}:null;
            var world=World(actors:bodies,parking:parking);var calls=0;
            var coordinator=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            var request=Request(key,Origin,P(2),world,frame:11);

            Assert.That(ParkingEndpointHint(coordinator,request),Is.False);
            Assert.That(ParkingEndpointHint(coordinator,request),Is.False,"Repeated availability reads cannot consume a candidate");

            Assert.That(D3ContainsIntent(coordinator,key),Is.False);Assert.That(coordinator.HasPendingWork,Is.False);
            Assert.That(coordinator.QueriesThisFrame,Is.Zero);Assert.That(calls,Is.Zero);
            Assert.That(canonical.Applies,Is.Zero);Assert.That(canonical.Rollbacks,Is.Zero);Assert.That(canonical.Version,Is.Zero);
            Assert.That(coordinator.DrainReady(),Is.Empty);Assert.That(D3ReadField(coordinator,"snapshot"),Is.SameAs(world));
        }

        [TestCase(false)]
        [TestCase(true)]
        public void ParkingEndpointHintProtectsPreparedAndAcquiredParking(bool acquired)
        {
            var world=World();var coordinator=Coordinator(world);var owner=Key("park-owner");var key=Key("park-intruder");
            coordinator.EvaluateParking(Request(owner,Origin,P(2),world));coordinator.ProcessReady(1);
            var prepared=coordinator.GetDecision(owner);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            if(acquired)Assert.That(coordinator.TryCommit(prepared),Is.True);
            var decision=coordinator.GetDecision(owner);var accounting=D3CaptureAccounting(coordinator,owner);
            var request=Request(key,P(10),P(2),world);

            Assert.That(ParkingEndpointHint(coordinator,request),Is.False);

            Assert.That(coordinator.GetDecision(owner),Is.SameAs(decision));D3AssertAccounting(coordinator,owner,accounting);
            Assert.That(D3ContainsIntent(coordinator,key),Is.False);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);
            coordinator.Retire(owner);
            Assert.That(ParkingEndpointHint(coordinator,request),Is.True,"Actual retirement releases this modeled right; its tombstone is not dereferenced");
            Assert.That(D3ContainsIntent(coordinator,owner),Is.True);Assert.That(D3ContainsIntent(coordinator,key),Is.False);
        }

        [TestCase("current-path")]
        [TestCase("selected-home")]
        [TestCase("retained-after-arrival")]
        public void ParkingEndpointHintProtectsActualSelectedAndRetainedRoutes(string state)
        {
            var world=World();var coordinator=Coordinator(world);var owner=Key("route-owner");var key=Key("route-intruder");
            var target=P(2);
            if(state=="current-path")
            {
                coordinator.EvaluateMovement(Request(owner,Origin,P(4),world));coordinator.ProcessReady(1);
                Assert.That(coordinator.GetDecision(owner).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That((Vector3[])D1Read(coordinator,owner,"CurrentPath"),Is.Not.Empty);
            }
            else if(state=="selected-home")
            {
                var home=new TrafficRouteRequirement("selected-home",P(2),P(8),.8f,selectedJourney:true,avoidProposedParking:false);
                coordinator.EvaluateParking(Request(owner,Origin,P(2),world,requirements:new[]{home}));coordinator.ProcessReady(1);
                Assert.That(coordinator.GetDecision(owner).Kind,Is.EqualTo(TrafficDecisionKind.Granted));target=P(6);
                Assert.That((Vector3[])D1Read(coordinator,owner,"CurrentPath"),Is.Empty);
                Assert.That((Vector3[])D1Read(coordinator,owner,"Journey"),Is.Not.Empty);
            }
            else
            {
                var stamp=new TrafficNativeStamp(801,1);var journey=new[]{Origin,P(2),P(2,3),P(6,3)};
                Grant(coordinator,Request(owner,Origin,P(2),world,journey:journey,stamp:stamp));
                Assert.That(coordinator.CompleteLeg(owner,stamp),Is.True);target=P(4,3);
                Assert.That(coordinator.HasActiveGrant(owner),Is.False);
                Assert.That((Vector3[])D1Read(coordinator,owner,"Journey"),Is.Not.Empty);
            }
            var decision=coordinator.GetDecision(owner);var accounting=D3CaptureAccounting(coordinator,owner);

            Assert.That(ParkingEndpointHint(coordinator,Request(key,P(12),target,world)),Is.False);

            Assert.That(coordinator.GetDecision(owner),Is.SameAs(decision));D3AssertAccounting(coordinator,owner,accounting);
            Assert.That(D3ContainsIntent(coordinator,key),Is.False);
        }

        [Test]
        public void ParkingEndpointHintClearReadKeepsAllExistingAccountingAndCanonicalState()
        {
            var key=Key("clear-candidate");var ownAlias=Key(key.ActorId,"old-body",4);var canonical=new CanonicalOwner();
            var world=World(actors:new[]{new TrafficBodyFact(ownAlias,Origin,.4f)},
                parking:new[]{new TrafficParkingFact(ownAlias,canonical,0,"own-slot",Origin,.4f)});
            var calls=0;var coordinator=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            var owner=Key("distant-owner");coordinator.EvaluateParking(Request(owner,P(20),P(21),world));coordinator.ProcessReady(1);
            var decision=coordinator.GetDecision(owner);var accounting=D3CaptureAccounting(coordinator,owner);
            var beforeCalls=calls;var beforeFrameQueries=coordinator.QueriesThisFrame;
            var counters=new[]{"requestSequence","acquiredSequence","permit","queryFrame"}.ToDictionary(name=>name,name=>D3ReadField(coordinator,name));
            var request=Request(key,Origin,Origin,world,frame:11);

            Assert.That(ParkingEndpointHint(coordinator,request),Is.True,"Own actor facts are excluded exactly as in real endpoint checks");
            Assert.That(ParkingEndpointHint(coordinator,request),Is.True);

            Assert.That(coordinator.GetDecision(owner),Is.SameAs(decision));D3AssertAccounting(coordinator,owner,accounting);
            foreach(var pair in counters)Assert.That(D3ReadField(coordinator,pair.Key),Is.EqualTo(pair.Value),pair.Key);
            Assert.That(D3ContainsIntent(coordinator,key),Is.False);Assert.That(calls,Is.EqualTo(beforeCalls));
            Assert.That(coordinator.QueriesThisFrame,Is.EqualTo(beforeFrameQueries));Assert.That(coordinator.DrainReady(),Is.Empty);
            Assert.That(canonical.Applies,Is.Zero);Assert.That(canonical.Rollbacks,Is.Zero);Assert.That(canonical.Version,Is.Zero);
            Assert.That(D3ReadField(coordinator,"snapshot"),Is.SameAs(world));
        }

