        [Test]
        public void ParkingEndpointHintTrueCannotAuthorizeLaterOccupiedTargetOrChangeTerminalPolicy()
        {
            var key=Key("stale-hint");var owner=Key("new-static-body");var initial=World();var coordinator=Coordinator(initial);
            Assert.That(ParkingEndpointHint(coordinator,Request(key,Origin,P(2),initial,frame:11)),Is.True);
            var occupied=World(1,2,new[]{new TrafficBodyFact(owner,P(2),.4f)});coordinator.SetSnapshot(occupied);

            coordinator.EvaluateParking(Request(key,Origin,P(2),occupied,frame:11),0,24);coordinator.ProcessReady(12);

            var failed=coordinator.GetDecision(key);
            Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal),"A hint never changes the original non-independent-owner stop contract");
            Assert.That(failed.Blockers.Any(blocker=>blocker.Owner.Equals(owner)),Is.True);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);
            Assert.That(failed.AcquiredSequence,Is.Zero);Assert.That(D1Read(coordinator,key,"EverCanonicalAttempt"),Is.EqualTo(false));
            Assert.That(coordinator.TryCommit(failed),Is.False);
            var clear=World(1,3);coordinator.SetSnapshot(clear);var refreshed=Request(key,Origin,P(2),clear,frame:11);
            Assert.That(ParkingEndpointHint(coordinator,refreshed),Is.True,"Availability is not eligibility to revive an existing Terminal intent");
            Assert.That(coordinator.EvaluateParking(refreshed,0,24),Is.SameAs(failed));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));
            CollectionAssert.AreEquivalent(new[]{0},(HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"));
        }

