        // C counter first: the existing full scan must expose the cold-history cost before any index change.
        // 先给旧遍历加默认关闭的计数；新测试只走公开生命周期，不写 Entry/Fail。
        [TestCase(0)]
        [TestCase(500)]
        public void D3CColdHistoryDoesNotIncreaseActualReadySourceVisits(int coldPairs)
        {
            var world=World();var queryCalls=0;
            var coordinator=Coordinator(world,query:(from,to)=>{queryCalls++;return new[]{from,to};});
            var cold=new List<TrafficIntentKey>();
            for(var index=0;index<coldPairs;index++)
            {
                var retired=Key("d3c-retired-"+index);var discarded=Key("d3c-discarded-"+index);
                coordinator.EvaluateMovement(Request(retired,Origin,P(2),world));coordinator.Retire(retired);cold.Add(retired);
                coordinator.EvaluateMovement(Request(discarded,Origin,P(2),world));
                Assert.That(coordinator.DiscardPrepared(discarded),Is.True);cold.Add(discarded);
            }
            var ready=Key("d3c-only-ready");coordinator.EvaluateMovement(Request(ready,Origin,P(2),world));
            foreach(var key in cold){Assert.That(D3ContainsIntent(coordinator,key),Is.True);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);}
            Assert.That(D3CVisitProperty("CountProcessReadySourceVisits").GetValue(coordinator),Is.EqualTo(false),"Counter must default OFF");
            coordinator.ProcessReady(0);Assert.That(queryCalls,Is.Zero);
            Assert.That(D3CReadySourceVisits(coordinator),Is.Zero,"Default-OFF scan must not collect observations");
            D3CVisitProperty("CountProcessReadySourceVisits").SetValue(coordinator,true);
            try
            {
                coordinator.ProcessReady(1);var decision=coordinator.GetDecision(ready);
                Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted),decision.Reason);
                Assert.That(decision.RequestSequence,Is.EqualTo(1));Assert.That(queryCalls,Is.EqualTo(1));
                Assert.That(coordinator.QueriesConsumed(ready),Is.EqualTo(1));Assert.That(coordinator.HasPendingWork,Is.True);
                Assert.That(D3ContainsIntent(coordinator,ready),Is.True);
                foreach(var key in cold)Assert.That(D3ContainsIntent(coordinator,key),Is.True,"Cold keys remain lookup-visible");
                Assert.That(D3CReadySourceVisits(coordinator),Is.EqualTo(1),
                    "PRODUCT: 500 real Retired + 500 real Discarded entries must not increase actual ProcessReady source enumeration");
            }
            finally{D3CVisitProperty("CountProcessReadySourceVisits").SetValue(coordinator,false);}
        }

        [Test]
        public void D3CDiscardResubmitPreservesOriginalBirthPriorityForTiedContextKeys()
        {
            var world=World();var coordinator=Coordinator(world);
            var first=new TrafficIntentKey("scene",1,"d3c-tied","same-phase",1,7,"birth.z");
            var second=new TrafficIntentKey("scene",1,"d3c-tied","same-phase",1,7,"birth.a");
            var firstRequest=Request(first,Origin,P(2),world);var secondRequest=Request(second,P(10),P(12),world);
            coordinator.EvaluateMovement(firstRequest);coordinator.EvaluateMovement(secondRequest);
            Assert.That(coordinator.GetDecision(first).RequestSequence,Is.Zero);Assert.That(coordinator.GetDecision(second).RequestSequence,Is.Zero);
            Assert.That(coordinator.DiscardPrepared(first),Is.True);Assert.That(coordinator.DiscardPrepared(second),Is.True);
            Assert.That(coordinator.HasPendingWork,Is.False);
            Assert.That(coordinator.GetDecision(first).RequestSequence,Is.Zero);Assert.That(coordinator.GetDecision(second).RequestSequence,Is.Zero);
            Assert.That(coordinator.QueriesConsumed(first),Is.Zero);Assert.That(coordinator.QueriesConsumed(second),Is.Zero);
            coordinator.EvaluateMovement(firstRequest);coordinator.EvaluateMovement(secondRequest);
            Assert.That(coordinator.HasPendingWork,Is.True);coordinator.ProcessReady(1);
            var firstDecision=coordinator.GetDecision(first);var secondDecision=coordinator.GetDecision(second);
            Assert.That(firstDecision.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(secondDecision.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(firstDecision.RequestSequence,Is.EqualTo(1),"Existing descriptors all tie; original dictionary birth wins despite later work-set re-add");
            Assert.That(secondDecision.RequestSequence,Is.EqualTo(2));
            Assert.That(coordinator.QueriesConsumed(first),Is.EqualTo(1));Assert.That(coordinator.QueriesConsumed(second),Is.EqualTo(1));
            Assert.That(coordinator.DiscardPrepared(first),Is.True);
            coordinator.EvaluateMovement(Request(first,Origin,P(2),world,frame:100));coordinator.ProcessReady(2);
            Assert.That(coordinator.GetDecision(first).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(coordinator.GetDecision(first).RequestSequence,Is.EqualTo(1));Assert.That(D1Read(coordinator,first,"FirstFrame"),Is.EqualTo(1));
            Assert.That(coordinator.QueriesConsumed(first),Is.EqualTo(2));
            Assert.That(coordinator.DiscardPrepared(first),Is.True);Assert.That(coordinator.DiscardPrepared(second),Is.True);
            Assert.That(coordinator.HasPendingWork,Is.False);
        }

        [TestCase("retire")]
        [TestCase("close")]
        [TestCase("reset")]
        public void D3CReadyBatchReentryCannotEvaluateRemovedOwnerOrLoseFreshContext(string action)
        {
            var world=World();var freshWorld=World(2,2);var first=Key("d3c-a");var second=Key("d3c-b");
            var fresh=Key("d3c-c-fresh",layout:8,epoch:2);var queryCalls=0;var changed=false;
            bool? pendingBefore=null,pendingAfter=null;ServiceTrafficCoordinator coordinator=null;
            coordinator=Coordinator(world,query:(from,to)=>
            {
                queryCalls++;
                if(!changed)
                {
                    changed=true;pendingBefore=coordinator.HasPendingWork;
                    if(action=="retire")coordinator.Retire(second);
                    else if(action=="close")coordinator.Close();
                    else
                    {
                        coordinator.ResetLayout(2,8,freshWorld);
                        coordinator.EvaluateMovement(Request(fresh,P(20),P(22),freshWorld,frame:2));
                    }
                    pendingAfter=coordinator.HasPendingWork;
                }
                return new[]{from,to};
            });
            coordinator.EvaluateMovement(Request(first,Origin,P(2),world));
            coordinator.EvaluateMovement(Request(second,P(10),P(12),world));coordinator.ProcessReady(1);
            Assert.That(changed,Is.True);Assert.That(pendingBefore,Is.EqualTo(true));
            Assert.That(queryCalls,Is.EqualTo(1),"The captured old batch must not issue a query for an owner removed during the first real query");
            Assert.That(coordinator.QueriesConsumed(second),Is.Zero);Assert.That(coordinator.HasActiveGrant(second),Is.False);
            if(action=="retire")
            {
                Assert.That(pendingAfter,Is.EqualTo(true));D3AssertRetiredPayloadReleased(coordinator,second);
                Assert.That(coordinator.GetDecision(first).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(coordinator.DiscardPrepared(first),Is.True);Assert.That(coordinator.HasPendingWork,Is.False);
            }
            else
            {
                Assert.That(D3ContainsIntent(coordinator,first),Is.False);Assert.That(D3ContainsIntent(coordinator,second),Is.False);
                if(action=="close")
                {
                    Assert.That(pendingAfter,Is.EqualTo(false));Assert.That(coordinator.HasPendingWork,Is.False);
                    coordinator.ProcessReady(2);Assert.That(queryCalls,Is.EqualTo(1));
                }
                else
                {
                    Assert.That(pendingAfter,Is.EqualTo(true));Assert.That(coordinator.HasPendingWork,Is.True);
                    Assert.That(coordinator.GetDecision(fresh).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                    Assert.That(coordinator.GetDecision(fresh).RequestSequence,Is.Zero);Assert.That(coordinator.QueriesConsumed(fresh),Is.Zero);
                    coordinator.ProcessReady(2);Assert.That(queryCalls,Is.EqualTo(2));
                    Assert.That(coordinator.GetDecision(fresh).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                    Assert.That(coordinator.GetDecision(fresh).RequestSequence,Is.EqualTo(2),"Reset does not rewrite original global request-sequence history");
                    Assert.That(coordinator.DiscardPrepared(fresh),Is.True);Assert.That(coordinator.HasPendingWork,Is.False);
                }
            }
            Assert.That(coordinator.DrainReady(),Is.Empty);
        }

        private static System.Reflection.PropertyInfo D3CVisitProperty(string name)
        {
            var property=typeof(ServiceTrafficCoordinator).GetProperty(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(property,Is.Not.Null,"PRECONDITION: pair these tests with the reviewed Editor-only counter on the old full scan");return property;
        }
        private static int D3CReadySourceVisits(ServiceTrafficCoordinator coordinator)
            =>(int)D3CVisitProperty("ProcessReadySourceVisits").GetValue(coordinator);

        // D3 Phase A draft: real contract transitions, read-only reflection, no GC/performance seam.
        // 只验证真实 Retired 的引用释放；外部 snapshot 仍可合法持有同一 ActorLife。
        [Test]
        public void D3RetiredCommittedJourneyReleasesPayloadAndPreservesAccounting()
        {
            var f=new LegFixture();f.Start();var stamp=new TrafficNativeStamp(601,1);
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.True);
            var request=(TrafficRequest)f.Read("Request");var committed=f.Coordinator.GetDecision(f.Key);
            Assert.That(request.Snapshot,Is.Not.Null,"PRECONDITION: an actually registered strict leg retains its snapshot");
            Assert.That(((TrafficBodyFact)f.Read("PreparationBody")).ActorLife,Is.SameAs(f.Actor));
            Assert.That(D3ReadField(f.Read("Leg"),"ActorLife"),Is.SameAs(f.Actor));
            Assert.That(f.Read("JourneyRequest"),Is.Not.Null);Assert.That(f.Read("JourneyPermit"),Is.SameAs(f.Journey));
            Assert.That((Vector3[])f.Read("Journey"),Is.Not.Empty);
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);

            f.Coordinator.Retire(f.Key);

            D3AssertRetiredPayloadReleased(f.Coordinator,f.Key);D3AssertAccounting(f.Coordinator,f.Key,accounting);
            var tombstone=f.Coordinator.GetDecision(f.Key);
            Assert.That(tombstone.Intent,Is.EqualTo(f.Key));Assert.That(tombstone.Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            Assert.That(tombstone.Reason,Is.EqualTo("intent-retired"));Assert.That(tombstone.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(tombstone.RequestSequence,Is.EqualTo(committed.RequestSequence));Assert.That(tombstone.AcquiredSequence,Is.EqualTo(committed.AcquiredSequence));
            Assert.That(D3ContainsIntent(f.Coordinator,f.Key),Is.True,"Retired keys remain lookup-visible to existing consumers");
            Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.False);Assert.That(f.Coordinator.HasPendingWork,Is.False);
            f.Coordinator.Retire(f.Key);Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(tombstone));
            Assert.That(f.Coordinator.EvaluateMovement(request),Is.SameAs(tombstone));
            Assert.That(f.Coordinator.TryCommit(committed),Is.False);
            Assert.That(f.Coordinator.PrepareLeg(f.Journey,"outward",0,f.Actor,2,f.World,Origin,.05f,f.Frame),Is.SameAs(tombstone));
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.False);Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,stamp,f.End),Is.False);
            Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,1),Is.False);
            Assert.That(f.Coordinator.TryGetCommittedJourney(f.Key,out var oldSource),Is.False);Assert.That(oldSource,Is.Null);
            Assert.That(f.Coordinator.TryGetCommittedLegProvenance(f.Key,f.Actor,1,out oldSource,out var oldSnapshot),Is.False);
            Assert.That(oldSource,Is.Null);Assert.That(oldSnapshot,Is.Null);
            Assert.That(RevokePhysicalPreparation(f.Coordinator,committed,out _),Is.False);
            Assert.That(D2Refresh(f.Coordinator,committed,request,out _),Is.False);
            f.Coordinator.SetSnapshot(f.World);f.Coordinator.Tick(1,false);f.Coordinator.NotifyChanged(f.Key,"body");
            Assert.That(f.Coordinator.DrainReady(),Is.Empty);D3AssertAccounting(f.Coordinator,f.Key,accounting);
        }

        [Test]
        public void D3AuthenticatedStoppedLegReleasesCapturedClaimsAndPreservesPhysicalFacts()
        {
            var key=Key("d3-stopped");var actor=new object();var canonical=new object();
            var claim=new TrafficParkingFact(key,canonical,3,"d3-paid-slot",P(4),.4f,businessOwner:new object(),releaseObligation:new object());
            var initial=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)},parking:new[]{claim});
            var coordinator=Coordinator(initial);var source=Grant(coordinator,Request(key,Origin,P(4),initial,resource:"d3-travel"));
            Assert.That(coordinator.PrepareLeg(source,"d3-travel",0,actor,5,initial,Origin,.05f,2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);Assert.That(coordinator.TryCommit(coordinator.GetDecision(key)),Is.True);
            var stamp=new TrafficNativeStamp(602,5);Assert.That(coordinator.BindLeg(key,actor,stamp),Is.True);
            var body=new TrafficBodyFact(key,P(1),.4f,actorLife:actor);var stoppedWorld=World(1,2,new[]{body},new[]{claim});
            coordinator.SetSnapshot(stoppedWorld);
            var request=(TrafficRequest)D1Read(coordinator,key,"Request");
            Assert.That(request.Snapshot,Is.SameAs(initial));Assert.That(D1Read(coordinator,key,"PreparationBody"),Is.SameAs(initial.Bodies.Single()));
            Assert.That((TrafficParkingFact[])D1Read(coordinator,key,"PreparationClaims"),Is.EqualTo(new[]{claim}),"PRECONDITION: real Submit captured a nonempty canonical claim");
            Assert.That(D3ReadField(D1Read(coordinator,key,"Leg"),"ActorLife"),Is.SameAs(actor));
            var accounting=D3CaptureAccounting(coordinator,key);
            var result=new MovementResult(stamp.RequestId,key.ActorId,MovementStatus.Cancelled,NavigationFailure.None,NavigationFailure.None,NavigationFailure.None,P(1),0);

            Assert.That(D3InvokeBool(coordinator,"TryRetireStoppedLeg",key,actor,stamp,result),Is.True,"Only the bound result at the actual model body position retires the leg");

            D3AssertRetiredPayloadReleased(coordinator,key);D3AssertAccounting(coordinator,key,accounting);
            var retained=(TrafficWorldSnapshot)D3ReadField(coordinator,"snapshot");
            Assert.That(retained,Is.SameAs(stoppedWorld));Assert.That(retained.Bodies.Single(),Is.SameAs(body));Assert.That(retained.Parking.Single(),Is.SameAs(claim));
            Assert.That(body.ActorLife,Is.SameAs(actor));Assert.That(claim.CanonicalOwner,Is.SameAs(canonical));
            Assert.That(D3InvokeBool(coordinator,"TryRetireStoppedLeg",key,actor,stamp,result),Is.False);
            coordinator.Retire(key);Assert.That(D3ContainsIntent(coordinator,key),Is.True);Assert.That(coordinator.HasPendingWork,Is.False);
            // A subsequent actual Nav-disable fact still has a physical body; retirement cannot erase it.
            // 真正停腿后公开新的 disabled 身体事实；它和 canonical 停车位仍须挡住其他角色。
            var disabled=new TrafficBodyFact(key,P(1),.4f,false,actorLife:actor,actorActive:true);
            var physical=World(1,3,new[]{disabled},new[]{claim});coordinator.SetSnapshot(physical);
            var targets=new[]{disabled.Position,claim.Position};
            for(var index=0;index<targets.Length;index++)
            {
                var intruder=Key("d3-intruder",index.ToString());
                coordinator.EvaluateParking(Request(intruder,P(12),targets[index],physical,frame:10+index));coordinator.ProcessReady(10+index);
                var refused=coordinator.GetDecision(intruder);Assert.That(refused.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(refused.Blockers.Any(b=>b.Owner.Equals(key)),Is.True,"The real body/claim survives traffic payload release");
            }
            Assert.That(((TrafficWorldSnapshot)D3ReadField(coordinator,"snapshot")).Bodies.Single(),Is.SameAs(disabled));
            Assert.That(physical.Parking.Single(),Is.SameAs(claim));D3AssertAccounting(coordinator,key,accounting);
        }

        [Test]
