            Assert.That(f.Current,Is.SameAs(expected));Assert.That(f.Current.Reason,Is.EqualTo(expected.Reason));
            Assert.That(f.Current.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));Assert.That(f.Current.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            CollectionAssert.AreEqual(blockers,f.Current.Blockers);Assert.That(D3ContainsIntent(f.Coordinator,f.Original),Is.True);
            Assert.That(f.Coordinator.EvaluateMovement(request),Is.SameAs(expected));Assert.That(f.Take(expected,f.Actor,out _),Is.False);
            Assert.That(f.Coordinator.TryCommit(expected),Is.False);Assert.That(D2Refresh(f.Coordinator,expected,request,out _),Is.False);
            f.SetBody(null);Assert.That(f.Begin(receipt,out var ready),Is.True);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            D3AssertAccounting(f.Coordinator,f.Next,D3RecoveryAccounting(accounting));
            Assert.That(f.Read("WaitRemaining",f.Next),Is.EqualTo(5f));Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(1));
            Assert.That(f.Begin(receipt,out _),Is.False);Assert.That(f.Begin(receipt,out _,generation:3),Is.False);
            f.Coordinator.ProcessReady(50);Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.QueryCalls,Is.EqualTo(2));Assert.That(f.Current,Is.SameAs(expected));
            D3AssertRetiredPayloadReleased(f.Coordinator,f.Original);D3AssertAccounting(f.Coordinator,f.Original,accounting);
        }

        [Test]
        public void D3FailedLegReceiptRetainsOnlyWeakActorAndOriginalAccounting()
        {
            var f=new RecoveryModelFixture(history:true);f.MoveBody(P(1));
            var request=(TrafficRequest)f.Read(f.Original,"Request");Assert.That(request.Snapshot,Is.Not.Null);
            Assert.That(D3ReadField(f.Read(f.Original,"Leg"),"ActorLife"),Is.SameAs(f.Actor));
            var accounting=D3CaptureAccounting(f.Coordinator,f.Original);
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out var receipt),Is.True);

            D3AssertRetiredPayloadReleased(f.Coordinator,f.Original);D3AssertAccounting(f.Coordinator,f.Original,accounting);
            var registry=(System.Collections.IDictionary)D3ReadField(f.Coordinator,"recoveryReceipts");
            Assert.That(registry.Contains(receipt),Is.True);var record=registry[receipt];
            var weak=(WeakReference<object>)D3ReadField(record,"Actor");
            Assert.That(weak.TryGetTarget(out var actor),Is.True);Assert.That(actor,Is.SameAs(f.Actor));
            const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            foreach(var field in record.GetType().GetFields(flags).Where(field=>field.Name!="Actor"))
            {
                var type=field.FieldType;
                var valueOnly=type.IsValueType || type==typeof(string) || type==typeof(HashSet<int>) ||
                    type==typeof(HashSet<TrafficIntentKey>) || type==typeof(Dictionary<TrafficIntentKey,HashSet<string>>);
                Assert.That(valueOnly,Is.True,"Receipt must not retain Request/Snapshot/ActorLife/Leg/permit/canonical owner: "+field.Name);
            }
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out var ready),Is.True);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));D3AssertAccounting(f.Coordinator,f.Next,D3RecoveryAccounting(accounting));
            Assert.That(registry.Contains(receipt),Is.False);Assert.That(f.Begin(receipt,f.Replacement(generation:3),f.Actor,out _),Is.False);
            Assert.That(f.Read(f.Next,"WaitRemaining"),Is.EqualTo(5f));Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(1));
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out _),Is.False);
            f.Coordinator.Close();Assert.That(registry.Count,Is.Zero);Assert.That(f.Coordinator.HasPendingWork,Is.False);
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.False);
        }

        [TestCase("apply-false")]
        [TestCase("apply-throw")]
        [TestCase("rollback-unknown")]
        public void D3TerminalCanonicalFailureKeepsActualParkingAndSelectedHomeProtected(string mode)
        {
            var key=Key("d3-terminal-parking");var actor=new object();var canonical=new CanonicalOwner{Version=1};
            var body=new TrafficBodyFact(key,Origin,.4f,actorLife:actor);
            var claim=new TrafficParkingFact(key,canonical,1,"d3-canonical-slot",P(2),.4f);
            var world=World(actors:new[]{body},parking:new[]{claim});var coordinator=Coordinator(world);
            var home=new TrafficRouteRequirement("d3-selected-home",P(2),P(8),.8f,selectedJourney:true,avoidProposedParking:false);
            var request=Request(key,Origin,P(2),world,requirements:new[]{home},resource:claim.ResourceId);
            var permission=Grant(coordinator,request,parking:true);var journey=(Vector3[])D1Read(coordinator,key,"Journey");
            Assert.That(journey.Length,Is.GreaterThan(1));Assert.That(permission.ProofRoutes.Any(p=>p.ResourceId==home.ResourceId),Is.True);
            var queries=coordinator.QueriesConsumed(key);var mutation=new PreparationCanonicalFailure(mode);

            Assert.That(coordinator.TryContinueCanonical(permission,request,canonical,1,mutation),Is.False);

            Assert.That(mutation.Applies,Is.EqualTo(1));Assert.That(mutation.Rollbacks,Is.EqualTo(1));
            var terminal=coordinator.GetDecision(key);Assert.That(terminal.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(D1Read(coordinator,key,"Retired"),Is.EqualTo(false));
            Assert.That(coordinator.HasActiveGrant(key),Is.True);Assert.That(coordinator.HasPendingWork,Is.True);
            Assert.That(D1Read(coordinator,key,"Parking"),Is.EqualTo(true));Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request));
            Assert.That(D1Read(coordinator,key,"JourneyRequest"),Is.SameAs(request));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(permission));
            CollectionAssert.AreEqual(journey,(Vector3[])D1Read(coordinator,key,"Journey"));
            Assert.That(world.Bodies.Single(),Is.SameAs(body));Assert.That(world.Parking.Single(),Is.SameAs(claim));
            var targets=new[]{claim.Position,P(6)};
            for(var index=0;index<targets.Length;index++)
            {
                var intruder=Key("d3-terminal-intruder",index.ToString());
                coordinator.EvaluateParking(Request(intruder,P(12),targets[index],world,frame:2+index));coordinator.ProcessReady(2+index);
                var refused=coordinator.GetDecision(intruder);Assert.That(refused.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(refused.Blockers.Any(b=>b.Owner.Equals(key)),Is.True,"Terminal diagnosis does not release actual parking or the selected home suffix");
            }
            Assert.That(coordinator.GetDecision(key),Is.SameAs(terminal));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            var accounting=D3CaptureAccounting(coordinator,key);coordinator.Retire(key);
            D3AssertRetiredPayloadReleased(coordinator,key);D3AssertAccounting(coordinator,key,accounting);
            var after=Key("d3-after-true-retirement");coordinator.EvaluateParking(Request(after,P(12),P(6),world,frame:4));coordinator.ProcessReady(4);
            Assert.That(coordinator.GetDecision(after).Kind,Is.EqualTo(TrafficDecisionKind.Granted),"True retirement releases selected route protection while the distinct actual claim remains");
            Assert.That(world.Parking.Single(),Is.SameAs(claim));
        }

        [Test]
        public void D3HandoffRetirementReleasesPredecessorBeforeReentrantPublication()
        {
            var f=new HandoffFixture();var pending=f.Begin();var successor=f.Successor();
            var oldRequest=(TrafficRequest)f.Read(f.Owner,"Request");Assert.That(oldRequest.Snapshot.Parking.Single(),Is.SameAs(f.OriginalClaim));
            Assert.That(D3ReadField(f.Read(f.Owner,"PendingHandoff"),"ActorLife"),Is.SameAs(f.Actor));
            Assert.That(D3ReadField(f.Read(f.Owner,"Leg"),"ActorLife"),Is.SameAs(f.Actor));
            var accounting=D3CaptureAccounting(f.Coordinator,f.Owner);var publications=0;

            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>
            {
                publications++;
                D3AssertRetiredPayloadReleased(f.Coordinator,f.Owner);D3AssertAccounting(f.Coordinator,f.Owner,accounting);
                var tombstone=f.Coordinator.GetDecision(f.Owner);Assert.That(D3ContainsIntent(f.Coordinator,f.Owner),Is.True);
                f.Coordinator.Retire(f.Owner);Assert.That(f.Coordinator.GetDecision(f.Owner),Is.SameAs(tombstone));
                Assert.That(f.Coordinator.EvaluateMovement(oldRequest),Is.SameAs(tombstone));
                Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.True);
                f.PublishSuccessor(successor.Intent);f.Coordinator.Retire(f.Waiter);
            }),Is.True);

            // Publication exceptions are recorded by Core; they must fail this test explicitly.
            // Core 会捕获 publish exception，所以必须检查原异常，不能把被吞断言误报为通过。
            Assert.That(f.Coordinator.LastPublicationException,Is.Null);Assert.That(publications,Is.EqualTo(1));
            D3AssertRetiredPayloadReleased(f.Coordinator,f.Owner);D3AssertRetiredPayloadReleased(f.Coordinator,f.Waiter);
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True);
            Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False);
            f.Coordinator.AbortPhaseHandoff(pending,"repeated-cleanup");
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt()),Is.False);
            Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.True);
            f.Coordinator.Close();Assert.That(f.Coordinator.HasPendingWork,Is.False);Assert.That(f.Coordinator.TryCommit(successor),Is.False);
        }

        private static object D3ReadField(object target,string name)
        {
            Assert.That(target,Is.Not.Null,"PRECONDITION: existing captured object for "+name);
            var field=target.GetType().GetField(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(field,Is.Not.Null,"Existing field must precede behavioral RED: "+name);return field.GetValue(target);
        }
        private static bool D3InvokeBool(ServiceTrafficCoordinator coordinator,string name,params object[] args)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"Existing internal contract must precede behavioral RED: "+name);return (bool)method.Invoke(coordinator,args);
        }
        private static bool D3ContainsIntent(ServiceTrafficCoordinator coordinator,TrafficIntentKey key)=>D3InvokeBool(coordinator,"ContainsIntent",key);
        private static void D3AssertRetiredPayloadReleased(ServiceTrafficCoordinator coordinator,TrafficIntentKey key)
        {
            Assert.That(D1Read(coordinator,key,"Retired"),Is.EqualTo(true),"Only actual retirement authorizes payload release");
            foreach(var name in new[]{"Request","PreparationBody","Leg","JourneyRequest","JourneyPermit","PendingHandoff"})
                Assert.That(D1Read(coordinator,key,name),Is.Null,"PRODUCT: retired tombstone must release "+name);
            var claims=(TrafficParkingFact[])D1Read(coordinator,key,"PreparationClaims");
            Assert.That(claims==null || claims.Length==0,Is.True,"PRODUCT: captured canonical owners must leave retired tombstones");
            foreach(var name in new[]{"Jobs","CurrentPath","Journey"})Assert.That((System.Collections.IEnumerable)D1Read(coordinator,key,name),Is.Empty,name);
            Assert.That(coordinator.GetDecision(key).Route,Is.Empty);Assert.That(coordinator.GetDecision(key).ProofRoutes,Is.Empty);
        }
        private static Dictionary<string,object> D3CaptureAccounting(ServiceTrafficCoordinator coordinator,TrafficIntentKey key)
        {
            var names=new[]{"FirstFrame","Queries","RequestSequence","AcquiredSequence","Suspensions","CandidateCount","CurrentIndex","FiniteLimit","WaitRemaining",
                "EverCanonicalAttempt","ContinuationAttempted","ExplicitRecoveryUsed","LegacyLegCompleted","PreparationIdentityCaptured"};
            var captured=names.ToDictionary(name=>name,name=>D1Read(coordinator,key,name));
            captured.Add("AttemptedIndices",((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices")).ToArray());
            captured.Add("FrozenOwners",((HashSet<TrafficIntentKey>)D1Read(coordinator,key,"FrozenOwners"))?.ToArray());
            captured.Add("FrozenResources",((Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(coordinator,key,"FrozenResources"))?.ToDictionary(pair=>pair.Key,pair=>pair.Value.ToArray()));
            return captured;
        }
        private static Dictionary<string,object> D3RecoveryAccounting(Dictionary<string,object> captured)
            =>captured.Where(pair=>pair.Key!="ExplicitRecoveryUsed" && pair.Key!="PreparationIdentityCaptured").ToDictionary(pair=>pair.Key,pair=>pair.Value);
        private static void D3AssertAccounting(ServiceTrafficCoordinator coordinator,TrafficIntentKey key,Dictionary<string,object> captured)
        {
            foreach(var pair in captured.Where(pair=>pair.Key!="AttemptedIndices" && pair.Key!="FrozenOwners" && pair.Key!="FrozenResources"))
                Assert.That(D1Read(coordinator,key,pair.Key),Is.EqualTo(pair.Value),"Retained accounting: "+pair.Key);
            CollectionAssert.AreEquivalent((int[])captured["AttemptedIndices"],(HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"));
            var owners=(TrafficIntentKey[])captured["FrozenOwners"];var actualOwners=(HashSet<TrafficIntentKey>)D1Read(coordinator,key,"FrozenOwners");
            if(owners==null)Assert.That(actualOwners,Is.Null);else CollectionAssert.AreEquivalent(owners,actualOwners);
            var resources=(Dictionary<TrafficIntentKey,string[]>)captured["FrozenResources"];
            var actual=(Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(coordinator,key,"FrozenResources");
            if(resources==null)Assert.That(actual,Is.Null);
            else
            {
                Assert.That(actual,Is.Not.Null);CollectionAssert.AreEquivalent(resources.Keys,actual.Keys);
                foreach(var pair in resources)CollectionAssert.AreEquivalent(pair.Value,actual[pair.Key]);
            }
        }

        // D3B: public drain semantics first; the work index/counter belongs to the later Phase C.
        // 只观察真实 callback/claim 核验窗口；不写 private state，也不引入 runtime observer。
        [TestCase("held")]
        [TestCase("released")]
        public void D3BFinalMilestoneReportsPendingUntilHeldOrReleasedClaimIsAuthenticated(string outcome)
        {
            var f=new MultiClaimFixture();foreach(var waiter in f.Waiters)f.Coordinator.Retire(waiter);
            f.Arrive();var accounting=D3CaptureAccounting(f.Coordinator,f.Owner);
            var stages=new List<string>();var pendingStates=new List<bool>();
            void Record(string stage){stages.Add(stage);pendingStates.Add(f.Coordinator.HasPendingWork);}
            Assert.That(f.Coordinator.HasPendingWork,Is.True,"FIXTURE: the only remaining live work is the bound final leg");
            var completedInside=false;var suffixLengthInside=-1;

            var accepted=f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
            {
                completedInside=f.Completed;suffixLengthInside=((Vector3[])f.Read(f.Owner,"Journey")).Length;
                Record("confirm-enter");f.Confirm();
                if(outcome=="released"){f.Release("counter");f.Release("service");f.Release("pickup");}
                Record("confirm-return");return new D3BMilestoneWitness(f.Receipt(),Record);
            },out var pending);

            Assert.That(accepted,Is.True,"FIXTURE: the actual final arrival and real canonical milestone must authenticate");
            Assert.That(completedInside,Is.True);Assert.That(suffixLengthInside,Is.LessThanOrEqualTo(1));
            Assert.That(stages,Does.Contain("IsCurrent"));Assert.That(stages,Does.Contain("ReadClaim"));
            Assert.That(pendingStates.All(value=>value),Is.True,
                "PRODUCT: final-leg completion cannot report drain-ready while its canonical callback/claim result is still being authenticated");
            D3AssertAccounting(f.Coordinator,f.Owner,accounting);Assert.That(f.Coordinator.DrainReady(),Is.Empty);
            f.Refresh();Assert.That(f.World.Bodies.Single().ActorLife,Is.SameAs(f.Actor));
            if(outcome=="held")
            {
                Assert.That(pending,Is.Not.Null);Assert.That(f.Coordinator.HasPendingWork,Is.True);
                Assert.That(f.World.Parking,Is.Not.Empty);f.Coordinator.AbortPhaseHandoff(pending,"d3b-explicit-abort");
                Assert.That(f.Coordinator.HasPendingWork,Is.False,"An aborted handoff must not leave callback work behind");
                Assert.That(f.World.Parking,Is.Not.Empty,"Draining derived traffic does not erase actual canonical facts");
            }
            else
            {
                Assert.That(pending,Is.Null);Assert.That(f.World.Parking,Is.Empty);
                Assert.That(f.Coordinator.HasPendingWork,Is.False,"All claims actually Released: no remaining suffix, waiter, handoff or callback");
            }
            Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False,"The real final leg cannot replay");
        }

        [TestCase("reject")]
        [TestCase("throw")]
        [TestCase("retire")]
        [TestCase("close")]
        [TestCase("reset")]
        public void D3BFinalMilestoneLifecycleReentryCannotLeavePhantomDrainWork(string action)
        {
            var f=new HandoffFixture();f.Coordinator.Retire(f.Waiter);f.ArriveBody();
            var originalRequest=(TrafficRequest)f.Read(f.Owner,"Request");var queries=f.Coordinator.QueriesConsumed(f.Owner);
            var pendingBeforeAction=false;bool? pendingAfterAction=null;Exception resetError=null;
            var completedInside=false;var suffixLengthInside=-1;

            var accepted=f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
            {
                completedInside=f.LegCompleted;suffixLengthInside=((Vector3[])f.Read(f.Owner,"Journey")).Length;
                pendingBeforeAction=f.Coordinator.HasPendingWork;
                if(action=="reject")return null;
                if(action=="throw")throw new InvalidOperationException("Modeled canonical callback rejection");
                if(action=="retire")f.Coordinator.Retire(f.Owner);
                else if(action=="close")f.Coordinator.Close();
                else
                {
                    try{f.Coordinator.ResetLayout(2,8,World(2,2));}catch(Exception error){resetError=error;}
                }
                pendingAfterAction=f.Coordinator.HasPendingWork;return f.Confirm();
            },out var pending);

            Assert.That(completedInside,Is.True);Assert.That(suffixLengthInside,Is.LessThanOrEqualTo(1));
            Assert.That(pendingBeforeAction,Is.True,
                "PRODUCT: a live final canonical callback is still traffic work before an explicit lifecycle action");
            if(action=="reset")
            {
                Assert.That(resetError,Is.InstanceOf<InvalidOperationException>(),"Reset remains forbidden inside the existing joint-commit boundary");
                Assert.That(pendingAfterAction,Is.EqualTo(true));Assert.That(accepted,Is.True);Assert.That(pending,Is.Not.Null);
                Assert.That(f.Coordinator.HasPendingWork,Is.True);
                var freshWorld=World(2,2);f.Coordinator.ResetLayout(2,8,freshWorld);
                Assert.That(f.Coordinator.HasPendingWork,Is.False);Assert.That(D3ContainsIntent(f.Coordinator,f.Owner),Is.False);
                Assert.That(f.Coordinator.EvaluateMovement(originalRequest).Kind,Is.EqualTo(TrafficDecisionKind.StaleContext));
                var freshKey=Key("d3b-fresh-after-reset",layout:8,epoch:2);
                f.Coordinator.EvaluateMovement(Request(freshKey,Origin,P(2),freshWorld,frame:100));
                Assert.That(f.Coordinator.HasPendingWork,Is.True);f.Coordinator.ProcessReady(100);
                Assert.That(f.Coordinator.GetDecision(freshKey).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(f.Coordinator.DiscardPrepared(freshKey),Is.True);Assert.That(f.Coordinator.HasPendingWork,Is.False);
            }
            else
            {
                Assert.That(accepted,Is.False);Assert.That(pending,Is.Null);Assert.That(f.Coordinator.HasPendingWork,Is.False);
                if(action=="retire")
                {
                    Assert.That(pendingAfterAction,Is.EqualTo(false),"A retired callback owner must stop counting immediately");
                    D3AssertRetiredPayloadReleased(f.Coordinator,f.Owner);
                    Assert.That(f.Coordinator.EvaluateMovement(originalRequest),Is.SameAs(f.Coordinator.GetDecision(f.Owner)));
                }
                else if(action=="close")
                {
                    Assert.That(pendingAfterAction,Is.EqualTo(false));Assert.That(D3ContainsIntent(f.Coordinator,f.Owner),Is.False);
                    Assert.That(f.Coordinator.EvaluateMovement(originalRequest).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
                }
                else
                {
                    Assert.That(f.Coordinator.GetDecision(f.Owner).Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
                    Assert.That(f.Coordinator.GetDecision(f.Owner).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                    Assert.That(f.Read(f.Owner,"Retired"),Is.EqualTo(false));
                }
            }
            if(action!="close" && action!="reset")Assert.That(f.Coordinator.QueriesConsumed(f.Owner),Is.EqualTo(queries));
            Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False);
            Assert.That(f.Coordinator.DrainReady(),Is.Empty);
        }

        [TestCase("suspended")]
        [TestCase("discarded")]
        public void D3BSinglePointUnfinishedLegKeepsDrainPendingUntilStrictCompletion(string state)
        {
            var key=Key("d3b-point-"+state);var actor=new object();
            var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});
            var coordinator=Coordinator(world,query:(from,to)=>new[]{Origin});
            var source=Grant(coordinator,Request(key,Origin,Origin,world));var queries=coordinator.QueriesConsumed(key);
            var firstFrame=D1Read(coordinator,key,"FirstFrame");var requestSequence=source.RequestSequence;var acquiredSequence=source.AcquiredSequence;
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,1,world,Origin,.05f,2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            var generation=1;
            if(state=="suspended")
            {
                Assert.That(coordinator.TryCommit(coordinator.GetDecision(key)),Is.True);var stamp=new TrafficNativeStamp(711,1);
                Assert.That(coordinator.BindLeg(key,actor,stamp),Is.True);
                world=World(1,2,new[]{new TrafficBodyFact(key,Origin,.4f,false,actorLife:actor,actorActive:true)});coordinator.SetSnapshot(world);
                Assert.That(coordinator.SuspendLeg(key,actor,stamp,SuspendedResult(key,request:711),7),Is.True);
                generation=2;
            }
            else Assert.That(coordinator.DiscardPrepared(key),Is.True);

            Assert.That(((Vector3[])D1Read(coordinator,key,"Journey")).Length,Is.LessThanOrEqualTo(1),"FIXTURE: a nonempty long suffix cannot mask this unfinished single-point leg");
            Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(false));Assert.That(D1Read(coordinator,key,"Prepared"),Is.EqualTo(false));
            Assert.That(coordinator.HasActiveGrant(key),Is.False);Assert.That(D1Read(coordinator,key,"Retired"),Is.EqualTo(false));
            Assert.That(coordinator.GetDecision(key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(coordinator.HasPendingWork,Is.True,
                "PRODUCT: an unfinished suspended/reprepareable strict leg still needs real completion even when its proof is one point");
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(firstFrame));
            world=World(1,3,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});coordinator.SetSnapshot(world);
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,generation,world,Origin,.05f,3).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(3);var ready=coordinator.GetDecision(key);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(ready.RequestSequence,Is.EqualTo(requestSequence));Assert.That(ready.AcquiredSequence,Is.EqualTo(acquiredSequence));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries+(state=="suspended"?1:0)));
            Assert.That(coordinator.TryCommit(ready),Is.True);var finalStamp=new TrafficNativeStamp(712,generation);
            Assert.That(coordinator.BindLeg(key,actor,finalStamp),Is.True);Assert.That(coordinator.HasPendingWork,Is.True);
            Assert.That(coordinator.CompleteLeg(key,actor,finalStamp,Origin),Is.True);Assert.That(coordinator.HasPendingWork,Is.False);
            Assert.That(coordinator.CompleteLeg(key,actor,finalStamp,Origin),Is.False);coordinator.Retire(key);
            D3AssertRetiredPayloadReleased(coordinator,key);Assert.That(coordinator.HasPendingWork,Is.False);
        }

        // Delegates the actual fixture receipt; records existing public authentication seams only.
        // 所有 owner/source/claim 身份仍来自真实 fixture receipt；这里只记录现有接口内的状态。
        private sealed class D3BMilestoneWitness:ITrafficPhaseMilestone
        {
            private readonly ITrafficPhaseMilestone inner;private readonly Action<string> record;
            internal D3BMilestoneWitness(ITrafficPhaseMilestone inner,Action<string> record){this.inner=inner;this.record=record;}
            public TrafficDecision SourcePermit=>inner.SourcePermit;
            public TrafficParkingFact OriginalClaim=>inner.OriginalClaim;
            public TrafficParkingFact CurrentClaim=>inner.CurrentClaim;
            public object ActorLife=>inner.ActorLife;
            public object BusinessOwner=>inner.BusinessOwner;
            public object ReleaseObligation=>inner.ReleaseObligation;
            public TrafficPhaseMilestoneKind Kind=>inner.Kind;
            public bool IsCurrent { get { record("IsCurrent");return inner.IsCurrent; } }
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)
            {record("ReadClaim");return inner.ReadClaim(captured,out current);}
            public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision sourcePermit,int firstFrame)
                =>inner.AuthorizesSuccessor(successor,sourcePermit,firstFrame);
        }

        [Test] public void CounterAdvanceAnchorAcceptsActualOwnerVersionOnlyDriftWithoutRenewingFrontierOrSleepingWait()
        {
            foreach(var sleeping in new[]{false,true})
            {
                var key=Key("counter-own-version");var counter=new CounterQueueService(new[]{Origin,P(20)});
                Assert.That(counter.TryJoin(key.ActorId),Is.True);Assert.That(counter.TryCaptureAssignment(key.ActorId,out var claim),Is.True);
                var life=new object();var business=new object();var admission=new object();var blocker=Key("counter-wait-owner");
                var bodies=new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)}
                    .Concat(sleeping?new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8,actorLife:new object())}:Array.Empty<TrafficBodyFact>()).ToArray();
                TrafficParkingFact Own()=>new TrafficParkingFact(key,counter,counter.Version,"counter/"+key.ActorId,Origin,.4f,0,business,admission);
                var world=World(17,1,bodies,new[]{Own()});var calls=0;
                var coordinator=Coordinator(world,frameBudget:sleeping?128:1,query:(from,to)=>{calls++;return new[]{from,to};});
                var requirements=new[]{new TrafficRouteRequirement("unchanged-goal",P(20,10),P(22,10),.8f,new[]{P(20,20)},avoidProposedParking:false)};
                coordinator.EvaluateParking(CfcAnchorRequest(key,world,P(4),requirements:requirements));coordinator.ProcessReady(11);
                var expected=coordinator.GetDecision(key);
                Assert.That(expected.Kind,Is.EqualTo(sleeping?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.DeferredByBudget));
                if(sleeping)coordinator.Tick(2,false);
                var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();var index=D1Read(coordinator,key,"JobIndex");
                var first=D1Read(coordinator,key,"FirstFrame");var wait=D1Read(coordinator,key,"WaitRemaining");var queued=D1Read(coordinator,key,"Queued");
                var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
                var queries=coordinator.QueriesConsumed(key);var beforeCalls=calls;var version=counter.Version;
                Assert.That(counter.TryJoin("actual-tail"),Is.True);Assert.That(counter.Version,Is.GreaterThan(version));
                Assert.That(claim.IsCurrent,Is.True,"Actual same reservation survives another queue member's version change");
                var fresh=World(18,1,bodies,new[]{Own()});coordinator.SetSnapshot(fresh);var afterTail=counter.Version;
                Assert.That(CfcReprepare(coordinator,expected,CfcAnchorRequest(key,fresh,P(4),99,requirements),out var next),Is.True);
                Assert.That(CfcReprepare(coordinator,next,CfcAnchorRequest(key,fresh,P(4),99,requirements),out var identical),Is.True);
                Assert.That(identical,Is.SameAs(next));Assert.That(counter.Version,Is.EqualTo(afterTail));Assert.That(claim.IsCurrent,Is.True);
                Assert.That(calls,Is.EqualTo(beforeCalls));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
                Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(first));Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
                Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(wait));Assert.That(D1Read(coordinator,key,"FiniteLimit"),Is.EqualTo(20f));
                Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(0));Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(1));
                Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{0}));
                Assert.That(next.RequestSequence,Is.EqualTo(expected.RequestSequence));Assert.That(next.AcquiredSequence,Is.Zero);
                Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
                Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(queued));
                Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(index));var retained=(System.Collections.IList)D1Read(coordinator,key,"Jobs");
                Assert.That(retained.Count,Is.EqualTo(jobs.Length));for(var i=0;i<jobs.Length;i++)Assert.That(retained[i],Is.SameAs(jobs[i]));
                if(sleeping){coordinator.ProcessReady(12);Assert.That(calls,Is.EqualTo(beforeCalls));Assert.That(coordinator.GetDecision(key),Is.SameAs(next));}
            }
        }

        [Test] public void CounterAdvanceOwnClaimVersionDriftStillCannotUseD2QueuedPort()
        {
            var key=Key("counter-d2-version");var counter=new CounterQueueService(new[]{Origin,P(20)});
            Assert.That(counter.TryJoin(key.ActorId),Is.True);Assert.That(counter.TryCaptureAssignment(key.ActorId,out var claim),Is.True);
            var life=new object();var business=new object();var admission=new object();var bodies=new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)};
            TrafficParkingFact Own()=>new TrafficParkingFact(key,counter,counter.Version,"counter/"+key.ActorId,Origin,.4f,0,business,admission);
            var world=World(17,1,bodies,new[]{Own()});var calls=0;var coordinator=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            var source=D2QueuedRequest(key,world);var expected=coordinator.EvaluateParking(source);
            Assert.That(counter.TryJoin("actual-tail"),Is.True);Assert.That(claim.IsCurrent,Is.True);var version=counter.Version;
            var fresh=World(18,1,bodies,new[]{Own()});coordinator.SetSnapshot(fresh);
            Assert.That(D2Refresh(coordinator,expected,D2FreshRequest(source,fresh),out var next),Is.False,"D2 exact own-claim version guard is unchanged");
            Assert.That(next,Is.Null);Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(source));Assert.That(coordinator.GetDecision(key),Is.SameAs(expected));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(coordinator,key,"FiniteLimit"),Is.EqualTo(20f));
            Assert.That(counter.Version,Is.EqualTo(version));Assert.That(calls,Is.Zero);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);Assert.That(expected.AcquiredSequence,Is.Zero);
        }

        private static TrafficRequest D2MovementRequest(TrafficIntentKey key,TrafficWorldSnapshot world,
            IEnumerable<Vector3> obstacles=null,TrafficDecisionKind? failure=null)
            =>new TrafficRequest(key,11,world,Origin,P(4),.4f,"movement/"+key.ActorId,
                requirements:new[]{new TrafficRouteRequirement("work-clearance",P(20),P(24),.8f,obstacles,
                    avoidProposedParking:false)},finiteSeconds:20,provenFailure:failure,planPrimaryRoute:true);

        [TestCase("compatible-frontier")] [TestCase("changed-obstacles")]
        [TestCase("identical-noop")] [TestCase("notified-waiter")]
        public void D2UnissuedMovementRefreshPreservesOriginalPreparation(string scenario)
        {
            var key=Key("d2-unissued-movement");var life=new object();var blocker=Key("movement-release");
            var waiting=scenario=="notified-waiter";
            var bodies=new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)}
                .Concat(waiting?new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8,actorLife:new object())}:Array.Empty<TrafficBodyFact>()).ToArray();
            var world=World(17,1,bodies);var calls=0;
            var coordinator=Coordinator(world,frameBudget:1,query:(from,to)=>{calls++;return new[]{from,to};});
            coordinator.EvaluateMovement(D2MovementRequest(key,world,new[]{P(30,30)}));coordinator.ProcessReady(11);
            Assert.That(D1Read(coordinator,key,"Parking"),Is.EqualTo(false),"Real Movement submission, not a parking fixture");
            var expected=coordinator.GetDecision(key);
            Assert.That(expected.Kind,Is.EqualTo(waiting?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.DeferredByBudget));
            if(waiting){coordinator.Tick(2,false);coordinator.NotifyChanged(blocker,"body");}
            Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(true));Assert.That(expected.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            var source=(TrafficRequest)D1Read(coordinator,key,"Request");
            var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();var index=D1Read(coordinator,key,"JobIndex");
            var fields=new[]{"FirstFrame","RequestSequence","AcquiredSequence","FiniteLimit","WaitRemaining","CurrentIndex","CandidateCount","Queued"};
            var before=fields.Select(n=>D1Read(coordinator,key,n)).ToArray();
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
            var queries=coordinator.QueriesConsumed(key);var beforeCalls=calls;
            if(waiting)Assert.That(((IReadOnlyList<TrafficBlocker>)edges).Any(b=>b.Owner.Equals(blocker)),Is.True);
            else Assert.That(jobs,Is.Not.Empty,"Authentic partially spent primary/proof frontier");
            var fresh=scenario=="identical-noop"?world:World(18,2,bodies);coordinator.SetSnapshot(fresh);
            var requirements=scenario=="changed-obstacles"?new[]{new TrafficRouteRequirement("work-clearance",P(20),P(24),.8f,
                new[]{P(40,30)},avoidProposedParking:false)}:source.Requirements;
            var request=D2FreshRequest(source,fresh,requirements:requirements);
            TestContext.WriteLine("D2_MOVEMENT_MODEL scenario="+scenario+" expected=True actualMovement=True queries="+queries);
            Assert.That(D2Refresh(coordinator,expected,request,out var next),Is.True,"D2 MOVEMENT FEATURE RED: original unissued Movement metadata must refresh");
            Assert.That(next,Is.SameAs(expected));Assert.That(D2Refresh(coordinator,next,request,out var again),Is.True);
            Assert.That(again,Is.SameAs(next));Assert.That(calls,Is.EqualTo(beforeCalls));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            CollectionAssert.AreEqual(before,fields.Select(n=>D1Read(coordinator,key,n)).ToArray());
            var retained=(TrafficRequest)D1Read(coordinator,key,"Request");Assert.That(retained.RequestedFrame,Is.EqualTo(11));Assert.That(retained.Snapshot,Is.SameAs(fresh));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{0}));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(coordinator.HasActiveGrant(key),Is.False);
            var after=(System.Collections.IList)D1Read(coordinator,key,"Jobs");
            if(scenario=="changed-obstacles")Assert.That(after,Is.Empty,"Changed proof inputs need ordinary bounded reproof");
            else {CollectionAssert.AreEqual(jobs,after);Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(index));}
            if(waiting)return;
            coordinator.ProcessReady(12);coordinator.ProcessReady(13);
            var granted=coordinator.GetDecision(key);Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted),granted.Reason);
            Assert.That(coordinator.TryCommit(granted),Is.True);var acquired=coordinator.GetDecision(key).AcquiredSequence;
            Assert.That(acquired,Is.GreaterThan(0));Assert.That(coordinator.TryCommit(granted),Is.False);
            Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.EqualTo(acquired));
        }

        [TestCase("external-phase-handoff")]
        [TestCase("far-canonical-birth")]
        public void PaidLikeInitialMovementUsesExistingQueuedPortBeforeCanonicalChangeIsProcessed(string scenario)
        {
            var key=Key("paid-like-customer","pickup-paid-movement",17);var bodyOwner=Key(key.ActorId,"counter-admission",7);
            var life=new object();var business=new object();var admission=new object();
            var counter=new CounterQueueService(new[]{Origin,P(-4)});Assert.That(counter.TryJoin(key.ActorId),Is.True);
            Assert.That(counter.TryCaptureAssignment(key.ActorId,out var counterClaim),Is.True);
            var pickup=new PickupQueueService(new[]{P(4)},new[]{P(4,2)});Assert.That(pickup.TryReserve(key.ActorId,out var reservation),Is.True);
            Assert.That(pickup.TryCaptureReservation(key.ActorId,out var pickupClaim),Is.True);
            var ownBody=new TrafficBodyFact(bodyOwner,Origin,.4f,actorLife:life);
            var ownClaims=new[]{new TrafficParkingFact(bodyOwner,counter,counter.Version,"counter/"+key.ActorId,counterClaim.Assignment.Position,.4f,businessOwner:business,releaseObligation:admission),
                new TrafficParkingFact(bodyOwner,pickup,pickup.Version,"pickup/"+key.ActorId,reservation.Position,.4f,businessOwner:business,releaseObligation:admission)};
            var otherBefore=Key("external-paid-probe","pickup-service",11);var otherAfter=Key(otherBefore.ActorId,"actual-exit",14);
            var otherLife=new object();var otherBusiness=new object();var otherOwner=new CanonicalOwner();var handoff=scenario=="external-phase-handoff";
            ITrafficMutationReceipt otherReceipt=null;if(handoff)Assert.That(otherOwner.Prepare().TryApply(out otherReceipt),Is.True);
            var bodies=new List<TrafficBodyFact>{ownBody};var claims=new List<TrafficParkingFact>(ownClaims);
            if(handoff)
            {bodies.Add(new TrafficBodyFact(otherBefore,P(-8,-8),.4f,actorLife:otherLife));claims.Add(new TrafficParkingFact(otherBefore,otherOwner,otherOwner.Version,"external/slot",P(-8,-8),.4f,businessOwner:otherBusiness,releaseObligation:otherReceipt));}
            var world=World(17,1,bodies.ToArray(),claims.ToArray());var calls=0;
            var coordinator=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            // Commit the external phase before queuing this request; its own query count must still be exactly zero.
            // 外部真实 Core phase 先获权；不提前处理被测 paid-like 请求，不伪造 Entry/Native 状态。
            if(handoff){var other=Grant(coordinator,Request(otherAfter,P(-8,-8),P(-7,-8),world,frame:1,resource:"external-exit",seconds:13));Assert.That(other.AcquiredSequence,Is.GreaterThan(0));}
            var request=D2MovementRequest(key,world,new[]{P(30,30)});var expected=coordinator.EvaluateMovement(request);
            Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(D1Read(coordinator,key,"Parking"),Is.False);
            Assert.That(D1Read(coordinator,key,"Queued"),Is.True);Assert.That(D1Read(coordinator,key,"Leg"),Is.Null);Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.Null);
            Assert.That(expected.AcquiredSequence,Is.Zero);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);Assert.That(D1Read(coordinator,key,"PreparationBody"),Is.SameAs(ownBody));
            var accounting=D3CaptureAccounting(coordinator,key);var callCount=calls;var counterVersion=counter.Version;var pickupVersion=pickup.Version;
            var jobs=D1Read(coordinator,key,"Jobs");var edges=D1Read(coordinator,key,"WaitingBlockers");
            if(handoff)
            {
                bodies[1]=new TrafficBodyFact(otherAfter,P(-8,-8),.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:otherLife);
                var prior=claims[2];claims[2]=new TrafficParkingFact(otherAfter,prior.CanonicalOwner,prior.OwnerVersion,prior.ResourceId,prior.Position,prior.Radius,prior.SafetyMargin,prior.BusinessOwner,prior.ReleaseObligation);
            }
            else
            {
                Assert.That(otherOwner.Prepare().TryApply(out otherReceipt),Is.True);
                bodies.Add(new TrafficBodyFact(otherBefore,P(-8,-8),.4f,actorLife:otherLife));
                claims.Add(new TrafficParkingFact(otherBefore,otherOwner,otherOwner.Version,"external/slot",P(-8,-8),.4f,businessOwner:otherBusiness,releaseObligation:otherReceipt));
            }
            var current=World(18,2,bodies.ToArray(),claims.ToArray());coordinator.SetSnapshot(current);
            Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request),"No implicit canonical refresh is assumed or requested");
            Assert.That(counterClaim.IsCurrent && pickupClaim.IsCurrent,Is.True);Assert.That(counter.Version,Is.EqualTo(counterVersion));Assert.That(pickup.Version,Is.EqualTo(pickupVersion));
            var fresh=D2FreshRequest(request,current);
            Assert.That(D2Refresh(coordinator,expected,fresh,out var next),Is.True,"Existing typed port must accept exact own identity and changed external world before first Evaluate");
            Assert.That(next,Is.SameAs(expected));Assert.That(D2Refresh(coordinator,next,fresh,out var identical),Is.True);Assert.That(identical,Is.SameAs(expected));
            D3AssertAccounting(coordinator,key,accounting);Assert.That(calls,Is.EqualTo(callCount));Assert.That(coordinator.QueriesConsumed(key),Is.Zero);
            Assert.That(D1Read(coordinator,key,"Jobs"),Is.SameAs(jobs));Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));
            var retained=(TrafficRequest)D1Read(coordinator,key,"Request");Assert.That(retained.Snapshot,Is.SameAs(current));Assert.That(retained.RequestedFrame,Is.EqualTo(11));Assert.That(retained.Intent,Is.EqualTo(key));
            Assert.That(retained.Start,Is.EqualTo(request.Start));Assert.That(retained.Target,Is.EqualTo(request.Target));Assert.That(retained.FiniteSeconds,Is.EqualTo(20f));
            coordinator.ProcessReady(12);var prepared=coordinator.GetDecision(key);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),prepared.Reason);
            Assert.That(prepared.RequestSequence,Is.GreaterThan(0),"The original sequence is first assigned by this normal batch, not by refresh");Assert.That(prepared.AcquiredSequence,Is.Zero);
            var unchanged=accounting.Where(pair=>pair.Key!="Queries" && pair.Key!="RequestSequence").ToDictionary(pair=>pair.Key,pair=>pair.Value);D3AssertAccounting(coordinator,key,unchanged);
            Assert.That(coordinator.QueriesConsumed(key),Is.GreaterThan(0));Assert.That(coordinator.QueriesConsumed(key),Is.LessThanOrEqualTo((int)D3ReadField(coordinator,"queriesPerIntent")));
            Assert.That(D1Read(coordinator,key,"Leg"),Is.Null);var sequence=prepared.RequestSequence;var queries=coordinator.QueriesConsumed(key);
            Assert.That(coordinator.TryCommit(prepared),Is.True);var acquired=prepared.AcquiredSequence;Assert.That(acquired,Is.GreaterThan(0));Assert.That(coordinator.TryCommit(prepared),Is.False);
            Assert.That(coordinator.GetDecision(key).RequestSequence,Is.EqualTo(sequence));Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.EqualTo(acquired));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
            Assert.That(counterClaim.IsCurrent && pickupClaim.IsCurrent,Is.True);Assert.That(counter.Version,Is.EqualTo(counterVersion));Assert.That(pickup.Version,Is.EqualTo(pickupVersion));
            Assert.That(otherOwner.Applies,Is.EqualTo(1));Assert.That(otherOwner.Rollbacks,Is.Zero);
        }

        [TestCase("other-counter-arrival")]
        [TestCase("current-target-blocker")]
        [TestCase("counter-remove-rejoin")]
        [TestCase("counter-front-exit")]
        [TestCase("counter-restart")]
        [TestCase("pickup-transfer")]
        [TestCase("null-checkpoint")]
        [TestCase("untyped-checkpoint")]
        [TestCase("version-regression")]
        public void PaidInitialMovementRefreshRequiresOriginalQueueClaimSemantics(string scenario)
        {
            var key=Key("paid-checkpoint","pickup-paid-movement",17);var owner=Key(key.ActorId,"counter-admission",7);
            var life=new object();var business=new object();var admission=new object();
            var counter=new CounterQueueService(new[]{Origin,P(-4)});
            Assert.That(counter.TryJoin(key.ActorId),Is.True);Assert.That(counter.Complete(key.ActorId,1),Is.True);
            Assert.That(counter.TryJoin("other-counter-customer"),Is.True);
            Assert.That(counter.TryCaptureAssignment(key.ActorId,out var oldCounter),Is.True);
            Assert.That(counter.TryCaptureAssignment("other-counter-customer",out var otherCounter),Is.True);
            var pickup=new PickupQueueService(new[]{P(4)},new[]{P(4,2)});
            Assert.That(pickup.TryReserve(key.ActorId,out var reservation),Is.True);
            Assert.That(pickup.TryCaptureReservation(key.ActorId,out var oldPickup),Is.True);
            var counterVersion=counter.Version;var pickupVersion=pickup.Version;var unknownCounter=new object();var unknownPickup=new object();
            // Real Queue claims occupy the existing optional field; no production API/stub is invented.
            // 真实旧 Claim 在首次 Submit 前捕获；未来 typed 合同须辨别 Entry、phase 与显式 restart。
            object Checkpoint(object claim,bool isCounter)=>scenario=="null-checkpoint"?null:
                scenario=="untyped-checkpoint"?(isCounter?unknownCounter:unknownPickup):claim;
            TrafficParkingFact CounterFact(CounterQueueService.AssignmentClaim claim,long version)=>new TrafficParkingFact(
                owner,counter,version,"counter/"+key.ActorId,claim.Assignment.Position,.4f,businessOwner:business,
                releaseObligation:admission,semanticCheckpoint:Checkpoint(claim,true));
            TrafficParkingFact PickupFact(PickupQueueService.ReservationClaim claim)=>new TrafficParkingFact(
                owner,pickup,pickup.Version,"pickup/"+key.ActorId,claim.Assignment.Position,.4f,businessOwner:business,
                releaseObligation:admission,semanticCheckpoint:Checkpoint(claim,false));
            var ownBody=new TrafficBodyFact(owner,Origin,.4f,actorLife:life);
            var world=World(17,1,new[]{ownBody},new[]{CounterFact(oldCounter,counterVersion),PickupFact(oldPickup)});
            var calls=0;var coordinator=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            var request=D2MovementRequest(key,world,new[]{P(30,30)});var expected=coordinator.EvaluateMovement(request);
            Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(expected.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(coordinator,key,"Queued"),Is.True);Assert.That(D1Read(coordinator,key,"Parking"),Is.False);
            Assert.That(D1Read(coordinator,key,"Leg"),Is.Null);Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.Null);
            var accounting=D3CaptureAccounting(coordinator,key);var edges=D1Read(coordinator,key,"WaitingBlockers");
            Assert.That(calls,Is.Zero);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);
            if(scenario=="counter-remove-rejoin")
            {
                Assert.That(counter.Remove("other-counter-customer"),Is.True);Assert.That(counter.Remove(key.ActorId),Is.True);
                Assert.That(counter.TryJoin(key.ActorId),Is.True);Assert.That(counter.Complete(key.ActorId,1),Is.True);
                Assert.That(counter.TryJoin("other-counter-customer"),Is.True);
            }
            else if(scenario=="counter-front-exit")
            {Assert.That(counter.TryBeginFrontExit(out var leaving),Is.True);Assert.That(leaving,Is.EqualTo(key.ActorId));}
            else if(scenario=="counter-restart")counter.RestartAssignments();
            else if(scenario=="pickup-transfer")
            {Assert.That(pickup.TryBeginTransfer(key.ActorId,out var transferred),Is.True);Assert.That(transferred.Generation,Is.GreaterThan(reservation.Generation));}
            else Assert.That(counter.Complete("other-counter-customer",otherCounter.Assignment.Generation),Is.True);
            Assert.That(counter.TryCaptureAssignment(key.ActorId,out var currentCounter),Is.True);
            Assert.That(pickup.TryCaptureReservation(key.ActorId,out var currentPickup),Is.True);
            // ABA uses equal public assignment values but a different actual Entry. Restart deliberately keeps own values equal.
            // 不私写 Entry；真实 remove/rejoin、front-exit、restart、Transfer 分别产生拒绝前提。
            Assert.That(currentCounter.Assignment.VisitId,Is.EqualTo(oldCounter.Assignment.VisitId));
            Assert.That(currentCounter.Assignment.Generation,Is.EqualTo(oldCounter.Assignment.Generation));
            Assert.That(currentCounter.Assignment.SlotIndex,Is.EqualTo(oldCounter.Assignment.SlotIndex));
            Assert.That(currentCounter.Assignment.Position,Is.EqualTo(oldCounter.Assignment.Position));
            Assert.That(currentCounter.Assignment.Arrived,Is.EqualTo(oldCounter.Assignment.Arrived));
            Assert.That(oldCounter.IsSameReservation(currentCounter),Is.EqualTo(scenario!="counter-remove-rejoin"));
            Assert.That(oldPickup.IsSameReservation(currentPickup),Is.True);
            Assert.That(oldPickup.IsCurrent,Is.EqualTo(scenario!="pickup-transfer"));
            if(scenario!="pickup-transfer")Assert.That(counter.Version,Is.GreaterThan(counterVersion));
            else Assert.That(pickup.Version,Is.GreaterThan(pickupVersion));
            var bodies=new List<TrafficBodyFact>{ownBody};
            if(scenario=="current-target-blocker")bodies.Add(new TrafficBodyFact(Key("new-target-body"),request.Target,.4f,actorLife:new object()));
            // The rollback case is an explicitly stale public snapshot DTO, never a mutation of the canonical Queue version.
            var reportedVersion=scenario=="version-regression"?counterVersion-1:counter.Version;
            var current=World(18,2,bodies.ToArray(),new[]{CounterFact(currentCounter,reportedVersion),PickupFact(currentPickup)});
            coordinator.SetSnapshot(current);Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request));
            var expectedRefresh=scenario=="other-counter-arrival" || scenario=="current-target-blocker";
            var result=D2Refresh(coordinator,expected,D2FreshRequest(request,current),out var next);
            TestContext.WriteLine("PAID_CLAIM_CHECKPOINT scenario="+scenario+" counterVersion="+counterVersion+"->"+counter.Version+
                " sameEntry="+oldCounter.IsSameReservation(currentCounter)+" oldClaimCurrent="+oldCounter.IsCurrent+" expectedRefresh="+expectedRefresh);
            Assert.That(result,Is.EqualTo(expectedRefresh),"FEATURE: unrelated Queue metadata requires original typed claim semantics, not a global version bypass");
            D3AssertAccounting(coordinator,key,accounting);Assert.That(calls,Is.Zero);Assert.That(coordinator.QueriesConsumed(key),Is.Zero);
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(expected.AcquiredSequence,Is.Zero);
            if(!expectedRefresh)
            {
                Assert.That(next,Is.Null);Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request));Assert.That(coordinator.GetDecision(key),Is.SameAs(expected));
                Assert.That(coordinator.TryCommit(expected),Is.False);return;
            }
            Assert.That(next,Is.SameAs(expected));var retained=(TrafficRequest)D1Read(coordinator,key,"Request");
            Assert.That(retained.Snapshot,Is.SameAs(current));Assert.That(retained.Intent,Is.EqualTo(key));Assert.That(retained.RequestedFrame,Is.EqualTo(11));
            Assert.That(retained.Start,Is.EqualTo(request.Start));Assert.That(retained.Target,Is.EqualTo(request.Target));Assert.That(retained.FiniteSeconds,Is.EqualTo(20f));
            var counterAfter=counter.Version;var pickupAfter=pickup.Version;
            Assert.That(D2Refresh(coordinator,next,D2FreshRequest(request,current),out var identical),Is.True);Assert.That(identical,Is.SameAs(next));
            D3AssertAccounting(coordinator,key,accounting);Assert.That(calls,Is.Zero);
            coordinator.ProcessReady(12);var prepared=coordinator.GetDecision(key);
            var stable=accounting.Where(pair=>pair.Key!="Queries" && pair.Key!="RequestSequence").ToDictionary(pair=>pair.Key,pair=>pair.Value);
            D3AssertAccounting(coordinator,key,stable);Assert.That(prepared.RequestSequence,Is.GreaterThan(0));Assert.That(prepared.AcquiredSequence,Is.Zero);
            if(scenario=="current-target-blocker")
            {
                Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),prepared.Reason);
                Assert.That(prepared.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(coordinator.TryCommit(prepared),Is.False);
                Assert.That(calls,Is.Zero,"Current endpoint body is checked before route queries");
            }
            else
            {
                Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),prepared.Reason);Assert.That(calls,Is.GreaterThan(0));
                Assert.That(coordinator.QueriesConsumed(key),Is.LessThanOrEqualTo((int)D3ReadField(coordinator,"queriesPerIntent")));
                var sequence=prepared.RequestSequence;var queries=coordinator.QueriesConsumed(key);var commits=0;
                Assert.That(coordinator.TryCommit(prepared,null,()=>commits++),Is.True);Assert.That(coordinator.TryCommit(prepared,null,()=>commits++),Is.False);
                Assert.That(commits,Is.EqualTo(1));Assert.That(prepared.AcquiredSequence,Is.GreaterThan(0));
                Assert.That(coordinator.GetDecision(key).RequestSequence,Is.EqualTo(sequence));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            }
            Assert.That(counter.Version,Is.EqualTo(counterAfter));Assert.That(pickup.Version,Is.EqualTo(pickupAfter));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
        }

        [TestCase("terminal")] [TestCase("acquired")] [TestCase("strict-leg")]
        [TestCase("canonical-attempt")] [TestCase("actor-life")] [TestCase("target-proof")]
        public void D2UnissuedMovementRefreshRejectsProtectedSources(string scenario)
        {
            var key=Key("d2-movement-protected");var life=new object();var calls=0;
            var world=World(17,1,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)});
            var coordinator=Coordinator(world,query:(from,to)=>{calls++;return new[]{from,to};});
            var source=D2MovementRequest(key,world,failure:scenario=="terminal"?TrafficDecisionKind.InvalidStart:(TrafficDecisionKind?)null);
            var expected=coordinator.EvaluateMovement(source);
            Assert.That(D1Read(coordinator,key,"Parking"),Is.EqualTo(false));
            if(scenario!="actor-life" && scenario!="target-proof")
            {
                coordinator.ProcessReady(11);expected=coordinator.GetDecision(key);
                if(scenario=="terminal")Assert.That(expected.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                else
                {
                    Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                    if(scenario=="canonical-attempt")
                    {Assert.That(coordinator.TryCommit(expected,new PreparationCanonicalFailure("apply-false")),Is.False);Assert.That(D1Read(coordinator,key,"EverCanonicalAttempt"),Is.EqualTo(true));}
                    else
                    {
                        Assert.That(coordinator.TryCommit(expected),Is.True);Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.GreaterThan(0));
                        if(scenario=="strict-leg")
                        {coordinator.PrepareLeg(expected,source.ResourceId,0,life,1,world,Origin,.05f,12);Assert.That(D1Read(coordinator,key,"Leg"),Is.Not.Null,"Real committed Movement primary produces its strict leg");}
                    }
                    expected=coordinator.GetDecision(key);
                }
            }
            var fresh=World(18,2,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:scenario=="actor-life"?new object():life)});
            coordinator.SetSnapshot(fresh);source=(TrafficRequest)D1Read(coordinator,key,"Request");
            var request=D2FreshRequest(source,fresh,target:scenario=="target-proof"?P(5):(Vector3?)null,
                requirements:scenario=="target-proof"?new[]{new TrafficRouteRequirement("changed-role",P(20),P(24),.8f,avoidProposedParking:false)}:null);
            var fields=new[]{"FirstFrame","RequestSequence","AcquiredSequence","WaitRemaining","FiniteLimit","CurrentIndex","CandidateCount","Queued","Prepared","Active","Retired"};
            var before=fields.Select(n=>D1Read(coordinator,key,n)).ToArray();var queries=coordinator.QueriesConsumed(key);var beforeCalls=calls;
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
            var leg=D1Read(coordinator,key,"Leg");var permit=D1Read(coordinator,key,"JourneyPermit");var attempted=((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices")).ToArray();
            TestContext.WriteLine("D2_MOVEMENT_MODEL protected="+scenario+" actualPremise=True deeperGuard=NOT_PROVEN_UNTIL_POSITIVE_PORT_GREEN");
            Assert.That(D2Refresh(coordinator,expected,request,out var rejected),Is.False);Assert.That(rejected,Is.Null);
            Assert.That(coordinator.GetDecision(key),Is.SameAs(expected));Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(source));
            CollectionAssert.AreEqual(before,fields.Select(n=>D1Read(coordinator,key,n)).ToArray());
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(calls,Is.EqualTo(beforeCalls));
            Assert.That(D1Read(coordinator,key,"Leg"),Is.SameAs(leg));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(permit));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(attempted));
        }

        private static bool RevokePhysicalPreparation(ServiceTrafficCoordinator coordinator,TrafficDecision expected,out TrafficDecision next)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryRevokePhysicalPreparedPreparation",
                System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"Physical revoke M1 declaration exists");
            var args=new object[]{expected,null};var accepted=(bool)method.Invoke(coordinator,args);next=(TrafficDecision)args[1];return accepted;
        }

        [TestCase("movement")] [TestCase("parking")]
        public void PhysicalPreparedRevocationPreservesOriginalPreparation(string kind)
        {
            var key=Key("physical-revoke");var blocker=Key("physical-finite-owner");var life=new object();var queries=0;
            var own=new TrafficBodyFact(key,Origin,.4f,actorLife:life);
            var world=World(17,1,new[]{own,new TrafficBodyFact(blocker,P(4),.4f,true,true,8,actorLife:new object())});
            var coordinator=Coordinator(world,query:(from,to)=>{queries++;return new[]{from,to};});
            var initial=D2MovementRequest(key,world);
            if(kind=="parking")coordinator.EvaluateParking(initial,1,4);else coordinator.EvaluateMovement(initial,1,4);
            coordinator.ProcessReady(11);var waiting=coordinator.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"Actual finite blocker establishes historical wait");
            var initialWait=(float)D1Read(coordinator,key,"WaitRemaining");coordinator.Tick(2,false);
            var spentWait=(float)D1Read(coordinator,key,"WaitRemaining");Assert.That(spentWait,Is.GreaterThan(0).And.LessThan(initialWait));
            var released=World(18,2,new[]{own});coordinator.SetSnapshot(released);coordinator.NotifyChanged(blocker,"body");
            Assert.That(D2Refresh(coordinator,waiting,D2FreshRequest(initial,released),out var queued),Is.True,"Existing queued refresh follows actual modeled body release");
            coordinator.ProcessReady(12);var expected=coordinator.GetDecision(key);
            Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(expected.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(coordinator,key,"Parking"),Is.EqualTo(kind=="parking"));Assert.That(D1Read(coordinator,key,"Prepared"),Is.EqualTo(true));
            var source=(TrafficRequest)D1Read(coordinator,key,"Request");var frozen=D1Read(coordinator,key,"FrozenOwners");
            var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
            Assert.That(((System.Collections.IEnumerable)frozen).Cast<object>(),Is.Not.Empty);
            Assert.That(((System.Collections.IEnumerable)resources).Cast<object>(),Is.Not.Empty);
            Assert.That((float)D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(spentWait));Assert.That(queries,Is.GreaterThan(0));
            var fields=new[]{"FirstFrame","RequestSequence","AcquiredSequence","FiniteLimit","WaitRemaining","CurrentIndex","CandidateCount","Parking"};
            var before=fields.Select(n=>D1Read(coordinator,key,n)).ToArray();var beforeQueries=queries;var consumed=coordinator.QueriesConsumed(key);
            var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();var index=D1Read(coordinator,key,"JobIndex");
            var path=D1Read(coordinator,key,"CurrentPath");Assert.That(jobs,Is.Not.Empty);
            var fresh=World(19,3,new[]{own});coordinator.SetSnapshot(fresh);var refreshed=D2FreshRequest(source,fresh);
            Assert.That(D2Refresh(coordinator,expected,refreshed,out _),Is.False,"Original D2 prepared-source rejection remains exact");
            Assert.That(CfcCancelPreparation(coordinator,expected),Is.False,"Original A cancellation remains unborn/bodyless-only");
            TestContext.WriteLine("PHYSICAL_REVOKE_MODEL source="+kind+" expected=True actualPrepared=True spentWait="+spentWait+" historicalFrozen=True queries="+consumed);
            Assert.That(RevokePhysicalPreparation(coordinator,expected,out var next),Is.True,"PHYSICAL REVOKE FEATURE RED: stale physical prepared authority must revoke without renewing the source");
            Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(next.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(coordinator.GetDecision(key),Is.SameAs(next));Assert.That(next.RequestSequence,Is.EqualTo(expected.RequestSequence));Assert.That(next.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(coordinator,key,"Prepared"),Is.EqualTo(false));Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(true));Assert.That(D1Read(coordinator,key,"Active"),Is.EqualTo(false));
            Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(source),"Revocation alone cannot adopt metadata");
            CollectionAssert.AreEqual(before,fields.Select(n=>D1Read(coordinator,key,n)).ToArray());
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"CurrentPath"),Is.SameAs(path));
            Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(index));CollectionAssert.AreEqual(jobs,(System.Collections.IList)D1Read(coordinator,key,"Jobs"));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{1}));
            var canonical=new CanonicalOwner();Assert.That(coordinator.TryCommit(expected,canonical.Prepare()),Is.False,"Revoked old Granted cannot commit");
            Assert.That(canonical.Applies,Is.Zero);Assert.That(queries,Is.EqualTo(beforeQueries));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(consumed));
            Assert.That(D2Refresh(coordinator,next,refreshed,out var refreshedDecision),Is.True,"Only the existing queued port adopts authenticated metadata");
            Assert.That(refreshedDecision,Is.SameAs(next));Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
            CollectionAssert.AreEqual(before,fields.Select(n=>D1Read(coordinator,key,n)).ToArray());
            CollectionAssert.AreEqual(jobs,(System.Collections.IList)D1Read(coordinator,key,"Jobs"));Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(index));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(queries,Is.EqualTo(beforeQueries));Assert.That(canonical.Applies,Is.Zero);
            coordinator.ProcessReady(13);var granted=coordinator.GetDecision(key);Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(coordinator.TryCommit(granted,canonical.Prepare()),Is.True);Assert.That(canonical.Applies,Is.EqualTo(1));
            Assert.That(coordinator.TryCommit(granted,canonical.Prepare()),Is.False);Assert.That(canonical.Applies,Is.EqualTo(1));
        }

        [TestCase("fresh")] [TestCase("acquired")] [TestCase("strict-leg")] [TestCase("actor-life")]
        public void PhysicalPreparedRevocationRejectsProtectedSources(string scenario)
        {
            var key=Key("physical-revoke-protected");var life=new object();var queries=0;
            var world=World(17,1,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)});
            var coordinator=Coordinator(world,query:(from,to)=>{queries++;return new[]{from,to};});var request=D2MovementRequest(key,world);
            coordinator.EvaluateMovement(request);coordinator.ProcessReady(11);var expected=coordinator.GetDecision(key);
            Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(expected.AcquiredSequence,Is.Zero);
            if(scenario=="acquired" || scenario=="strict-leg")
            {
                Assert.That(coordinator.TryCommit(expected),Is.True);Assert.That(coordinator.HasActiveGrant(key),Is.True);
                if(scenario=="strict-leg")
                {coordinator.PrepareLeg(expected,request.ResourceId,0,life,1,world,Origin,.05f,12);coordinator.ProcessReady(12);Assert.That(D1Read(coordinator,key,"Leg"),Is.Not.Null);}
                expected=coordinator.GetDecision(key);Assert.That(expected.AcquiredSequence,Is.GreaterThan(0));
            }
            if(scenario!="fresh")coordinator.SetSnapshot(World(18,2,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:scenario=="actor-life"?new object():life)}));
            var fields=new[]{"FirstFrame","RequestSequence","AcquiredSequence","FiniteLimit","WaitRemaining","CurrentIndex","CandidateCount","Parking","Prepared","Queued","Active","Retired"};
            var before=fields.Select(n=>D1Read(coordinator,key,n)).ToArray();var source=D1Read(coordinator,key,"Request");var queriesBefore=queries;
            var consumed=coordinator.QueriesConsumed(key);var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();
            var path=D1Read(coordinator,key,"CurrentPath");var index=D1Read(coordinator,key,"JobIndex");
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
            var leg=D1Read(coordinator,key,"Leg");var permit=D1Read(coordinator,key,"JourneyPermit");
            TestContext.WriteLine("PHYSICAL_REVOKE_MODEL protected="+scenario+" authenticState=True deeperGuard=NOT_PROVEN_UNTIL_POSITIVES_GREEN");
            for(var poll=0;poll<(scenario=="fresh"?3:1);poll++)
            {Assert.That(RevokePhysicalPreparation(coordinator,expected,out var rejected),Is.False);Assert.That(rejected,Is.Null);}
            Assert.That(coordinator.GetDecision(key),Is.SameAs(expected));Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(source));
            CollectionAssert.AreEqual(before,fields.Select(n=>D1Read(coordinator,key,n)).ToArray());
            CollectionAssert.AreEqual(jobs,(System.Collections.IList)D1Read(coordinator,key,"Jobs"));Assert.That(D1Read(coordinator,key,"CurrentPath"),Is.SameAs(path));Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(index));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"Leg"),Is.SameAs(leg));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(permit));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{0}));
            Assert.That(queries,Is.EqualTo(queriesBefore));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(consumed));
            if(scenario=="fresh")Assert.That(coordinator.TryCommit(expected),Is.True,"Fresh repeated probes must preserve normal commit, never revoke/regrant forever");
        }

        [Test]
        public void RevokedUncommittedParkingCacheCannotBecomeOwnedJourneyOrBlockSameSourceTypedRefreshAfterRealBirth()
        {
            var key=Key("provisional-cache-worker","employee-pickup-journey",62);var actor=new object();var work=P(3,-1);var target=P(0,-1);
            var f=new CanonicalSuccessorPreparationFixture(extraBody:new TrafficBodyFact(Key(key.ActorId,"body",2),work,.4f,actorLife:actor));
            var home=new TrafficRouteRequirement("selected-home",target,work,.8f,new[]{f.Start,f.End},selectedJourney:true,avoidProposedParking:false);
            var initial=new TrafficRequest(key,10,f.World,work,target,.4f,"pickup/"+key.ActorId,requirements:new[]{home},finiteSeconds:30,planPrimaryRoute:true);
            // Public real pickup arrival/checkpoint gives this same candidate a spent finite wait, then complete primary/home proofs.
            // 复用真实Queue与stamped完成；此处不用会自动Commit的Grant helper，原预算必须真实已消耗。
            f.Core.EvaluateParking(initial);f.Core.ProcessReady(10);var sleeping=f.Core.GetDecision(key);
            Assert.That(sleeping.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),sleeping.Reason);
            Assert.That(sleeping.Blockers.All(b=>b.Owner.Equals(f.Owner)&&b.Proof=="selected-journey-parking-protection"),Is.True);
            f.Core.Tick(.5f,false);var before=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(before.IndependentlyProgressing,Is.True);
            Assert.That(f.Begin(),Is.Not.Null);var after=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));
            Assert.That(after.ActorLife,Is.SameAs(before.ActorLife));Assert.That(after.Owner,Is.EqualTo(before.Owner));Assert.That(after.IndependentlyProgressing,Is.False);
            f.Core.NotifyChanged(f.Owner,"body");Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true));f.Core.ProcessReady(11);
            var prepared=f.Core.GetDecision(key);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),prepared.Reason);
            Assert.That(prepared.ProofRoutes.Count,Is.EqualTo(2));Assert.That(prepared.ProofRoutes.All(proof=>proof.ExpandedPath.Count>=2),Is.True);
            Assert.That(((Vector3[])D1Read(f.Core,key,"Journey")).Length,Is.GreaterThan(1),"PREMISE: original complete selected-home proof really generated a provisional cache");
            Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(f.Core.HasActiveGrant(key),Is.False);
            Assert.That(D1Read(f.Core,key,"JourneyPermit"),Is.Null);Assert.That(D1Read(f.Core,key,"JourneyRequest"),Is.Null);Assert.That(D1Read(f.Core,key,"Leg"),Is.Null);
            Assert.That(D1Read(f.Core,key,"EverCanonicalAttempt"),Is.EqualTo(false));Assert.That((float)D1Read(f.Core,key,"WaitRemaining"),Is.EqualTo(29.5f).Within(.0001f));
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var heldGoal),Is.True);Assert.That(heldGoal,Is.EqualTo(f.End));
            var goal=new TrafficRouteRequirement("existing-goal/"+f.Owner.ActorId,heldGoal,heldGoal,.8f,new[]{work});
            var replacement=new TrafficRequest(key,12,f.World,work,target,.4f,initial.ResourceId,requirements:new[]{goal,home},finiteSeconds:30,planPrimaryRoute:true);
            var queued=f.Core.EvaluateParking(replacement);Assert.That(queued.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(queued.Reason,Is.EqualTo("ready-batch-pending"));Assert.That(D1Read(f.Core,key,"Prepared"),Is.EqualTo(false));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true));
            Assert.That(f.Core.TryCommit(prepared),Is.False,"Revoked original permission cannot commit even before a second birth");
            Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(D1Read(f.Core,key,"JourneyPermit"),Is.Null);
            Assert.That(D1Read(f.Core,key,"JourneyRequest"),Is.Null);Assert.That(D1Read(f.Core,key,"Leg"),Is.Null);
            Assert.That(((TrafficRequest)D1Read(f.Core,key,"Request")).Requirements.Count,Is.EqualTo(2));
            TestContext.WriteLine("PROVISIONAL_CACHE_REQUEUE cachedPoints="+((Vector3[])D1Read(f.Core,key,"Journey")).Length+" acq=0 permit=NULL journeyRequest=NULL leg=NULL; cached geometry is not a repaired-policy premise");
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,key);var queueVersion=f.Pickup.Version;
            var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];var oldRequest=(TrafficRequest)D1Read(f.Core,key,"Request");
            var second=Key("actual-second-counter-birth","counter-admission",63);var counter=new CounterQueueService(new[]{P(-6,4)});
            Assert.That(counter.TryJoin(second.ActorId),Is.True);Assert.That(counter.TryCaptureAssignment(second.ActorId,out var born),Is.True);Assert.That(born.IsCurrent,Is.True);
            var birthBody=new TrafficBodyFact(second,born.Assignment.Position,.4f,actorLife:new object());
            var birthFact=new TrafficParkingFact(second,counter,counter.Version,"counter/"+second.ActorId,born.Assignment.Position,.4f,businessOwner:born,releaseObligation:born,semanticCheckpoint:born);
            f.World=World(f.World.Version+1,f.World.BodyVersion+1,f.World.Bodies.Concat(new[]{birthBody}).ToArray(),f.World.Parking.Concat(new[]{birthFact}).ToArray());f.Core.SetSnapshot(f.World);
            Assert.That(f.Core.GetDecision(key),Is.SameAs(queued));Assert.That(D1Read(f.Core,key,"Request"),Is.SameAs(oldRequest),"PREMISE: generic unborn refresh does not adopt physical worker facts");
            Assert.That(oldRequest.Snapshot.Version,Is.LessThan(f.World.Version));Assert.That(f.World.Bodies.Single(b=>b.Owner.ActorId==key.ActorId).ActorLife,Is.SameAs(actor));
            var freshGoal=new TrafficRouteRequirement(goal.ResourceId,heldGoal,heldGoal,.8f,new[]{work,born.Assignment.Position});
            var freshHome=new TrafficRouteRequirement(home.ResourceId,target,work,.8f,new[]{f.Start,f.End,born.Assignment.Position},selectedJourney:true,avoidProposedParking:false);
            var refreshed=new TrafficRequest(key,99,f.World,work,target,.4f,initial.ResourceId,requirements:new[]{freshGoal,freshHome},finiteSeconds:30,planPrimaryRoute:true);
            var spent=f.Core.QueriesConsumed(key);var frameQueries=f.Core.QueriesThisFrame;
            Assert.That(D2Refresh(f.Core,queued,refreshed,out var next),Is.True,
                "FEATURE RED: revoked uncommitted proof cache cannot masquerade as owned journey and reject authentic same-source queued metadata refresh");
            Assert.That(next,Is.SameAs(queued));Assert.That(D1Read(f.Core,key,"Journey"),Is.Empty);Assert.That(entries[key],Is.SameAs(entry));
            Assert.That(((TrafficRequest)D1Read(f.Core,key,"Request")).Snapshot,Is.SameAs(f.World));D3AssertAccounting(f.Core,key,accounting);
            Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(frameQueries));Assert.That(f.Core.TryCommit(prepared),Is.False);Assert.That(f.Core.TryCommit(next),Is.False);
            f.Core.ProcessReady(12);var ready=f.Core.GetDecision(key);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(ready.ProofRoutes.Select(proof=>proof.ResourceId),Is.EquivalentTo(new[]{initial.ResourceId,goal.ResourceId,home.ResourceId}));
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo(spent+3),"All three current-world model roles need ordinary fresh complete queries, charged to the original source");
            var retained=accounting.Where(pair=>pair.Key!="Queries").ToDictionary(pair=>pair.Key,pair=>pair.Value);D3AssertAccounting(f.Core,key,retained);
            Assert.That(f.Pickup.Version,Is.EqualTo(queueVersion));Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);Assert.That(born.IsCurrent,Is.True);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var actualHeld),Is.True);Assert.That(actualHeld,Is.EqualTo(heldGoal));
            Assert.That(ready.RequestSequence,Is.EqualTo(queued.RequestSequence));Assert.That(D1Read(f.Core,key,"FirstFrame"),Is.EqualTo(10));
            Assert.That(f.Core.TryCommit(ready),Is.True,"Only the later original full proof grants kernel permission; no employee Native/canonical delivery is claimed");
        }

