        public void ParkingCacheRevocationCannotEraseRealCommittedJourneyOrStrictNativeLeg(bool strict)
        {
            var key=Key("owned-cache-guard",strict?"strict-service":"parking-delivery",64);var actor=new object();var start=Origin;var target=P(4);
            var world=World(17,1,new[]{new TrafficBodyFact(key,start,.4f,actorLife:actor)});var core=Coordinator(world);
