                core.ProcessReady(12);var legReady=core.GetDecision(key);Assert.That(legReady.Kind,Is.EqualTo(TrafficDecisionKind.Granted),legReady.Reason);
                Assert.That(core.TryCommit(legReady),Is.True);Assert.That(core.BindLeg(key,actor,new TrafficNativeStamp(707,9)),Is.True);
                Assert.That(D3ReadField(D1Read(core,key,"Leg"),"Bound"),Is.EqualTo(true));
            }
            var expected=core.GetDecision(key);var originalRequest=D1Read(core,key,"Request");var permit=D1Read(core,key,"JourneyPermit");
            var journeyRequest=D1Read(core,key,"JourneyRequest");var leg=D1Read(core,key,"Leg");var journey=D1Read(core,key,"Journey");var path=D1Read(core,key,"CurrentPath");
            var accounting=D3CaptureAccounting(core,key);var changed=new TrafficRequest(key,99,world,start,target,.4f,"owned-outward",
                requirements:request.Requirements.Concat(new[]{new TrafficRouteRequirement("additional-role",P(10),P(12),.8f)}),finiteSeconds:20,planPrimaryRoute:true);
            var actual=strict?core.EvaluateMovement(changed):core.EvaluateParking(changed);
            Assert.That(actual,Is.SameAs(expected));Assert.That(D1Read(core,key,"Request"),Is.SameAs(originalRequest));
            Assert.That(D1Read(core,key,"JourneyPermit"),Is.SameAs(permit));Assert.That(D1Read(core,key,"JourneyRequest"),Is.SameAs(journeyRequest));
            Assert.That(D1Read(core,key,"Leg"),Is.SameAs(leg));Assert.That(D1Read(core,key,"Journey"),Is.SameAs(journey));Assert.That(D1Read(core,key,"CurrentPath"),Is.SameAs(path));
            D3AssertAccounting(core,key,accounting);Assert.That(core.HasActiveGrant(key),Is.True);
        }

