            core.EvaluateMovement(request);core.ProcessReady(11);var source=core.GetDecision(key);
            Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted),source.Reason);Assert.That(core.TryCommit(source),Is.True);
            Assert.That(D1Read(core,key,"Leg"),Is.Null);Assert.That(D1Read(core,key,"JourneyPermit"),Is.SameAs(source));
            world=World(18,2,new[]{new TrafficBodyFact(key,first,.4f,actorLife:actor)});core.SetSnapshot(world);
            Assert.That(core.CompleteLeg(key,stamp),Is.True,"PREMISE: original public stamped legacy completion, not a forged LegacyLegCompleted flag");
            Assert.That(D1Read(core,key,"LegacyLegCompleted"),Is.EqualTo(true));Assert.That(D1Read(core,key,"AcquiredSequence"),Is.Not.EqualTo(0L));
            var journey=D1Read(core,key,"Journey");Assert.That(((Vector3[])journey).Contains(future),Is.True);
            var firstFrame=D1Read(core,key,"FirstFrame");var sequence=D1Read(core,key,"RequestSequence");var acquired=D1Read(core,key,"AcquiredSequence");
            var queries=core.QueriesConsumed(key);var remaining=D1Read(core,key,"WaitRemaining");
            var next=core.EvaluateMovement(new TrafficRequest(key,99,world,first,future,.4f,"legacy-future",nativeStamp:new TrafficNativeStamp(802,2),finiteSeconds:20));
            Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(D1Read(core,key,"Queued"),Is.EqualTo(true));
            Assert.That(D1Read(core,key,"Journey"),Is.SameAs(journey),"Real legacy selected future protection survives its explicitly allowed continuation reset");
            Assert.That(D1Read(core,key,"FirstFrame"),Is.EqualTo(firstFrame));Assert.That(D1Read(core,key,"RequestSequence"),Is.EqualTo(sequence));
            Assert.That(D1Read(core,key,"AcquiredSequence"),Is.EqualTo(acquired));Assert.That(core.QueriesConsumed(key),Is.EqualTo(queries));
            Assert.That(D1Read(core,key,"WaitRemaining"),Is.EqualTo(remaining));Assert.That(core.TryCommit(source),Is.False);
        }

