            Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(next.AcquiredSequence,Is.Zero);
            Assert.That(f.Entry,Is.SameAs(entry));D3AssertAccounting(f.Core,f.Key,accounting);Assert.That(f.Calls,Is.EqualTo(calls));
            var retained=(TrafficRequest)D1Read(f.Core,f.Key,"Request");Assert.That(retained.Snapshot,Is.SameAs(f.World));
            Assert.That(retained.RequestedFrame,Is.EqualTo(11));Assert.That(retained.Requirements.Select(r=>r.ResourceId),Is.EqualTo(new[]{"existing-goal/real-role-guest","selected-home"}));
            Assert.That(D1Read(f.Core,f.Key,"Jobs"),Is.Empty);Assert.That(f.Core.TryCommit(next),Is.False);
            for(var frame=12;frame<=14;frame++)f.Core.ProcessReady(frame);
            var ready=f.Core.GetDecision(f.Key);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(ready.ProofRoutes.Select(r=>r.ResourceId),Is.EquivalentTo(new[]{f.Initial.ResourceId,"existing-goal/real-role-guest","selected-home"}));
            Assert.That(f.Core.QueriesConsumed(f.Key),Is.EqualTo((int)accounting["Queries"]+3));
            D3AssertAccounting(f.Core,f.Key,accounting.Where(x=>x.Key!="Queries").ToDictionary(x=>x.Key,x=>x.Value));
            Assert.That(f.OwnClaim.IsCurrent,Is.True);Assert.That(f.Pickup.TryCaptureReservation(f.Guest.ActorId,out var held),Is.True);
            Assert.That(held.IsCurrent,Is.True);Assert.That(held.Assignment.Arrived,Is.True);Assert.That(f.Core.CanIssueLeg(f.Key,f.Actor,1),Is.False);
        }
