        [TestCase("same-schema")] [TestCase("selected-role")] [TestCase("own-aba")]
        [TestCase("selected-order")] [TestCase("paused")] [TestCase("terminal")] [TestCase("issued")] [TestCase("producer-reentry")]
        public void QueuedParkingRoleResubmitCannotBorrowOwnedOrInvalidPreparationAuthority(string scenario)
        {
            var f=new QueuedRoleTransitionFixture(scenario=="selected-order");
            if(scenario=="issued")
            {
                f.Core.ProcessReady(12);var source=f.Core.GetDecision(f.Key);Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(f.Core.TryCommit(source),Is.True);Assert.That(f.Core.PrepareLeg(source,f.Initial.ResourceId,0,f.Actor,1,f.World,Origin,.05f,13).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                f.Core.ProcessReady(13);Assert.That(f.Core.TryCommit(f.Core.GetDecision(f.Key)),Is.True);Assert.That(f.Core.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(905,1)),Is.True);
            }
            if(scenario=="own-aba")
            {Assert.That(f.Counter.Remove(f.Key.ActorId),Is.True);Assert.That(f.Counter.TryJoin(f.Key.ActorId),Is.True);}
            f.ArriveGuest();if(scenario=="paused")f.Core.Tick(0,true);if(scenario=="terminal")f.Core.Retire(f.Key);
            var expected=f.Core.GetDecision(f.Key);var request=f.CurrentProposal();
            if(scenario=="same-schema")request=D2FreshRequest(f.Initial,f.World);
            if(scenario=="selected-role")request=D2FreshRequest(request,f.World,requirements:new[]{request.Requirements[0],
                new TrafficRouteRequirement("selected-home",P(4),P(-1),.8f,selectedJourney:true,avoidProposedParking:false)});
            if(scenario=="selected-order")request=D2FreshRequest(request,f.World,requirements:request.Requirements.Where(r=>!r.SelectedJourney)
                .Concat(request.Requirements.Where(r=>r.SelectedJourney).Reverse()));
            if(scenario=="own-aba")
            {Assert.That(f.Counter.TryCaptureAssignment(f.Key.ActorId,out var replacement),Is.True);Assert.That(f.OwnClaim.IsSameReservation(replacement),Is.False);}
            var accounting=D3CaptureAccounting(f.Core,f.Key);var oldRequest=D1Read(f.Core,f.Key,"Request");var leg=D1Read(f.Core,f.Key,"Leg");var calls=f.Calls;
            Func<bool> current=()=>true;if(scenario=="producer-reentry")current=()=>{f.Core.Retire(f.Key);return true;};
            Assert.That(ResubmitQueuedRoles(f.Core,expected,request,current,out var rejected),Is.False,scenario);Assert.That(rejected,Is.Null);
            Assert.That(f.Calls,Is.EqualTo(calls));D3AssertAccounting(f.Core,f.Key,accounting);
            if(scenario=="producer-reentry")
            {Assert.That(D1Read(f.Core,f.Key,"Retired"),Is.EqualTo(true));Assert.That(f.Core.GetDecision(f.Key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));}
            else
            {Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(expected));Assert.That(D1Read(f.Core,f.Key,"Request"),Is.SameAs(oldRequest));Assert.That(D1Read(f.Core,f.Key,"Leg"),Is.SameAs(leg));}
        }
        private static bool ResubmitQueuedRoles(ServiceTrafficCoordinator core,TrafficDecision expected,TrafficRequest request,Func<bool> current,out TrafficDecision next)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryResubmitQueuedParkingPreparation",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null);var args=new object[]{expected,request,current,null};var accepted=(bool)method.Invoke(core,args);next=(TrafficDecision)args[3];return accepted;
        }
        private sealed class QueuedRoleTransitionFixture
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("role-worker","employee-pickup-journey",77);
            internal readonly TrafficIntentKey Guest=ServiceTrafficCoordinatorTests.Key("real-role-guest","pickup-paid-movement",78);
            internal readonly object Actor=new object(),GuestLife=new object(),Business=new object(),Obligation=new object();
            internal readonly CounterQueueService Counter=new CounterQueueService(new[]{Origin});
            internal readonly PickupQueueService Pickup=new PickupQueueService(new[]{P(0,4)},new[]{P(6,4)});
            internal readonly CounterQueueService.AssignmentClaim OwnClaim;internal readonly ServiceTrafficCoordinator Core;
            internal readonly TrafficRequest Initial;internal TrafficWorldSnapshot World;internal int Calls;private bool arrived;
            internal QueuedRoleTransitionFixture(bool secondSelected=false)
            {
                Assert.That(Counter.TryJoin(Key.ActorId),Is.True);Assert.That(Counter.TryCaptureAssignment(Key.ActorId,out OwnClaim),Is.True);
                Assert.That(Pickup.TryReserve(Guest.ActorId,out _),Is.True);Assert.That(Pickup.TryBeginTransfer(Guest.ActorId,out _),Is.True);
                World=BuildWorld(1);Core=Coordinator(World,frameBudget:1,query:(a,b)=>{Calls++;return new[]{a,b};});
                var first=D2QueuedRequest(Key,World,new[]{P(0,4)});
                Initial=secondSelected?new TrafficRequest(Key,11,World,Origin,P(4),.4f,first.ResourceId,
                    requirements:first.Requirements.Concat(new[]{new TrafficRouteRequirement("selected-rest",Origin,P(0,-2),.8f,selectedJourney:true,avoidProposedParking:false)}),
                    finiteSeconds:20,planPrimaryRoute:true):first;
                Core.EvaluateParking(Initial,1,4);Core.ProcessReady(11);
                Assert.That(Core.GetDecision(Key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(Core.QueriesConsumed(Key),Is.EqualTo(1));
                Assert.That(D1Read(Core,Key,"JobIndex"),Is.EqualTo(1));Assert.That(D1Read(Core,Key,"Journey"),Is.Empty);
                Assert.That(D1Read(Core,Key,"JourneyPermit"),Is.Null);Assert.That(D1Read(Core,Key,"Leg"),Is.Null);
            }
            internal object Entry=>((System.Collections.IDictionary)D3ReadField(Core,"entries"))[Key];
            private TrafficWorldSnapshot BuildWorld(long version)
            {
                Assert.That(Counter.TryCaptureAssignment(Key.ActorId,out var own),Is.True);Assert.That(Pickup.TryCaptureReservation(Guest.ActorId,out var guest),Is.True);
                return ServiceTrafficCoordinatorTests.World(version,version,new[]{new TrafficBodyFact(Key,Origin,.4f,actorLife:Actor),
                    new TrafficBodyFact(Guest,arrived?guest.Assignment.Position:P(0,6),.4f,true,!arrived,arrived?0:8,actorLife:GuestLife)},
                    new[]{new TrafficParkingFact(Key,Counter,Counter.Version,"counter/role-worker",own.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:own),
                        new TrafficParkingFact(Guest,Pickup,Pickup.Version,"pickup/real-role-guest",guest.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:guest)});
            }
            internal void ArriveGuest()
            {Assert.That(Pickup.TryGetReservation(Guest.ActorId,out var assignment),Is.True);Assert.That(Pickup.MarkArrived(Guest.ActorId,assignment.Generation),Is.True);arrived=true;World=BuildWorld(2);Core.SetSnapshot(World);}
            internal TrafficRequest CurrentProposal()
            {
                Assert.That(Pickup.TryGetReservation(Guest.ActorId,out var assignment),Is.True);Assert.That(assignment.Arrived,Is.True);
                var goal=new TrafficRouteRequirement("existing-goal/real-role-guest",assignment.Position,assignment.Position,.8f,new[]{Origin});
                return D2FreshRequest(Initial,World,requirements:new[]{goal}.Concat(Initial.Requirements));
            }
        }

        private static TrafficRequest D2QueuedRequest(TrafficIntentKey key,TrafficWorldSnapshot world,
            IEnumerable<Vector3> obstacles=null,IEnumerable<Vector3> selected=null,TrafficDecisionKind? failure=null)
            =>new TrafficRequest(key,11,world,Origin,P(4),.4f,"delivery/"+key.ActorId,selectedJourney:selected,
                requirements:new[]{new TrafficRouteRequirement("selected-home",P(4),Origin,.8f,obstacles,
                    selectedJourney:true,avoidProposedParking:false)},finiteSeconds:20,provenFailure:failure,planPrimaryRoute:true);
        private static TrafficRequest D2FreshRequest(TrafficRequest source,TrafficWorldSnapshot world,
            TrafficIntentKey? key=null,Vector3? target=null,string resource=null,
            IEnumerable<TrafficRouteRequirement> requirements=null,float? finite=null)
            =>new TrafficRequest(key??source.Intent,99,world,source.Start,target??source.Target,source.Radius,resource??source.ResourceId,
                source.SelectedJourney,requirements??source.Requirements,source.NativeStamp,source.IndependentlyProgressing,
                finite??source.FiniteSeconds,source.ProvenFailure,source.SafetyMargin,source.PlanPrimaryRoute);
        private static bool D2Refresh(ServiceTrafficCoordinator coordinator,TrafficDecision expected,TrafficRequest refreshed,out TrafficDecision next)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryRefreshQueuedPreparation",
                System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"D2 MODEL FIXTURE: compile-only declaration exists");
            var args=new object[]{expected,refreshed,null};var result=(bool)method.Invoke(coordinator,args);next=(TrafficDecision)args[2];return result;
        }

        [TestCase("compatible-frontier")] [TestCase("changed-obstacles")]
        [TestCase("identical-noop")] [TestCase("notified-waiter")]
        public void D2QueuedPreparationRefreshPreservesBoundedOriginalAuthority(string scenario)
        {
            var key=Key("d2-proposal");var life=new object();var blocker=Key("d2-release");var waiting=scenario=="notified-waiter";
            var bodies=new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)}
                .Concat(waiting?new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8,actorLife:new object())}:Array.Empty<TrafficBodyFact>()).ToArray();
            var world=World(17,1,bodies);var calls=0;
            var coordinator=Coordinator(world,frameBudget:1,query:(from,to)=>{calls++;return new[]{from,to};});
            coordinator.EvaluateParking(D2QueuedRequest(key,world,new[]{P(30,30)}),1,4);coordinator.ProcessReady(11);
            if(waiting)
            {
                Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"D2 FIXTURE: actual finite owner wait");
                coordinator.Tick(2,false);coordinator.NotifyChanged(blocker,"body");
            }
            else Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"D2 FIXTURE: real shared budget leaves selected-home unfinished");
            var expected=coordinator.GetDecision(key);var source=(TrafficRequest)D1Read(coordinator,key,"Request");
            var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();var jobIndex=D1Read(coordinator,key,"JobIndex");
            var queryBefore=coordinator.QueriesConsumed(key);var callsBefore=calls;var waitBefore=D1Read(coordinator,key,"WaitRemaining");
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
            Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(true));Assert.That(expected.AcquiredSequence,Is.Zero);
            if(waiting)Assert.That(((IReadOnlyList<TrafficBlocker>)edges).Any(b=>b.Owner.Equals(blocker)),Is.True,"D2 FIXTURE: unresolved current edge");
            else Assert.That(jobs.Length,Is.GreaterThan(0),"D2 FIXTURE: actual partially spent frontier");
            var fresh=scenario=="identical-noop"?world:World(18,2,bodies);coordinator.SetSnapshot(fresh);
            var requirements=scenario=="changed-obstacles"?new[]{new TrafficRouteRequirement("selected-home",P(4),Origin,.8f,
                new[]{P(40,30)},selectedJourney:true,avoidProposedParking:false)}:source.Requirements;
            var refreshed=D2FreshRequest(source,fresh,requirements:requirements);
            TestContext.WriteLine("D2_MODEL feature=queued-refresh expected=True scenario="+scenario+" queries="+queryBefore+" wait="+waitBefore);
            Assert.That(D2Refresh(coordinator,expected,refreshed,out var next),Is.True,"D2 FEATURE RED: authenticated queued metadata must refresh before Evaluate without a query");
            Assert.That(next,Is.Not.Null);Assert.That(next.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(calls,Is.EqualTo(callsBefore));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queryBefore));
            Assert.That(next.RequestSequence,Is.EqualTo(expected.RequestSequence));Assert.That(next.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh));
            Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(waitBefore));Assert.That(D1Read(coordinator,key,"FiniteLimit"),Is.EqualTo(20f));
            Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(1));Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(4));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{1}));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(coordinator.HasActiveGrant(key),Is.False);
            var after=(System.Collections.IList)D1Read(coordinator,key,"Jobs");
            if(scenario=="changed-obstacles")Assert.That(after,Is.Empty,"Changed external obstacle proof must not reuse old geometry");
            else {CollectionAssert.AreEqual(jobs,after);Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(jobIndex));}
            if(waiting)return;
            coordinator.ProcessReady(12);coordinator.ProcessReady(13);var granted=coordinator.GetDecision(key);
            Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted),granted.Reason);
            var canonical=new CanonicalOwner();Assert.That(canonical.Applies,Is.Zero);
            Assert.That(coordinator.TryCommit(granted,canonical.Prepare()),Is.True);Assert.That(canonical.Applies,Is.EqualTo(1));
            Assert.That(coordinator.TryCommit(granted,canonical.Prepare()),Is.False,"Refresh cannot create duplicate canonical authority");
        }

        [TestCase("stale-expected")] [TestCase("foreign-key")] [TestCase("target")] [TestCase("resource")]
        [TestCase("proof-role")] [TestCase("actor-life")] [TestCase("own-pose")] [TestCase("owned-claim")]
        [TestCase("nonqueued")] [TestCase("prepared")] [TestCase("acquired")] [TestCase("strict-leg")]
        [TestCase("selected-permit")] [TestCase("direct-selected")] [TestCase("canonical-attempt")] [TestCase("recovery")]
        [TestCase("terminal")] [TestCase("retired")] [TestCase("finite-limit")] [TestCase("stale-snapshot")]
        public void D2QueuedPreparationRefreshRejectsProtectedOriginalSources(string scenario)
        {
            var key=Key("d2-protected");var life=new object();var blocker=Key("d2-blocker");
            TrafficWorldSnapshot world;ServiceTrafficCoordinator coordinator;TrafficDecision expected;
            TrafficRequest retiredSource=null; // Caller-owned replay input; Core must still release Request. / 外部输入不保留 Core 引用。
            if(scenario=="strict-leg" || scenario=="selected-permit")
            {
                var fixture=new LegFixture();if(scenario=="strict-leg")fixture.Prepare();
                coordinator=fixture.Coordinator;key=fixture.Key;world=fixture.World;expected=coordinator.GetDecision(key);
                Assert.That(D1Read(coordinator,key,scenario=="strict-leg"?"Leg":"JourneyPermit"),Is.Not.Null,"D2 FIXTURE: real protected selected source");
            }
            else if(scenario=="recovery")
            {
                var fixture=new PreparationRecoveryFixture();fixture.FailWithBody();Assert.That(fixture.Take(fixture.Current,fixture.Actor,out var receipt),Is.True);
                fixture.SetBody(null);Assert.That(fixture.Begin(receipt,out _),Is.True);coordinator=fixture.Coordinator;key=fixture.Next;world=fixture.World;
                expected=coordinator.GetDecision(key);Assert.That(D1Read(coordinator,key,"ExplicitRecoveryUsed"),Is.EqualTo(true));
            }
            else
            {
                var bodies=new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)}.Concat(scenario=="nonqueued"
                    ?new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8)}:Array.Empty<TrafficBodyFact>()).ToArray();
                world=World(17,1,bodies);coordinator=Coordinator(world,frameBudget:scenario=="stale-expected"?1:128);
                expected=coordinator.EvaluateParking(D2QueuedRequest(key,world,selected:scenario=="direct-selected"?new[]{Origin,P(4)}:null,
                    failure:scenario=="terminal"?TrafficDecisionKind.InvalidStart:(TrafficDecisionKind?)null),0,4);
                if(scenario=="stale-expected" || scenario=="nonqueued" || scenario=="prepared" || scenario=="acquired" || scenario=="canonical-attempt" || scenario=="terminal")
                {
                    coordinator.ProcessReady(11);if(scenario!="stale-expected")expected=coordinator.GetDecision(key);
                }
                if(scenario=="stale-expected")Assert.That(coordinator.GetDecision(key),Is.Not.SameAs(expected));
                if(scenario=="nonqueued") {Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(false));}
                if(scenario=="prepared")Assert.That(D1Read(coordinator,key,"Prepared"),Is.EqualTo(true));
                if(scenario=="acquired") {Assert.That(coordinator.TryCommit(expected),Is.True);expected=coordinator.GetDecision(key);Assert.That(expected.AcquiredSequence,Is.GreaterThan(0));}
                if(scenario=="canonical-attempt")
                {Assert.That(coordinator.TryCommit(expected,new PreparationCanonicalFailure("apply-false")),Is.False);expected=coordinator.GetDecision(key);Assert.That(D1Read(coordinator,key,"EverCanonicalAttempt"),Is.EqualTo(true));}
                if(scenario=="terminal")Assert.That(expected.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                if(scenario=="retired") {retiredSource=(TrafficRequest)D1Read(coordinator,key,"Request");coordinator.Retire(key);expected=coordinator.GetDecision(key);Assert.That(D1Read(coordinator,key,"Retired"),Is.EqualTo(true));}
            }
            var bodiesNow=world.Bodies.Select(b=>b.Owner.ActorId==key.ActorId && (scenario=="actor-life" || scenario=="own-pose")
                ?new TrafficBodyFact(b.Owner,scenario=="own-pose"?P(.1f):b.Position,b.Radius,b.Enabled,b.IndependentlyProgressing,b.RemainingSeconds,b.SafetyMargin,
                    scenario=="actor-life"?new object():b.ActorLife,b.ActorActive):b).ToArray();
            var claimsNow=scenario=="owned-claim"?world.Parking.Concat(new[]{new TrafficParkingFact(key,new object(),1,"own-new",P(20),.4f)}).ToArray():world.Parking.ToArray();
            var fresh=World(world.Version+1,world.BodyVersion+1,bodiesNow,claimsNow);coordinator.SetSnapshot(fresh);
            var current=coordinator.GetDecision(key);var source=(TrafficRequest)D1Read(coordinator,key,"Request");
            var request=D2FreshRequest(scenario=="retired"?retiredSource:source,scenario=="stale-snapshot"?world:fresh,key:scenario=="foreign-key"?Key("other"):(TrafficIntentKey?)null,
                target:scenario=="target"?P(5):(Vector3?)null,resource:scenario=="resource"?"foreign-resource":null,finite:scenario=="finite-limit"?21f:(float?)null,
                requirements:scenario=="proof-role"?new[]{new TrafficRouteRequirement("different-home",P(4),Origin,.8f,selectedJourney:true,avoidProposedParking:false)}:null);
            var queryBefore=coordinator.QueriesConsumed(key);var fields=new[]{"FirstFrame","RequestSequence","AcquiredSequence","WaitRemaining","FiniteLimit","CurrentIndex","CandidateCount","Queued","Prepared","Active","Retired"};
            var before=fields.Select(n=>D1Read(coordinator,key,n)).ToArray();var legs=D1Read(coordinator,key,"Leg");var permit=D1Read(coordinator,key,"JourneyPermit");
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");var edges=D1Read(coordinator,key,"WaitingBlockers");
            var attempted=((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices")).ToArray();
            Assert.That(D2Refresh(coordinator,expected,request,out var rejected),Is.False,"D2 protected source: "+scenario);Assert.That(rejected,Is.Null);
            Assert.That(coordinator.GetDecision(key),Is.SameAs(current));Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(source));
            CollectionAssert.AreEqual(before,fields.Select(n=>D1Read(coordinator,key,n)).ToArray());Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queryBefore));
            Assert.That(D1Read(coordinator,key,"Leg"),Is.SameAs(legs));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(permit));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(attempted));
        }

        private static TrafficRequest CfcAnchorRequest(TrafficIntentKey key,TrafficWorldSnapshot world,Vector3 target,
            int frame=11,IEnumerable<TrafficRouteRequirement> requirements=null,IEnumerable<Vector3> journey=null)
            =>new TrafficRequest(key,frame,world,Origin,target,.4f,"canonical/"+key.ActorId,
                selectedJourney:journey,requirements:requirements,finiteSeconds:20,planPrimaryRoute:true);
        private static bool CfcReprepare(ServiceTrafficCoordinator coordinator,TrafficDecision expected,TrafficRequest request,out TrafficDecision next)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryReprepareCanonicalAnchor",
                System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"MODEL FIXTURE: inert internal declaration exists before behavior RED");
            var args=new object[]{expected,request,null};var accepted=(bool)method.Invoke(coordinator,args);next=(TrafficDecision)args[2];return accepted;
        }

        private static bool CfcCancelPreparation(ServiceTrafficCoordinator coordinator,TrafficDecision expected)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryCancelCanonicalAnchorPreparation",
                System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"MODEL FIXTURE: inert cancellation declaration exists before behavior RED");
            return (bool)method.Invoke(coordinator,new object[]{expected});
        }

        [Test] public void Fix5PreCanonicalCancellationRevokesPermissionWithoutRenewingOriginalAccounting()
        {
            var key=Key("cancel-unborn");var blocker=Key("cancel-finite-owner");
            var world=World(17,1,new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8,actorLife:new object())});
            var coordinator=Coordinator(world);coordinator.EvaluateParking(CfcAnchorRequest(key,world,P(4)),1,2);coordinator.ProcessReady(11);
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            coordinator.Tick(2,false);
            world=World(18,2);coordinator.SetSnapshot(world);coordinator.NotifyChanged(blocker,"body");coordinator.ProcessReady(12);
            var expected=coordinator.GetDecision(key);Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            var request=D1Read(coordinator,key,"Request");var queries=coordinator.QueriesConsumed(key);
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");
            var edges=D1Read(coordinator,key,"WaitingBlockers");var attempted=((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices")).ToArray();
            Assert.That(queries,Is.EqualTo(1));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(6f));
            Assert.That((HashSet<TrafficIntentKey>)frozen,Is.EquivalentTo(new[]{blocker}),"FIXTURE: retain spent real finite-wait eligibility");
            Assert.That(CfcCancelPreparation(coordinator,expected),Is.True,"PRODUCT: cancel only this unissued unborn preparation, without discarding its phase");
            var cancelled=coordinator.GetDecision(key);Assert.That(cancelled,Is.Not.SameAs(expected));
            Assert.That(cancelled.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(cancelled.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(coordinator.TryCommit(expected),Is.False,"The cancelled exact permission must be unusable immediately");
            Assert.That(CfcCancelPreparation(coordinator,expected),Is.False,"Cancellation cannot replay an old expected");
            Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request));Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));
            Assert.That(cancelled.RequestSequence,Is.EqualTo(expected.RequestSequence));Assert.That(cancelled.AcquiredSequence,Is.Zero);
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(6f));
            Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(2));
            Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(1));Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(attempted));
            Assert.That(((TrafficRequest)request).FiniteSeconds,Is.EqualTo(20));Assert.That(D1Read(coordinator,key,"Discarded"),Is.EqualTo(false));
            Assert.That(D1Read(coordinator,key,"Prepared"),Is.EqualTo(false));Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(true));
            Assert.That((System.Collections.IList)D1Read(coordinator,key,"Jobs"),Is.Empty);Assert.That(coordinator.HasActiveGrant(key),Is.False);
            coordinator.ProcessReady(13);var resumed=coordinator.GetDecision(key);
            Assert.That(resumed.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries+1));
            Assert.That(resumed.RequestSequence,Is.EqualTo(expected.RequestSequence));Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));
            Assert.That(resumed.ProofRoutes.Single().Waypoints.Last(),Is.EqualTo(P(4)));
            var canonical=new CanonicalOwner();Assert.That(coordinator.TryCommit(resumed,canonical.Prepare()),Is.True);
            Assert.That(coordinator.TryCommit(resumed,canonical.Prepare()),Is.False);Assert.That(canonical.Applies,Is.EqualTo(1));
        }

        [TestCase("copied")] [TestCase("stale")] [TestCase("foreign")] [TestCase("body")]
        [TestCase("claim")] [TestCase("acquired")] [TestCase("canonical-failed")] [TestCase("non-granted")]
        public void Fix5CancellationRejectsUnownedPhysicalOrCanonicalSources(string state)
        {
            var key=Key("cancel-guard");var world=World(17,1);
            var coordinator=Coordinator(world,query:(from,to)=>state=="non-granted"?null:new[]{from,to});
            var stale=coordinator.EvaluateParking(CfcAnchorRequest(key,world,P(4)));
            if(state=="non-granted")
            {
                Assert.That(stale.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Assert.That(CfcCancelPreparation(coordinator,stale),Is.False,"A queued proposal has no birth permission to cancel");
                Assert.That(coordinator.GetDecision(key),Is.SameAs(stale));Assert.That(coordinator.QueriesConsumed(key),Is.Zero);
            }
            coordinator.ProcessReady(11);var prepared=coordinator.GetDecision(key);
            if(state=="non-granted")Assert.That(prepared.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal),"FIXTURE: actual failed route planning");
            else Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            if(state=="acquired")Assert.That(coordinator.TryCommit(prepared),Is.True);
            if(state=="canonical-failed")
            {
                Assert.That(coordinator.TryCommit(prepared,new PreparationCanonicalFailure("apply-false")),Is.False);
                Assert.That(D1Read(coordinator,key,"EverCanonicalAttempt"),Is.EqualTo(true));
            }
            if(state=="body" || state=="claim")
            {
                var alias=Key(key.ActorId,"actual-owner",4);
                world=World(18,2,state=="body"?new[]{new TrafficBodyFact(alias,Origin,.4f,actorLife:new object())}:null,
                    state=="claim"?new[]{new TrafficParkingFact(alias,new object(),1,"counter",Origin,.4f)}:null);
                coordinator.SetSnapshot(world);
            }
            var current=coordinator.GetDecision(key);var expected=state=="stale"?stale:current;
            if(state=="copied")expected=new TrafficDecision(key,current.Kind,current.Reason);
            if(state=="foreign")
            {
                var foreign=Coordinator(world);foreign.EvaluateParking(CfcAnchorRequest(key,world,P(4)));foreign.ProcessReady(11);expected=foreign.GetDecision(key);
                Assert.That(expected.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            }
            var request=D1Read(coordinator,key,"Request");var queries=coordinator.QueriesConsumed(key);var active=coordinator.HasActiveGrant(key);
            var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();
            var edges=D1Read(coordinator,key,"WaitingBlockers");var queued=D1Read(coordinator,key,"Queued");var ready=D1Read(coordinator,key,"Prepared");
            Assert.That(CfcCancelPreparation(coordinator,expected),Is.False,"PRODUCT: cancellation is not authority to revive or replace a protected source");
            Assert.That(coordinator.GetDecision(key),Is.SameAs(current));Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(coordinator.HasActiveGrant(key),Is.EqualTo(active));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(queued));
            Assert.That(D1Read(coordinator,key,"Prepared"),Is.EqualTo(ready));
            CollectionAssert.AreEqual(jobs,((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray());
        }

        [Test] public void CfcBodyOnlySafeWalkingAllowsBoundedCanonicalConsumptionAfterPostPumpRefresh()
        {
            var key=Key("body-only-unborn");var walker=Key("body-only-walker");var life=new object();
            var heldQueue=new CounterQueueService(new[]{P(40,40)});var heldKey=Key("body-only-held");
            Assert.That(heldQueue.TryJoin(heldKey.ActorId),Is.True);Assert.That(heldQueue.TryCaptureAssignment(heldKey.ActorId,out var claim),Is.True);
            var heldVersion=heldQueue.Version;var held=new TrafficParkingFact(heldKey,heldQueue,heldVersion,"counter/"+heldKey.ActorId,
                claim.Assignment.Position,.4f,businessOwner:claim,releaseObligation:claim);
            var incoming=new CounterQueueService(new[]{P(4)});var incomingVersion=incoming.Version;Assert.That(incoming.TryPrepareMutation(CounterQueueService.MutationKind.Join,key.ActorId,incoming.Version,out var birth),Is.True);
            var requirements=new[]{new TrafficRouteRequirement("body-only-exit",P(20,10),P(24,10),.8f,avoidProposedParking:false),
                new TrafficRouteRequirement("body-only-home",P(20,20),P(24,20),.8f,avoidProposedParking:false)};
            TrafficWorldSnapshot At(int bodyVersion)=>World(17,bodyVersion,new[]{new TrafficBodyFact(walker,P(30+bodyVersion,30),.4f,true,true,8,actorLife:life)},new[]{held});
            var world=At(1);var queryCalls=0;var coordinator=Coordinator(world,query:(from,to)=>{queryCalls++;return new[]{from,to};});var target=birth.Assignment.Position;
            coordinator.EvaluateParking(CfcAnchorRequest(key,world,target,requirements:requirements));coordinator.ProcessReady(11);
            var initial=coordinator.GetDecision(key);var originalQueries=coordinator.QueriesConsumed(key);
            Assert.That(initial.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"MODEL PREMISE: actual primary plus both capability proofs are prepared");
            Assert.That(initial.ProofRoutes.Count,Is.EqualTo(3));Assert.That(originalQueries,Is.EqualTo(3));
            Assert.That(initial.ProofRoutes.Last().ExpandedPath,Is.EqualTo(new[]{P(20,20),P(24,20)}));
            var sequence=initial.RequestSequence;var committed=false;var rounds=0;var body=1;var spent=originalQueries;
            for(var frame=12;frame<16 && !committed;frame++)
            {
                rounds++;world=At(++body);coordinator.SetSnapshot(world);
                Assert.That(CfcReprepare(coordinator,coordinator.GetDecision(key),CfcAnchorRequest(key,world,target,99,requirements),out _),Is.True);
                coordinator.ProcessReady(frame);var prepared=coordinator.GetDecision(key);
                Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"MODEL PREMISE: all paths remain clear in the ordinary ready batch");
                // Actual CFC order: another normal body checkpoint can follow the pump, before the public producer tries its same source.
                // 模型仅更新公开snapshot输入；不假装Native运动，不绕过原producer重验或joint commit。
                world=At(++body);coordinator.SetSnapshot(world);
                Assert.That(world.Version,Is.EqualTo(17));Assert.That(claim.IsCurrent,Is.True);Assert.That(heldQueue.Version,Is.EqualTo(heldVersion));
                Assert.That(CfcReprepare(coordinator,prepared,CfcAnchorRequest(key,world,target,99,requirements),out var current),Is.True);
                Assert.That(current.RequestSequence,Is.EqualTo(sequence));Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));
                Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
                Assert.That(D1Read(coordinator,key,"FiniteLimit"),Is.EqualTo(20f));Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(1));
                Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(0));CollectionAssert.AreEquivalent(new[]{0},(HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"));
                var queries=coordinator.QueriesConsumed(key);Assert.That(queries,Is.GreaterThanOrEqualTo(spent),"Original cumulative work cannot be reset");Assert.That(queries,Is.EqualTo(queryCalls),"Every actual model query stays charged to this original key");spent=queries;
                if(current.Kind==TrafficDecisionKind.Granted)committed=coordinator.TryCommit(current,birth);
            }
            TestContext.WriteLine("BODY_ONLY_REPROOF rounds="+rounds+" queries="+coordinator.QueriesConsumed(key)+" committed="+committed+" canonicalVersion="+heldQueue.Version);
            Assert.That(committed,Is.True,"PRODUCT: complete current-world validation of safe retained proofs must allow the same unborn source to consume within bounded ordinary pre/post-pump rounds");
            Assert.That(incoming.Version,Is.EqualTo(incomingVersion+1));Assert.That(incoming.Snapshot.Single().VisitId,Is.EqualTo(key.ActorId));
            Assert.That(coordinator.HasActiveGrant(key),Is.True);Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.GreaterThan(0));
        }

        [TestCase("primary")] [TestCase("capability")] [TestCase("new-role")]
        public void CfcBodyOnlyRefreshCannotReuseUnsafeOrIncompleteOriginalProof(string change)
        {
            var key=Key("body-only-safety");var walker=Key("body-only-safety-walker");var life=new object();
            var heldQueue=new CounterQueueService(new[]{P(40,40)});var heldKey=Key("body-only-safety-held");
            Assert.That(heldQueue.TryJoin(heldKey.ActorId),Is.True);Assert.That(heldQueue.TryCaptureAssignment(heldKey.ActorId,out var claim),Is.True);
            var held=new TrafficParkingFact(heldKey,heldQueue,heldQueue.Version,"counter/"+heldKey.ActorId,claim.Assignment.Position,.4f,businessOwner:claim,releaseObligation:claim);
            var incoming=new CounterQueueService(new[]{P(4)});var incomingVersion=incoming.Version;Assert.That(incoming.TryPrepareMutation(CounterQueueService.MutationKind.Join,key.ActorId,incoming.Version,out var birth),Is.True);
            var requirements=new[]{new TrafficRouteRequirement("body-only-exit",P(20,10),P(24,10),.8f,avoidProposedParking:false),
                new TrafficRouteRequirement("body-only-home",P(20,20),P(24,20),.8f,avoidProposedParking:false)};
            var world=World(17,1,new[]{new TrafficBodyFact(walker,P(30,30),.4f,true,true,8,actorLife:life)},new[]{held});var coordinator=Coordinator(world);
            coordinator.EvaluateParking(CfcAnchorRequest(key,world,birth.Assignment.Position,requirements:requirements));coordinator.ProcessReady(11);
            var original=coordinator.GetDecision(key);var queries=coordinator.QueriesConsumed(key);
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(original.ProofRoutes.Count,Is.EqualTo(3));
            Assert.That(original.ProofRoutes.First().ExpandedPath,Is.EqualTo(new[]{Origin,P(4)}));
            Assert.That(original.ProofRoutes.Last().ExpandedPath,Is.EqualTo(new[]{P(20,20),P(24,20)}),"MODEL PREMISE: the final capability, far from the primary, crosses the prospective obstacle");
            var position=change=="primary"?P(2):change=="capability"?P(22,20):P(31,30);
            var currentRequirements=requirements;
            if(change=="capability")currentRequirements=new[]{requirements[0],new TrafficRouteRequirement("body-only-home",P(20,20),P(24,20),.8f,new[]{position},avoidProposedParking:false)};
            if(change=="new-role")currentRequirements=requirements.Concat(new[]{new TrafficRouteRequirement("late-real-goal",P(20,30),P(24,30),.8f,avoidProposedParking:false)}).ToArray();
            world=World(17,2,new[]{new TrafficBodyFact(walker,position,.4f,true,true,8,actorLife:life)},new[]{held});coordinator.SetSnapshot(world);
            Assert.That(claim.IsCurrent,Is.True);Assert.That(world.Version,Is.EqualTo(17));
            Assert.That(CfcReprepare(coordinator,original,CfcAnchorRequest(key,world,birth.Assignment.Position,99,currentRequirements),out var refreshed),Is.True);
            Assert.That(coordinator.TryCommit(original,birth),Is.False,"PRODUCT: a clear primary alone or an incomplete old role set cannot authorize canonical writes from this saved permission");
            Assert.That(incoming.Version,Is.EqualTo(incomingVersion));Assert.That(incoming.Snapshot,Is.Empty);Assert.That(birth.IsCurrent,Is.True);
            Assert.That(refreshed,Is.Not.SameAs(original));Assert.That(refreshed.RequestSequence,Is.EqualTo(original.RequestSequence));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(coordinator,key,"FiniteLimit"),Is.EqualTo(20f));
            Assert.That(coordinator.QueriesConsumed(key),Is.GreaterThanOrEqualTo(queries));
            // Only the unsafe old permission is rejected; a later ordinary reproof may discover a valid detour.
        }

        // Model the real pre-pump -> ready -> post-pump order; no Native or private Entry mutation.
        // 同一snapshot中无身体/业务变化；两条分离路线不能因彼此prepared而永久重算。
        [Test] public void CfcSameSnapshotIndependentParkingReproofCompletesWithoutQueryChurn()
        {
            var keys=new[]{Key("pair-a"),Key("pair-b")};var lives=new[]{new object(),new object()};
            var starts=new[]{Origin,P(0,10)};var targets=new[]{P(4),P(4,10)};
            var world=World(17,1,new[]{new TrafficBodyFact(keys[0],starts[0],.4f,actorLife:lives[0]),
                new TrafficBodyFact(keys[1],starts[1],.4f,actorLife:lives[1])});
            var coordinator=Coordinator(world);var owners=new[]{new CanonicalOwner(),new CanonicalOwner()};
            var requirements=new[]{
                new[]{new TrafficRouteRequirement("collection-exit-capability",P(20,20),P(22,20),.8f,avoidProposedParking:false)},
                new[]{new TrafficRouteRequirement("existing-goal",P(20,30),P(22,30),.8f,avoidProposedParking:false),
                    new TrafficRouteRequirement("work-outward",P(20,40),P(22,40),.8f,avoidProposedParking:false),
                    new TrafficRouteRequirement("work-home",P(22,40),P(20,40),.8f,avoidProposedParking:false),
                    new TrafficRouteRequirement("waiting-exit-capability",P(20,50),P(22,50),.8f,avoidProposedParking:false)}};
            var requests=Enumerable.Range(0,2).Select(i=>new TrafficRequest(keys[i],11,world,starts[i],targets[i],.4f,
                "canonical/"+keys[i].ActorId,requirements:requirements[i],finiteSeconds:20,planPrimaryRoute:true)).ToArray();
            foreach(var request in requests)coordinator.EvaluateParking(request);
            var committed=new bool[2];var rounds=0;
            for(var frame=11;frame<15 && !committed.All(value=>value);frame++)
            {
                rounds++;
                // Actual CFC pre-pump refreshes reservation before collection; post-pump visits collection first.
                // 先pre-pump原顺序，再ready batch，再逐visit重验/合法joint commit。
                foreach(var i in new[]{1,0})
                    if(!committed[i])Assert.That(CfcReprepare(coordinator,coordinator.GetDecision(keys[i]),requests[i],out _),Is.True);
                coordinator.ProcessReady(frame);
                if(frame==11)
                    foreach(var key in keys)Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.Granted),
                        "MODEL PREMISE: both separated primary/capability routes actually prepare in the same batch");
                foreach(var i in new[]{0,1})
                {
                    if(committed[i])continue;
                    Assert.That(CfcReprepare(coordinator,coordinator.GetDecision(keys[i]),requests[i],out var decision),Is.True);
                    if(decision.Kind==TrafficDecisionKind.Granted)committed[i]=coordinator.TryCommit(decision,owners[i].Prepare());
                }
            }
            TestContext.WriteLine("PAIR_REPROOF rounds="+rounds+" queriesA="+coordinator.QueriesConsumed(keys[0])+
                " queriesB="+coordinator.QueriesConsumed(keys[1])+" committedA="+committed[0]+" committedB="+committed[1]);
            Assert.That(committed.All(value=>value),Is.True,
                "PRODUCT: fixed clear geometry must complete both canonical submissions instead of repeatedly revoking each other's prepared proof");
            Assert.That(coordinator.QueriesConsumed(keys[0])+coordinator.QueriesConsumed(keys[1]),Is.LessThanOrEqualTo(14),
                "Two direct complete batches are enough for the literal 2+5 proof fixture; no budget is enlarged");
            foreach(var i in new[]{0,1})
            {
                Assert.That(coordinator.HasActiveGrant(keys[i]),Is.True);Assert.That(owners[i].Applies,Is.EqualTo(1));
                Assert.That(owners[i].Rollbacks,Is.Zero);Assert.That(coordinator.GetDecision(keys[i]).AcquiredSequence,Is.GreaterThan(0));
            }
        }

        [TestCase(false)] [TestCase(true)]
        public void CfcSameSnapshotReproofRejectsRealPreparedOrCanonicalEndpointConflict(bool acquired)
        {
            var owner=Key("conflict-owner");var candidate=Key("conflict-candidate");
            var world=World(17,1,new[]{new TrafficBodyFact(owner,Origin,.4f,actorLife:new object()),
                new TrafficBodyFact(candidate,P(0,10),.4f,actorLife:new object())});
            var coordinator=Coordinator(world);var heldOwner=new CanonicalOwner();var incomingOwner=new CanonicalOwner();
            var held=CfcAnchorRequest(owner,world,P(4));
            var initial=new TrafficRequest(candidate,11,world,P(0,10),P(4,10),.4f,"canonical/"+candidate.ActorId,finiteSeconds:20,planPrimaryRoute:true);
            coordinator.EvaluateParking(held);coordinator.EvaluateParking(initial);coordinator.ProcessReady(11);
            var permission=coordinator.GetDecision(owner);var original=coordinator.GetDecision(candidate);
            Assert.That(permission.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            if(acquired)Assert.That(coordinator.TryCommit(permission,heldOwner.Prepare()),Is.True);
            var moved=new TrafficRequest(candidate,11,world,P(0,10),P(4),.4f,"canonical/"+candidate.ActorId,finiteSeconds:20,planPrimaryRoute:true);
            Assert.That(CfcReprepare(coordinator,original,moved,out _),Is.True);
            Assert.That(coordinator.TryCommit(original,incomingOwner.Prepare()),Is.False,"The old clear-target permission cannot submit the conflicting target");
            coordinator.ProcessReady(12);var blocked=coordinator.GetDecision(candidate);
            Assert.That(blocked.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(blocked.Blockers.Select(value=>value.Owner),Does.Contain(owner));
            Assert.That(coordinator.TryCommit(blocked,incomingOwner.Prepare()),Is.False);Assert.That(incomingOwner.Applies,Is.Zero);
            Assert.That(coordinator.GetDecision(owner),Is.SameAs(permission));Assert.That(coordinator.HasActiveGrant(owner),Is.EqualTo(acquired));
            Assert.That(heldOwner.Applies,Is.EqualTo(acquired?1:0));Assert.That(heldOwner.Rollbacks,Is.Zero);
        }

        [Test] public void CfcSameSnapshotReproofKeepsCommittedSelectedHomeProtected()
        {
            var owner=Key("selected-owner");var candidate=Key("selected-candidate");var world=World();var coordinator=Coordinator(world);
            var home=new TrafficRouteRequirement("selected-home",P(2),P(8),.8f,selectedJourney:true,avoidProposedParking:false);
            var canonical=new CanonicalOwner();var incoming=new CanonicalOwner();
            coordinator.EvaluateParking(Request(owner,Origin,P(2),world,requirements:new[]{home}));coordinator.ProcessReady(1);
            var source=coordinator.GetDecision(owner);Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(coordinator.TryCommit(source,canonical.Prepare()),Is.True);
            var request=CfcAnchorRequest(candidate,world,P(6));coordinator.EvaluateParking(request);
            Assert.That(CfcReprepare(coordinator,coordinator.GetDecision(candidate),request,out _),Is.True);coordinator.ProcessReady(11);
            var blocked=coordinator.GetDecision(candidate);
            Assert.That(blocked.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(blocked.Blockers.Select(value=>value.Owner),Does.Contain(owner));
            Assert.That(coordinator.TryCommit(blocked,incoming.Prepare()),Is.False);Assert.That(incoming.Applies,Is.Zero);
            Assert.That(coordinator.TryGetCommittedJourney(owner,out var retained),Is.True);Assert.That(retained,Is.SameAs(source));
            Assert.That(coordinator.HasActiveGrant(owner),Is.True);Assert.That(canonical.Applies,Is.EqualTo(1));Assert.That(canonical.Rollbacks,Is.Zero);
        }

        [TestCase(false)] [TestCase(true)]
        public void CfcLateParkingPeerOnSavedCapabilityRequiresReproofBeforeCanonicalCommit(bool acquired)
        {
            var key=Key("capability-owner");var peer=Key("late-capability-peer");
            var world=World(17,1,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:new object()),
                new TrafficBodyFact(peer,P(22,14),.4f,actorLife:new object())});
            var coordinator=Coordinator(world);var canonical=new CanonicalOwner();var peerOwner=new CanonicalOwner();
            var capability=new TrafficRouteRequirement("collection-exit-capability",P(20,10),P(24,10),.8f,avoidProposedParking:false);
            var request=CfcAnchorRequest(key,world,P(4),requirements:new[]{capability});
            coordinator.EvaluateParking(request);coordinator.ProcessReady(11);var original=coordinator.GetDecision(key);
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(original.ProofRoutes.Single(value=>value.ResourceId==request.ResourceId).Waypoints.Last(),Is.EqualTo(P(4)));
            Assert.That(original.ProofRoutes.Single(value=>value.ResourceId==capability.ResourceId).ExpandedPath,
                Is.EqualTo(new[]{P(20,10),P(24,10)}),"MODEL PREMISE: the saved capability actually crosses the future peer target, far from the primary");
            var late=new TrafficRequest(peer,12,world,P(22,14),P(22,10),.4f,"canonical/"+peer.ActorId,finiteSeconds:20,planPrimaryRoute:true);
            coordinator.EvaluateParking(late);coordinator.ProcessReady(12);var held=coordinator.GetDecision(peer);
            Assert.That(held.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            if(acquired)Assert.That(coordinator.TryCommit(held,peerOwner.Prepare()),Is.True);
            // A clear primary alone cannot preserve permission when a saved capability is obstructed.
            // 主路不相交也不能借旧proof直接写业务；进入原完整重证，允许未来找到真实绕路。
            Assert.That(CfcReprepare(coordinator,original,request,out var refreshed),Is.True);
            Assert.That(refreshed.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"PRODUCT: reprove the capability against the late actual prepared/canonical peer");
            Assert.That(coordinator.TryCommit(original,canonical.Prepare()),Is.False);Assert.That(canonical.Applies,Is.Zero);
            Assert.That(coordinator.HasActiveGrant(key),Is.False);Assert.That(coordinator.GetDecision(peer),Is.SameAs(held));
            Assert.That(coordinator.HasActiveGrant(peer),Is.EqualTo(acquired));Assert.That(peerOwner.Applies,Is.EqualTo(acquired?1:0));
        }

        // Moving only the real canonical anchor must neither spend a side nor refill the original phase.
        // 同一候选只更新 canonical anchor；旧许可不能提交，已花预算与未解决依赖仍保留。
        [TestCase(1,"queued",false)] [TestCase(2,"queued",true)]
        [TestCase(1,"waiting",false)] [TestCase(2,"waiting",true)]
        [TestCase(1,"prepared",false)] [TestCase(2,"prepared",true)]
        public void CfcAnchorMovedRepreparesSameCandidateWithoutResettingAccounting(int count,string state,bool physical)
        {
            var key=Key("anchor-move");var bodyOwner=Key(key.ActorId,"counter-body",4);var blocker=Key("anchor-blocker");
            var actor=new object();var canonical=new object();var business=new object();var release=new object();
            var bodies=new List<TrafficBodyFact>();
            if(physical)bodies.Add(new TrafficBodyFact(bodyOwner,Origin,.4f,actorLife:actor));
            if(state=="waiting")bodies.Add(new TrafficBodyFact(blocker,P(4),.4f,true,true,8,actorLife:new object()));
            var claims=physical?new[]{new TrafficParkingFact(bodyOwner,canonical,1,"counter",Origin,.4f,businessOwner:business,releaseObligation:release)}:Array.Empty<TrafficParkingFact>();
            var world=World(17,1,bodies.ToArray(),claims);var goals=new List<Vector3>();
            var coordinator=Coordinator(world,frameBudget:state=="queued"?1:128,query:(from,to)=>{goals.Add(to);return new[]{from,to};});
            var requirements=new[]{new TrafficRouteRequirement("side-capability",P(20,10),P(22,10),.8f,avoidProposedParking:false)};
            coordinator.EvaluateParking(CfcAnchorRequest(key,world,P(4),requirements:requirements),count-1,count);coordinator.ProcessReady(11);
            var expected=coordinator.GetDecision(key);
            Assert.That(expected.Kind,Is.EqualTo(state=="queued"?TrafficDecisionKind.DeferredByBudget:state=="waiting"?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.Granted));
            if(state=="waiting")coordinator.Tick(2,false);
            var queries=coordinator.QueriesConsumed(key);var wait=D1Read(coordinator,key,"WaitRemaining");
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");
            var edges=(IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers");
            if(state=="waiting")Assert.That(edges.Any(b=>b.Owner.Equals(blocker)),Is.True,"FIXTURE: current unresolved edge, not only historical eligibility");
            var fresh=World(18,2,bodies.ToArray(),claims);coordinator.SetSnapshot(fresh);
            if(!physical && state=="queued")Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh),
                "FIXTURE: automatic prospective refresh already adopted the version while retaining the old anchor");
            var moved=CfcAnchorRequest(key,fresh,P(6,4),99,requirements);
            Assert.That(coordinator.EvaluateParking(moved,count-1,count),Is.SameAs(expected),"Ordinary Submit still cannot replace the canonical target");
            Assert.That(CfcReprepare(coordinator,expected,moved,out var ready),Is.True,"PRODUCT: explicit same-candidate canonical anchor preparation must be accepted");
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(coordinator.HasActiveGrant(key),Is.False);
            Assert.That(coordinator.TryCommit(expected),Is.False,"Old unissued permission must not apply the new canonical target");
            Assert.That(CfcReprepare(coordinator,expected,moved,out _),Is.False,"The consumed exact expected cannot replay");
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(ready.RequestSequence,Is.EqualTo(expected.RequestSequence));
            Assert.That(ready.AcquiredSequence,Is.EqualTo(expected.AcquiredSequence));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(wait));Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));
            Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));
            Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(count));Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(count-1));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{count-1}));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).RequestedFrame,Is.EqualTo(11));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).FiniteSeconds,Is.EqualTo(20));
            Assert.That((System.Collections.IList)D1Read(coordinator,key,"Jobs"),Is.Empty,"Moved anchor requires fresh geometry, without a query in this port");
            coordinator.ProcessReady(12);coordinator.ProcessReady(13);var final=coordinator.GetDecision(key);
            Assert.That(final.Kind,Is.EqualTo(TrafficDecisionKind.Granted),final.Reason);
            Assert.That(final.ProofRoutes.Single(p=>p.ResourceId=="canonical/"+key.ActorId).Waypoints.Last(),Is.EqualTo(P(6,4)));
            Assert.That(goals.Count(p=>p==P(6,4)),Is.EqualTo(1));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries+2));
            var mutation=new CanonicalOwner();Assert.That(coordinator.TryCommit(final,mutation.Prepare()),Is.True);
            Assert.That(coordinator.TryCommit(final,mutation.Prepare()),Is.False);Assert.That(mutation.Applies,Is.EqualTo(1));
        }

        [TestCase("queued",false)] [TestCase("queued",true)]
        [TestCase("waiting",false)] [TestCase("waiting",true)]
        [TestCase("prepared",false)] [TestCase("prepared",true)]
        public void CfcAnchorSameTargetMetadataKeepsCompatibleFrontierAndSleepingWait(string state,bool walking)
        {
            var key=Key("anchor-metadata");var actor=new object();var blocker=Key("metadata-blocker");var walker=Key("unrelated-walker");var walkerLife=new object();
            TrafficBodyFact[] Bodies(bool moved)=>new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor),
                new TrafficBodyFact(walker,moved?P(31,30):P(30,30),.4f,true,true,8,actorLife:walkerLife)}
                .Concat(state=="waiting"?new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8)}:Array.Empty<TrafficBodyFact>()).ToArray();
            var world=World(17,1,Bodies(false));var calls=0;
            var coordinator=Coordinator(world,frameBudget:state=="queued"?1:128,query:(from,to)=>{calls++;return new[]{from,to};});
            var requirements=new[]{new TrafficRouteRequirement("side-capability",P(20,10),P(22,10),.8f,new[]{P(20,20)},avoidProposedParking:false)};
            coordinator.EvaluateParking(CfcAnchorRequest(key,world,P(4),requirements:requirements),1,2);coordinator.ProcessReady(11);
            var expected=coordinator.GetDecision(key);Assert.That(expected.Kind,Is.EqualTo(state=="queued"?TrafficDecisionKind.DeferredByBudget:state=="waiting"?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.Granted));
            if(state=="waiting")coordinator.Tick(2,false);
            var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();var index=D1Read(coordinator,key,"JobIndex");
            var wait=D1Read(coordinator,key,"WaitRemaining");var edges=D1Read(coordinator,key,"WaitingBlockers");var beforeCalls=calls;
            var fresh=World(18,walking?2:1,Bodies(walking));coordinator.SetSnapshot(fresh);
            Assert.That(CfcReprepare(coordinator,expected,CfcAnchorRequest(key,fresh,P(4),99,requirements),out var next),Is.True,
                "PRODUCT: current same-target metadata is accepted without restarting compatible work");
            Assert.That(calls,Is.EqualTo(beforeCalls));Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(index));
            var retained=(System.Collections.IList)D1Read(coordinator,key,"Jobs");Assert.That(retained.Count,Is.EqualTo(jobs.Length));
            for(var i=0;i<jobs.Length;i++)Assert.That(retained[i],Is.SameAs(jobs[i]),"Compatible bounded jobs retain their spent frontier");
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(wait));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(next.RequestSequence,Is.EqualTo(expected.RequestSequence));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{1}));
            if(state=="waiting")
            {
                Assert.That(next,Is.SameAs(expected));Assert.That(D1Read(coordinator,key,"Queued"),Is.EqualTo(false));
                coordinator.ProcessReady(12);Assert.That(coordinator.GetDecision(key),Is.SameAs(expected));Assert.That(calls,Is.EqualTo(beforeCalls));
                Assert.That(coordinator.DrainReady(),Is.Empty,"Unrelated version/walking is not a release notification");return;
            }
            if(state=="prepared")
            {Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(coordinator.TryCommit(expected),Is.False);}
            coordinator.ProcessReady(12);var final=coordinator.GetDecision(key);
            Assert.That(final.Kind,Is.EqualTo(TrafficDecisionKind.Granted),final.Reason);Assert.That(calls,Is.EqualTo(state=="queued"?beforeCalls+1:beforeCalls));
            Assert.That(final.ProofRoutes.Single(p=>p.ResourceId=="canonical/"+key.ActorId).Waypoints.Last(),Is.EqualTo(P(4)));
        }

        [TestCase("copied")] [TestCase("stale")] [TestCase("foreign")]
        [TestCase("terminal")] [TestCase("alternate")] [TestCase("acquired")] [TestCase("canonical-failed")]
        [TestCase("strict-leg")] [TestCase("bound-leg")] [TestCase("recovery")]
        [TestCase("selected-primary")] [TestCase("selected-requirement")]
        [TestCase("actor-life")] [TestCase("actor-pose")] [TestCase("actor-missing")]
        [TestCase("unborn-body")] [TestCase("unborn-claim")] [TestCase("own-claim-owner")]
        public void CfcAnchorReprepareRejectsForeignProtectedOrChangedActualLife(string state)
        {
            var key=Key("anchor-guard");var actor=new object();var canonical=new object();var business=new object();var release=new object();
            ServiceTrafficCoordinator coordinator;TrafficWorldSnapshot fresh;TrafficDecision stale=null;
            if(state=="strict-leg" || state=="bound-leg")
            {
                var f=new LegFixture();f.Prepare();if(state=="bound-leg"){f.CommitPrepared();Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(90,1)),Is.True);}
                coordinator=f.Coordinator;key=f.Key;fresh=f.World;
            }
            else if(state=="recovery")
            {
                var f=new PreparationRecoveryFixture();f.FailWithBody();Assert.That(f.Take(f.Current,f.Actor,out var receipt),Is.True);
                f.SetBody(null);Assert.That(f.Begin(receipt,out _),Is.True);coordinator=f.Coordinator;key=f.Next;fresh=f.World;
            }
            else
            {
                var unborn=state.StartsWith("unborn-",StringComparison.Ordinal);var own=Key(key.ActorId,"counter-body",4);
                var claims=unborn?Array.Empty<TrafficParkingFact>():new[]{new TrafficParkingFact(own,canonical,1,"counter",Origin,.4f,businessOwner:business,releaseObligation:release)};
                var world=World(17,1,unborn?null:new[]{new TrafficBodyFact(own,Origin,.4f,actorLife:actor)},claims);
                coordinator=Coordinator(world,query:(from,to)=>state=="terminal" || state=="alternate"?null:new[]{from,to});
                var requirements=state=="selected-requirement"?new[]{new TrafficRouteRequirement("selected-home",P(4),P(8),.8f,selectedJourney:true,avoidProposedParking:false)}:null;
                stale=coordinator.EvaluateParking(CfcAnchorRequest(key,world,P(4),requirements:requirements,
                    journey:state=="selected-primary"?new[]{Origin,P(4)}:null),0,state=="alternate"?2:1);coordinator.ProcessReady(11);
                var prepared=coordinator.GetDecision(key);
                if(state=="terminal" || state=="alternate")Assert.That(prepared.FailureDisposition,Is.EqualTo(state=="terminal"?TrafficFailureDisposition.Terminal:TrafficFailureDisposition.AlternateAllowed));
                else Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                if(state=="acquired")Assert.That(coordinator.TryCommit(prepared),Is.True);
                if(state=="canonical-failed")Assert.That(coordinator.TryCommit(prepared,new PreparationCanonicalFailure("apply-false")),Is.False);
                var bodies=state=="actor-missing" || unborn && state!="unborn-body"?Array.Empty<TrafficBodyFact>():
                    new[]{new TrafficBodyFact(own,state=="actor-pose"?P(-1):Origin,.4f,actorLife:state=="actor-life"?new object():actor)};
                if(state=="own-claim-owner" || state=="unborn-claim")claims=new[]{new TrafficParkingFact(own,new object(),2,"counter",Origin,.4f,businessOwner:business,releaseObligation:release)};
                fresh=World(18,2,bodies,claims);coordinator.SetSnapshot(fresh);
            }
            var current=coordinator.GetDecision(key);var expected=state=="stale"?stale:state=="copied"?
                new TrafficDecision(key,current.Kind,current.Reason,failureDisposition:current.FailureDisposition):current;
            var source=(TrafficRequest)D1Read(coordinator,key,"Request");var queries=coordinator.QueriesConsumed(key);
            var jobs=((System.Collections.IList)D1Read(coordinator,key,"Jobs")).Cast<object>().ToArray();
            var leg=D1Read(coordinator,key,"Leg");var journey=D1Read(coordinator,key,"JourneyPermit");var edges=D1Read(coordinator,key,"WaitingBlockers");
            var wait=D1Read(coordinator,key,"WaitRemaining");var active=coordinator.HasActiveGrant(key);
            var changed=new TrafficRequest(state=="foreign"?Key("foreign-anchor"):key,99,fresh,source.Start,P(6,4),source.Radius,source.ResourceId,
                source.SelectedJourney,source.Requirements,source.NativeStamp,source.IndependentlyProgressing,source.FiniteSeconds,source.ProvenFailure,source.SafetyMargin,source.PlanPrimaryRoute);
            Assert.That(CfcReprepare(coordinator,expected,changed,out var rejected),Is.False,"PRODUCT: anchor preparation cannot replace this actual source/life");
            Assert.That(rejected,Is.Null);Assert.That(coordinator.GetDecision(key),Is.SameAs(current));Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(source));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(coordinator.HasActiveGrant(key),Is.EqualTo(active));
            Assert.That(D1Read(coordinator,key,"Leg"),Is.SameAs(leg));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(journey));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(wait));
            var retained=(System.Collections.IList)D1Read(coordinator,key,"Jobs");Assert.That(retained.Count,Is.EqualTo(jobs.Length));
            for(var i=0;i<jobs.Length;i++)Assert.That(retained[i],Is.SameAs(jobs[i]));
        }

        // Prospective parking has no actor/claim yet. Refresh must precede the ordinary ready pump.
        // 测试只通过公开模型操作准备状态，不修改 private Entry 或复活 Terminal。
        private static TrafficRequest ProspectiveParking(TrafficIntentKey key,TrafficWorldSnapshot world,
            IEnumerable<TrafficRouteRequirement> requirements=null)
            =>new TrafficRequest(key,11,world,Origin,P(4),.4f,"prospective/"+key.ActorId,
                requirements:requirements,finiteSeconds:20,planPrimaryRoute:true);

        [TestCase(1)]
        [TestCase(2)]
        public void Fix3ProspectiveParkingAdoptsCanonicalVersionBeforeFirstReadyPump(int count)
        {
            var key=Key("unborn");var owner=Key("other-claim");var canonical=new object();var business=new object();var release=new object();
            var old=World(17,1,parking:new[]{new TrafficParkingFact(owner,canonical,1,"other",P(20),.4f,businessOwner:business,releaseObligation:release)});
            var fresh=World(18,2,parking:new[]{new TrafficParkingFact(owner,canonical,2,"other",P(20),.4f,businessOwner:business,releaseObligation:release)});
            var coordinator=Coordinator(old);var request=ProspectiveParking(key,old);
            coordinator.EvaluateParking(request,count-1,count);
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(coordinator.QueriesConsumed(key),Is.Zero);Assert.That(coordinator.HasActiveGrant(key),Is.False);
            coordinator.SetSnapshot(fresh);coordinator.ProcessReady(11);
            var decision=coordinator.GetDecision(key);
            Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"PRODUCT: unrelated canonical version must not create zero-query terminal before fresh caller evaluation");
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(1));Assert.That(coordinator.HasActiveGrant(key),Is.False);
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(count-1));
            Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(count));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{count-1}));
            var queries=coordinator.QueriesConsumed(key);var sequence=decision.RequestSequence;
            Assert.That(coordinator.EvaluateParking(ProspectiveParking(key,fresh),count-1,count),Is.SameAs(decision));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(decision.RequestSequence,Is.EqualTo(sequence));
        }

        [TestCase(false)]
        [TestCase(true)]
        public void Fix3ProspectiveVersionOnlyRefreshKeepsSpentCursorAndFrozenAccounting(bool waited)
        {
            var key=Key("unborn-cursor");var blocker=Key("cursor-progress");var claimOwner=Key("other-claim");
            var canonical=new object();var business=new object();var release=new object();
            TrafficParkingFact Claim(long version)=>new TrafficParkingFact(claimOwner,canonical,version,"other",P(20,5),.4f,
                businessOwner:business,releaseObligation:release);
            var bodies=waited?new[]{new TrafficBodyFact(blocker,P(4),.4f,true,true,8)}:Array.Empty<TrafficBodyFact>();
            var world=World(17,1,bodies,new[]{Claim(1)});var calls=0;
            var coordinator=Coordinator(world,frameBudget:1,query:(from,to)=>{calls++;return new[]{from,to};});
            var extra=new[]{new TrafficRouteRequirement("extra",P(10),P(12),.8f,avoidProposedParking:false)};
            coordinator.EvaluateParking(ProspectiveParking(key,world,extra),1,2);coordinator.ProcessReady(11);
            if(waited)
            {
                Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));coordinator.Tick(2,false);
                bodies=new[]{new TrafficBodyFact(blocker,P(20,-5),.4f,true,true,6)};
                world=World(17,2,bodies,new[]{Claim(1)});coordinator.SetSnapshot(world);coordinator.NotifyChanged(blocker,"body");coordinator.ProcessReady(12);
            }
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(calls,Is.EqualTo(1));
            var jobs=(System.Collections.IList)D1Read(coordinator,key,"Jobs");var first=jobs[0];var second=jobs[1];
            var before=coordinator.GetDecision(key);var wait=D1Read(coordinator,key,"WaitRemaining");
            var edges=(IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers");
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");
            var fresh=World(18,world.BodyVersion,bodies,new[]{Claim(2)});coordinator.SetSnapshot(fresh);
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh),"PRODUCT: refresh accepted before the pump, without a Submit or synthetic Notify");
            Assert.That(jobs[0],Is.SameAs(first));Assert.That(jobs[1],Is.SameAs(second));Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(1));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));
            Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(wait));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(coordinator,key,"AcquiredSequence"),Is.EqualTo(0));
            Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(2));Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(1));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{1}));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(1));Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).FiniteSeconds,Is.EqualTo(20));
            coordinator.ProcessReady(13);var granted=coordinator.GetDecision(key);
            Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(calls,Is.EqualTo(2));
            Assert.That(granted.RequestSequence,Is.EqualTo(before.RequestSequence));Assert.That(granted.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(wait));
        }

        [TestCase("target")]
        [TestCase("path")]
        [TestCase("claim-owner")]
        [TestCase("canonical-owner")]
        [TestCase("business-owner")]
        [TestCase("release-owner")]
        [TestCase("body-life")]
        public void Fix3ProspectiveChangedPhysicalOrClaimIdentityCannotReuseObsoleteGeometry(string change)
        {
            var key=Key("unborn-changed");var other=Key("changed-owner");var canonical=new object();var business=new object();var release=new object();
            var oldBodyLife=new object();var oldClaim=new TrafficParkingFact(other,canonical,1,"other",P(20),.4f,
                businessOwner:business,releaseObligation:release);
            var old=World(17,1,new[]{new TrafficBodyFact(other,P(20,5),.4f,true,true,8,actorLife:oldBodyLife)},new[]{oldClaim});
            var coordinator=Coordinator(old,frameBudget:1);var extra=new[]{new TrafficRouteRequirement("extra",P(10),P(12),.8f,avoidProposedParking:false)};
            coordinator.EvaluateParking(ProspectiveParking(key,old,extra),1,2);coordinator.ProcessReady(11);
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(1));
            var jobs=(System.Collections.IList)D1Read(coordinator,key,"Jobs");var completed=jobs[0];var sequence=coordinator.GetDecision(key).RequestSequence;
            var position=change=="target"?P(4):change=="path"?P(2):P(20);
            var newClaim=new TrafficParkingFact(change=="claim-owner"?Key(other.ActorId,"changed",2):other,
                change=="canonical-owner"?new object():canonical,2,"other",position,.4f,
                businessOwner:change=="business-owner"?new object():business,releaseObligation:change=="release-owner"?new object():release);
            var fresh=World(18,2,new[]{new TrafficBodyFact(other,change=="body-life"?P(2):P(20,5),.4f,true,change!="body-life",8,
                actorLife:change=="body-life"?new object():oldBodyLife)},new[]{newClaim});
            coordinator.SetSnapshot(fresh);
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh));
            Assert.That(jobs.Count==0 || !ReferenceEquals(jobs[0],completed),Is.True,"Only owner-version metadata may retain a cursor across canonical version changes");
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(1));Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));
            Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(2));Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(1));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{1}));
            coordinator.ProcessReady(12);var decision=coordinator.GetDecision(key);
            Assert.That(decision.Kind,Is.Not.EqualTo(TrafficDecisionKind.StaleContext));Assert.That(decision.RequestSequence,Is.EqualTo(sequence));
            Assert.That(coordinator.HasActiveGrant(key),Is.False);
            if(change=="target")
            {Assert.That(decision.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(decision.Blockers.Any(b=>b.Owner.Equals(other) && b.ResourceId=="other"),Is.True);}
            if((change=="path" || change=="body-life") && decision.Kind==TrafficDecisionKind.Granted)
            {
                var path=decision.ProofRoutes.Single(p=>p.ResourceId=="prospective/"+key.ActorId).ExpandedPath;
                for(var i=1;i<path.Count;i++)
                {
                    var segment=path[i]-path[i-1];var t=segment.sqrMagnitude==0?0:Mathf.Clamp01(Vector3.Dot(P(2)-path[i-1],segment)/segment.sqrMagnitude);
                    Assert.That(Vector3.Distance(P(2),path[i-1]+segment*t),Is.GreaterThanOrEqualTo(.799f),"Fresh physical obstacle cannot be crossed by an old prepared primary path");
                }
            }
        }

        [TestCase("terminal")]
        [TestCase("prepared")]
        [TestCase("acquired")]
        [TestCase("canonical-attempt")]
        [TestCase("strict-leg")]
        [TestCase("handoff")]
        [TestCase("recovery")]
        [TestCase("old-body")]
        [TestCase("new-body")]
        [TestCase("other-intent-body")]
        [TestCase("old-claim")]
        [TestCase("new-claim")]
        [TestCase("other-intent-claim")]
        public void Fix3ProspectiveRefreshDoesNotAdoptProtectedOrAlreadyPhysicalSources(string state)
        {
            var key=Key("excluded");ServiceTrafficCoordinator coordinator;TrafficWorldSnapshot old,fresh;
            if(state=="strict-leg")
            {
                var f=new LegFixture();f.Prepare();coordinator=f.Coordinator;key=f.Key;old=f.World;
                fresh=World(old.Version+1,old.BodyVersion,old.Bodies.ToArray(),old.Parking.ToArray());
            }
            else if(state=="handoff")
            {
                var f=new HandoffFixture();f.Begin();coordinator=f.Coordinator;key=f.Owner;old=f.World;
                fresh=World(old.Version+1,old.BodyVersion,old.Bodies.ToArray(),old.Parking.ToArray());
            }
            else if(state=="recovery")
            {
                var f=new PreparationRecoveryFixture();f.FailWithBody();Assert.That(f.Take(f.Current,f.Actor,out var receipt),Is.True);
                f.SetBody(null);Assert.That(f.Begin(receipt,out _),Is.True);coordinator=f.Coordinator;key=f.Next;old=f.World;
                fresh=World(old.Version+1,old.BodyVersion,old.Bodies.ToArray(),old.Parking.ToArray());
            }
            else
            {
                var alias=Key(key.ActorId,"registered",4);var canonical=new object();
                var oldBodies=state=="old-body" || state=="other-intent-body"?
                    new[]{new TrafficBodyFact(state=="old-body"?key:alias,Origin,.4f,actorLife:new object())}:Array.Empty<TrafficBodyFact>();
                var oldClaims=state=="old-claim" || state=="other-intent-claim"?
                    new[]{new TrafficParkingFact(state=="old-claim"?key:alias,canonical,1,"owned",P(20),.4f)}:Array.Empty<TrafficParkingFact>();
                old=World(17,1,oldBodies,oldClaims);coordinator=Coordinator(old,query:(from,to)=>state=="terminal"?null:new[]{from,to});
                coordinator.EvaluateParking(ProspectiveParking(key,old));
                if(state=="terminal" || state=="prepared" || state=="acquired" || state=="canonical-attempt")coordinator.ProcessReady(11);
                if(state=="acquired" || state=="canonical-attempt")
                    Assert.That(coordinator.TryCommit(coordinator.GetDecision(key),state=="canonical-attempt"?new CanonicalOwner().Prepare():null),Is.True);
                if(state=="terminal")Assert.That(coordinator.GetDecision(key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                fresh=World(18,2,state=="new-body"?new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:new object())}:Array.Empty<TrafficBodyFact>(),
                    state=="new-claim"?new[]{new TrafficParkingFact(key,canonical,2,"owned",P(20),.4f)}:Array.Empty<TrafficParkingFact>());
            }
            var request=D1Read(coordinator,key,"Request");var decision=coordinator.GetDecision(key);var queries=coordinator.QueriesConsumed(key);
            var leg=D1Read(coordinator,key,"Leg");var journey=D1Read(coordinator,key,"JourneyPermit");var handoff=D1Read(coordinator,key,"PendingHandoff");
            coordinator.SetSnapshot(fresh);
            Assert.That(D1Read(coordinator,key,"Request"),Is.SameAs(request),"Prospective refresh excludes existing body/claim, authority and explicit recovery state");
            Assert.That(coordinator.GetDecision(key),Is.SameAs(decision));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            Assert.That(D1Read(coordinator,key,"Leg"),Is.SameAs(leg));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(journey));
            Assert.That(D1Read(coordinator,key,"PendingHandoff"),Is.SameAs(handoff));
            if(state=="terminal")Assert.That(coordinator.EvaluateParking(ProspectiveParking(key,fresh)),Is.SameAs(decision));
        }

        [TestCase("release")]
        [TestCase("move")]
        [TestCase("compatible-body")]
        [TestCase("release-with-static-keepout")]
        public void Fix4QueuedMovementRefreshesCanonicalGeometryWithoutDroppingStaticKeepouts(string change)
        {
            var key=Key("interior-waiter");var blocker=Key("interior-progress");var claimOwner=Key("interior-claim");
            var actor=new object();var business=new object();var release=new object();
            var queue=new PickupQueueService(new[]{P(2)},new[]{P(10)});
            Assert.That(queue.TryReserve(claimOwner.ActorId,out _),Is.True);
            Assert.That(queue.TryBeginTransfer(claimOwner.ActorId,out var assignment),Is.True);
            Assert.That(queue.MarkArrived(claimOwner.ActorId,assignment.Generation),Is.True);
            TrafficWorldSnapshot Snapshot(long version,Vector3 bodyPosition,float remaining)
            {
                var parking=queue.TryGetReservation(claimOwner.ActorId,out var current)
                    ?new[]{new TrafficParkingFact(claimOwner,queue,queue.Version,"pickup/interior",current.Position,.4f,
                        businessOwner:business,releaseObligation:release)}:Array.Empty<TrafficParkingFact>();
                return World(queue.Version,version,new[]{new TrafficBodyFact(blocker,bodyPosition,.4f,true,true,remaining,actorLife:actor)},parking);
            }
            var explicitKeepout=change=="release-with-static-keepout";var compatible=change=="compatible-body";
            var requirements=explicitKeepout?new[]{new TrafficRouteRequirement("fixed-keepout",Origin,P(4),.8f,
                new[]{P(2)},avoidProposedParking:false)}:Array.Empty<TrafficRouteRequirement>();
            var calls=0;var directCalls=0;var world=Snapshot(1,P(4),8);
            // Pure model corridor: only the original direct leg is reachable; no Native result is claimed.
            // 真实 Queue 提供当前 claim；只有路径查询是模型，旧 detour targets 没有可用路径。
            // C has a canonical reservation only in this model; moving/removing it makes no C-body release claim.
            var coordinator=Coordinator(world,frameBudget:1,query:(from,to)=>
            {
                calls++;if(from==Origin && to==P(4)){directCalls++;return new[]{from,to};}return null;
            });
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world,frame:11,requirements:requirements));coordinator.ProcessReady(11);
            var waiting=coordinator.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(waiting.Blockers.Single().Owner,Is.EqualTo(blocker));Assert.That(waiting.Blockers.Single().ResourceId,Is.EqualTo("body"));
            Assert.That(calls,Is.Zero);coordinator.Tick(3,false);
            world=Snapshot(2,P(20),5);coordinator.SetSnapshot(world);coordinator.NotifyChanged(blocker,"body");
            Assert.That(coordinator.DrainReady(),Is.EquivalentTo(new[]{key}));coordinator.ProcessReady(12);
            var deferred=coordinator.GetDecision(key);
            Assert.That(deferred.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(calls,Is.EqualTo(1));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(1));
            Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(0),"The primary itself is partially searched, not a later requirement");
            var primary=((System.Collections.IList)D1Read(coordinator,key,"Jobs"))[0];
            var edges=(IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers");
            var frozen=D1Read(coordinator,key,"FrozenOwners");var resources=D1Read(coordinator,key,"FrozenResources");
            Assert.That(edges.Single().Owner,Is.EqualTo(blocker));Assert.That(edges.Single().ResourceId,Is.EqualTo("body"));
            Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(5f));
            var oldVersion=queue.Version;
            if(change=="move")
            {
                Assert.That(queue.TryPrepareMutation(PickupQueueService.MutationKind.BeginYield,claimOwner.ActorId,queue.Version,out var move,P(2,4)),Is.True);
                Assert.That(queue.TryApplyPrepared(move,out var receipt),Is.True);Assert.That(receipt.IsCurrent,Is.True);
                Assert.That(queue.TryGetReservation(claimOwner.ActorId,out assignment),Is.True);Assert.That(assignment.Position,Is.EqualTo(P(2,4)));
            }
            else if(!compatible)Assert.That(queue.Remove(claimOwner.ActorId),Is.True);
            Assert.That(queue.Version,compatible?Is.EqualTo(oldVersion):Is.GreaterThan(oldVersion));
            world=Snapshot(3,P(20,2),5);coordinator.SetSnapshot(world);coordinator.NotifyChanged(blocker,"body");
            Assert.That(coordinator.DrainReady(),Is.EquivalentTo(new[]{key}));
            var refreshed=(TrafficRequest)D1Read(coordinator,key,"Request");
            Assert.That(refreshed.Snapshot,Is.SameAs(world));Assert.That(refreshed.Intent,Is.EqualTo(key));Assert.That(refreshed.Start,Is.EqualTo(Origin));
            Assert.That(refreshed.RequestedFrame,Is.EqualTo(11));Assert.That(refreshed.FiniteSeconds,Is.EqualTo(20));
            Assert.That(D1Read(coordinator,key,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,key,"FrozenOwners"),Is.SameAs(frozen));
            Assert.That(D1Read(coordinator,key,"FrozenResources"),Is.SameAs(resources));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(5f));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(1));Assert.That(coordinator.GetDecision(key).RequestSequence,Is.EqualTo(deferred.RequestSequence));
            Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.EqualTo(deferred.AcquiredSequence));
            if(compatible)
            {
                Assert.That(((System.Collections.IList)D1Read(coordinator,key,"Jobs"))[0],Is.SameAs(primary),
                    "An independently moving body changes safety facts without changing the captured planning obstacles");
                Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(0));
            }
            if(explicitKeepout)Assert.That(refreshed.Requirements.Single().Obstacles,Is.EqualTo(new[]{P(2)}));
            // Two rings supply 16 inaccessible detour nodes. Twenty single-query pumps cover old exhaustion or the valid continuation.
            // 不补充 query/wait 预算；释放后直接路径只需再查询一次，静态 keepout 仍必须挡住对应 proof。
            for(var frame=13;frame<33 && coordinator.GetDecision(key).Kind==TrafficDecisionKind.DeferredByBudget;frame++)coordinator.ProcessReady(frame);
            var result=coordinator.GetDecision(key);
            Assert.That(result.Kind,Is.EqualTo(compatible || explicitKeepout?TrafficDecisionKind.PlanningFailed:TrafficDecisionKind.Granted),
                "PRODUCT: current canonical geometry must decide the original candidate; actual="+result.Kind+"/"+result.Reason+" queries="+calls);
            if(compatible || explicitKeepout)
            {
                Assert.That(result.Reason,Is.EqualTo("bounded-route-proof-failed"));
                Assert.That(result.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                if(compatible)Assert.That(directCalls,Is.EqualTo(1),"A compatible checkpoint must not restart the partially searched primary");
            }
            else
            {
                Assert.That(calls,Is.EqualTo(2),"Retain the spent query, then prove the now-clear direct route once");
                Assert.That(result.ProofRoutes.Single().ExpandedPath,Is.EqualTo(new[]{Origin,P(4)}));
            }
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(calls));Assert.That(calls,Is.LessThanOrEqualTo(19));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(5f));
            Assert.That(result.RequestSequence,Is.EqualTo(waiting.RequestSequence));Assert.That(result.AcquiredSequence,Is.Zero);
            Assert.That(D1Read(coordinator,key,"CandidateCount"),Is.EqualTo(1));Assert.That(D1Read(coordinator,key,"CurrentIndex"),Is.EqualTo(0));
            Assert.That((HashSet<int>)D1Read(coordinator,key,"AttemptedIndices"),Is.EquivalentTo(new[]{0}));
            Assert.That(coordinator.HasActiveGrant(key),Is.False);
        }

        [TestCase("exact")]
        [TestCase("other-resource")]
        [TestCase("other-actor")]
        [TestCase("other-generation")]
        [TestCase("other-context")]
        public void Fix3WakeRequiresExactCurrentFullOwnerAndResource(string change)
        {
            var owner=Key("wake-owner");var waiter=Key("wake-waiter");
            var world=World(actors:new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,8)});var coordinator=Coordinator(world);
            coordinator.EvaluateMovement(Request(waiter,Origin,P(4),world));coordinator.ProcessReady(1);
            var waiting=coordinator.GetDecision(waiter);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(waiting.Blockers.Single().Owner,Is.EqualTo(owner));Assert.That(waiting.Blockers.Single().ResourceId,Is.EqualTo("body"));
            var fresh=World(2,2,new[]{new TrafficBodyFact(owner,P(20),.4f,true,true,8)});coordinator.SetSnapshot(fresh);
            var eventOwner=change=="other-actor"?Key("foreign"):change=="other-generation"?Key("wake-owner",generation:2):
                change=="other-context"?new TrafficIntentKey(owner.Session,owner.Epoch,owner.ActorId,owner.IntentId,owner.Generation,owner.LayoutRevision,"foreign-order"):owner;
            coordinator.NotifyChanged(eventOwner,change=="other-resource"?"service/wake-owner":"body");
            Assert.That(coordinator.DrainReady(),change=="exact"?Is.EquivalentTo(new[]{waiter}):Is.Empty,
                "PRODUCT: generic body spelling and ActorId are not full dependency authority");
            coordinator.ProcessReady(2);
            if(change=="exact")Assert.That(coordinator.GetDecision(waiter).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            else {Assert.That(coordinator.GetDecision(waiter),Is.SameAs(waiting));Assert.That(coordinator.QueriesConsumed(waiter),Is.Zero);}
        }

        [TestCase(false)]
        [TestCase(true)]
        public void Fix3QueuedWakeCoalescesSameCheckpointButInspectsFreshBodyFacts(bool changedBody)
        {
            var owner=Key("cursor-owner");var key=Key("cursor-waiter");var calls=0;
            var world=World(actors:new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,8)});
            var coordinator=Coordinator(world,frameBudget:1,query:(from,to)=>{calls++;return new[]{from,to};});
            var extra=new[]{new TrafficRouteRequirement("extra",P(10),P(12),.8f)};
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world,requirements:extra));coordinator.ProcessReady(1);coordinator.Tick(3,false);
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            world=World(2,2,new[]{new TrafficBodyFact(owner,P(20),.4f,true,true,5)});coordinator.SetSnapshot(world);coordinator.NotifyChanged(owner,"body");
            coordinator.ProcessReady(2);Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            var jobs=(System.Collections.IList)D1Read(coordinator,key,"Jobs");var firstJob=jobs[0];var secondJob=jobs[1];
            Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(1));Assert.That(calls,Is.EqualTo(1));
            var budget=D1Read(coordinator,key,"WaitRemaining");var decision=coordinator.GetDecision(key);
            coordinator.DrainReady();
            if(changedBody)
            {world=World(3,3,new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,5)});coordinator.SetSnapshot(world);}
            coordinator.NotifyChanged(owner,"body");coordinator.NotifyChanged(owner,"body");
            Assert.That(((System.Collections.IList)D1Read(coordinator,key,"Jobs"))[0],Is.SameAs(firstJob));
            Assert.That(((System.Collections.IList)D1Read(coordinator,key,"Jobs"))[1],Is.SameAs(secondJob));
            Assert.That(D1Read(coordinator,key,"JobIndex"),Is.EqualTo(1));Assert.That(calls,Is.EqualTo(1));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(world),"Queued coalescing must not drop a newly published authenticated checkpoint");
            coordinator.ProcessReady(3);var result=coordinator.GetDecision(key);
            Assert.That(result.Kind,Is.EqualTo(changedBody?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.Granted));
            Assert.That(calls,Is.EqualTo(changedBody?1:2),"Completed primary query is never repeated");
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(1));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That(result.RequestSequence,Is.EqualTo(decision.RequestSequence));
            Assert.That((HashSet<TrafficIntentKey>)D1Read(coordinator,key,"FrozenOwners"),Is.EquivalentTo(new[]{owner}));
            if(changedBody)Assert.That(result.Blockers.Single().Owner,Is.EqualTo(owner));
        }

