            Assert.That(f.World.Bodies.Single().Owner,Is.EqualTo(f.BodyOwner));Assert.That(f.World.Bodies.Single().ActorLife,Is.SameAs(f.Actor));
            Assert.That(f.World.Parking.Single(),Is.SameAs(f.Parking));
