            Assert.That(f.Coordinator.GetDecision(incoming).Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted),"Stopped/arrived body still physically exists");
            Assert.That(f.Coordinator.GetDecision(incoming).Blockers.Any(b=>b.Owner.Equals(f.BodyOwner)&&b.ResourceId=="body"),Is.True);
        }

