        [TestCase("resource")]
        [TestCase("body")]
        public void Fix3FinalHandoffProtectsHeldDependencyBeforeCanonicalCallbackNotification(string notification)
        {
            var f=new HandoffFixture();var waiter=f.Coordinator.GetDecision(f.Waiter);var queries=f.Coordinator.QueriesConsumed(f.Waiter);
            var wait=f.Read(f.Waiter,"WaitRemaining");f.ArriveBody();IReadOnlyList<TrafficIntentKey> observedReady=null;object observedQueued=null;
            Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
            {
                f.Coordinator.NotifyChanged(f.Owner,notification=="body"?"body":f.Resource);
                observedReady=f.Coordinator.DrainReady();observedQueued=f.Read(f.Waiter,"Queued");return f.Confirm();
            },out var pending),Is.True);
            Assert.That(observedReady,Is.Empty,"PRODUCT: actual final-arrival gap is protected before reentrant canonical notification");
            Assert.That(observedQueued,Is.EqualTo(false));
            Assert.That(pending,Is.Not.Null);Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(waiter));
            Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(wait));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(queries));
        }

        [Test] public void Fix3AllReleasedMilestoneWakesEveryOriginalResourceAndActualBody()
        {
            var f=new MultiClaimFixture();var originals=f.Waiters.Select(k=>f.Coordinator.GetDecision(k)).ToArray();f.Arrive();
            Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
            {
                f.Confirm();f.Release("counter");f.Release("service");f.Release("pickup");var receipt=f.Receipt();
                foreach(var claim in f.Originals)Assert.That(receipt.ReadClaim(claim,out _),Is.EqualTo(TrafficPhaseClaimState.Released));
                return receipt;
            },out var pending),Is.True);
            Assert.That(pending,Is.Null);f.Refresh(); // Real canonical facts are fresh before any later query pump.
            Assert.That(f.Coordinator.DrainReady(),Is.EquivalentTo(f.Waiters));
            Assert.That(f.World.Parking,Is.Empty);Assert.That(f.World.Bodies.Single().ActorLife,Is.SameAs(f.Actor));
            for(var i=0;i<f.Waiters.Length;i++)
            {Assert.That(f.Coordinator.GetDecision(f.Waiters[i]),Is.SameAs(originals[i]));Assert.That(f.Read(f.Waiters[i],"Queued"),Is.True);}
            Assert.That(f.Completed,Is.True);Assert.That(f.ConfirmCalls,Is.EqualTo(1));
        }

        [TestCase(false)]
        [TestCase(true)]
        public void Fix3AcceptedSameLimitRefreshPreservesCurrentEdgesAndOriginalAccounting(bool deferred)
        {
            var owner=Key("accepted-refresh-owner");var key=Key("accepted-refresh-waiter");
            var world=World(actors:new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,8)});var coordinator=Coordinator(world,frameBudget:1);
            var requirements=new[]{new TrafficRouteRequirement("extra",P(10),P(12),.8f)};
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world,requirements:requirements));coordinator.ProcessReady(1);coordinator.Tick(3,false);
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            if(deferred)
            {world=World(2,2);coordinator.SetSnapshot(world);coordinator.NotifyChanged(owner,"body");coordinator.ProcessReady(2);
                Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));}
            var old=coordinator.GetDecision(key);var edges=((IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers")).ToArray();
            Assert.That(edges,Is.Not.Empty);var queries=coordinator.QueriesConsumed(key);var budget=D1Read(coordinator,key,"WaitRemaining");
            var frozen=((HashSet<TrafficIntentKey>)D1Read(coordinator,key,"FrozenOwners")).ToArray();
            var resources=((Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(coordinator,key,"FrozenResources")).ToDictionary(p=>p.Key,p=>p.Value.ToArray());
            var fresh=World(3,3,world.Bodies.ToArray());coordinator.SetSnapshot(fresh);
            coordinator.EvaluateMovement(Request(key,Origin,P(4),fresh,frame:99,requirements:requirements,seconds:20));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).Snapshot,Is.SameAs(fresh),"Accepted same-limit refresh, not the finite-refill refusal branch");
            Assert.That(((IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers")).Select(b=>new{b.Owner,b.ResourceId}),
                Is.EquivalentTo(edges.Select(b=>new{b.Owner,b.ResourceId})));
            Assert.That((HashSet<TrafficIntentKey>)D1Read(coordinator,key,"FrozenOwners"),Is.EquivalentTo(frozen));
            foreach(var pair in resources)Assert.That(((Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(coordinator,key,"FrozenResources"))[pair.Key],Is.EquivalentTo(pair.Value));
            Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).FiniteSeconds,Is.EqualTo(20));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(1));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(coordinator.GetDecision(key).RequestSequence,Is.EqualTo(old.RequestSequence));
            Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.EqualTo(old.AcquiredSequence));
        }

        // A model-only bound leg authenticates the full registered body key, not an ActorId alias.
        private sealed class BodyCheckpointFixture
        {
            internal readonly object Actor=new object(),Canonical=new object();
            internal readonly TrafficIntentKey Motion=Key("checkpoint-actor","motion",4),Waiter=Key("checkpoint-body-waiter"),ParkingWaiter=Key("checkpoint-parking-waiter");
            internal readonly TrafficIntentKey BodyOwner;internal readonly TrafficNativeStamp Stamp=new TrafficNativeStamp(401,4);
            internal readonly ServiceTrafficCoordinator Coordinator;internal readonly TrafficParkingFact Parking;
            internal TrafficWorldSnapshot World;internal Vector3 Position=Origin;
            internal BodyCheckpointFixture(bool distinct,bool bind=true)
            {
                BodyOwner=distinct?Key(Motion.ActorId,"registered-body",8):Motion;
                Parking=new TrafficParkingFact(BodyOwner,Canonical,1,"retained-slot",P(8),.4f);
                World=Snapshot(1,true);Coordinator=ServiceTrafficCoordinatorTests.Coordinator(World);
                var source=Grant(Coordinator,Request(Motion,Origin,P(4),World,resource:"motion"));
                Assert.That(Coordinator.PrepareLeg(source,"motion",0,Actor,4,World,Origin,.05f,2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Coordinator.ProcessReady(2);Assert.That(Coordinator.TryCommit(Coordinator.GetDecision(Motion)),Is.True);
                if(bind)Assert.That(Coordinator.BindLeg(Motion,Actor,Stamp),Is.True);
                Coordinator.EvaluateMovement(Request(Waiter,P(0,-3),Origin,World,frame:3));
                Coordinator.EvaluateMovement(Request(ParkingWaiter,P(8,-3),P(8),World,frame:3));Coordinator.ProcessReady(3);
                Assert.That(Coordinator.GetDecision(Waiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                Assert.That(Coordinator.GetDecision(Waiter).Blockers.Single().Owner,Is.EqualTo(BodyOwner));
                Assert.That(Coordinator.GetDecision(Waiter).Blockers.Single().ResourceId,Is.EqualTo("body"));
                Assert.That(Coordinator.GetDecision(ParkingWaiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                Assert.That(Coordinator.DrainReady(),Is.Empty);
            }
            private TrafficWorldSnapshot Snapshot(int version,bool progressing)=>ServiceTrafficCoordinatorTests.World(version,version,
                new[]{new TrafficBodyFact(BodyOwner,Position,.4f,true,progressing,progressing?8:0,actorLife:Actor)},new[]{Parking});
            internal void Move(Vector3 position){Position=position;World=Snapshot(2,false);Coordinator.SetSnapshot(World);}
            internal MovementResult StopResult()=>new MovementResult(Stamp.RequestId,Motion.ActorId,MovementStatus.Failed,
                NavigationFailure.MovementTimeout,NavigationFailure.MovementTimeout,NavigationFailure.None,Position,0);
            internal bool Stop(object actor,TrafficNativeStamp stamp,MovementResult result)
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod("TryRetireStoppedLeg",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That(method,Is.Not.Null,"Inert API declaration exists before actual behavior RED");
                return (bool)method.Invoke(Coordinator,new object[]{Motion,actor,stamp,result});
            }
            internal bool TakePaidFailure()
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod("TryRetireFailedLeg",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                var args=new object[]{Motion,Actor,Stamp,StopResult(),null};var accepted=(bool)method.Invoke(Coordinator,args);
                if(accepted)Assert.That(args[4],Is.Not.Null,"Original once-only receipt remains required");return accepted;
            }
        }

        // D1 contract RED: public model operations create every failure; no private Fail/state injection.
        // 仅模拟 Native query 的输入结果；terminal、预算和共同提交都由实际 Core 产生。
        [TestCase("query")]
        [TestCase("wait")]
        [TestCase("non-independent")]
        [TestCase("cycle")]
        [TestCase("apply-false")]
        [TestCase("apply-throw")]
        [TestCase("null-receipt")]
        [TestCase("rollback-unknown")]
        [TestCase("retired")]
        public void D1TerminalDecisionRejectsOrdinaryMetadataResurrection(string failure)
        {
            var key=Key("b-terminal");var owner=Key("a-owner");var calls=0;
            var finite=failure=="wait" || failure=="cycle";
            var bodies=failure=="wait" || failure=="non-independent" || failure=="cycle"
                ?new[]{new TrafficBodyFact(owner,P(4),.4f,true,finite,finite?8:0),
                    new TrafficBodyFact(key,Origin,.4f,true,true,8)}:Array.Empty<TrafficBodyFact>();
            var world=World(actors:bodies);
            var coordinator=Coordinator(world,intentBudget:failure=="query"?1:16,
                query:(from,to)=>{calls++;return new[]{from,to};});
            var requirements=failure=="query"?new[]{new TrafficRouteRequirement("second-proof",P(10),P(12),.8f)}:null;
            if(failure=="cycle")coordinator.EvaluateMovement(Request(owner,P(4),Origin,world));
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world,requirements:requirements),1,2);
            coordinator.ProcessReady(1);
            PreparationCanonicalFailure mutation=null;
            if(failure=="wait")
            {
                Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: finite original owner");
                coordinator.Tick(8.1f,false);
            }
            else if(failure=="retired")
            {
                Assert.That(coordinator.TryCommit(coordinator.GetDecision(key)),Is.True);
                coordinator.Retire(key);
            }
            else if(failure.StartsWith("apply-") || failure=="null-receipt" || failure=="rollback-unknown")
            {
                Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                mutation=new PreparationCanonicalFailure(failure);
                Assert.That(coordinator.TryCommit(coordinator.GetDecision(key),mutation),Is.False);
                Assert.That(mutation.Applies,Is.EqualTo(1));
            }
            var terminal=coordinator.GetDecision(key);
            Assert.That(terminal.Kind,Is.EqualTo(failure=="retired"?TrafficDecisionKind.Cancelled:TrafficDecisionKind.PlanningFailed),"FIXTURE: actual terminal source");
            if(failure=="query")Assert.That(terminal.Reason,Is.EqualTo("intent-query-budget-exhausted"));
            if(failure=="wait")Assert.That(terminal.Reason,Is.EqualTo("wait-budget-exhausted"));
            var queries=coordinator.QueriesConsumed(key);var oldCalls=calls;var rollbacks=mutation?.Rollbacks??0;
            var age=D1Read(coordinator,key,"FirstFrame");var remaining=D1Read(coordinator,key,"WaitRemaining");
            var fresh=World(2,2);coordinator.SetSnapshot(fresh);coordinator.NotifyChanged(owner,"body");
            var discarded=coordinator.DiscardPrepared(key);
            var replacement=Request(key,P(-1),P(6),fresh,frame:99,seconds:100);
            var polled=coordinator.EvaluateMovement(replacement,0,3);
            var advanced=coordinator.TryAdvanceCandidate(terminal,0,replacement,out _);
            coordinator.ProcessReady(99);
            var cleanOwner=new CanonicalOwner();var published=0;
            var committed=coordinator.TryCommit(coordinator.GetDecision(key),cleanOwner.Prepare(),()=>published++);
            // The project's NUnit 3.5 has no Assert.Multiple; use ordinary behavioral assertions.
            // 使用项目已有 NUnit 支持的断言，避免把编译错误当成 RED。
            {
                Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                Assert.That(discarded,Is.False,"Metadata discard cannot erase a genuine terminal");
                Assert.That(polled,Is.SameAs(terminal));Assert.That(coordinator.GetDecision(key),Is.SameAs(terminal));
                Assert.That(advanced,Is.False);Assert.That(committed,Is.False);Assert.That(published,Is.Zero);
                Assert.That(cleanOwner.Applies,Is.Zero);Assert.That(cleanOwner.Rollbacks,Is.Zero);
                Assert.That(calls,Is.EqualTo(oldCalls));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
                Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(age));Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(remaining));
                Assert.That(coordinator.HasActiveGrant(key),Is.False);
                if(mutation!=null){Assert.That(mutation.Applies,Is.EqualTo(1));Assert.That(mutation.Rollbacks,Is.EqualTo(rollbacks));}
            }
        }

        [TestCase(false)]
        [TestCase(true)]
        public void D1FiniteOriginalCandidatesAdvanceBackwardOnceAndNeverWrap(bool lastAlsoFails)
        {
            var key=Key("finite-candidates");var world=World();var calls=0;
            var coordinator=Coordinator(world,query:(from,to)=>{calls++;return to==P(4) || lastAlsoFails?null:new[]{from,to};});
            var first=Request(key,Origin,P(4),world);
            coordinator.EvaluateMovement(first,1,2);coordinator.ProcessReady(1);
            var failed=coordinator.GetDecision(key);
            Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(failed.Reason,Is.EqualTo("bounded-route-proof-failed"),"FIXTURE: real uncommitted route-proof failure");
            var next=Request(key,Origin,P(6),world,frame:2);
            var copied=new TrafficDecision(key,failed.Kind,failed.Reason,failureDisposition:TrafficFailureDisposition.AlternateAllowed);
            Assert.That(coordinator.TryAdvanceCandidate(copied,0,next,out _),Is.False,"A caller-created DTO is not the exact current decision");
            Assert.That(coordinator.TryAdvanceCandidate(failed,1,first,out _),Is.False,"Already attempted descriptor");
            Assert.That(coordinator.TryAdvanceCandidate(failed,2,next,out _),Is.False,"Outside original count");
            Assert.That(coordinator.TryAdvanceCandidate(failed,0,Request(Key("foreign"),Origin,P(6),world),out _),Is.False);
            Assert.That(coordinator.EvaluateMovement(next,0,3),Is.SameAs(failed),"Ordinary Submit cannot enlarge count or switch side");
            Assert.That(coordinator.EvaluateMovement(first,1,2),Is.SameAs(failed));coordinator.ProcessReady(2);
            Assert.That(calls,Is.EqualTo(1),"Polling failed candidate cannot re-run its query");
            Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.AlternateAllowed));
            Assert.That(coordinator.TryAdvanceCandidate(failed,0,next,out var ready),Is.True,"PRODUCT: unused original index 0 remains eligible after index 1");
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(calls,Is.EqualTo(1));
            Assert.That(coordinator.TryAdvanceCandidate(failed,0,next,out _),Is.False,"Consumed expected decision cannot replay");
            Assert.That(coordinator.EvaluateMovement(first,1,2),Is.SameAs(ready));
            Assert.That(coordinator.EvaluateMovement(next,0,3),Is.SameAs(ready));
            Assert.That(coordinator.EvaluateMovement(next,0,2),Is.SameAs(ready));
            coordinator.ProcessReady(3);var final=coordinator.GetDecision(key);
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(1));
            Assert.That(final.RequestSequence,Is.EqualTo(failed.RequestSequence));Assert.That(calls,Is.EqualTo(2));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(2));
            if(lastAlsoFails)
            {
                Assert.That(final.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
                Assert.That(final.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            }
            else
            {
                Assert.That(final.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(coordinator.TryCommit(final),Is.True);
                Assert.That(coordinator.TryCommit(final),Is.False,"Commit cannot recharge the same permission");
            }
            Assert.That(coordinator.TryAdvanceCandidate(final,1,first,out _),Is.False);
            Assert.That(coordinator.TryAdvanceCandidate(final,0,next,out _),Is.False);
            Assert.That(coordinator.TryAdvanceCandidate(failed,0,next,out _),Is.False);
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(2));
        }

        [TestCase(false)]
        [TestCase(true)]
        public void D1MetadataRefreshKeepsUnresolvedWaitingEdgesAndCannotSwitchCandidate(bool deferred)
        {
            var key=Key("z-waiter");var owner=Key("owner");var world=World(actors:new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,8)});
            var coordinator=Coordinator(world,frameBudget:1);
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world),1,2);coordinator.ProcessReady(1);
            var waiting=coordinator.GetDecision(key);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            coordinator.Tick(2,false);
            if(deferred)
            {
                world=World(2,2,new[]{new TrafficBodyFact(owner,P(20),.4f,true,true,6)});coordinator.SetSnapshot(world);
                coordinator.EvaluateMovement(Request(Key("a-budget"),P(10),P(12),world,frame:1));
                coordinator.NotifyChanged(owner,"body");coordinator.ProcessReady(2);
                Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"FIXTURE: waiting recheck must actually defer behind shared frame budget");
            }
            var before=coordinator.GetDecision(key);var edges=((IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers")).ToArray();
            Assert.That(edges.Select(b=>b.Owner),Does.Contain(owner),"FIXTURE: an actual unresolved edge, not just historical FrozenOwners");
            var queries=coordinator.QueriesConsumed(key);var budget=D1Read(coordinator,key,"WaitRemaining");
            var fresh=World(3,3,world.Bodies.ToArray());coordinator.SetSnapshot(fresh);
            var changed=Request(key,Origin,P(4),fresh,frame:99,seconds:100);
            Assert.That(coordinator.TryAdvanceCandidate(before,0,changed,out _),Is.False,"Deferred/Waiting never authorize side replacement");
            coordinator.EvaluateMovement(changed,1,2);
            {
                Assert.That(((IReadOnlyList<TrafficBlocker>)D1Read(coordinator,key,"WaitingBlockers")).Select(b=>b.Owner),Is.EquivalentTo(edges.Select(b=>b.Owner)));
                Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(1));
                Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(budget));
                Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
                Assert.That(((TrafficRequest)D1Read(coordinator,key,"Request")).FiniteSeconds,Is.EqualTo(20),"Metadata cannot refill the phase finite limit");
                Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.Zero);
            }
        }

        [TestCase(false)]
        [TestCase(true)]
        public void D1CommittedPublicationFailureAndStrictLegSurviveMetadataAttack(bool bound)
        {
            var key=Key("committed-proof");var actor=new object();var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});
            var coordinator=Coordinator(world);var canonical=new CanonicalOwner();var publications=0;
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world));coordinator.ProcessReady(1);var source=coordinator.GetDecision(key);
            Assert.That(coordinator.TryCommit(source,canonical.Prepare(),()=>{publications++;throw new InvalidOperationException("Modeled publication failure");}),Is.True);
            Assert.That(coordinator.LastPublicationException,Is.Not.Null);Assert.That(canonical.Value,Is.EqualTo(1));
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,4,world,Origin,.05f,2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);Assert.That(coordinator.TryCommit(coordinator.GetDecision(key)),Is.True);
            var stamp=new TrafficNativeStamp(90,4);if(bound)Assert.That(coordinator.BindLeg(key,actor,stamp),Is.True);
            var leg=D1Read(coordinator,key,"Leg");var journey=D1Read(coordinator,key,"JourneyPermit");
            var request=D1Read(coordinator,key,"JourneyRequest");var original=coordinator.GetDecision(key);var queries=coordinator.QueriesConsumed(key);
            var path=((Vector3[])D1Read(coordinator,key,"CurrentPath")).ToArray();
            var fresh=World(2,2,new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});coordinator.SetSnapshot(fresh);
            var discarded=coordinator.DiscardPrepared(key);
            coordinator.EvaluateMovement(Request(key,Origin,P(8),fresh,frame:3,seconds:100),0,2);
            var advanced=coordinator.TryAdvanceCandidate(original,1,Request(key,Origin,P(8),fresh,frame:3),out _);
            coordinator.ProcessReady(3);
            var recommitted=coordinator.TryCommit(coordinator.GetDecision(key),canonical.Prepare(),()=>publications++);
            {
                Assert.That(discarded,Is.False);Assert.That(advanced,Is.False);Assert.That(recommitted,Is.False);
                Assert.That(D1Read(coordinator,key,"Leg"),Is.SameAs(leg));Assert.That(D1Read(coordinator,key,"JourneyPermit"),Is.SameAs(journey));
                Assert.That(D1Read(coordinator,key,"JourneyRequest"),Is.SameAs(request));
                Assert.That((Vector3[])D1Read(coordinator,key,"CurrentPath"),Is.EqualTo(path));
                Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(coordinator.HasActiveGrant(key),Is.True);
                Assert.That(canonical.Value,Is.EqualTo(1));Assert.That(canonical.Applies,Is.EqualTo(1));Assert.That(canonical.Rollbacks,Is.Zero);
                Assert.That(publications,Is.EqualTo(1));Assert.That(coordinator.GetDecision(key).AcquiredSequence,Is.EqualTo(source.AcquiredSequence));
            }
        }

        [Test] public void D1AlternateCandidatePreservesFrozenAccountingAndRejectsNewOwner()
        {
            var key=Key("frozen-alternate");var owner=Key("original-owner");var intruder=Key("new-owner");
            var world=World(actors:new[]{new TrafficBodyFact(owner,P(4),.4f,true,true,8)});
            var coordinator=Coordinator(world,query:(from,to)=>to==P(4)?null:new[]{from,to});
            coordinator.EvaluateMovement(Request(key,Origin,P(4),world,frame:11),1,2);coordinator.ProcessReady(11);
            Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));coordinator.Tick(3,false);
            var originalResources=(Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(coordinator,key,"FrozenResources");
            var budget=D1Read(coordinator,key,"WaitRemaining");
            world=World(2,2);coordinator.SetSnapshot(world);coordinator.NotifyChanged(owner,"body");coordinator.ProcessReady(12);
            var failed=coordinator.GetDecision(key);Assert.That(failed.Reason,Is.EqualTo("bounded-route-proof-failed"));
            var queries=coordinator.QueriesConsumed(key);
            world=World(3,3,new[]{new TrafficBodyFact(intruder,P(6),.4f,true,true,8)});coordinator.SetSnapshot(world);
            Assert.That(coordinator.TryAdvanceCandidate(failed,0,Request(key,Origin,P(6),world,frame:13),out var ready),Is.True,
                "PRODUCT: alternate authorization preserves the old frozen contract rather than creating another phase");
            Assert.That(ready.RequestSequence,Is.EqualTo(failed.RequestSequence));Assert.That(ready.AcquiredSequence,Is.EqualTo(failed.AcquiredSequence));
            Assert.That(D1Read(coordinator,key,"FirstFrame"),Is.EqualTo(11));Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That((HashSet<TrafficIntentKey>)D1Read(coordinator,key,"FrozenOwners"),Is.EquivalentTo(new[]{owner}));
            Assert.That(((Dictionary<TrafficIntentKey,HashSet<string>>)D1Read(coordinator,key,"FrozenResources"))[owner],Is.EquivalentTo(originalResources[owner]));
            coordinator.ProcessReady(13);var terminal=coordinator.GetDecision(key);
            Assert.That(terminal.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));Assert.That(terminal.Blockers.Any(b=>b.Owner.Equals(intruder)),Is.True);
            Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries),"New frozen owner is refused before another query");
            Assert.That(D1Read(coordinator,key,"WaitRemaining"),Is.EqualTo(budget));
        }

        private static object D1Read(ServiceTrafficCoordinator coordinator,TrafficIntentKey key,string name)
        {
            const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            var entries=(System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("entries",flags).GetValue(coordinator);
            return entries[key].GetType().GetField(name,flags).GetValue(entries[key]);
        }

        // Pure Core model only; real Native cancellation/acceptance stays in the existing Side PlayMode test.
        // 模型只验证权限/账本；不把手动model stamp声称为真实Native验收。
        [Test] public void YieldOwnerHoldRequiresCancelConfirmationAndPreservesOriginalAccounting()
        {
            var f=new YieldOwnerHoldModel();f.MoveBody(P(1));var spent=f.Core.QueriesConsumed(f.Original);var calls=f.Calls;
            var originalEntry=f.Entry(f.Original);var first=f.Read(f.Original,"FirstFrame");var finite=f.Read(f.Original,"FiniteLimit");
            var remaining=f.Read(f.Original,"WaitRemaining");var attempts=((IEnumerable<int>)f.Read(f.Original,"AttemptedIndices")).ToArray();
            f.Core.Tick(0,true);
            Assert.That(f.Take(f.Source,f.Actor,f.Stamp,f.Position,out var receipt),Is.True,"Capture during Pause retires rights; it grants no continuation");
            Assert.That(f.Core.QueriesConsumed(f.Original),Is.EqualTo(spent));Assert.That(f.Calls,Is.EqualTo(calls));
            Assert.That(f.Read(f.Original,"Retired"),Is.EqualTo(true));Assert.That(f.Core.HasActiveGrant(f.Original),Is.False);
            Assert.That(f.Core.GetDecision(f.Original).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            f.Core.Tick(0,false);
            Assert.That(f.Begin(receipt,f.Replacement(),out _),Is.False,"An unconfirmed owner cancellation is not recovery authority");
            Assert.That(f.Contains(f.Next),Is.False);Assert.That(f.Calls,Is.EqualTo(calls));
            Assert.That(f.Confirm(receipt,true),Is.True);Assert.That(f.Confirm(receipt,true),Is.False,"Confirmation itself is one-use");
            Assert.That(f.Begin(receipt,f.Replacement(),out var ready),Is.True);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(f.Core.HasActiveGrant(f.Next),Is.False);
            Assert.That(f.Core.QueriesConsumed(f.Next),Is.EqualTo(spent));Assert.That(f.Calls,Is.EqualTo(calls));
            Assert.That(f.Read(f.Next,"FirstFrame"),Is.EqualTo(first));Assert.That(f.Read(f.Next,"FiniteLimit"),Is.EqualTo(finite));
            Assert.That(f.Read(f.Next,"WaitRemaining"),Is.EqualTo(remaining));Assert.That(f.Read(f.Next,"CandidateCount"),Is.EqualTo(24));
            Assert.That(f.Read(f.Next,"CurrentIndex"),Is.EqualTo(3));Assert.That((IEnumerable<int>)f.Read(f.Next,"AttemptedIndices"),Is.EquivalentTo(attempts));
            Assert.That(f.Read(f.Next,"RequestSequence"),Is.EqualTo(f.Source.RequestSequence));
            Assert.That(f.Read(f.Next,"AcquiredSequence"),Is.EqualTo(f.Source.AcquiredSequence));
            Assert.That(f.Begin(receipt,f.Replacement(generation:3),out _),Is.False,"No new key can reconsume the original receipt");
            f.Core.ProcessReady(100);var source=f.Core.GetDecision(f.Next);
            Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted),source.Reason);Assert.That(f.Core.TryCommit(source),Is.True);
            Assert.That(f.Core.QueriesConsumed(f.Next),Is.GreaterThan(spent));Assert.That(f.QueryStarts.Last(),Is.EqualTo(P(1)));
            f.Publish(f.Next);Assert.That(f.Core.PrepareLeg(source,f.Resource,0,f.Actor,5,f.World,f.Position,.05f,101).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Core.ProcessReady(101);Assert.That(f.Core.TryCommit(f.Core.GetDecision(f.Next)),Is.True);
            var nextStamp=new TrafficNativeStamp(72,5);Assert.That(f.Core.BindLeg(f.Next,f.Actor,nextStamp),Is.True);
            Assert.That(f.Take(source,f.Actor,nextStamp,f.Position,out var chained),Is.False,"The one continuation cannot mint another receipt");
            Assert.That(chained,Is.Null);Assert.That(f.Entry(f.Original),Is.SameAs(originalEntry));Assert.That(f.Read(f.Original,"Retired"),Is.EqualTo(true));
            Assert.That(f.Core.PrepareLeg(f.Source,f.Resource,0,f.Actor,4,f.World,f.Position,.05f,102).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            Assert.That(f.Core.CompleteLeg(f.Original,f.Actor,f.Stamp,f.End),Is.False,"Old retired stamp can never arrive");
        }
