            Assert.That(f.Begin(receipt,f.Replacement(),out _),Is.True);f.Core.ProcessReady(100);var source=f.Core.GetDecision(f.Next);
            Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted),source.Reason);Assert.That(f.Core.TryCommit(source),Is.True);
            f.Publish(f.Next);Assert.That(f.Core.PrepareLeg(source,f.Resource,0,f.Actor,5,f.World,f.Position,.05f,101).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Core.ProcessReady(101);Assert.That(f.Core.TryCommit(f.Core.GetDecision(f.Next)),Is.True);var stamp=new TrafficNativeStamp(72,5);
