        private sealed class YieldOwnerHoldModel
        {
            internal readonly object Actor=new object(),ParentActor=new object(),Business=new object(),Obligation=new object();
            internal readonly CanonicalOwner Canonical=new CanonicalOwner();
            internal readonly TrafficIntentKey Original,Parent=Key("yield-parent","employee-pickup-journey"),Blocker=Key("yield-original-blocker"),NewBlocker=Key("yield-new-blocker");
            internal TrafficIntentKey Next=>Key(Original.ActorId,Original.IntentId,2);
            internal readonly TrafficNativeStamp Stamp=new TrafficNativeStamp(71,4);
            internal readonly string Resource;internal readonly Vector3 End=P(4),ParentStart=P(10);
            internal readonly ServiceTrafficCoordinator Core;internal readonly TrafficDecision Source,ParentSource;
            internal readonly List<Vector3> QueryStarts=new List<Vector3>();internal int Calls;
            internal Vector3 Position=Origin;internal TrafficWorldSnapshot World;internal TrafficIntentKey CurrentOwner;
            private long version=1;private bool originalBlocker,newBlocker;
            internal YieldOwnerHoldModel(string phase="pickup-yield",bool parking=true,bool bind=true,int intentBudget=16384,string resource=null,
                bool parentHistory=false,bool parentExhausted=false)
            {
                Original=Key("yield-hold-model",phase);CurrentOwner=Original;Resource=resource??"pickup/"+Original.ActorId;originalBlocker=parentHistory;
                Assert.That(Canonical.Prepare().TryApply(out _),Is.True,"MODEL: pre-existing actual canonical owner holds the yield target");
                World=Snapshot();Core=Coordinator(World,intentBudget:intentBudget,waitSeconds:30,
                    query:(from,to)=>{Calls++;QueryStarts.Add(from);return from==ParentStart?null:new[]{from,to};});
                Core.EvaluateMovement(ParentRequest(P(12),15),0,2);Core.ProcessReady(15);
                if(parentHistory)
                {
                    Assert.That(Core.GetDecision(Parent).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                    Core.Tick(parentExhausted?8.1f:3f,false);originalBlocker=false;Refresh();Core.NotifyChanged(Blocker,"body");Core.ProcessReady(16);
                }
                ParentSource=Core.GetDecision(Parent);
                Assert.That(ParentSource.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),ParentSource.Reason);
                Assert.That(ParentSource.FailureDisposition,Is.EqualTo(parentExhausted?TrafficFailureDisposition.Terminal:TrafficFailureDisposition.AlternateAllowed));
                var request=new TrafficRequest(Original,17,World,Position,End,.4f,Resource,finiteSeconds:20,safetyMargin:.02f,planPrimaryRoute:true);
                if(parking)Core.EvaluateParking(request,3,24);else Core.EvaluateMovement(request,3,24);
                Core.ProcessReady(17);Source=Core.GetDecision(Original);Assert.That(Source.Kind,Is.EqualTo(TrafficDecisionKind.Granted),Source.Reason);
                Assert.That(Core.TryCommit(Source),Is.True);
                Assert.That(Core.PrepareLeg(Source,Resource,0,Actor,4,World,Position,.05f,18).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Core.ProcessReady(18);Assert.That(Core.TryCommit(Core.GetDecision(Original)),Is.True);
                if(bind)Assert.That(Core.BindLeg(Original,Actor,Stamp),Is.True);
            }
            private TrafficParkingFact Claim()=>new TrafficParkingFact(CurrentOwner,Canonical,Canonical.Version,Resource,End,.4f,.02f,Business,Obligation);
            private TrafficWorldSnapshot Snapshot()
            {
                var bodies=new List<TrafficBodyFact>{new TrafficBodyFact(CurrentOwner,Position,.4f,actorLife:Actor),new TrafficBodyFact(Parent,ParentStart,.4f,actorLife:ParentActor)};
                if(originalBlocker)bodies.Add(new TrafficBodyFact(Blocker,P(12),.4f,true,true,8,actorLife:BlockerLife));
                if(newBlocker)bodies.Add(new TrafficBodyFact(NewBlocker,P(14),.4f,true,true,30,actorLife:BlockerLife));
                return ServiceTrafficCoordinatorTests.World(version,version,bodies.ToArray(),new[]{Claim()});
            }
            private readonly object BlockerLife=new object();
            private void Refresh(){version++;World=Snapshot();Core.SetSnapshot(World);}
            internal void MoveBody(Vector3 position){Position=position;Refresh();}
            internal void Publish(TrafficIntentKey key){CurrentOwner=key;Refresh();}
            private TrafficRequest ParentRequest(Vector3 goal,int frame)=>new TrafficRequest(Parent,frame,World,ParentStart,goal,.4f,"pickup/"+Parent.ActorId,finiteSeconds:20,safetyMargin:.02f,planPrimaryRoute:true);
            internal void BlockParentAtNewCandidate()
            {
                newBlocker=true;Refresh();Assert.That(Core.TryAdvanceCandidate(ParentSource,1,ParentRequest(P(14),200),out _),Is.True);
                Core.ProcessReady(200);
            }
            internal void CanonicalArrival(TrafficDecision source,TrafficNativeStamp stamp)
            {
                var request=(TrafficRequest)Read(Next,"Request");var original=request.Snapshot.Parking.Single(claim=>claim.Owner.Equals(Next) && claim.ResourceId==Resource);
                MoveBody(End);var result=new MovementResult(stamp.RequestId,Next.ActorId,MovementStatus.Arrived,NavigationFailure.None,NavigationFailure.None,NavigationFailure.None,End,0);
                Assert.That(Core.CompleteLegAndBeginHandoff(Next,Actor,stamp,result,()=>
                {
                    Assert.That(Canonical.Prepare().TryApply(out _),Is.True,"MODEL: canonical arrival changes the real model ledger only inside the guarded callback");
                    return new YieldOwnerHoldArrival(this,source,original,Claim());
                },out var handle),Is.True);Assert.That(handle,Is.Not.Null);
            }
            internal TrafficRequest Replacement(int generation=2,TrafficIntentKey? key=null,Vector3? goal=null)=>
                new TrafficRequest(key??Key(Original.ActorId,Original.IntentId,generation),99,World,Position,goal??End,.4f,Resource,finiteSeconds:20,safetyMargin:.02f,planPrimaryRoute:true);
            private bool Invoke(string name,object[] args)
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That(method,Is.Not.Null,"MODEL: required internal seam missing; existing real Native case supplies behavior RED");return (bool)method.Invoke(Core,args);
            }
            internal bool Take(TrafficDecision source,object actor,TrafficNativeStamp stamp,Vector3 pose,out object receipt,TrafficDecision parent=null)
            {var args=new object[]{parent??ParentSource,source,actor,stamp,pose,null};var accepted=Invoke("TryRetireYieldForOwnerHold",args);receipt=args[5];return accepted;}
            internal bool Confirm(object receipt,bool cancelled)=>Invoke("ConfirmYieldOwnerHoldCancellation",new[]{receipt,(object)cancelled});
            internal bool Begin(object receipt,TrafficRequest request,out TrafficDecision decision)
            {var args=new object[]{receipt,request,Actor,null};var accepted=Invoke("TryBeginExplicitRecovery",args);decision=(TrafficDecision)args[3];return accepted;}
            internal void Discard(object receipt)=>typeof(ServiceTrafficCoordinator).GetMethod("DiscardRecovery",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(Core,new[]{receipt});
            internal object Entry(TrafficIntentKey key)
            {
                const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
                return ((System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("entries",flags).GetValue(Core))[key];
            }
            internal object Read(TrafficIntentKey key,string name)=>Entry(key).GetType().GetField(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(Entry(key));
            internal bool Contains(TrafficIntentKey key)=>D3ContainsIntent(Core,key);
        }
        private sealed class YieldOwnerHoldArrival:ITrafficPhaseMilestone
        {
            private readonly YieldOwnerHoldModel model;
            internal YieldOwnerHoldArrival(YieldOwnerHoldModel model,TrafficDecision source,TrafficParkingFact original,TrafficParkingFact current)
            {this.model=model;SourcePermit=source;OriginalClaim=original;CurrentClaim=current;}
            public TrafficDecision SourcePermit{get;}public TrafficParkingFact OriginalClaim{get;}public TrafficParkingFact CurrentClaim{get;}
            public object ActorLife=>model.Actor;public object BusinessOwner=>model.Business;public object ReleaseObligation=>model.Obligation;
            public TrafficPhaseMilestoneKind Kind=>TrafficPhaseMilestoneKind.Arrived;
            public bool IsCurrent=>model.Canonical.Value==2 && model.Canonical.Version==CurrentClaim.OwnerVersion && model.Position==model.End &&
                ReferenceEquals(CurrentClaim.CanonicalOwner,model.Canonical) && SourcePermit.Intent.Equals(model.CurrentOwner);
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)
            {current=null;if(!ReferenceEquals(captured,OriginalClaim) || !IsCurrent)return TrafficPhaseClaimState.Invalid;current=CurrentClaim;return TrafficPhaseClaimState.Held;}
            public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision sourcePermit,int firstFrame)=>false;
        }

        [TestCase(false)]
        [TestCase(true)]
        public void FailedLegRecoveryCreatesNewReadyAttemptWithOriginalAgeAndCumulativeQueries(bool recovered)
        {
            var f=new RecoveryModelFixture();f.MoveBody(P(1));
            var spent=f.Coordinator.QueriesConsumed(f.Original);var source=f.Source;
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(recovered:recovered),out var receipt),Is.True,
                "PRODUCT: matching bound model failure must yield one explicit recovery receipt");
            Assert.That(receipt,Is.Not.Null);Assert.That(f.Coordinator.HasActiveGrant(f.Original),Is.False);
            Assert.That(f.Read(f.Original,"Retired"),Is.EqualTo(true));
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out var ready),Is.True);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(f.Coordinator.HasActiveGrant(f.Next),Is.False);
            Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(spent),"Beginning an explicit attempt performs no Native-model query");
            Assert.That(f.Read(f.Next,"FirstFrame"),Is.EqualTo(f.Read(f.Original,"FirstFrame")));
            f.Coordinator.ProcessReady(100);var replacement=f.Coordinator.GetDecision(f.Next);
            Assert.That(replacement.Kind,Is.EqualTo(TrafficDecisionKind.Granted),replacement.Reason);
            Assert.That(replacement.RequestSequence,Is.EqualTo(source.RequestSequence));Assert.That(replacement.AcquiredSequence,Is.EqualTo(source.AcquiredSequence));
            Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(spent+1));Assert.That(f.QueryStarts.Last(),Is.EqualTo(P(1)));
            Assert.That(f.Coordinator.TryCommit(replacement),Is.True);Assert.That(replacement,Is.Not.SameAs(source));
            Assert.That(f.Coordinator.PrepareLeg(source,f.Resource,0,f.Actor,5,f.World,P(1),.05f,101).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            Assert.That(f.Read(f.Original,"Retired"),Is.EqualTo(true),"New transport attempt never revives the retired source");
        }

        [Test] public void FailedLegRecoveryConsumesReceiptOnceAndCannotChainAnotherAttempt()
        {
            var f=new RecoveryModelFixture();f.MoveBody(P(1));
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out var receipt),Is.True,"PRODUCT: valid modeled Native failure receipt");
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out var duplicate),Is.False);Assert.That(duplicate,Is.Null);
            Assert.That(f.Coordinator.CompleteLeg(f.Original,f.Actor,f.Stamp,f.End),Is.False,"Retired original callback cannot arrive");
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.True);
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.False,"Repeated Resume must not reuse the receipt");
            Assert.That(f.Begin(receipt,f.Replacement(generation:3),f.Actor,out _),Is.False,"Changing the attempt key cannot bypass one-shot authority");
            f.Coordinator.ProcessReady(100);var next=f.Coordinator.GetDecision(f.Next);Assert.That(f.Coordinator.TryCommit(next),Is.True);
            Assert.That(f.Coordinator.PrepareLeg(next,f.Resource,0,f.Actor,5,f.World,f.Position,.05f,101).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(101);Assert.That(f.Coordinator.TryCommit(f.Coordinator.GetDecision(f.Next)),Is.True);
            var nextStamp=new TrafficNativeStamp(72,5);Assert.That(f.Coordinator.BindLeg(f.Next,f.Actor,nextStamp),Is.True);
            var nextFailure=new MovementResult(72,f.Next.ActorId,MovementStatus.Failed,NavigationFailure.MovementTimeout,
                NavigationFailure.MovementTimeout,NavigationFailure.None,f.Position,1);
            Assert.That(f.Take(f.Next,f.Actor,nextStamp,nextFailure,out var chained),Is.False,"One business phase has only one explicit recovery attempt");
            Assert.That(chained,Is.Null);Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(2));
        }

        [TestCase("authority")]
        [TestCase("closed")]
        [TestCase("epoch")]
        public void FailedLegRecoveryRejectsForeignAuthorityAndRetiredContext(string mode)
        {
            var f=new RecoveryModelFixture();
            if(mode=="authority")
            {
                Assert.That(f.Take(f.Original,new object(),f.Stamp,f.Failure(),out _),Is.False);
                Assert.That(f.Take(f.Original,f.Actor,new TrafficNativeStamp(99,4),f.Failure(),out _),Is.False);
                Assert.That(f.Take(f.Original,f.Actor,new TrafficNativeStamp(71,9),f.Failure(),out _),Is.False);
                Assert.That(f.Take(Key("recovery-model","pickup-paid-movement",epoch:2),f.Actor,f.Stamp,f.Failure(),out _),Is.False);
                foreach(var status in new[]{MovementStatus.Arrived,MovementStatus.Cancelled,MovementStatus.LayoutChanged,MovementStatus.Recovered})
                {
                    var wrong=new MovementResult(71,f.Original.ActorId,status,NavigationFailure.None,NavigationFailure.None,NavigationFailure.None,f.Position,0);
                    Assert.That(f.Take(f.Original,f.Actor,f.Stamp,wrong,out _),Is.False,"Not a real failed target: "+status);
                }
                var foreign=new MovementResult(71,"foreign-actor",MovementStatus.Failed,NavigationFailure.MovementTimeout,
                    NavigationFailure.MovementTimeout,NavigationFailure.None,f.Position,1);
                Assert.That(f.Take(f.Original,f.Actor,f.Stamp,foreign,out _),Is.False);
                Assert.That(f.Coordinator.HasActiveGrant(f.Original),Is.True,"Invalid failure claims leave the actual live leg intact");
                var unbound=new RecoveryModelFixture(bind:false);
                Assert.That(unbound.Take(unbound.Original,unbound.Actor,unbound.Stamp,unbound.Failure(),out _),Is.False,"A committed proposal is not a bound Native result");
            }
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out var receipt),Is.True,"PRODUCT: only the matching bound failure supplies authority");
            if(mode=="closed")f.Coordinator.Close();
            else if(mode=="epoch")f.Coordinator.ResetLayout(2,8,World());
            else
            {
                Assert.That(f.Begin(receipt,f.Replacement(),new object(),out _),Is.False);
                Assert.That(f.Begin(receipt,f.Replacement(actor:"foreign"),f.Actor,out _),Is.False);
                Assert.That(f.Begin(receipt,f.Replacement(epoch:2),f.Actor,out _),Is.False);
                Assert.That(f.Begin(receipt,f.Replacement(generation:1),f.Actor,out _),Is.False,"Retired source key cannot be reopened");
                Assert.That(f.Begin(receipt,f.Replacement(goal:P(5)),f.Actor,out _),Is.False,"Receipt binds the original business goal");
                Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.True,"Invalid inputs must not steal a valid owner's receipt");
                return;
            }
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.False,"Close/reset permanently revokes old receipt authority");
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out _),Is.False);Assert.That(f.Coordinator.HasActiveGrant(f.Next),Is.False);
        }

        [TestCase("history")]
        [TestCase("query-exhausted")]
        [TestCase("wait-exhausted")]
        public void FailedLegRecoveryKeepsFrozenHistoryAndCannotRefillSpentBudgets(string mode)
        {
            var history=mode!="query-exhausted";var f=new RecoveryModelFixture(history:history,intentBudget:history?16:1);
            Assert.That(f.Coordinator.QueriesConsumed(f.Original),Is.EqualTo(1));
            if(history)
            {
                Assert.That((IEnumerable<TrafficIntentKey>)f.Read(f.Original,"FrozenOwners"),Is.EquivalentTo(new[]{f.Blocker}));
                Assert.That(f.Read(f.Original,"WaitRemaining"),Is.EqualTo(5f),"Model used 3 of the original 8 seconds before actual bound leg");
            }
            Assert.That(f.Take(f.Original,f.Actor,f.Stamp,f.Failure(),out var receipt),Is.True,"PRODUCT: capture the original accounting before retirement");
            if(!history)
            {
                Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.False,"An exhausted phase cannot obtain a fresh query allowance");
                Assert.That(f.Coordinator.QueriesConsumed(f.Original),Is.EqualTo(1));Assert.That(f.Coordinator.HasActiveGrant(f.Next),Is.False);return;
            }
            if(mode=="wait-exhausted")f.SetBlocker(f.Blocker);
            Assert.That(f.Begin(receipt,f.Replacement(),f.Actor,out _),Is.True);
            Assert.That(f.Read(f.Next,"WaitRemaining"),Is.EqualTo(5f));
            Assert.That((IEnumerable<TrafficIntentKey>)f.Read(f.Next,"FrozenOwners"),Is.EquivalentTo(new[]{f.Blocker}));
            var frozen=(Dictionary<TrafficIntentKey,HashSet<string>>)f.Read(f.Next,"FrozenResources");
            Assert.That(frozen[f.Blocker],Is.EquivalentTo(new[]{"body"}));
            f.Coordinator.ProcessReady(100);
            if(mode=="history")
            {
                Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.Granted),"Historical eligibility is not a current blocker after actual release");
                Assert.That(f.Read(f.Next,"WaitRemaining"),Is.EqualTo(5f));Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(2));
                var newcomer=Key("new-blocker");f.SetBlocker(newcomer);
                f.Coordinator.EvaluateMovement(f.Replacement(frame:101));f.Coordinator.ProcessReady(101);
                Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
                Assert.That(f.Coordinator.GetDecision(f.Next).Blockers.Any(b=>b.Owner.Equals(newcomer)),Is.True);
                Assert.That((IEnumerable<TrafficIntentKey>)f.Read(f.Next,"FrozenOwners"),Is.EquivalentTo(new[]{f.Blocker}),"New obstruction cannot expand frozen eligibility");
            }
            else
            {
                Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                f.Coordinator.Tick(100,true);Assert.That(f.Read(f.Next,"WaitRemaining"),Is.EqualTo(5f));
                f.Coordinator.Tick(4.5f,false);Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                f.Coordinator.Tick(.6f,false);Assert.That(f.Coordinator.GetDecision(f.Next).Reason,Is.EqualTo("wait-budget-exhausted"));
                Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(1),"Endpoint wait did not spend or replace the inherited query counter");
            }
            Assert.That(f.Begin(receipt,f.Replacement(generation:3),f.Actor,out _),Is.False,"Failure cannot convert a consumed receipt into another budget");
        }

        [Test] public void FailedPreparationRecoveryCreatesOneReadyAttemptWithoutReopeningOriginal()
        {
            var f=new PreparationRecoveryFixture();f.FailWithBody();var original=f.Current;
            Assert.That(original.Blockers.Any(b=>b.Owner.Equals(f.Blocker)),Is.True);
            Assert.That(f.Read("Leg"),Is.Null);Assert.That(f.Read("JourneyPermit"),Is.Null);Assert.That(original.AcquiredSequence,Is.Zero);
            Assert.That(f.Take(original,f.Actor,out var receipt),Is.True,"PRODUCT: exact uncommitted modeled preparation failure must yield one receipt");
            Assert.That(f.Take(original,f.Actor,out _),Is.False);Assert.That(f.Read("Retired"),Is.EqualTo(true));
            f.SetBody(null);Assert.That(f.Begin(receipt,out var ready),Is.True);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(f.Coordinator.HasActiveGrant(f.Next),Is.False);
            Assert.That(f.Read("FirstFrame",f.Next),Is.EqualTo(11));Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.Zero);
            Assert.That(f.Read("WaitRemaining",f.Next),Is.EqualTo(0f),"No frozen wait means no spent wait allowance; it is not exhaustion");
            Assert.That(f.Read("FrozenOwners",f.Next),Is.Null);Assert.That(ready.RequestSequence,Is.EqualTo(original.RequestSequence));
            Assert.That(f.Begin(receipt,out _),Is.False);Assert.That(f.Begin(receipt,out _,generation:3),Is.False);
            f.Coordinator.ProcessReady(50);var replacement=f.Coordinator.GetDecision(f.Next);
            Assert.That(replacement.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.QueryCalls,Is.EqualTo(1));
            Assert.That(replacement,Is.Not.SameAs(original));Assert.That(replacement.RequestSequence,Is.EqualTo(original.RequestSequence));
            Assert.That(f.Read("Leg",f.Next),Is.Null,"Preparation recovery must not invent a Native leg or arrival");
            Assert.That(f.Coordinator.TryCommit(original),Is.False);Assert.That(f.Read("Retired"),Is.EqualTo(true));
            f.SetBody(f.Blocker);f.Coordinator.EvaluateMovement(f.Request(f.Next,51));f.Coordinator.ProcessReady(51);
            Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(f.Take(f.Coordinator.GetDecision(f.Next),f.Actor,out _),Is.False,"The same business phase cannot chain recovery attempts");
        }

        [Test] public void FailedPreparationRecoveryRejectsForeignStaleLifecycleAndWrongStage()
        {
            var f=new PreparationRecoveryFixture();f.Coordinator.EvaluateMovement(f.Request());f.Coordinator.ProcessReady(11);
            var earlier=f.Current;Assert.That(earlier.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Coordinator.HasActiveGrant(f.Original),Is.False,"FIXTURE: earlier actual decision is uncommitted");
            f.FailWithBody();var source=f.Current;Assert.That(source,Is.Not.SameAs(earlier));
            Assert.That(f.Take(source,new object(),out _),Is.False);Assert.That(f.Take(null,f.Actor,out _),Is.False);
            Assert.That(f.Take(new TrafficDecision(source.Intent,source.Kind,source.Reason),f.Actor,out _),Is.False,"Equal scalar values are not exact source authority");
            var foreign=new PreparationRecoveryFixture();foreign.FailWithBody();Assert.That(f.Take(foreign.Current,f.Actor,out _),Is.False);
            f.FailWithBody();Assert.That(f.Current,Is.SameAs(source),"Ordinary polling cannot replace a genuine terminal decision");
            Assert.That(f.Current.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(f.Take(earlier,f.Actor,out _),Is.False,"An earlier actual decision of the same entry is stale");
            foreach(var stage in new[]{"parking","ready","committed","retired","epoch","closed","disabled","replacement-life"})
            {
                var bad=new PreparationRecoveryFixture();
                if(stage=="parking")bad.FailWithBody(parking:true);
                else if(stage=="ready" || stage=="committed")
                {bad.Coordinator.EvaluateMovement(bad.Request());bad.Coordinator.ProcessReady(11);if(stage=="committed")Assert.That(bad.Coordinator.TryCommit(bad.Current),Is.True);}
                else bad.FailWithBody();
                var expected=bad.Current;
                if(stage=="retired")bad.Coordinator.Retire(bad.Original);
                if(stage=="epoch")bad.Coordinator.ResetLayout(2,7,bad.World);
                if(stage=="closed")bad.Coordinator.Close();
                if(stage=="disabled" || stage=="replacement-life")bad.SetBody(null,enabled:stage!="disabled",life:stage=="replacement-life"?new object():bad.Actor);
                Assert.That(bad.Take(expected,bad.Actor,out var rejected),Is.False,stage);Assert.That(rejected,Is.Null,stage);
            }
            var leg=new RecoveryModelFixture();
            Assert.That(PreparationRecoveryFixture.TakeFrom(leg.Coordinator,leg.Coordinator.GetDecision(leg.Original),leg.Actor,out _),Is.False,"An actual model bound leg belongs to its separate terminal-result authority");
            Assert.That(f.Take(source,f.Actor,out var receipt),Is.True,"PRODUCT: refusals cannot consume the valid preparation owner's authority");
            f.SetBody(null);Assert.That(f.Begin(receipt,out _),Is.True);
        }

        [TestCase("apply-false")]
        [TestCase("apply-throw")]
        [TestCase("null-receipt")]
        [TestCase("rollback-unknown")]
        public void FailedPreparationRecoveryNeverAuthorizesCanonicalFailureOrLaundersItsOrigin(string mode)
        {
            var f=new PreparationRecoveryFixture();f.Coordinator.EvaluateMovement(f.Request());f.Coordinator.ProcessReady(11);
            Assert.That(f.Current.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            var publications=0;var mutation=new PreparationCanonicalFailure(mode);
            Assert.That(f.Coordinator.TryCommit(f.Current,mutation,()=>publications++),Is.False);
            var canonicalFailure=f.Current;Assert.That(canonicalFailure.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(f.Read("Leg"),Is.Null);Assert.That(f.Read("JourneyPermit"),Is.Null);Assert.That(canonicalFailure.AcquiredSequence,Is.Zero);
            Assert.That(f.Take(canonicalFailure,f.Actor,out _),Is.False,"No failed/unknown canonical apply is a preparation failure");
            Assert.That(mutation.Applies,Is.EqualTo(1));var rollbacks=mutation.Rollbacks;var queries=f.Coordinator.QueriesConsumed(f.Original);
            Assert.That(f.Read("EverCanonicalAttempt"),Is.EqualTo(true));
            // Fresh metadata cannot replace the canonical terminal with a new preparation diagnosis.
            // 旧 fixture 的再次失败前提已被前置 terminal guard 禁止；原 canonical 不确定性必须保留。
            f.SetBody(f.Blocker);f.Coordinator.EvaluateMovement(f.Request(frame:12));f.Coordinator.ProcessReady(12);
            Assert.That(f.Current,Is.SameAs(canonicalFailure));Assert.That(f.Current.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(f.Coordinator.QueriesConsumed(f.Original),Is.EqualTo(queries));Assert.That(f.Read("EverCanonicalAttempt"),Is.EqualTo(true));
            Assert.That(f.Coordinator.HasActiveGrant(f.Original),Is.False);Assert.That(publications,Is.Zero);
            Assert.That(f.Coordinator.TryCommit(f.Current,mutation,()=>publications++),Is.False);Assert.That(publications,Is.Zero);
            Assert.That(f.Take(f.Current,f.Actor,out _),Is.False);Assert.That(mutation.Applies,Is.EqualTo(1));Assert.That(mutation.Rollbacks,Is.EqualTo(rollbacks));
            var clean=new PreparationRecoveryFixture();clean.FailWithBody();
            Assert.That(clean.Take(clean.Current,clean.Actor,out _),Is.True,"PRODUCT: independent noncanonical preparation failure is eligible; rejecting everything is not a fix");
        }

        [TestCase("history")]
        [TestCase("query-exhausted")]
        [TestCase("wait-exhausted")]
        public void FailedPreparationRecoveryPreservesSpentQueryAndFrozenWaitAccounting(string mode)
        {
            var f=new PreparationRecoveryFixture(intentBudget:mode=="query-exhausted"?1:16);
            // Spend one real model query first, without any canonical commit or Native leg.
            f.Coordinator.EvaluateMovement(f.Request());f.Coordinator.ProcessReady(11);
            Assert.That(f.Current.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.QueryCalls,Is.EqualTo(1));
            var finite=mode!="query-exhausted";f.SetBody(f.Blocker,finite:finite);
            f.Coordinator.EvaluateMovement(f.Request(frame:12));f.Coordinator.ProcessReady(12);
            if(finite)
            {
                Assert.That(f.Current.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));f.Coordinator.Tick(3,false);
                Assert.That(f.Read("WaitRemaining"),Is.EqualTo(5f));
                if(mode=="wait-exhausted")f.Coordinator.Tick(6,false);
                else {f.SetBody(Key("new-static-blocker"));f.Coordinator.EvaluateMovement(f.Request(frame:13));f.Coordinator.ProcessReady(13);}
            }
            Assert.That(f.Current.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"MODEL FIXTURE: actual terminal preparation failure");
            var source=f.Current;var wait=(float)f.Read("WaitRemaining");var frozen=((IEnumerable<TrafficIntentKey>)f.Read("FrozenOwners"))?.ToArray();
            Assert.That(f.Coordinator.QueriesConsumed(f.Original),Is.EqualTo(1));
            Assert.That(f.Take(source,f.Actor,out var receipt),Is.True,"PRODUCT: receipt must preserve accounting of the original failed preparation");
            f.SetBody(null);
            if(mode!="history")
            {
                Assert.That(f.Begin(receipt,out _),Is.False,"Spent query/wait limit cannot become a fresh allowance");
                Assert.That(f.Begin(receipt,out _,generation:3),Is.False);Assert.That(f.QueryCalls,Is.EqualTo(1));return;
            }
            Assert.That(f.Begin(receipt,out var ready),Is.True);Assert.That(ready.RequestSequence,Is.EqualTo(source.RequestSequence));
            Assert.That(f.Read("FirstFrame",f.Next),Is.EqualTo(11));Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(1));
            Assert.That(f.Read("WaitRemaining",f.Next),Is.EqualTo(wait));Assert.That(wait,Is.EqualTo(5f));
            CollectionAssert.AreEquivalent(frozen,(IEnumerable<TrafficIntentKey>)f.Read("FrozenOwners",f.Next));
            var resources=(Dictionary<TrafficIntentKey,HashSet<string>>)f.Read("FrozenResources",f.Next);
            Assert.That(resources[f.Blocker],Is.EquivalentTo(new[]{"body"}));
            f.Coordinator.ProcessReady(50);Assert.That(f.Coordinator.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.Granted),"Old eligibility history is not a current blocker");
            Assert.That(f.QueryCalls,Is.EqualTo(2));Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(2));
            Assert.That(f.Read("WaitRemaining",f.Next),Is.EqualTo(5f));Assert.That(f.Begin(receipt,out _),Is.False);
        }

        [TestCase("nav-only")]
        [TestCase("actor-inactive")]
        [TestCase("replacement-life")]
        [TestCase("missing-body")]
        public void AuthenticatedPreparationReceiptDistinguishesTemporaryNavGapFromActorRetirement(string mode)
        {
            var f=new PreparationRecoveryFixture();f.FailWithBody();var source=f.Current;
            Assert.That(f.Take(source,f.Actor,out var receipt),Is.True,"MODEL FIXTURE: genuine preparation failure already authenticated");
            Assert.That(f.HasReceipt(receipt),Is.True);var queries=f.Coordinator.QueriesConsumed(f.Original);
            var first=f.Read("FirstFrame");var wait=f.Read("WaitRemaining");
            f.SetBody(null,enabled:false,life:mode=="replacement-life"?new object():f.Actor,
                actorActive:mode!="actor-inactive",omitActor:mode=="missing-body");
            Assert.That(f.Begin(receipt,out _),Is.False,"PRODUCT: no explicit attempt may start while its actual Nav body is unavailable");
            Assert.That(f.Coordinator.QueriesConsumed(f.Original),Is.EqualTo(queries));Assert.That(f.Read("FirstFrame"),Is.EqualTo(first));
            Assert.That(f.Read("WaitRemaining"),Is.EqualTo(wait));Assert.That(f.Current,Is.SameAs(source));
            var retained=f.HasReceipt(receipt);
            f.SetBody(null); // Restore the same real model body; never write the private registry.
            if(mode=="nav-only")
            {
                Assert.That(retained,Is.True,"PRODUCT: temporary Nav disabled with active same ActorLife must retain the authenticated receipt");
                Assert.That(f.HasReceipt(receipt),Is.True);Assert.That(f.Begin(receipt,out var ready),Is.True);
                Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(ready.RequestSequence,Is.EqualTo(source.RequestSequence));
                Assert.That(f.Read("FirstFrame",f.Next),Is.EqualTo(first));Assert.That(f.Read("WaitRemaining",f.Next),Is.EqualTo(wait));
                Assert.That(f.Coordinator.QueriesConsumed(f.Next),Is.EqualTo(queries));Assert.That(f.Begin(receipt,out _),Is.False);
            }
            else
            {
                Assert.That(retained,Is.False,"PRODUCT: real actor retirement/replacement revokes authority");
                Assert.That(f.HasReceipt(receipt),Is.False);Assert.That(f.Begin(receipt,out _),Is.False,"Restoring a body cannot resurrect a revoked receipt");
            }
        }

        // Contract-only preparation fixture; no Native result/claim/arrival is fabricated.
        private sealed class PreparationRecoveryFixture
        {
            internal readonly object Actor=new object();
            internal readonly TrafficIntentKey Original=Key("preparation-model","pickup-paid-movement"),Blocker=Key("preparation-blocker");
            internal TrafficIntentKey Next=>Key("preparation-model","pickup-paid-movement",2);
            internal readonly ServiceTrafficCoordinator Coordinator;
            internal TrafficWorldSnapshot World;internal int QueryCalls;private long version;
            internal TrafficDecision Current=>Coordinator.GetDecision(Original);
            internal PreparationRecoveryFixture(int intentBudget=16)
            {
                SetBody(null);Coordinator=ServiceTrafficCoordinatorTests.Coordinator(World,intentBudget:intentBudget,
                    query:(from,to)=>{QueryCalls++;return new[]{from,to};});
            }
            internal void SetBody(TrafficIntentKey? blocker,bool finite=false,bool enabled=true,object life=null,bool? actorActive=null,bool omitActor=false)
            {
                var bodies=new List<TrafficBodyFact>();
                if(!omitActor)bodies.Add(new TrafficBodyFact(Original,Origin,.4f,enabled,actorLife:life??Actor,actorActive:actorActive));
                if(blocker.HasValue)bodies.Add(new TrafficBodyFact(blocker.Value,P(4),.4f,true,finite,finite?8:0,actorLife:new object()));
                World=ServiceTrafficCoordinatorTests.World(++version,version,bodies.ToArray());Coordinator?.SetSnapshot(World);
            }
            internal TrafficRequest Request(TrafficIntentKey? key=null,int frame=11)
                =>ServiceTrafficCoordinatorTests.Request(key??Original,Origin,P(4),World,frame:frame,resource:"pickup/preparation-model");
            internal void FailWithBody(bool parking=false)
            {
                SetBody(Blocker);if(parking)Coordinator.EvaluateParking(Request());else Coordinator.EvaluateMovement(Request());
                Coordinator.ProcessReady(11);Assert.That(Current.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"MODEL FIXTURE: real endpoint body rejection");
            }
            internal static bool TakeFrom(ServiceTrafficCoordinator coordinator,TrafficDecision expected,object actor,out object receipt)
            {var args=new object[]{expected,actor,null};var accepted=Invoke(coordinator,"TryRetireFailedPreparation",args);receipt=args[2];return accepted;}
            internal bool Take(TrafficDecision expected,object actor,out object receipt)=>TakeFrom(Coordinator,expected,actor,out receipt);
            internal bool HasReceipt(object receipt)
            {
                var registry=(System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("recoveryReceipts",
                    System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(Coordinator);
                return receipt!=null && registry.Contains(receipt);
            }
            internal bool Begin(object receipt,out TrafficDecision decision,int generation=2)
            {var args=new object[]{receipt,Request(Key("preparation-model","pickup-paid-movement",generation),50),Actor,null};var accepted=Invoke(Coordinator,"TryBeginExplicitRecovery",args);decision=(TrafficDecision)args[3];return accepted;}
            private static bool Invoke(ServiceTrafficCoordinator coordinator,string name,object[] args)
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That(method,Is.Not.Null,"MODEL FIXTURE: internal API exists before behavior RED");return (bool)method.Invoke(coordinator,args);
            }
            internal object Read(string name,TrafficIntentKey? key=null)
            {
                const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
                var entries=(System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("entries",flags).GetValue(Coordinator);
                var entry=entries[key??Original];return entry.GetType().GetField(name,flags).GetValue(entry);
            }
        }
        private sealed class PreparationCanonicalFailure:IPreparedTrafficMutation,ITrafficMutationReceipt
        {
            private readonly string mode;internal int Applies,Rollbacks;
            internal PreparationCanonicalFailure(string value){mode=value;}
            public bool IsCurrent=>true;
            public bool TryApply(out ITrafficMutationReceipt receipt)
            {
                Applies++;receipt=mode=="null-receipt"?null:this;
                if(mode=="apply-throw")throw new InvalidOperationException("Modeled canonical apply uncertainty");
                return mode=="null-receipt";
            }
            public void RollbackOwnMutation()
            {Rollbacks++;if(mode=="rollback-unknown")throw new InvalidOperationException("Modeled rollback UNKNOWN");}
        }

