        [Test] public void JointWinnerRetiresOnlyUnselectedProvisionalSiblingBeforePublication()
        {
            var coordinator=Coordinator();var winner=Key("customer","advance");var sibling=Key("customer","collect");
            coordinator.EvaluateMovement(Request(winner,Origin,P(2),resource:"pickup/customer"));
            coordinator.EvaluateMovement(Request(sibling,Origin,P(4),resource:"pickup/customer"));coordinator.ProcessReady(1);
            Assert.That(coordinator.GetDecision(sibling).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(coordinator.GetDecision(sibling).AcquiredSequence,Is.Zero);
            var canonical=new CanonicalOwner();var publishedRetired=false;
            Assert.That(coordinator.TryCommit(coordinator.GetDecision(winner),canonical.Prepare(),()=>
                publishedRetired=coordinator.GetDecision(sibling).Kind==TrafficDecisionKind.Cancelled),Is.True);
            Assert.That(canonical.Value,Is.EqualTo(1));Assert.That(coordinator.HasActiveGrant(winner),Is.True);
            Assert.That(publishedRetired,Is.True,"A real joint winner must discard its unselected provisional before external publication");
            Assert.That(coordinator.GetDecision(sibling).AcquiredSequence,Is.Zero);
        }

        [Test] public void FailedJointWinnerDoesNotRetirePreparedSibling()
        {
