            coordinator.EvaluateMovement(Request(winner,Origin,P(2),resource:"pickup/customer"));
            coordinator.EvaluateMovement(Request(sibling,Origin,P(4),resource:"pickup/customer"));coordinator.ProcessReady(1);
            var canonical=new CanonicalOwner{FailAfterWrite=true};
            Assert.That(coordinator.TryCommit(coordinator.GetDecision(winner),canonical.Prepare()),Is.False);
            Assert.That(canonical.Value,Is.Zero);Assert.That(coordinator.GetDecision(sibling).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
        }

        [Test] public void WinningAlternativeDiscardsSiblingWithoutRetiringItsPhaseOrResettingBudgets()
        {
            var coordinator=Coordinator(intentBudget:2);var winner=Key("customer","advance");var sibling=Key("customer","collect");
            coordinator.EvaluateMovement(Request(winner,Origin,P(2),resource:"pickup/customer"));
            coordinator.EvaluateMovement(Request(sibling,Origin,P(4),resource:"pickup/customer"));coordinator.ProcessReady(1);
            var first=coordinator.GetDecision(sibling);var queries=coordinator.QueriesConsumed(sibling);
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            var entries=(System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("entries",flags).GetValue(coordinator);
            var entry=entries[sibling];var firstFrame=entry.GetType().GetField("FirstFrame",flags).GetValue(entry);
            var publishedCancelled=false;
            Assert.That(coordinator.TryCommit(coordinator.GetDecision(winner),new CanonicalOwner().Prepare(),()=>
                publishedCancelled=coordinator.GetDecision(sibling).Kind==TrafficDecisionKind.Cancelled),Is.True);
            Assert.That(publishedCancelled,Is.True,"Sibling spatial rights must be gone before publication");
            coordinator.Retire(winner);
            Assert.That(coordinator.EvaluateMovement(Request(winner,Origin,P(2),frame:2,resource:"pickup/customer")).Kind,
                Is.EqualTo(TrafficDecisionKind.Cancelled),"A truly completed business phase must remain retired");
            Assert.That(coordinator.EvaluateMovement(Request(sibling,Origin,P(6),frame:3,resource:"pickup/customer")).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"PRODUCT: discarding an unselected spatial candidate must not permanently retire its business phase");
            coordinator.ProcessReady(3);var again=coordinator.GetDecision(sibling);
            Assert.That(again.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(again.RequestSequence,Is.EqualTo(first.RequestSequence));
            Assert.That(entry.GetType().GetField("FirstFrame",flags).GetValue(entry),Is.EqualTo(firstFrame));
            Assert.That(coordinator.QueriesConsumed(sibling),Is.EqualTo(queries+1),"Re-preparation keeps cumulative Native query consumption");
            Assert.That(coordinator.DiscardPrepared(sibling),Is.True);
            coordinator.EvaluateMovement(Request(sibling,Origin,P(8),frame:4,resource:"pickup/customer"));coordinator.ProcessReady(4);
            Assert.That(coordinator.GetDecision(sibling).Reason,Is.EqualTo("intent-query-budget-exhausted"));
            Assert.That(coordinator.QueriesConsumed(sibling),Is.EqualTo(2));
        }

