        [Test] public void JointWinnerPreservesCommittedOwnerAndUnrelatedProposals()
        {
            var coordinator=Coordinator();var committed=Key("customer","existing");
            Grant(coordinator,Request(committed,Origin,P(1),resource:"pickup/customer"));
            var winner=Key("customer","advance");var otherResource=Key("customer","other-resource");var otherActor=Key("other","collect");
            coordinator.EvaluateMovement(Request(winner,Origin,P(2),frame:2,resource:"pickup/customer"));
