        [TestCase(2)]
        [TestCase(3)]
        public void CircularBodyDependencyCannotBecomeAllWaiting(int count)
        {
            var keys = Enumerable.Range(0, count).Select(i => Key(((char)('a' + i)).ToString())).ToArray();
            var bodies = keys.Select((key, i) => new TrafficBodyFact(key, P(i * 3), .4f, true, true, 10)).ToArray();
            var world = World(actors: bodies); var coordinator = Coordinator(world);
            for (var i = 0; i < count; i++)
                coordinator.EvaluateMovement(Request(keys[i], P(i * 3), P(((i + 1) % count) * 3), world));
            coordinator.ProcessReady(1);
            var decisions = keys.Select(coordinator.GetDecision).ToArray();
            Assert.That(decisions.Any(d => d.Kind == TrafficDecisionKind.PlanningFailed), Is.True,
                "at least one dependency must be rejected instead of closing a wait cycle");
