        [Test]
        public void ResumablePlannerKeepsFrontierAndDoesNotRepeatNativeEdges()
        {
            var edges = new List<string>();
            IReadOnlyList<Vector3> Query(Vector3 from, Vector3 to)
            { edges.Add(from.ToString("R") + ">" + to.ToString("R")); return new[] { from, to }; }
            var coordinator = Coordinator(frameBudget: 1, intentBudget: 500, query: Query); var key = Key("a");
            var proof = new TrafficRouteRequirement("detour", P(-2), P(2), .8f, new[] { Origin });
            coordinator.EvaluateParking(Request(key, P(10), P(11), requirements: new[] { proof }));
            var deferred = 0;
            for (var frame = 1; frame <= 500; frame++)
            {
                var before = edges.Count; coordinator.ProcessReady(frame);
                Assert.That(edges.Count - before, Is.LessThanOrEqualTo(1));
                var decision = coordinator.GetDecision(key);
                if (decision.Kind == TrafficDecisionKind.Granted) break;
                Assert.That(decision.Kind, Is.EqualTo(TrafficDecisionKind.DeferredByBudget)); deferred++;
            }
            Assert.That(coordinator.GetDecision(key).Kind, Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(deferred, Is.GreaterThan(1), "obstacle forces real cursor continuation");
            Assert.That(edges.Count, Is.EqualTo(edges.Distinct().Count()), "processed edges must not restart next frame");
        }

