        [Test]
        public void UnchangedWaitDoesZeroQueriesAndOnlyRelatedEventWakes()
        {
            var blocker = Key("owner"); var waiter = Key("waiter"); var calls = 0;
            var world = World(actors: new[] { new TrafficBodyFact(blocker, P(2), .4f, true, true, 8) });
            var coordinator = Coordinator(world, query: (a, b) => { calls++; return new[] { a, b }; });
            coordinator.EvaluateMovement(Request(waiter, Origin, P(2), world)); coordinator.ProcessReady(1);
            Assert.That(coordinator.GetDecision(waiter).Kind, Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            coordinator.DrainReady(); var initial = calls;
            for (var frame = 2; frame < 10; frame++) coordinator.ProcessReady(frame);
            Assert.That(calls, Is.EqualTo(initial));
            coordinator.NotifyChanged(Key("unrelated"), "elsewhere");
            Assert.That(coordinator.DrainReady(), Is.Empty);
            coordinator.SetSnapshot(World(2, 2)); coordinator.NotifyChanged(blocker, "body");
            Assert.That(coordinator.DrainReady(), Does.Contain(waiter));
            coordinator.ProcessReady(10);
            Assert.That(coordinator.GetDecision(waiter).Kind, Is.EqualTo(TrafficDecisionKind.Granted));
