        [TestCase("body-life")]
        [TestCase("claim-restart")]
        [TestCase("opaque-claim")]
        [TestCase("requirements")]
        public void SleepingMovementChangedFactsRequireOrdinaryReproof(string change)
        {
            var f=new NormalSleepingPollFixture(opaque:change=="opaque-claim");f.Refresh(change);
            var accounting=D3CaptureAccounting(f.Core,f.Waiter);var before=f.QueryCalls;
            var result=f.Core.EvaluateMovement(f.Poll(change));
            Assert.That(result,Is.Not.SameAs(f.Waiting),"Changed identity, descriptor or an unauthenticated claim cannot borrow the sleeping fast path");
            Assert.That(result.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(f.Core.TryCommit(result),Is.False);
            Assert.That(D1Read(f.Core,f.Waiter,"Queued"),Is.True);Assert.That(f.QueryCalls,Is.EqualTo(before));
            D3AssertAccounting(f.Core,f.Waiter,accounting);
        }

        [TestCase("retire")]
        [TestCase("snapshot")]
        public void SleepingMovementClaimInspectionCannotResumeAfterPublicReentry(string mutation)
        {
            var f=new NormalSleepingPollFixture(callback:true);f.Refresh("metadata");
            Assert.That(f.Comparisons,Is.Zero,"PREMISE: no checkpoint comparison fired before this actual poll");
            var replacement=new TrafficWorldSnapshot(f.Current.Version,f.Current.BodyVersion,f.Current.Bodies,f.Current.Parking);
            f.OnCompare=()=>{if(mutation=="retire")f.Core.Retire(f.Waiter);else f.Core.SetSnapshot(replacement);};
            var accounting=D3CaptureAccounting(f.Core,f.Waiter);var before=f.QueryCalls;
            var result=f.Core.EvaluateMovement(f.Poll("metadata"));
            Assert.That(f.Comparisons,Is.EqualTo(1),"The guard is proven only after the real typed authentication callback was reached");
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(result.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(f.Core.TryCommit(result),Is.False);
            Assert.That(f.QueryCalls,Is.EqualTo(before));D3AssertAccounting(f.Core,f.Waiter,accounting);
            if(mutation=="retire")
            {
                Assert.That(D1Read(f.Core,f.Waiter,"Retired"),Is.True);Assert.That(D1Read(f.Core,f.Waiter,"Request"),Is.Null);
                Assert.That(f.Core.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            }
            else
            {
                Assert.That(D3ReadField(f.Core,"snapshot"),Is.SameAs(replacement));
                Assert.That(f.Core.GetDecision(f.Waiter),Is.SameAs(f.Waiting));Assert.That(D1Read(f.Core,f.Waiter,"Request"),Is.SameAs(f.OriginalRequest));
                Assert.That(D1Read(f.Core,f.Waiter,"Queued"),Is.False);
            }
        }

        private sealed class NormalSleepingCheckpoint : ITrafficClaimCheckpoint
        {
            private readonly CounterQueueService.AssignmentClaim claim;private readonly Action callback;private bool fired;
            internal NormalSleepingCheckpoint(CounterQueueService.AssignmentClaim claim,Action callback){this.claim=claim;this.callback=callback;}
            public object CanonicalOwner=>claim.CanonicalOwner;public string ResourceId=>claim.ResourceId;
            public long CapturedOwnerVersion=>claim.CapturedOwnerVersion;
            public bool IsSameCurrentClaim(ITrafficClaimCheckpoint current)
            {
                if(!(current is NormalSleepingCheckpoint other))return false;
                if(!fired){fired=true;callback?.Invoke();}
                return claim.IsSameCurrentClaim(other.claim);
            }
        }
        private sealed class NormalSleepingPollFixture
        {
            internal readonly TrafficIntentKey Waiter=Key("sleeping-guard","actual-exit",14);
            internal readonly ServiceTrafficCoordinator Core;internal readonly TrafficRequest OriginalRequest;internal readonly TrafficDecision Waiting;
            internal TrafficWorldSnapshot Current;internal Action OnCompare;internal int QueryCalls,Comparisons;
            private readonly object life=new object(),business=new object(),release=new object(),opaqueMarker=new object();
            private readonly CounterQueueService counter=new CounterQueueService(new[]{Origin,P(-4)});
            private readonly bool opaque,callback;private readonly TrafficIntentKey held,blocker=Key("guard-crossing"),neighbor=Key("guard-neighbor");
            private readonly TrafficBodyFact own,other,first;private readonly CounterQueueService.AssignmentClaim neighborClaim;
            internal NormalSleepingPollFixture(bool opaque=false,bool callback=false)
            {
                this.opaque=opaque;this.callback=callback;held=Key(Waiter.ActorId,"counter-admission",7);
                own=new TrafficBodyFact(held,Origin,.4f,actorLife:life);other=new TrafficBodyFact(neighbor,P(-4),.4f,actorLife:new object());
                first=new TrafficBodyFact(blocker,P(1),.4f,true,true,8,actorLife:new object());
                Assert.That(counter.TryJoin(Waiter.ActorId),Is.True);Assert.That(counter.Complete(Waiter.ActorId,1),Is.True);
                Assert.That(counter.TryJoin(neighbor.ActorId),Is.True);Assert.That(counter.TryCaptureAssignment(Waiter.ActorId,out var claim),Is.True);
                Assert.That(counter.TryCaptureAssignment(neighbor.ActorId,out var capturedNeighbor),Is.True);neighborClaim=capturedNeighbor;
                Current=World(17,1,new[]{own,other,first},new[]{OwnClaim(claim,true),OtherClaim(neighborClaim)});
                Core=Coordinator(Current,query:(from,to)=>{QueryCalls++;return new[]{from,to};});
                Grant(Core,Request(blocker,P(1),P(1,2),Current,frame:10,resource:"crossing/"+blocker.ActorId));
                OriginalRequest=Request(Waiter,Origin,P(4),Current,frame:11,resource:"exit/"+Waiter.ActorId);
                Core.EvaluateMovement(OriginalRequest);Core.ProcessReady(11);Waiting=Core.GetDecision(Waiter);
                Assert.That(Waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));Assert.That(Waiting.AcquiredSequence,Is.Zero);
                Assert.That(D1Read(Core,Waiter,"Queued"),Is.False);Assert.That(D1Read(Core,Waiter,"Leg"),Is.Null);
                Assert.That(D1Read(Core,Waiter,"JourneyPermit"),Is.Null);Assert.That(D1Read(Core,Waiter,"JourneyRequest"),Is.Null);
                Assert.That((Vector3[])D1Read(Core,Waiter,"Journey"),Is.Empty);Core.DrainReady();Core.Tick(2,false);
            }
            private TrafficParkingFact OwnClaim(CounterQueueService.AssignmentClaim claim,bool initial)
            {
                object marker=opaque?opaqueMarker:callback?(object)new NormalSleepingCheckpoint(claim,initial?(Action)(()=>{Comparisons++;OnCompare?.Invoke();}):null):claim;
                return new TrafficParkingFact(held,counter,counter.Version,"counter/"+Waiter.ActorId,claim.Assignment.Position,.4f,
                    businessOwner:business,releaseObligation:release,semanticCheckpoint:marker);
            }
            private TrafficParkingFact OtherClaim(CounterQueueService.AssignmentClaim claim)=>new TrafficParkingFact(neighbor,counter,counter.Version,
                "counter/"+neighbor.ActorId,claim.Assignment.Position,.4f,semanticCheckpoint:claim);
            internal void Refresh(string change)
            {
                if(change=="claim-restart")counter.RestartAssignments();else Assert.That(counter.Complete(neighbor.ActorId,neighborClaim.Assignment.Generation),Is.True);
                Assert.That(counter.TryCaptureAssignment(Waiter.ActorId,out var claim),Is.True);Assert.That(counter.TryCaptureAssignment(neighbor.ActorId,out var otherClaim),Is.True);
                var body=change=="body-life"?new TrafficBodyFact(held,Origin,.4f,actorLife:new object()):own;
                Current=World(18,change=="body-life"?2:1,new[]{body,other,first},new[]{OwnClaim(claim,false),OtherClaim(otherClaim)});
                Core.SetSnapshot(Current);
            }
            internal TrafficRequest Poll(string change)=>Request(Waiter,Origin,P(4),Current,frame:99,
                requirements:change=="requirements"?new[]{new TrafficRouteRequirement("new-capability",P(-8),P(-7),.8f)}:null,
                resource:"exit/"+Waiter.ActorId);
        }

        [TestCase(false)]
        [TestCase(true)]
        public void SleepingUnacquiredMovementMetadataPollNeedsActualRelatedNotification(bool relatedNotification)
        {
            var waiter=Key("sleeping-exit","actual-exit",14);var held=Key(waiter.ActorId,"counter-admission",7);
            var neighbor=Key("metadata-neighbor");var originalOwner=Key("original-crossing");var later=Key("later-crossing");
            var life=new object();var ownBody=new TrafficBodyFact(held,Origin,.4f,actorLife:life);
            var neighborBody=new TrafficBodyFact(neighbor,P(-4),.4f,actorLife:new object());
            var firstBody=new TrafficBodyFact(originalOwner,P(1),.4f,true,true,8,actorLife:new object());
            var business=new object();var release=new object();var counter=new CounterQueueService(new[]{Origin,P(-4)});
            Assert.That(counter.TryJoin(waiter.ActorId),Is.True);Assert.That(counter.Complete(waiter.ActorId,1),Is.True);
            Assert.That(counter.TryJoin(neighbor.ActorId),Is.True);
            Assert.That(counter.TryCaptureAssignment(waiter.ActorId,out var oldClaim),Is.True);
            Assert.That(counter.TryCaptureAssignment(neighbor.ActorId,out var oldNeighbor),Is.True);
            TrafficParkingFact OwnFact(CounterQueueService.AssignmentClaim claim)=>new TrafficParkingFact(held,counter,counter.Version,
                "counter/"+waiter.ActorId,claim.Assignment.Position,.4f,businessOwner:business,releaseObligation:release,semanticCheckpoint:claim);
            TrafficParkingFact NeighborFact(CounterQueueService.AssignmentClaim claim)=>new TrafficParkingFact(neighbor,counter,counter.Version,
                "counter/"+neighbor.ActorId,claim.Assignment.Position,.4f,semanticCheckpoint:claim);
            var original=World(17,1,new[]{ownBody,neighborBody,firstBody},new[]{OwnFact(oldClaim),NeighborFact(oldNeighbor)});
            var calls=0;var coordinator=Coordinator(original,query:(from,to)=>{calls++;return new[]{from,to};});
            Grant(coordinator,Request(originalOwner,P(1),P(1,2),original,frame:10,resource:"crossing/"+originalOwner.ActorId));
            Assert.That(coordinator.HasActiveGrant(originalOwner),Is.True);
            var request=Request(waiter,Origin,P(4),original,frame:11,resource:"exit/"+waiter.ActorId);
            coordinator.EvaluateMovement(request);coordinator.ProcessReady(11);
            var waiting=coordinator.GetDecision(waiter);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"PREMISE: original finite body owns the real frozen wait");
            Assert.That(waiting.Blockers.Any(b=>b.Owner.Equals(originalOwner)),Is.True);
            Assert.That(waiting.AcquiredSequence,Is.Zero);Assert.That(coordinator.HasActiveGrant(waiter),Is.False);
            Assert.That(coordinator.QueriesConsumed(waiter),Is.GreaterThan(0),"PREMISE: this is a queried route-interior wait, not an endpoint refusal");
            Assert.That(D1Read(coordinator,waiter,"Parking"),Is.False);Assert.That(D1Read(coordinator,waiter,"Prepared"),Is.False);
            Assert.That(D1Read(coordinator,waiter,"Queued"),Is.False);Assert.That(D1Read(coordinator,waiter,"Leg"),Is.Null);
            Assert.That(D1Read(coordinator,waiter,"JourneyPermit"),Is.Null);Assert.That(D1Read(coordinator,waiter,"JourneyRequest"),Is.Null);
            Assert.That((Vector3[])D1Read(coordinator,waiter,"Journey"),Is.Empty);
            coordinator.DrainReady();coordinator.Tick(2,false);
            var accounting=D3CaptureAccounting(coordinator,waiter);var edges=D1Read(coordinator,waiter,"WaitingBlockers");
            var frozen=D1Read(coordinator,waiter,"FrozenOwners");var frozenResources=D1Read(coordinator,waiter,"FrozenResources");
            CollectionAssert.AreEquivalent(new[]{originalOwner},(HashSet<TrafficIntentKey>)frozen);
            var version=counter.Version;
            Assert.That(counter.Complete(neighbor.ActorId,oldNeighbor.Assignment.Generation),Is.True);
            Assert.That(counter.Version,Is.GreaterThan(version));
            Assert.That(counter.TryCaptureAssignment(waiter.ActorId,out var currentClaim),Is.True);
            Assert.That(counter.TryCaptureAssignment(neighbor.ActorId,out var currentNeighbor),Is.True);
            Assert.That(oldClaim.IsSameReservation(currentClaim),Is.True);Assert.That(oldClaim.IsCurrent && currentClaim.IsCurrent,Is.True);
            Assert.That(currentClaim.Assignment.Generation,Is.EqualTo(oldClaim.Assignment.Generation));
            Assert.That(currentClaim.Assignment.SlotIndex,Is.EqualTo(oldClaim.Assignment.SlotIndex));
            Assert.That(currentClaim.Assignment.Position,Is.EqualTo(oldClaim.Assignment.Position));
            Assert.That(currentClaim.Assignment.Arrived,Is.EqualTo(oldClaim.Assignment.Arrived));
            var laterBody=new TrafficBodyFact(later,P(3,-2),.4f,true,true,8,actorLife:new object());
            var current=World(18,relatedNotification?2:1,new[]{ownBody,neighborBody,relatedNotification?laterBody:firstBody},
                new[]{OwnFact(currentClaim),NeighborFact(currentNeighbor)});
            coordinator.SetSnapshot(current);
            Assert.That(coordinator.GetDecision(waiter),Is.SameAs(waiting));Assert.That(D1Read(coordinator,waiter,"Request"),Is.SameAs(request));
            if(relatedNotification)
            {
                // A real granted crossing path appears; only the old owner's actual removal is notified.
                // 新owner由公开Core真正获权；旧owner真实移出snapshot后才发原相关Notify，不扩Frozen。
                Grant(coordinator,Request(later,P(3,-2),P(3,2),current,frame:12,resource:"crossing/"+later.ActorId));
                Assert.That(coordinator.HasActiveGrant(later),Is.True);
                Assert.That(D1Read(coordinator,waiter,"Queued"),Is.False);
                coordinator.Retire(originalOwner);
                coordinator.NotifyChanged(originalOwner,"body");
                Assert.That(D1Read(coordinator,waiter,"Queued"),Is.True,"PREMISE: original related release queued a real safety recheck");
            }
            var beforePollCalls=calls;var originalQueries=coordinator.QueriesConsumed(waiter);
            var polled=coordinator.EvaluateMovement(Request(waiter,Origin,P(4),current,frame:99,resource:"exit/"+waiter.ActorId));
            Assert.That(calls,Is.EqualTo(beforePollCalls),"Polling itself never runs the Native delegate");
            if(!relatedNotification)
            {
                Assert.That(polled,Is.SameAs(waiting),"FEATURE: unrelated Queue version polling must retain the original sleeping decision");
                Assert.That(D1Read(coordinator,waiter,"Queued"),Is.False);Assert.That(D1Read(coordinator,waiter,"Request"),Is.SameAs(request));
                Assert.That(D1Read(coordinator,waiter,"WaitingBlockers"),Is.SameAs(edges));Assert.That(D1Read(coordinator,waiter,"FrozenOwners"),Is.SameAs(frozen));
                Assert.That(D1Read(coordinator,waiter,"FrozenResources"),Is.SameAs(frozenResources));D3AssertAccounting(coordinator,waiter,accounting);
                Assert.That(coordinator.DrainReady(),Is.Empty);coordinator.ProcessReady(99);
                Assert.That(calls,Is.EqualTo(beforePollCalls));Assert.That(coordinator.GetDecision(waiter),Is.SameAs(waiting));
                Assert.That(coordinator.TryCommit(waiting),Is.False);D3AssertAccounting(coordinator,waiter,accounting);
            }
            else
            {
                coordinator.ProcessReady(99);var failed=coordinator.GetDecision(waiter);
                Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"CONTROL: a real related wake cannot swallow the new owner");
                Assert.That(failed.Blockers.Any(b=>b.Owner.Equals(later) && b.ResourceId=="crossing/"+later.ActorId),Is.True);
                Assert.That(coordinator.TryCommit(failed),Is.False);Assert.That(failed.AcquiredSequence,Is.Zero);
                Assert.That(coordinator.QueriesConsumed(waiter),Is.GreaterThan(originalQueries),"Related wake must run the current route proof");
                Assert.That(D1Read(coordinator,waiter,"FrozenOwners"),Is.SameAs(frozen));
                CollectionAssert.AreEquivalent(new[]{originalOwner},(HashSet<TrafficIntentKey>)frozen);
                Assert.That(D1Read(coordinator,waiter,"FirstFrame"),Is.EqualTo(accounting["FirstFrame"]));
                Assert.That(failed.RequestSequence,Is.EqualTo(waiting.RequestSequence));
                Assert.That(D1Read(coordinator,waiter,"WaitRemaining"),Is.EqualTo(accounting["WaitRemaining"]));
            }
        }

        [Test]
        public void FrozenWaitDoesNotAcquireNewBlockerOrResetOnResubmission()
        {
            var a = Key("a"); var b = Key("b"); var waiter = Key("waiter");
            var world = World(actors: new[] { new TrafficBodyFact(a, P(2), .4f, true, true, 8) });
            var coordinator = Coordinator(world);
            coordinator.EvaluateMovement(Request(waiter, Origin, P(2), world)); coordinator.ProcessReady(1);
            coordinator.Tick(6, false);
            var changed = World(2, 2, new[] { new TrafficBodyFact(b, P(2), .4f, true, true, 8) });
            coordinator.SetSnapshot(changed); coordinator.NotifyChanged(a, "body");
            coordinator.EvaluateMovement(Request(waiter, Origin, P(2), changed, frame: 2, stamp: new TrafficNativeStamp(9, 9)));
            coordinator.ProcessReady(2);
            Assert.That(coordinator.GetDecision(waiter).Kind, Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(coordinator.GetDecision(waiter).Blockers.Any(x => x.Owner.Equals(b)), Is.True);
        }

        [Test]
        public void PauseHoldsRightsAndWaitBudgetAndSceneDeltaIsScaledOnlyOnce()
        {
            var blocker = Key("owner"); var waiter = Key("waiter");
            var world = World(actors: new[] { new TrafficBodyFact(blocker, P(2), .4f, true, true, 8) });
            var coordinator = Coordinator(world);
            coordinator.EvaluateMovement(Request(waiter, Origin, P(2), world)); coordinator.ProcessReady(1);
            coordinator.Tick(100, true);
            Assert.That(coordinator.GetDecision(waiter).Kind, Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            coordinator.Tick(4, false);
            Assert.That(coordinator.GetDecision(waiter).Kind, Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            coordinator.Tick(4.1f, false);
            Assert.That(coordinator.GetDecision(waiter).Kind, Is.EqualTo(TrafficDecisionKind.PlanningFailed));
        }

