        [Test]
        public void ArrivedLegKeepsUnissuedJourneyProtectedAcrossCallbackGap()
        {
            var coordinator = Coordinator(); var owner = Key("a"); var stamp = new TrafficNativeStamp(1, 1);
            // The future route loops near an earlier segment; no nearest-point suffix guess is valid.
            var journey = new[] { Origin, P(2), P(2, 3), P(.1f, 3), P(.1f, .1f), P(-3, .1f) };
            Grant(coordinator, Request(owner, Origin, P(2), journey: journey, stamp: stamp));
            Assert.That(coordinator.CompleteLeg(owner, stamp), Is.True);
            coordinator.EvaluateParking(Request(Key("b"), P(6), P(-2, .1f), frame: 2));
            coordinator.ProcessReady(2);
