            Assert.That(coordinator.GetDecision(Key("b")).Blockers.Select(b => b.Owner), Does.Contain(owner));
            Grant(coordinator, Request(owner, P(2), P(2, 3), frame: 3, journey: journey.Skip(1).ToArray(), stamp: new TrafficNativeStamp(2, 2)));
            Assert.That(coordinator.CompleteLeg(owner, stamp), Is.False);
            Assert.That(coordinator.HasActiveGrant(owner), Is.True);
        }

