        [Test]
        public void NamedProofsReturnPrimaryAndHomeNativePathsWithoutExtraQueries()
        {
            var outward=new[]{Origin,P(1,1),P(2)};var home=new[]{P(2),P(3,-1),P(4)};var calls=0;
            var coordinator=Coordinator(frameBudget:1,query:(from,to)=>
            {
                calls++;
                if(from==Origin && to==P(2)) return outward;
                if(from==P(2) && to==P(4)) return home;
                Assert.Fail("Unexpected extra Native query: "+from+" -> "+to);return null;
            });
            var key=Key("employee");
            var homeRequirement=new TrafficRouteRequirement("selected-home",P(2),P(4),.8f);
            coordinator.EvaluateMovement(Request(key,Origin,P(2),resource:"selected-outward",requirements:new[]{homeRequirement}));
            coordinator.ProcessReady(1);Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);var decision=coordinator.GetDecision(key);
            Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(calls,Is.EqualTo(2));
            Assert.That(decision.ProofRoutes.Count,Is.EqualTo(2),"consumer needs both already-expanded Native paths, not another planner pass");
            var delivery=decision.ProofRoutes.Single(p=>p.ResourceId=="selected-outward");
            var returning=decision.ProofRoutes.Single(p=>p.ResourceId=="selected-home");
            CollectionAssert.AreEqual(new[]{P(2)},delivery.Waypoints);CollectionAssert.AreEqual(new[]{P(4)},returning.Waypoints);
            // Native adapter buffers may later be reused; emitted proof must retain this decision's geometry.
            outward[1]=P(99);home[1]=P(99);
            CollectionAssert.AreEqual(new[]{Origin,P(1,1),P(2)},delivery.ExpandedPath);
            CollectionAssert.AreEqual(new[]{P(2),P(3,-1),P(4)},returning.ExpandedPath);
            CollectionAssert.AreEqual(delivery.Waypoints,decision.Route);
            Assert.That(coordinator.TryCommit(decision),Is.True);Assert.That(calls,Is.EqualTo(2));
        }

