        [Test]
        public void MovingOtherBodyRefreshPreservesDeferredCursorAndNativeEdgeCache()
        {
            var key=Key("requester");var other=Key("moving-other");var edges=new List<string>();
            TrafficWorldSnapshot Snapshot(int frame)=>World(1,frame,new[]{new TrafficBodyFact(key,P(10),.4f),new TrafficBodyFact(other,P(20,frame*.01f),.4f,true,true,10)});
            var world=Snapshot(1);var proof=new TrafficRouteRequirement("detour-capability",P(-2),P(2),.8f,new[]{Origin});
            var coordinator=Coordinator(world,frameBudget:1,intentBudget:500,query:(a,b)=>
            {edges.Add(a.ToString("R")+">"+b.ToString("R"));return new[]{a,b};});
            var deferred=0;long requestSequence=0;
            for(var frame=1;frame<=500;frame++)
            {
                world=Snapshot(frame);coordinator.SetSnapshot(world);
                coordinator.EvaluateParking(Request(key,P(10),P(11),world,frame,requirements:new[]{proof}));
                var before=edges.Count;coordinator.ProcessReady(frame);var decision=coordinator.GetDecision(key);
                Assert.That(edges.Count-before,Is.LessThanOrEqualTo(1));
                Assert.That(edges.Count,Is.EqualTo(edges.Distinct().Count()),"unrelated moving body must not restart already-queried Native edges");
                Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(edges.Count));
                if(requestSequence==0)requestSequence=decision.RequestSequence;
                Assert.That(decision.RequestSequence,Is.EqualTo(requestSequence));
                if(decision.Kind==TrafficDecisionKind.Granted)break;
                Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));deferred++;
            }
            Assert.That(deferred,Is.GreaterThan(1));Assert.That(coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(coordinator.TryCommit(coordinator.GetDecision(key)),Is.True,"refreshed proof must bind the current snapshot at commit");
        }

