        [TestCase(0f)][TestCase(.0125f)]
        public void ProjectedDetourWaypointUsesProvenNativeEndpointAndNextLegKeepsItsSuffix(float surfaceHeight)
        {
            var offset=new Vector3(.053363f,0,-.0311281f);
            var native=new HashSet<Vector3>{Origin,P(4),P(8),P(20),P(24)};
            var projections=new Dictionary<Vector3,Vector3>();
            Vector3 Project(Vector3 point)
            {
                point.y=0;
                if(!native.Contains(point))
                {
                    if(!projections.TryGetValue(point,out var projected))
                    {projected=point+(point-P(2)).normalized*offset.magnitude;projections.Add(point,projected);native.Add(projected);}
                    point=projected;
                }
                point.y=surfaceHeight;return point;
            }
            var f=new LegFixture((from,to)=>new[]{Project(from),Project(to)});
            var raw=f.Outward.ExpandedPath.ToArray();var ends=f.Outward.LegEnds.ToArray();var home=f.Home.ExpandedPath.ToArray();
            var endpoint=raw[ends[0]];endpoint.y=0;
            var logical=projections.Single(pair=>pair.Value==endpoint).Key;
            Assert.That(Vector3.Distance(logical,endpoint),Is.GreaterThan(.05f),"PREMISE: recorded Main projection shifts a virtual detour point");
            Assert.That(Project(endpoint),Is.EqualTo(raw[ends[0]]),"Native projection must be idempotent, including a ground-y request");
            Assert.That(f.Outward.Waypoints[0],Is.EqualTo(endpoint),"RED: a virtual intermediate waypoint must use its proven Native endpoint instead of adding projection and arrival errors");
            Assert.That(f.Outward.Waypoints.Last(),Is.EqualTo(P(4)));Assert.That(f.Home.Waypoints.Last(),Is.EqualTo(P(8)));
            var queries=f.Coordinator.QueriesConsumed(f.Key);var age=f.Read("FirstFrame");
            Assert.That(f.Coordinator.PrepareLeg(f.Journey,"outward",0,f.Actor,1,f.World,Origin,.08f,f.Frame).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.CommitPrepared();var stamp=new TrafficNativeStamp(7411,1);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.True);
            // This is the real failure shape: Native arrival is near its sampled end, over 8cm from the old virtual node.
            // 只移动模型中的真实body事实；不写Core Entry，也不放宽到位阈值或构造许可。
            var actual=endpoint+(endpoint-logical).normalized*.03f;native.Add(actual);
            Assert.That(Vector3.Distance(actual,logical),Is.GreaterThan(.08f));Assert.That(Vector3.Distance(actual,endpoint),Is.LessThan(.08f));
            f.World=World(1,2,new[]{new TrafficBodyFact(f.Key,actual,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,stamp,actual),Is.True,"The same actual stamped arrival must complete its original strict leg");
            var segment=f.Outward.Waypoints[1]-actual;segment.y=0;
            Assert.That(segment.sqrMagnitude,Is.GreaterThan(0),"PREMISE: the next real leg is distinct");
            var nearest=actual+segment*Mathf.Clamp01(Vector3.Dot(P(2)-actual,segment)/segment.sqrMagnitude);
            Assert.That(Vector3.Distance(nearest,P(2)),Is.GreaterThan(.8f),"PREMISE: the model's Native next-leg straight path must actually clear the original obstacle");
            Assert.That(f.Prepare(1,2,actual,.08f).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));f.CommitPrepared();
            Assert.That(((TrafficRequest)f.Read("Request")).Target,Is.EqualTo(f.Outward.Waypoints[1]));
            CollectionAssert.AreEqual(raw,f.Outward.ExpandedPath);CollectionAssert.AreEqual(ends,f.Outward.LegEnds);CollectionAssert.AreEqual(home,f.Home.ExpandedPath);
            CollectionAssert.IsSubsetOf(home,(Vector3[])f.Read("Journey"));Assert.That(f.Read("FirstFrame"),Is.EqualTo(age));
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.GreaterThanOrEqualTo(queries));
            Assert.That(f.Coordinator.TryGetCommittedJourney(f.Key,out var source),Is.True);Assert.That(source,Is.SameAs(f.Journey));
            var nextStamp=new TrafficNativeStamp(7412,2);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,nextStamp),Is.True);
            var outside=f.Outward.Waypoints[1]+P(.2f);f.World=World(1,4,new[]{new TrafficBodyFact(f.Key,outside,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,nextStamp,outside),Is.False,"An arrival outside the unchanged strict tolerance still fails closed");
        }
        [Test] public void DetourProofCannotBridgeAnUnsafeNativeEdgeSeam()
        {
            var key=Key("native-seam");var life=new object();var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:life)});
            var core=Coordinator(world,query:(from,to)=>from==Origin && to==P(4)?new[]{from,to}:
                from==Origin?new[]{Origin,P(2,1)}:to==P(4)?new[]{P(2,-1),P(4)}:null);
            var route=new TrafficRouteRequirement("outward",Origin,P(4),.8f,new[]{P(2)},selectedJourney:true,avoidProposedParking:false);
            core.EvaluateParking(Request(key,Origin,Origin,world,requirements:new[]{route},resource:"canonical-parking"));
            for(var frame=1;frame<101 && core.GetDecision(key).Kind==TrafficDecisionKind.DeferredByBudget;frame++)core.ProcessReady(frame);
            var result=core.GetDecision(key);
            Assert.That(result.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"RED: individually clear Native edges cannot grant a joined path whose seam crosses an obstacle");
            Assert.That(core.TryCommit(result),Is.False);Assert.That(core.HasActiveGrant(key),Is.False);
        }

