        // A genuine retained leg is queued by public PrepareLeg; its actual start requires the ordinary query.
        // 原 proof 起点与实际身体略差；不写 Entry/NeedsQuery，不伪造 Native callback。
        private static LegFixture QueuedUnissuedStrictLegAtActualStart()
        {
            var f=new LegFixture();var actual=P(0,-.2f);var ownBodyOwner=Key(f.Key.ActorId,"owned-before-strict",generation:7);
            var owner=new CanonicalOwner();Assert.That(owner.Prepare().TryApply(out var receipt),Is.True);
            var claim=new TrafficParkingFact(ownBodyOwner,owner,owner.Version,"owned-pickup",actual,.4f,businessOwner:f.Journey,releaseObligation:receipt);
            f.World=World(2,2,new[]{new TrafficBodyFact(ownBodyOwner,actual,.4f,actorLife:f.Actor),
                new TrafficBodyFact(Key("queued-other"),P(-8,-8),.4f,true,true,10,actorLife:new object())},new[]{claim});
            f.Coordinator.SetSnapshot(f.World);var before=f.Coordinator.QueriesConsumed(f.Key);
            Assert.That(f.Prepare(generation:8,start:actual).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(f.Read("Queued"),Is.True);Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Active"),Is.False);
            var leg=f.Read("Leg");Assert.That(D3ReadField(leg,"NeedsQuery"),Is.EqualTo(true),"FIXTURE: actual start deviation must require the normal retained-leg query");
            Assert.That(D3ReadField(leg,"Committed"),Is.EqualTo(false));Assert.That(D3ReadField(leg,"Bound"),Is.EqualTo(false));Assert.That(D3ReadField(leg,"Stamp"),Is.EqualTo(default(TrafficNativeStamp)));
            Assert.That(before,Is.GreaterThan(0));Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(before));return f;
        }

        [TestCase(false)]
        [TestCase(true)]
        public void QueuedUnissuedStrictLegQueriesCurrentWorldWithoutReplacingItsOriginalSource(bool canonicalBirth)
        {
            var f=QueuedUnissuedStrictLegAtActualStart();var original=(TrafficRequest)f.Read("Request");var leg=f.Read("Leg");var source=f.Read("JourneyPermit");var journey=f.Read("JourneyRequest");
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);accounting.Remove("Queries");var before=f.Coordinator.QueriesConsumed(f.Key);var suffix=D3ReadField(leg,"Suffix");
            var proofEnds=f.Outward.LegEnds.ToArray();var proofPath=f.Outward.ExpandedPath.ToArray();var own=original.Snapshot.Bodies.Single(b=>b.Owner.ActorId==f.Key.ActorId);var other=original.Snapshot.Bodies.Single(b=>b.Owner.ActorId!=f.Key.ActorId);
            Assert.That(own.Owner,Is.Not.EqualTo(f.Key),"FIXTURE: actual same-body owner can be a prior intent; authenticate the stored strict snapshot");
            var bodies=new List<TrafficBodyFact>{own,new TrafficBodyFact(other.Owner,P(-7,-8),other.Radius,true,true,9,other.SafetyMargin,other.ActorLife)};
            var parking=original.Snapshot.Parking.ToList();
            if(canonicalBirth)
            {
                var newborn=Key("queued-new-far-body");var owner=new CanonicalOwner();Assert.That(owner.Prepare().TryApply(out var receipt),Is.True);
                bodies.Add(new TrafficBodyFact(newborn,P(-10,-8),.4f,actorLife:new object()));parking.Add(new TrafficParkingFact(newborn,owner,owner.Version,"new-far-slot",P(-10,-8),.4f,businessOwner:owner,releaseObligation:receipt));
            }
            f.World=World(canonicalBirth?3:2,3,bodies.ToArray(),parking.ToArray());f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(before),"SetSnapshot does not run the pending query");Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,8),Is.False);
            f.Coordinator.ProcessReady(f.Frame++);var current=f.Coordinator.GetDecision(f.Key);
            Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FEATURE: original queued unissued leg must query/recheck current external facts in the ordinary batch");
            D3AssertAccounting(f.Coordinator,f.Key,accounting);Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.GreaterThan(before));Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.LessThanOrEqualTo((int)D3ReadField(f.Coordinator,"queriesPerIntent")));
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("JourneyPermit"),Is.SameAs(source));Assert.That(f.Read("JourneyRequest"),Is.SameAs(journey));Assert.That(D3ReadField(leg,"Suffix"),Is.SameAs(suffix));
            Assert.That(D3ReadField(leg,"NeedsQuery"),Is.EqualTo(false));Assert.That(D3ReadField(leg,"Generation"),Is.EqualTo(8));Assert.That(D3ReadField(leg,"Index"),Is.EqualTo(0));Assert.That(D3ReadField(leg,"Proof"),Is.SameAs(f.Outward));
            var request=(TrafficRequest)f.Read("Request");Assert.That(request.Snapshot,Is.SameAs(f.World));Assert.That(request.RequestedFrame,Is.EqualTo(original.RequestedFrame));Assert.That(request.Intent,Is.EqualTo(original.Intent));Assert.That(request.NativeStamp,Is.EqualTo(original.NativeStamp));
            Assert.That(request.Start,Is.EqualTo(original.Start));Assert.That(request.Target,Is.EqualTo(original.Target));Assert.That(request.ResourceId,Is.EqualTo(original.ResourceId));Assert.That(((Vector3[])f.Read("CurrentPath"))[0],Is.EqualTo(own.Position));
            CollectionAssert.AreEqual(proofEnds,f.Outward.LegEnds);CollectionAssert.AreEqual(proofPath,f.Outward.ExpandedPath);Assert.That(f.Read("Active"),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,8),Is.False);
            Assert.That(f.Coordinator.TryCommit(current),Is.True);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,8),Is.True);
            Assert.That(((CanonicalOwner)original.Snapshot.Parking.Single().CanonicalOwner).Applies,Is.EqualTo(1));
        }

        [TestCase("life")]
        [TestCase("pose")]
        [TestCase("enabled")]
        [TestCase("active")]
        [TestCase("radius")]
        [TestCase("safety")]
        [TestCase("retired")]
        [TestCase("scope")]
        public void QueuedStrictLegFreshnessCannotAdoptChangedOwnBodyOrRetiredScope(string change)
        {
            var f=QueuedUnissuedStrictLegAtActualStart();var original=(TrafficRequest)f.Read("Request");var before=f.Coordinator.QueriesConsumed(f.Key);var own=original.Snapshot.Bodies.Single(b=>b.Owner.ActorId==f.Key.ActorId);
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);var bodies=original.Snapshot.Bodies.Where(b=>b.Owner.ActorId!=f.Key.ActorId).ToList();
            bodies.Insert(0,new TrafficBodyFact(own.Owner,change=="pose"?own.Position+P(.1f):own.Position,change=="radius"?own.Radius+.1f:own.Radius,
                enabled:change!="enabled",independentlyProgressing:own.IndependentlyProgressing,remainingSeconds:own.RemainingSeconds,
                safetyMargin:change=="safety"?own.SafetyMargin+.01f:own.SafetyMargin,actorLife:change=="life"?new object():own.ActorLife,actorActive:change!="active"));
            f.World=World(2,3,bodies.ToArray(),original.Snapshot.Parking.ToArray());
            if(change=="scope")
            {
                f.Coordinator.ResetLayout(2,8,f.World);f.Coordinator.ProcessReady(f.Frame++);
                Assert.That(D3ContainsIntent(f.Coordinator,f.Key),Is.False);Assert.That(f.Coordinator.PrepareLeg(f.Journey,"outward",0,f.Actor,8,f.World,original.Start,.05f,f.Frame).Kind,Is.EqualTo(TrafficDecisionKind.StaleContext));
                Assert.That(f.Coordinator.TryCommit(f.Journey),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,8),Is.False);Assert.That(f.Coordinator.QueriesThisFrame,Is.Zero);return;
            }
            if(change=="retired")f.Coordinator.Retire(f.Key);
            f.Coordinator.SetSnapshot(f.World);f.Coordinator.ProcessReady(f.Frame++);var refused=f.Coordinator.GetDecision(f.Key);
            Assert.That(refused.Kind!=TrafficDecisionKind.Granted && refused.Kind!=TrafficDecisionKind.DeferredByBudget && refused.Kind!=TrafficDecisionKind.WaitingForTraffic,Is.True,
                "PROTECTED: changed own physical/life facts cannot inherit stale geometry or remain an authorized pending source");
            Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Active"),Is.False);Assert.That(f.Read("Queued"),Is.False);Assert.That(f.Coordinator.TryCommit(refused),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,8),Is.False);
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(before),"Own invalidation must be rejected before a new query");D3AssertAccounting(f.Coordinator,f.Key,accounting);
            if(change!="retired")Assert.That(((TrafficRequest)f.Read("Request")).RequestedFrame,Is.EqualTo(original.RequestedFrame));
        }

        [Test] public void QueuedStrictLegRechecksNewActualTargetBlockerBeforeAnyGrant()
        {
            var f=QueuedUnissuedStrictLegAtActualStart();var original=(TrafficRequest)f.Read("Request");var before=f.Coordinator.QueriesConsumed(f.Key);var blocker=Key("new-strict-target-blocker");
            var owner=new CanonicalOwner();Assert.That(owner.Prepare().TryApply(out var receipt),Is.True);var accounting=D3CaptureAccounting(f.Coordinator,f.Key);accounting.Remove("Queries");
            var claim=new TrafficParkingFact(blocker,owner,owner.Version,"new-blocking-slot",f.End,.4f,businessOwner:owner,releaseObligation:receipt);
            f.World=World(3,3,original.Snapshot.Bodies.Concat(new[]{new TrafficBodyFact(blocker,f.End,.4f,actorLife:new object())}).ToArray(),original.Snapshot.Parking.Concat(new[]{claim}).ToArray());
            f.Coordinator.SetSnapshot(f.World);Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(before));f.Coordinator.ProcessReady(f.Frame++);var blocked=f.Coordinator.GetDecision(f.Key);
            Assert.That(blocked.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"FEATURE: current physical target blocker must decide the result, not stale snapshot rejection or blind grant");
            Assert.That(blocked.Blockers.Any(b=>b.Owner.Equals(blocker)),Is.True);Assert.That(blocked.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.GreaterThan(before));Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.LessThanOrEqualTo((int)D3ReadField(f.Coordinator,"queriesPerIntent")));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            Assert.That(f.Coordinator.TryCommit(blocked),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,8),Is.False);Assert.That(owner.Applies,Is.EqualTo(1));
            var spent=f.Coordinator.QueriesConsumed(f.Key);f.World=World(4,4,original.Snapshot.Bodies.ToArray(),original.Snapshot.Parking.ToArray());f.Coordinator.SetSnapshot(f.World);f.Coordinator.NotifyChanged(blocker,"body");f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(blocked),"Removing the later blocker cannot revive a genuine terminal source");Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(spent));
        }

