        [Test] public void RevalidatedCurrentLegProtectsItsActualDetourAndOriginalFutureSuffixFromParking()
        {
            var actual=P(0,-.2f);var detour=Origin;
            var f=new LegFixture((from,to)=>from==actual?new[]{from,detour,to}:new[]{from,to});
            var originalEnds=f.Outward.LegEnds.ToArray();
            float DistanceToPolyline(Vector3 point,IReadOnlyList<Vector3> path)
            {
                var best=float.PositiveInfinity;
                for(var i=1;i<path.Count;i++)
                {
                    var delta=path[i]-path[i-1];var length=delta.sqrMagnitude;
                    var fraction=length==0?0:Mathf.Clamp01(Vector3.Dot(point-path[i-1],delta)/length);
                    best=Mathf.Min(best,Vector3.Distance(point,path[i-1]+delta*fraction));
                }
                return best;
            }
            var oldJourney=f.Outward.ExpandedPath.Concat(f.Home.ExpandedPath).ToArray();
            var candidates=new[]{P(-4,4),P(-4,-4),P(-6,6),P(-6,-6)};
            var safe=candidates.Where(candidate=>DistanceToPolyline(P(2),new[]{actual,candidate,f.End})>=.8f &&
                DistanceToPolyline(candidate,oldJourney)>2 && Vector3.Distance(actual,candidate)>2).ToArray();
            Assert.That(safe,Is.Not.Empty,"FIXTURE: a deterministic detour must avoid the original obstacle and the full old selected polyline");
            detour=safe[0];
            Assert.That(DistanceToPolyline(P(2),new[]{actual,detour,f.End}),Is.GreaterThanOrEqualTo(.8f),
                "FIXTURE: every new Native-model segment must clear the original outward obstacle");
            Assert.That(DistanceToPolyline(detour,oldJourney),Is.GreaterThan(2),
                "FIXTURE: proposed parking is far from every segment of the old selected journey, not only its vertices");
            TestContext.WriteLine("SAFE_CURRENT_DETOUR actual="+actual+" detour="+detour+" endpoint="+f.End+
                " obstacleClearance="+DistanceToPolyline(P(2),new[]{actual,detour,f.End})+" oldJourneyDistance="+DistanceToPolyline(detour,oldJourney));
            var queries=f.Coordinator.QueriesConsumed(f.Key);
            f.World=World(1,2,new[]{new TrafficBodyFact(f.Key,actual,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(start:actual).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            var leg=f.CommitPrepared();
            CollectionAssert.Contains((Vector3[])f.Read("CurrentPath"),detour,"Fixture: actual budgeted Native result includes the changed current leg");
            Assert.That(Vector3.Distance(actual,detour),Is.GreaterThan(2));
            var later=Key("later-detour-parking");
            f.Coordinator.EvaluateParking(Request(later,P(-8,-4),detour,f.World,frame:f.Frame));f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(later).Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted),
                "PRODUCT: long parking must protect the actual current detour as well as the retained selected suffix");
            var homeParking=Key("later-home-parking");
            f.Coordinator.EvaluateParking(Request(homeParking,P(10),P(6),f.World,frame:f.Frame));f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(homeParking).Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
