        [Test] public void DiscardedUnissuedLegCanExplicitlyReprepareWithCumulativeQueriesAndOriginalAge()
        {
            var f=new LegFixture();var initialQueries=f.Coordinator.QueriesConsumed(f.Key);var actual=P(0,-.2f);
            f.World=World(1,2,new[]{new TrafficBodyFact(f.Key,actual,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(start:actual).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(f.Key).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.False,"Fixture: spatial candidate is ready, but no Native leg was committed/bound");
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(initialQueries+1));
            Assert.That(f.Coordinator.DiscardPrepared(f.Key),Is.True);
            var protectedDuringGap=((Vector3[])f.Read("Journey")).Contains(P(8));
            var firstActual=actual;actual=P(0,-.1f);
            var segment=f.End-actual;var projected=Mathf.Clamp01(Vector3.Dot(P(2)-actual,segment)/segment.sqrMagnitude);
            var obstacleClearance=Vector3.Distance(P(2),actual+segment*projected);
            Assert.That(actual,Is.Not.EqualTo(firstActual),"FIXTURE: retry must require a fresh actual-start query");
            Assert.That(obstacleClearance,Is.GreaterThanOrEqualTo(.8f),"FIXTURE: the complete second Native-model segment must clear the original obstacle");
            TestContext.WriteLine("SAFE_DISCARD_RETRY firstActual="+firstActual+" secondActual="+actual+" endpoint="+f.End+" obstacleClearance="+obstacleClearance);
            f.World=World(1,3,new[]{new TrafficBodyFact(f.Key,actual,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(start:actual).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),
                "PRODUCT: discarding an unissued leg cannot strand an already-acquired business journey");
            Assert.That(protectedDuringGap,Is.True,"Discard only candidate movement rights, not the original selected home obligation");
            var leg=f.CommitPrepared();
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(initialQueries+2));
            Assert.That(leg.RequestSequence,Is.EqualTo(f.Journey.RequestSequence));Assert.That(leg.AcquiredSequence,Is.EqualTo(f.Journey.AcquiredSequence));
            Assert.That(f.Read("FirstFrame"),Is.EqualTo(1));
        }

        [Test] public void BoundUnfinishedLegCannotBeReplacedByFreshSnapshotOrCandidateDiscard()
        {
            var f=new LegFixture();f.Start();var stamp=new TrafficNativeStamp(51,1);
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.True);
            var oldLeg=f.Read("Leg");var oldPath=((Vector3[])f.Read("CurrentPath")).ToArray();var queries=f.Coordinator.QueriesConsumed(f.Key);
            var actual=P(0,-.2f);f.World=World(2,2,new[]{new TrafficBodyFact(f.Key,actual,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            var replacement=f.Prepare(generation:2,start:actual);
            Assert.That(replacement.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(replacement.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(f.Coordinator.DiscardPrepared(f.Key),Is.False,"A bound live Native leg is not an unissued proposal");
            Assert.That(f.Read("Leg"),Is.SameAs(oldLeg));CollectionAssert.AreEqual(oldPath,(Vector3[])f.Read("CurrentPath"));
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries));
            f.Coordinator.Retire(f.Key);
            Assert.That(f.Prepare(generation:2,start:actual).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled),"Explicit retirement remains terminal under fresh facts");
