        [Test] public void BoundSameRevisionSuspensionPreservesUnfinishedJourneyAndRevalidatesSamePhaseOnRestore()
        {
            var f=new LegFixture();f.Start();var stamp=new TrafficNativeStamp(71,1);
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.True);
            var journey=((Vector3[])f.Read("Journey")).ToArray();var queries=f.Coordinator.QueriesConsumed(f.Key);
            f.World=World(1,2,new[]{new TrafficBodyFact(f.Key,Origin,.4f,enabled:false,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Coordinator.SuspendLeg(f.Key,f.Actor,stamp,SuspendedResult(f.Key),7),Is.True,
                "PRODUCT: actual bound LayoutChanged must suspend without fabricating Arrived or retiring the business phase");
            Assert.That((Vector3[])f.Read("CurrentPath"),Is.Empty);CollectionAssert.AreEqual(journey,(Vector3[])f.Read("Journey"));
            var leg=f.Read("Leg");const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            Assert.That(leg.GetType().GetField("Completed",flags).GetValue(leg),Is.False);
            Assert.That(leg.GetType().GetField("Index",flags).GetValue(leg),Is.EqualTo(0));
            var unavailable=f.Prepare(generation:2);
            Assert.That(unavailable.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(unavailable.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget),"Disabled/unavailable body cannot resume");
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries));
            f.World=World(1,3,new[]{new TrafficBodyFact(f.Key,Origin,.4f,actorLife:f.Actor)});f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(generation:2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries),"Restore uses the ordinary ready batch");
            var resumed=f.CommitPrepared();
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries+1),"Even unchanged pose needs budgeted proof revalidation after Native suspension");
            Assert.That(resumed.RequestSequence,Is.EqualTo(f.Journey.RequestSequence));Assert.That(resumed.AcquiredSequence,Is.EqualTo(f.Journey.AcquiredSequence));
            Assert.That(f.Read("FirstFrame"),Is.EqualTo(1));
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(72,2)),Is.True);
        }

        // Invoke the actual internal producer port once across the separate test assembly.
        // 与既有 CfcReprepare 一样：只调用真实入口，不写 Entry 或伪造状态。
        private static string RequeuePreparedLeg(ServiceTrafficCoordinator coordinator,TrafficDecision source,string resource,int index,
            object actor,int generation,TrafficWorldSnapshot current,Vector3 start,out TrafficDecision next)
        {
            var method=typeof(ServiceTrafficCoordinator).GetMethod("TryRequeuePreparedLeg",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(method,Is.Not.Null,"TESTFIRST scaffold: real producer port must exist");
            Assert.That(method.ReturnType.IsEnum,Is.True,"Actual internal port must expose the single typed protocol");
            CollectionAssert.AreEquivalent(new[]{"NoOp","Requeued","Rejected"},Enum.GetNames(method.ReturnType));
            var arguments=new object[]{source,resource,index,actor,generation,current,start,null};
            var result=method.Invoke(coordinator,arguments);next=(TrafficDecision)arguments[7];return Enum.GetName(method.ReturnType,result);
        }

        // Explicit reproof is separate from legacy PrepareLeg metadata compatibility.
        // 公开 Core 产生真实 prepared leg；模型 snapshot 发布外部阶段变化，不写私有 Entry。
        [TestCase(false)]
        [TestCase(true)]
        public void ExplicitPreparedLegRequeueRechecksActualExternalPhaseHandoff(bool blockedTarget)
        {
            var externalOwner=new CanonicalOwner();Assert.That(externalOwner.Prepare().TryApply(out var externalReceipt),Is.True);
            var beforeKey=Key("external-phase-actor","pickup-service",11);var afterKey=Key(beforeKey.ActorId,"actual-exit",14);
            var externalLife=new object();var business=new object();var position=P(-8,-8);
            var oldClaims=new[]{"pickup/external","service/external"}.Select(resource=>new TrafficParkingFact(beforeKey,externalOwner,externalOwner.Version,
                resource,position,.4f,businessOwner:business,releaseObligation:externalReceipt)).ToArray();
            var f=PreparedCanonicalMetadataLeg(out var ownOwner,out var ownClaim,out var stale,oldClaims,
                new[]{new TrafficBodyFact(beforeKey,position,.4f,actorLife:externalLife)});
            var original=(TrafficRequest)f.Read("Request");var leg=f.Read("Leg");var source=f.Read("JourneyPermit");var journey=f.Read("JourneyRequest");
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);var suffix=((Vector3[])f.Read("Journey")).ToArray();
            // Real public Core commit establishes the other actor's new progressing phase.
            var externalSource=Grant(f.Coordinator,Request(afterKey,position,P(-7,-8),f.World,frame:f.Frame++,resource:"external-exit",seconds:13));
            Assert.That(f.Coordinator.HasActiveGrant(afterKey),Is.True);Assert.That(externalSource.AcquiredSequence,Is.GreaterThan(0));
            var bodies=new List<TrafficBodyFact>{original.Snapshot.Bodies.Single(body=>body.Owner.ActorId==f.Key.ActorId),
                new TrafficBodyFact(afterKey,position,.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:externalLife)};
            var blocker=Key("current-endpoint-blocker");if(blockedTarget)bodies.Add(new TrafficBodyFact(blocker,f.End,.4f,actorLife:new object()));
            var changed=oldClaims.Select(claim=>new TrafficParkingFact(afterKey,claim.CanonicalOwner,claim.OwnerVersion,claim.ResourceId,
                claim.Position,claim.Radius,claim.SafetyMargin,claim.BusinessOwner,claim.ReleaseObligation)).ToArray();
            f.World=World(3,2,bodies.ToArray(),new[]{ownClaim}.Concat(changed).ToArray());f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Read("Prepared"),Is.True);Assert.That(f.Read("Active"),Is.False);Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(stale));
            Assert.That(ownOwner.Version,Is.EqualTo(ownClaim.OwnerVersion));Assert.That(externalOwner.Version,Is.EqualTo(oldClaims[0].OwnerVersion));
            Assert.That(RequeuePreparedLeg(f.Coordinator,f.Journey,"outward",0,f.Actor,9,f.World,Origin,out var pending),Is.EqualTo("Requeued"),
                "FEATURE: authenticated unissued prepared source must revoke its stale permit before full current-world evaluation");
            Assert.That(pending.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(pending.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(pending));Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Queued"),Is.True);Assert.That(f.Read("Active"),Is.False);
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("JourneyPermit"),Is.SameAs(source));Assert.That(f.Read("JourneyRequest"),Is.SameAs(journey));
            var refreshed=(TrafficRequest)f.Read("Request");Assert.That(refreshed.Snapshot,Is.SameAs(f.World));Assert.That(refreshed.RequestedFrame,Is.EqualTo(original.RequestedFrame));
            Assert.That(refreshed.Intent,Is.EqualTo(original.Intent));Assert.That(refreshed.Start,Is.EqualTo(original.Start));Assert.That(refreshed.Target,Is.EqualTo(original.Target));Assert.That(refreshed.ResourceId,Is.EqualTo(original.ResourceId));Assert.That(refreshed.NativeStamp,Is.EqualTo(original.NativeStamp));
            D3AssertAccounting(f.Coordinator,f.Key,accounting);CollectionAssert.AreEqual(suffix,(Vector3[])f.Read("Journey"));
            Assert.That(f.Coordinator.TryCommit(stale),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
            Assert.That(RequeuePreparedLeg(f.Coordinator,f.Journey,"outward",0,f.Actor,9,f.World,Origin,out _),Is.EqualTo("NoOp"),"Already queued is not another prepared permission");
            f.Coordinator.ProcessReady(f.Frame++);var current=f.Coordinator.GetDecision(f.Key);
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(D3ReadField(leg,"Proof"),Is.SameAs(f.Outward));Assert.That(D3ReadField(leg,"Index"),Is.EqualTo(0));Assert.That(D3ReadField(leg,"Generation"),Is.EqualTo(9));
            Assert.That(((TrafficRequest)f.Read("Request")).RequestedFrame,Is.EqualTo(original.RequestedFrame));Assert.That(f.Read("JourneyPermit"),Is.SameAs(source));
            var after=accounting.Where(pair=>pair.Key!="Queries").ToDictionary(pair=>pair.Key,pair=>pair.Value);
            D3AssertAccounting(f.Coordinator,f.Key,after);Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.GreaterThanOrEqualTo((int)accounting["Queries"]));
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.LessThanOrEqualTo((int)D3ReadField(f.Coordinator,"queriesPerIntent")));
            if(blockedTarget)
            {
                Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));Assert.That(current.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                Assert.That(current.Blockers.Any(item=>item.Owner.Equals(blocker)),Is.True,"Only the real current-world blocker determines failure");
                Assert.That(f.Coordinator.TryCommit(current),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
                Assert.That(RequeuePreparedLeg(f.Coordinator,f.Journey,"outward",0,f.Actor,9,f.World,Origin,out _),Is.EqualTo("NoOp"),"No Terminal resurrection");
            }
            else
            {
                Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(current,Is.Not.SameAs(stale));
                Assert.That(f.Coordinator.TryCommit(current),Is.True);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.True);
                Assert.That(RequeuePreparedLeg(f.Coordinator,f.Journey,"outward",0,f.Actor,9,f.World,Origin,out _),Is.EqualTo("NoOp"),"No acquired-right replacement");
            }
            Assert.That(ownOwner.Applies,Is.EqualTo(1));Assert.That(ownOwner.Rollbacks,Is.Zero);Assert.That(externalOwner.Applies,Is.EqualTo(1));Assert.That(externalOwner.Rollbacks,Is.Zero);
        }

        [TestCase("fresh")]
        [TestCase("permit")]
        [TestCase("proof")]
        [TestCase("index")]
        [TestCase("generation")]
        [TestCase("start")]
        [TestCase("life")]
        [TestCase("radius")]
        [TestCase("safety")]
        [TestCase("own-version")]
        [TestCase("own-owner")]
        [TestCase("checkpoint")]
        [TestCase("committed")]
        [TestCase("bound")]
        [TestCase("retired")]
        [TestCase("snapshot")]
        public void ExplicitPreparedLegRequeueRejectsNonCurrentOrChangedOwnSource(string change)
        {
            var f=PreparedCanonicalMetadataLeg(out var owner,out var claim,out var stale);
            if(change=="committed" || change=="bound")Assert.That(f.Coordinator.TryCommit(stale),Is.True);
            if(change=="bound")Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(71,9)),Is.True);
            if(change=="retired")f.Coordinator.Retire(f.Key);
            if(change=="own-version")owner.ExternalChange();var canonical=owner;var release=claim.ReleaseObligation;
            if(change=="own-owner"){canonical=new CanonicalOwner();Assert.That(canonical.Prepare().TryApply(out var replacement),Is.True);release=replacement;}
            var actualLife=change=="life"?new object():f.Actor;var actualStart=change=="start"?P(-.1f):Origin;
            var currentClaim=new TrafficParkingFact(claim.Owner,canonical,canonical.Version,claim.ResourceId,claim.Position,claim.Radius,claim.SafetyMargin,
                claim.BusinessOwner,release,change=="checkpoint"?new object():claim.SemanticCheckpoint);
            if(change!="fresh")f.World=World(3,2,new[]{new TrafficBodyFact(f.Key,actualStart,change=="radius"?.5f:.4f,
                safetyMargin:change=="safety"?.01f:0,actorLife:actualLife)},new[]{currentClaim});
            f.Coordinator.SetSnapshot(f.World);var leg=f.Read("Leg");var request=f.Read("Request");var decision=f.Coordinator.GetDecision(f.Key);var accounting=D3CaptureAccounting(f.Coordinator,f.Key);
            var supplied=change=="snapshot"?World(f.World.Version,f.World.BodyVersion,f.World.Bodies.ToArray(),f.World.Parking.ToArray()):f.World;
            // Authenticate original caller identity first; changed actual body/claims are facts to reject, not foreign arguments.
            // 保留原 Actor/起点入参，真实当前 snapshot 的变化必须触发 Rejected，不能落回旧 body-only 分支。
            var rejectOwnFacts=new[]{"start","life","radius","safety","own-version","own-owner","checkpoint"}.Contains(change);
            var outcome=RequeuePreparedLeg(f.Coordinator,change=="permit"?stale:f.Journey,change=="proof"?"home":"outward",change=="index"?1:0,
                f.Actor,change=="generation"?10:9,supplied,Origin,out var next);
            Assert.That(outcome,Is.EqualTo(rejectOwnFacts?"Rejected":"NoOp"),"FEATURE: authenticated own-fact loss must not masquerade as no-op/fallback permission");
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("Request"),Is.SameAs(request));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            if(rejectOwnFacts)
            {
                Assert.That(next,Is.Not.Null);Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.StaleContext));Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(next));
                Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Queued"),Is.False);Assert.That(f.Read("Active"),Is.False);
                Assert.That(f.Coordinator.TryCommit(stale),Is.False,"The authentic candidate lost authority; old permit cannot commit");Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
                Assert.That(D3ReadField(leg,"Proof"),Is.SameAs(f.Outward));Assert.That(D3ReadField(leg,"Generation"),Is.EqualTo(9));Assert.That(D3ReadField(leg,"Index"),Is.EqualTo(0));
            }
            else
            {
                Assert.That(next,Is.Null);Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(decision),"Foreign/fresh/not-applicable calls cannot alter the original owner");
                if(change=="committed" || change=="bound")Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.True);
            }
            Assert.That(owner.Applies,Is.EqualTo(1));Assert.That(owner.Rollbacks,Is.Zero);
        }

        // Public Core model: publish a real model-owner mutation, then prepare (never commit) a strict leg.
        // 使用原 LegFixture 与公开 API；reflection 只读账本，不写 Entry/Native 状态。
        private static LegFixture PreparedCanonicalMetadataLeg(out CanonicalOwner owner,out TrafficParkingFact claim,out TrafficDecision prepared,
            TrafficParkingFact[] externalClaims=null,TrafficBodyFact[] externalBodies=null)
        {
            var f=new LegFixture();owner=new CanonicalOwner();
            Assert.That(owner.Prepare().TryApply(out var receipt),Is.True);Assert.That(receipt.IsCurrent,Is.True);
            claim=new TrafficParkingFact(f.Key,owner,owner.Version,"actual-owned-slot",Origin,.4f,businessOwner:f.Journey,releaseObligation:receipt);
            f.World=World(2,1,f.World.Bodies.Concat(externalBodies??Array.Empty<TrafficBodyFact>()).ToArray(),
                new[]{claim}.Concat(externalClaims??Array.Empty<TrafficParkingFact>()).ToArray());f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(generation:9).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(f.Frame++);prepared=f.Coordinator.GetDecision(f.Key);
            Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FIXTURE: actual prepared unissued strict leg");
            Assert.That(f.Read("Prepared"),Is.True);Assert.That(f.Read("Active"),Is.False);
            Assert.That(D3ReadField(f.Read("Leg"),"Committed"),Is.EqualTo(false));Assert.That(D3ReadField(f.Read("Leg"),"Bound"),Is.EqualTo(false));
            Assert.That(D3ReadField(f.Read("Leg"),"Stamp"),Is.EqualTo(default(TrafficNativeStamp)));return f;
        }

        [TestCase(false)] // Existing body-only contract control.
        [TestCase(true)] // Canonical-only metadata drift: expected FEATURE RED before the narrow fix.
        public void PreparedUnissuedStrictLegRevalidatesSameFactsWithoutReplacingOriginalAccounting(bool canonicalVersion)
        {
            var f=PreparedCanonicalMetadataLeg(out var owner,out var claim,out var stalePermission);
            var leg=f.Read("Leg");var source=f.Read("JourneyPermit");var journeyRequest=f.Read("JourneyRequest");var original=(TrafficRequest)f.Read("Request");
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);var suffix=((Vector3[])f.Read("Journey")).ToArray();
            var proofEnds=f.Outward.LegEnds.ToArray();var proofPath=f.Outward.ExpandedPath.ToArray();
            var clone=new TrafficParkingFact(claim.Owner,claim.CanonicalOwner,claim.OwnerVersion,claim.ResourceId,claim.Position,claim.Radius,claim.SafetyMargin,claim.BusinessOwner,claim.ReleaseObligation);
            f.World=World(canonicalVersion?3:2,canonicalVersion?1:2,f.World.Bodies.ToArray(),new[]{clone});f.Coordinator.SetSnapshot(f.World);
            var pending=f.Prepare(generation:9);
            Assert.That(pending.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"FEATURE: same unissued strict leg must revalidate metadata in the ordinary batch");
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("JourneyPermit"),Is.SameAs(source));Assert.That(f.Read("JourneyRequest"),Is.SameAs(journeyRequest));
            var refreshed=(TrafficRequest)f.Read("Request");Assert.That(refreshed.Snapshot,Is.SameAs(f.World));Assert.That(refreshed.RequestedFrame,Is.EqualTo(original.RequestedFrame));
            Assert.That(refreshed.Intent,Is.EqualTo(original.Intent));Assert.That(refreshed.ResourceId,Is.EqualTo(original.ResourceId));Assert.That(refreshed.Start,Is.EqualTo(original.Start));Assert.That(refreshed.Target,Is.EqualTo(original.Target));
            Assert.That(refreshed.NativeStamp,Is.EqualTo(original.NativeStamp));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Queued"),Is.True);Assert.That(f.Read("Active"),Is.False);
            Assert.That(f.Coordinator.TryCommit(stalePermission),Is.False,"The revoked original prepared permit must not commit");Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
            CollectionAssert.AreEqual(suffix,(Vector3[])f.Read("Journey"));
            f.Coordinator.ProcessReady(f.Frame++);var current=f.Coordinator.GetDecision(f.Key);
            Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(current,Is.Not.SameAs(stalePermission));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(D3ReadField(leg,"Proof"),Is.SameAs(f.Outward));Assert.That(D3ReadField(leg,"Index"),Is.EqualTo(0));Assert.That(D3ReadField(leg,"Generation"),Is.EqualTo(9));
            CollectionAssert.AreEqual(proofEnds,f.Outward.LegEnds);CollectionAssert.AreEqual(proofPath,f.Outward.ExpandedPath);
            Assert.That(((TrafficRequest)f.Read("Request")).RequestedFrame,Is.EqualTo(original.RequestedFrame));Assert.That(f.Read("JourneyRequest"),Is.SameAs(journeyRequest));
            Assert.That(f.Coordinator.TryCommit(current),Is.True);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.True);
            Assert.That(owner.Applies,Is.EqualTo(1));Assert.That(owner.Rollbacks,Is.Zero);Assert.That(owner.Version,Is.EqualTo(claim.OwnerVersion));
        }

        [TestCase(false)]
        [TestCase(true)]
        public void PreparedStrictLegAcceptsFreshRealClaimMarkersWithoutNarrowingExternalRemoval(bool externalRemoval)
        {
            var remaining=Key("typed-counter-remaining");var departing=Key("typed-counter-departing");
            var counter=new CounterQueueService(new[]{P(-8,-8),P(-7,-8)});
            Assert.That(counter.TryJoin(remaining.ActorId),Is.True);Assert.That(counter.Complete(remaining.ActorId,1),Is.True);
            Assert.That(counter.TryJoin("actual-other-arrival"),Is.True);
            Assert.That(counter.TryCaptureAssignment(remaining.ActorId,out var beforeClaim),Is.True);
            Assert.That(counter.TryCaptureAssignment("actual-other-arrival",out var arriving),Is.True);
            var otherQueue=new CounterQueueService(new[]{P(-6,-8)});Assert.That(otherQueue.TryJoin(departing.ActorId),Is.True);
            Assert.That(otherQueue.TryCaptureAssignment(departing.ActorId,out var beforeDeparture),Is.True);
            var remainingBusiness=new object();var remainingRelease=new object();var departingBusiness=new object();var departingRelease=new object();
            TrafficParkingFact RemainingFact(CounterQueueService.AssignmentClaim claim)=>new TrafficParkingFact(remaining,counter,counter.Version,
                "counter/"+remaining.ActorId,claim.Assignment.Position,.4f,businessOwner:remainingBusiness,releaseObligation:remainingRelease,semanticCheckpoint:claim);
            var oldRemaining=RemainingFact(beforeClaim);
            var oldDeparture=new TrafficParkingFact(departing,otherQueue,otherQueue.Version,"counter/"+departing.ActorId,
                beforeDeparture.Assignment.Position,.4f,businessOwner:departingBusiness,releaseObligation:departingRelease,semanticCheckpoint:beforeDeparture);
            var bodies=new[]{new TrafficBodyFact(remaining,oldRemaining.Position,.4f,actorLife:new object()),
                new TrafficBodyFact(departing,oldDeparture.Position,.4f,actorLife:new object())};
            var f=PreparedCanonicalMetadataLeg(out var ownOwner,out var ownClaim,out var stale,new[]{oldRemaining,oldDeparture},bodies);
            var original=(TrafficRequest)f.Read("Request");var leg=f.Read("Leg");var source=f.Read("JourneyPermit");var journey=f.Read("JourneyRequest");
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);var suffix=((Vector3[])f.Read("Journey")).ToArray();var counterVersion=counter.Version;
            // Distinct public owners isolate shared-version drift from actual removal. Bodies and this owner's claims stay fixed.
            // 不私写 canonical/Entry；另一顾客真实到达与另一 Queue 真实 Remove 是独立的外部账本事件。
            if(externalRemoval)
            {Assert.That(counter.Complete(arriving.Assignment.VisitId,arriving.Assignment.Generation),Is.True);Assert.That(otherQueue.Remove(departing.ActorId),Is.True);}
            Assert.That(counter.TryCaptureAssignment(remaining.ActorId,out var freshClaim),Is.True);
            Assert.That(freshClaim,Is.Not.SameAs(beforeClaim));Assert.That(beforeClaim.IsSameReservation(freshClaim),Is.True);
            Assert.That(beforeClaim.IsCurrent && freshClaim.IsCurrent,Is.True);
            Assert.That(freshClaim.Assignment.Generation,Is.EqualTo(beforeClaim.Assignment.Generation));Assert.That(freshClaim.Assignment.SlotIndex,Is.EqualTo(beforeClaim.Assignment.SlotIndex));
            Assert.That(freshClaim.Assignment.Position,Is.EqualTo(beforeClaim.Assignment.Position));Assert.That(freshClaim.Assignment.Arrived,Is.EqualTo(beforeClaim.Assignment.Arrived));
            Assert.That(counter.Version,Is.EqualTo(counterVersion+(externalRemoval?1:0)));
            Assert.That(beforeDeparture.IsCurrent,Is.EqualTo(!externalRemoval));
            var freshRemaining=RemainingFact(freshClaim);
            var claims=externalRemoval?new[]{ownClaim,freshRemaining}:new[]{ownClaim,freshRemaining,oldDeparture};
            f.World=World(original.Snapshot.Version+1,original.Snapshot.BodyVersion,original.Snapshot.Bodies.ToArray(),claims);
            Assert.That(f.World.Parking.Count,Is.EqualTo(original.Snapshot.Parking.Count-(externalRemoval?1:0)));
            Assert.That(f.World.Parking[0],Is.SameAs(ownClaim));Assert.That(ownOwner.Version,Is.EqualTo(ownClaim.OwnerVersion));
            for(var i=0;i<original.Snapshot.Bodies.Count;i++)Assert.That(f.World.Bodies[i],Is.SameAs(original.Snapshot.Bodies[i]));
            f.Coordinator.SetSnapshot(f.World);var pending=f.Prepare(generation:9);
            TestContext.WriteLine("STRICT_REAL_CLAIM_MARKER removal="+externalRemoval+" counterVersion="+counterVersion+"->"+counter.Version+" sameEntry=True freshMarker=True");
            Assert.That(pending.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"FEATURE: fresh real claim markers must preserve the original strict metadata/removal contract");
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("JourneyPermit"),Is.SameAs(source));Assert.That(f.Read("JourneyRequest"),Is.SameAs(journey));
            D3AssertAccounting(f.Coordinator,f.Key,accounting);CollectionAssert.AreEqual(suffix,(Vector3[])f.Read("Journey"));
            var refreshed=(TrafficRequest)f.Read("Request");Assert.That(refreshed.Snapshot,Is.SameAs(f.World));Assert.That(refreshed.RequestedFrame,Is.EqualTo(original.RequestedFrame));
            Assert.That(refreshed.Intent,Is.EqualTo(original.Intent));Assert.That(refreshed.NativeStamp,Is.EqualTo(original.NativeStamp));
            Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Queued"),Is.True);Assert.That(f.Read("Active"),Is.False);
            Assert.That(f.Coordinator.TryCommit(stale),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
            f.Coordinator.ProcessReady(f.Frame++);var current=f.Coordinator.GetDecision(f.Key);
            Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.Granted),current.Reason);Assert.That(current,Is.Not.SameAs(stale));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(D3ReadField(leg,"Proof"),Is.SameAs(f.Outward));
            Assert.That(D3ReadField(leg,"Index"),Is.EqualTo(0));Assert.That(D3ReadField(leg,"Generation"),Is.EqualTo(9));
            Assert.That(((TrafficRequest)f.Read("Request")).RequestedFrame,Is.EqualTo(original.RequestedFrame));CollectionAssert.AreEqual(suffix,(Vector3[])f.Read("Journey"));
            Assert.That(f.Coordinator.TryCommit(current),Is.True);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.True);
            Assert.That(counter.Version,Is.EqualTo(counterVersion+(externalRemoval?1:0)));Assert.That(ownOwner.Version,Is.EqualTo(ownClaim.OwnerVersion));
            Assert.That(ownOwner.Applies,Is.EqualTo(1));Assert.That(ownOwner.Rollbacks,Is.Zero);
        }

        [Test] public void PreparedUnissuedStrictLegRevalidatesExternalRemovalAndOnlyExternalOwnerVersionDrift()
        {
            var counter=new CanonicalOwner();Assert.That(counter.Prepare().TryApply(out var counterReceipt),Is.True);
            var departing=Key("counter-departing");var remaining=Key("counter-remaining");var firstBusiness=new object();var secondBusiness=new object();
            var firstClaim=new TrafficParkingFact(departing,counter,counter.Version,"counter/departing",P(-8,-8),.4f,businessOwner:firstBusiness);
            var secondClaim=new TrafficParkingFact(remaining,counter,counter.Version,"counter/remaining",P(-7,-8),.4f,businessOwner:secondBusiness);
            var externalBodies=new[]{new TrafficBodyFact(departing,firstClaim.Position,.4f,actorLife:new object()),new TrafficBodyFact(remaining,secondClaim.Position,.4f,actorLife:new object())};
            var f=PreparedCanonicalMetadataLeg(out var ownOwner,out var ownClaim,out var stale,new[]{firstClaim,secondClaim},externalBodies);
            var original=(TrafficRequest)f.Read("Request");var leg=f.Read("Leg");var source=f.Read("JourneyPermit");var journey=f.Read("JourneyRequest");var accounting=D3CaptureAccounting(f.Coordinator,f.Key);
            var suffix=((Vector3[])f.Read("Journey")).ToArray();var ownVersion=ownOwner.Version;
            // Model actual public owner bookkeeping: one external claim disappears; remaining bodies do not move.
            // 外部共享 owner 的版本变化不能冒充本任务 claim 变化，也不能重置当前 strict leg 的预算。
            counter.ExternalChange();
            var updatedRemaining=new TrafficParkingFact(remaining,counter,counter.Version,secondClaim.ResourceId,secondClaim.Position,secondClaim.Radius,secondClaim.SafetyMargin,secondClaim.BusinessOwner,secondClaim.ReleaseObligation);
            var sameOwnClaim=new TrafficParkingFact(ownClaim.Owner,ownClaim.CanonicalOwner,ownClaim.OwnerVersion,ownClaim.ResourceId,ownClaim.Position,ownClaim.Radius,ownClaim.SafetyMargin,ownClaim.BusinessOwner,ownClaim.ReleaseObligation);
            var sameBodies=original.Snapshot.Bodies.Select(b=>new TrafficBodyFact(b.Owner,b.Position,b.Radius,b.Enabled,b.IndependentlyProgressing,b.RemainingSeconds,b.SafetyMargin,b.ActorLife,b.ActorActive)).ToArray();
            f.World=World(original.Snapshot.Version+1,original.Snapshot.BodyVersion,sameBodies,new[]{sameOwnClaim,updatedRemaining});
            Assert.That(original.Snapshot.Parking.Count,Is.EqualTo(3));Assert.That(f.World.Parking.Count,Is.EqualTo(2));Assert.That(f.World.Bodies.Count,Is.EqualTo(original.Snapshot.Bodies.Count));
            for(var i=0;i<sameBodies.Length;i++)
            {
                var before=original.Snapshot.Bodies[i];var currentBody=sameBodies[i];Assert.That(currentBody,Is.Not.SameAs(before));Assert.That(currentBody.ActorLife,Is.SameAs(before.ActorLife));Assert.That(currentBody.Owner,Is.EqualTo(before.Owner));
                Assert.That(currentBody.Position,Is.EqualTo(before.Position));Assert.That(currentBody.Radius,Is.EqualTo(before.Radius));Assert.That(currentBody.SafetyMargin,Is.EqualTo(before.SafetyMargin));Assert.That(currentBody.Enabled,Is.EqualTo(before.Enabled));Assert.That(currentBody.ActorActive,Is.EqualTo(before.ActorActive));
                Assert.That(currentBody.IndependentlyProgressing,Is.EqualTo(before.IndependentlyProgressing));Assert.That(currentBody.RemainingSeconds,Is.EqualTo(before.RemainingSeconds));
            }
            Assert.That(sameOwnClaim,Is.Not.SameAs(ownClaim));Assert.That(sameOwnClaim.CanonicalOwner,Is.SameAs(ownOwner));Assert.That(sameOwnClaim.OwnerVersion,Is.EqualTo(ownVersion));Assert.That(ownOwner.Version,Is.EqualTo(ownVersion));
            Assert.That(updatedRemaining.OwnerVersion,Is.EqualTo(secondClaim.OwnerVersion+1));Assert.That(updatedRemaining.CanonicalOwner,Is.SameAs(secondClaim.CanonicalOwner));
            f.Coordinator.SetSnapshot(f.World);var pending=f.Prepare(generation:9);
            Assert.That(pending.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"FEATURE: exact external removal and unrelated shared-owner version drift must revalidate the same unissued strict leg");
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("JourneyPermit"),Is.SameAs(source));Assert.That(f.Read("JourneyRequest"),Is.SameAs(journey));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            var refreshed=(TrafficRequest)f.Read("Request");Assert.That(refreshed.Snapshot,Is.SameAs(f.World));Assert.That(refreshed.RequestedFrame,Is.EqualTo(original.RequestedFrame));Assert.That(refreshed.NativeStamp,Is.EqualTo(original.NativeStamp));
            Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Queued"),Is.True);Assert.That(f.Read("Active"),Is.False);CollectionAssert.AreEqual(suffix,(Vector3[])f.Read("Journey"));
            Assert.That(f.Coordinator.TryCommit(stale),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
            f.Coordinator.ProcessReady(f.Frame++);var current=f.Coordinator.GetDecision(f.Key);Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(current,Is.Not.SameAs(stale));
            D3AssertAccounting(f.Coordinator,f.Key,accounting);Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(D3ReadField(leg,"Proof"),Is.SameAs(f.Outward));
            Assert.That(D3ReadField(leg,"Index"),Is.EqualTo(0));Assert.That(D3ReadField(leg,"Generation"),Is.EqualTo(9));Assert.That(((TrafficRequest)f.Read("Request")).RequestedFrame,Is.EqualTo(original.RequestedFrame));
            Assert.That(f.Coordinator.TryCommit(current),Is.True);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.True);
            Assert.That(counter.Applies,Is.EqualTo(1));Assert.That(counter.Rollbacks,Is.Zero);Assert.That(counter.Version,Is.EqualTo(2));Assert.That(ownOwner.Applies,Is.EqualTo(1));Assert.That(ownOwner.Version,Is.EqualTo(ownVersion));
        }

        [TestCase(false)]
        [TestCase(true)]
        public void CanonicalRemovalRefreshRejectsMovedOrReplacedExternalClaim(bool replaced)
        {
            var counter=new CanonicalOwner();Assert.That(counter.Prepare().TryApply(out var receipt),Is.True);var otherKey=Key("external-original");var business=new object();
            var oldClaim=new TrafficParkingFact(otherKey,counter,counter.Version,"counter/external",P(-8,-8),.4f,businessOwner:business);
            var f=PreparedCanonicalMetadataLeg(out var ownOwner,out var ownClaim,out var stale,new[]{oldClaim});
            var leg=f.Read("Leg");var request=f.Read("Request");var accounting=D3CaptureAccounting(f.Coordinator,f.Key);
            var currentOwner=counter;if(replaced){currentOwner=new CanonicalOwner();Assert.That(currentOwner.Prepare().TryApply(out var otherReceipt),Is.True);}
            var changed=new TrafficParkingFact(otherKey,currentOwner,currentOwner.Version,oldClaim.ResourceId,replaced?oldClaim.Position:f.End,oldClaim.Radius,oldClaim.SafetyMargin,oldClaim.BusinessOwner,oldClaim.ReleaseObligation);
            f.World=World(3,1,f.World.Bodies.ToArray(),new[]{ownClaim,changed});f.Coordinator.SetSnapshot(f.World);var refused=f.Prepare(generation:9);
            Assert.That(refused.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(refused.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted),"External relocation/replacement is not a removal-only metadata delta");
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("Request"),Is.SameAs(request));Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(stale));D3AssertAccounting(f.Coordinator,f.Key,accounting);
            Assert.That(f.Coordinator.TryCommit(stale),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);Assert.That(ownOwner.Applies,Is.EqualTo(1));Assert.That(ownOwner.Rollbacks,Is.Zero);
        }

        [TestCase("proof")]
        [TestCase("index")]
        [TestCase("generation")]
        [TestCase("start")]
        [TestCase("actor-life")]
        [TestCase("body-radius")]
        [TestCase("retired")]
        [TestCase("committed")]
        [TestCase("bound")]
        [TestCase("own-claim-version")]
        [TestCase("own-claim-owner")]
        [TestCase("own-claim-geometry")]
        [TestCase("external-geometry")]
        public void CanonicalMetadataRevalidationCannotReplaceStrictIdentityOrChangedPhysicalFacts(string change)
        {
            var f=PreparedCanonicalMetadataLeg(out var owner,out var claim,out var stalePermission);
            var resource=change=="proof"?"home":"outward";var index=change=="index"?1:0;var generation=change=="generation"?10:9;
            var actor=change=="actor-life"?new object():f.Actor;var start=change=="start"?P(-.1f):Origin;
            if(change=="committed" || change=="bound")Assert.That(f.Coordinator.TryCommit(stalePermission),Is.True);
            if(change=="bound")Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(71,9)),Is.True);
            if(change=="retired")f.Coordinator.Retire(f.Key);
            if(change=="own-claim-version")owner.ExternalChange();
            var canonical=owner;object release=claim.ReleaseObligation;
            if(change=="own-claim-owner")
            {canonical=new CanonicalOwner();Assert.That(canonical.Prepare().TryApply(out var replacementReceipt),Is.True);release=replacementReceipt;}
            var currentClaim=new TrafficParkingFact(f.Key,canonical,canonical.Version,claim.ResourceId,change=="own-claim-geometry"?P(-2):claim.Position,claim.Radius,claim.SafetyMargin,claim.BusinessOwner,release);
            var parking=new List<TrafficParkingFact>{currentClaim};
            if(change=="external-geometry")
            {
                var other=new CanonicalOwner();Assert.That(other.Prepare().TryApply(out var receipt),Is.True);
                parking.Add(new TrafficParkingFact(Key("canonical-new-obstacle"),other,other.Version,"actual-other-slot",f.End,.4f,businessOwner:other,releaseObligation:receipt));
            }
            var leg=f.Read("Leg");var original=f.Read("Request");var originalDecision=f.Coordinator.GetDecision(f.Key);var accounting=D3CaptureAccounting(f.Coordinator,f.Key);
            var currentPath=((Vector3[])f.Read("CurrentPath")).ToArray();var strictBody=new TrafficBodyFact(f.Key,start,change=="body-radius" ? .5f : .4f,actorLife:actor);
            f.World=World(3,1,new[]{strictBody},parking.ToArray());f.Coordinator.SetSnapshot(f.World);
            var rejected=f.Coordinator.PrepareLeg(f.Journey,resource,index,actor,generation,f.World,start,.05f,f.Frame++);
            Assert.That(rejected.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(rejected.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget),"Protected change cannot enter metadata revalidation");
            Assert.That(f.Read("Leg"),Is.SameAs(leg));Assert.That(f.Read("Request"),Is.SameAs(original));Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(originalDecision));
            D3AssertAccounting(f.Coordinator,f.Key,accounting);CollectionAssert.AreEqual(currentPath,(Vector3[])f.Read("CurrentPath"));
            if(change=="committed" || change=="bound")Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.True,"Rejecting reprepare must not rewrite an already issued right");
            else
            {Assert.That(f.Coordinator.TryCommit(stalePermission),Is.False,"Changed/retired source must not commit the stale permit");Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);}
            Assert.That(owner.Applies,Is.EqualTo(1));Assert.That(owner.Rollbacks,Is.Zero);
        }

        [TestCase(false)]
        [TestCase(true)]
        public void RestoredPreparedLegRevalidatesBodyOnlyChangeWithinSameNativeAttempt(bool blockingBody)
        {
            var f=new LegFixture();var other=Key("changed-body");var otherLife=new object();
            TrafficWorldSnapshot Bodies(long version,Vector3 otherPosition,bool enabled=true)=>World(1,version,new[]{
                new TrafficBodyFact(f.Key,Origin,.4f,enabled:enabled,actorLife:f.Actor),
                new TrafficBodyFact(other,otherPosition,.4f,actorLife:otherLife)});
            object LegField(string name)=>f.Read("Leg").GetType().GetField(name,
                System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(f.Read("Leg"));
            var originalEnds=f.Outward.LegEnds.ToArray();var originalPath=f.Outward.ExpandedPath.ToArray();
            Assert.That(f.Prepare(generation:2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));f.CommitPrepared();
            var oldStamp=new TrafficNativeStamp(71,2);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,oldStamp),Is.True);
            var beforeSuspendQueries=f.Coordinator.QueriesConsumed(f.Key);
            f.World=Bodies(2,P(-8,-8),false);f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Coordinator.SuspendLeg(f.Key,f.Actor,oldStamp,SuspendedResult(f.Key),7),Is.True);
            f.World=Bodies(3,P(-8,-8));f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(generation:3).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(f.Frame++);
            var stalePermission=f.Coordinator.GetDecision(f.Key);
            Assert.That(stalePermission.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Read("Prepared"),Is.True);Assert.That(f.Read("Active"),Is.False);
            Assert.That(LegField("Committed"),Is.False);Assert.That(LegField("Bound"),Is.False);
            Assert.That(LegField("Suspended"),Is.False);Assert.That(LegField("Completed"),Is.False);
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(beforeSuspendQueries+1));
            var selectedJourney=((Vector3[])f.Read("Journey")).ToArray();

            // Only another body's facts change after ready-batch preparation, before ordinary consumer polling.
            // 已准备但尚未发出的同一腿，只更新另一真实身体；不改 source、自己位置或 canonical version。
            f.World=Bodies(4,blockingBody?f.End:P(-7,-8));f.Coordinator.SetSnapshot(f.World);
            var pending=f.Prepare(generation:3);
            Assert.That(pending.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),
                "PRODUCT: changed body metadata must revalidate the unissued candidate, not cancel the restored task");
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(beforeSuspendQueries+1),"Polling cannot query Native");
            Assert.That(f.Coordinator.TryCommit(stalePermission),Is.False,"The old prepared decision cannot authorize movement");
            Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,3),Is.False);
            CollectionAssert.AreEqual(selectedJourney,(Vector3[])f.Read("Journey"));
            f.Coordinator.ProcessReady(f.Frame++);var current=f.Coordinator.GetDecision(f.Key);
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(beforeSuspendQueries+1),
                "Unchanged start and retained Native proof require body checks, not another Native query");
            Assert.That(f.Read("JourneyPermit"),Is.SameAs(f.Journey));Assert.That(f.Read("FirstFrame"),Is.EqualTo(1));
            Assert.That(current.RequestSequence,Is.EqualTo(f.Journey.RequestSequence));
            Assert.That(current.AcquiredSequence,Is.EqualTo(f.Journey.AcquiredSequence));
            Assert.That(LegField("Generation"),Is.EqualTo(3));Assert.That(LegField("Index"),Is.EqualTo(0));
            Assert.That(LegField("Proof"),Is.SameAs(f.Outward));Assert.That(f.Read("Suspensions"),Is.EqualTo(1));
            CollectionAssert.AreEqual(originalEnds,f.Outward.LegEnds);CollectionAssert.AreEqual(originalPath,f.Outward.ExpandedPath);
            if(blockingBody)
            {
                Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
                Assert.That(current.Blockers.Any(b=>b.Owner.Equals(other)),Is.True,"Current physical body must prevent issue");
                Assert.That(f.Coordinator.TryCommit(current),Is.False);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(72,3)),Is.False);
                f.World=Bodies(5,P(-7,-8));f.Coordinator.SetSnapshot(f.World);f.Coordinator.NotifyChanged(other,"body");
                var retry=f.Prepare(generation:3);
                Assert.That(retry.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(retry.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
                f.Coordinator.ProcessReady(f.Frame++);Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(current),"Real terminal failure cannot revive after body changes");
                Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(beforeSuspendQueries+1));return;
            }
            Assert.That(current.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Coordinator.TryCommit(current),Is.True);
            var resumedStamp=new TrafficNativeStamp(72,3);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,resumedStamp),Is.True);
            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,oldStamp,f.End),Is.False);
