            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,resumedStamp,f.End),Is.True,"Only the matching endpoint completion consumes the resumed leg");
            Assert.That(LegField("Completed"),Is.True);Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,resumedStamp,f.End),Is.False);
            Assert.That(((Vector3[])f.Read("Journey")).Contains(P(8)),Is.True,"Original selected home remains protected after completion");
        }

