        [Test] public void SuspendedLegRejectsOldCallbacksAndAllowsOnlyOneRecoveryPerPhase()
        {
            var f=new LegFixture();f.Start();var stamp=new TrafficNativeStamp(71,1);
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.True);
            Assert.That(f.Coordinator.SuspendLeg(f.Key,f.Actor,stamp,SuspendedResult(f.Key),7),Is.True);
            Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.False);
            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,stamp,f.End),Is.False,"Cancelled Native request cannot later consume Arrived");
            Assert.That(f.Coordinator.SuspendLeg(f.Key,f.Actor,stamp,SuspendedResult(f.Key),7),Is.False);
            Assert.That(f.Prepare(generation:1).Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget),"Recovery needs a new Native leg generation");
            Assert.That(f.Prepare(generation:2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));f.CommitPrepared();
            var resumedStamp=new TrafficNativeStamp(72,2);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,resumedStamp),Is.True);
            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,stamp,f.End),Is.False);
            Assert.That(f.Coordinator.SuspendLeg(f.Key,f.Actor,resumedStamp,SuspendedResult(f.Key,72),7),Is.False,
                "Changing leg/request identity cannot reset the original one-suspension recovery limit");
            Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.True);Assert.That((Vector3[])f.Read("CurrentPath"),Is.Not.Empty);
        }

