        [Test] public void CommittedCoincidentSinglePointProofRequiresStrictNativeCompletion()
        {
            var key=Key("single-point-work");var actor=new object();
            var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});
            var coordinator=Coordinator(world,query:(from,to)=>new[]{Origin});
            var source=Grant(coordinator,Request(key,Origin,Origin,world));
            var proof=source.ProofRoutes.Single();
            CollectionAssert.AreEqual(new[]{Origin},proof.ExpandedPath);
            CollectionAssert.AreEqual(new[]{0},proof.LegEnds);
            var queries=coordinator.QueriesConsumed(key);
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,1,world,Origin,.05f,2).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"A real committed coincident Native proof has a zero-index leg endpoint");
            Assert.That(coordinator.CanIssueLeg(key,actor,1),Is.False);
            coordinator.ProcessReady(2);var leg=coordinator.GetDecision(key);
            Assert.That(leg.Kind,Is.EqualTo(TrafficDecisionKind.Granted),leg.Reason);
            CollectionAssert.AreEqual(new[]{Origin},leg.ProofRoutes.Single().ExpandedPath,"Do not manufacture duplicate path points");
            Assert.That(coordinator.TryCommit(leg),Is.True);
            Assert.That(coordinator.BindLeg(key,actor,new TrafficNativeStamp(91,1)),Is.True);
            Assert.That(coordinator.HasActiveGrant(key),Is.True,"Permission and binding are not Arrived");
            Assert.That(coordinator.CompleteLeg(key,actor,new TrafficNativeStamp(91,1),P(1)),Is.False);
            // Model the actual callback boundary; this Edit test does not claim Unity Native arrival.
            Assert.That(coordinator.CompleteLeg(key,actor,new TrafficNativeStamp(91,1),Origin),Is.True);
            Assert.That(coordinator.CompleteLeg(key,actor,new TrafficNativeStamp(91,1),Origin),Is.False);
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries));
            Assert.That(leg.RequestSequence,Is.EqualTo(source.RequestSequence));
            Assert.That(leg.AcquiredSequence,Is.EqualTo(source.AcquiredSequence));
        }

