        [TestCase(0f,.0125f,0f)]
        [TestCase(.06f,0f,.03f)]
        public void ProjectedSinglePointProofUsesOriginalArrivalTolerance(float goalX,float cornerY,float cornerX)
        {
            var key=Key("projected-singleton");var actor=new object();var goal=P(goalX);var corner=new Vector3(cornerX,cornerY,0);
            var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});
            var coordinator=Coordinator(world,query:(from,to)=>new[]{corner});
            var source=Grant(coordinator,Request(key,Origin,goal,world));var original=source.ProofRoutes.Single();
            Assert.That(Vector3.Distance(Origin,goal),Is.LessThanOrEqualTo(.08f));
            Assert.That(Vector3.Distance(Origin,corner),Is.LessThanOrEqualTo(.08f));
            Assert.That(Vector3.Distance(goal,corner),Is.LessThanOrEqualTo(.08f));
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,1,world,Origin,.08f,2).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);var prepared=coordinator.GetDecision(key);
            Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),prepared.Reason);
            CollectionAssert.AreEqual(new[]{corner},prepared.ProofRoutes.Single().ExpandedPath);
            CollectionAssert.AreEqual(new[]{corner},original.ExpandedPath);
            CollectionAssert.AreEqual(new[]{0},original.LegEnds);
            Assert.That(coordinator.TryCommit(prepared),Is.True);
            Assert.That(coordinator.BindLeg(key,actor,new TrafficNativeStamp(101,1)),Is.True);
            Assert.That(coordinator.HasActiveGrant(key),Is.True,"Projected geometry is not an arrival event");
            Assert.That(coordinator.CompleteLeg(key,actor,new TrafficNativeStamp(101,1),goal),Is.True);
            Assert.That(prepared.AcquiredSequence,Is.EqualTo(source.AcquiredSequence));
        }

