        [TestCase(.0125f,true)]
        [TestCase(.081f,false)]
        public void ActualStartRequeryChecksProjectedMultiPointEndpointsAgainstOriginalTolerance(float projection,bool compatible)
        {
            var key=Key("projected-current-leg");var actor=new object();var actual=P(0,-.1f);var goal=P(4);
            var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});
            var coordinator=Coordinator(world,query:(from,to)=>from==Origin?new[]{from,to}:new[]{from+Vector3.up*projection,to+Vector3.up*projection});
            var source=Grant(coordinator,Request(key,Origin,goal,world));var original=source.ProofRoutes.Single();
            var queries=coordinator.QueriesConsumed(key);
            world=World(1,2,new[]{new TrafficBodyFact(key,actual,.4f,actorLife:actor)});coordinator.SetSnapshot(world);
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,1,world,actual,.08f,2).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);var result=coordinator.GetDecision(key);
            Assert.That(result.Kind,Is.EqualTo(compatible?TrafficDecisionKind.Granted:TrafficDecisionKind.PlanningFailed),result.Reason);
            Assert.That(coordinator.QueriesConsumed(key),Is.EqualTo(queries+1));
            CollectionAssert.AreEqual(new[]{Origin,goal},original.ExpandedPath);
            CollectionAssert.AreEqual(new[]{1},original.LegEnds);
            if(!compatible){Assert.That(coordinator.BindLeg(key,actor,new TrafficNativeStamp(101,1)),Is.False);return;}
            CollectionAssert.AreEqual(new[]{actual+Vector3.up*projection,goal+Vector3.up*projection},result.ProofRoutes.Single().ExpandedPath,
                "Connector guards must not be represented as Native corners");
            Assert.That(coordinator.TryCommit(result),Is.True);
            Assert.That(result.RequestSequence,Is.EqualTo(source.RequestSequence));
            Assert.That(result.AcquiredSequence,Is.EqualTo(source.AcquiredSequence));
        }

        [Test] public void ProjectedCurrentLegProtectsActualStartToNativeCornerConnector()
        {
            var key=Key("connector-leg");var actor=new object();var blocker=Key("connector-body");
            var actual=P(0,-.1f);var goal=P(4);var corner=actual+Vector3.right*.07f;var body=actual-Vector3.right*.75f;
            var world=World(actors:new[]{new TrafficBodyFact(key,Origin,.4f,actorLife:actor)});
            var coordinator=Coordinator(world,query:(from,to)=>from==Origin?new[]{from,to}:new[]{corner,to});
            var source=Grant(coordinator,Request(key,Origin,goal,world));
            Assert.That(Vector3.Distance(body,corner),Is.GreaterThan(.8f));
            Assert.That(Vector3.Distance(body,actual),Is.LessThan(.8f));
            Assert.That(Vector3.Distance(corner,actual),Is.LessThan(.08f));
            world=World(1,2,new[]{new TrafficBodyFact(key,actual,.4f,actorLife:actor),new TrafficBodyFact(blocker,body,.4f)});
            coordinator.SetSnapshot(world);
            Assert.That(coordinator.PrepareLeg(source,"lane",0,actor,1,world,actual,.08f,2).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            coordinator.ProcessReady(2);var result=coordinator.GetDecision(key);
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(result.Blockers.Any(b=>b.Owner.Equals(blocker) && b.Proof=="current-leg-body"),Is.True,
                "The actual start connector is occupied although every original Native corner/segment is clear");
            Assert.That(coordinator.BindLeg(key,actor,new TrafficNativeStamp(101,1)),Is.False);
        }

        [TestCase(false)] [TestCase(true)]
        public void CommittedLegProvenanceReturnsExactPublishedStrictSnapshot(bool bound)
        {
            var f=new HandoffFixture();var pending=f.Begin();var successor=f.Successor();
            var planned=((TrafficRequest)f.Read(successor.Intent,"JourneyRequest")).Snapshot;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            var actual=((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot;
            Assert.That(actual,Is.SameAs(f.World));Assert.That(actual,Is.Not.SameAs(planned));
            Assert.That(planned.Parking.Single().Owner,Is.EqualTo(f.Owner));Assert.That(actual.Parking.Single().Owner,Is.EqualTo(successor.Intent));
            Assert.That(f.ReadLeg(successor.Intent,"Committed"),Is.True);Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True);
            if(bound)
            {
                Assert.That(f.Coordinator.BindLeg(successor.Intent,f.Actor,new TrafficNativeStamp(91,5)),Is.True);
                // Normal Native progress changes body facts, not the bound leg's historical provenance.
                // 实际身体移动不重发权限，也不改写已bound leg原始strict快照。
                f.World=World(actual.Version,actual.BodyVersion+1,actual.Bodies.Select(b=>new TrafficBodyFact(b.Owner,
                    b.Position+Vector3.right*.1f,b.Radius,b.Enabled,b.IndependentlyProgressing,b.RemainingSeconds,b.SafetyMargin,b.ActorLife)).ToArray(),
                    actual.Parking.ToArray());f.Coordinator.SetSnapshot(f.World);
                Assert.That(f.World.BodyVersion,Is.GreaterThan(actual.BodyVersion));Assert.That(f.World,Is.Not.SameAs(actual));
            }
            Assert.That(f.ReadLeg(successor.Intent,"Bound"),Is.EqualTo(bound));
            var leg=f.Read(successor.Intent,"Leg");var request=f.Read(successor.Intent,"Request");var queries=f.Coordinator.QueriesConsumed(successor.Intent);
            Assert.That(f.Coordinator.TryGetCommittedLegProvenance(successor.Intent,f.Actor,5,out var source,out var snapshot),Is.True,
                "PRODUCT: both pre-Native unbound and already-bound current committed legs expose only their authenticated original references");
            Assert.That(source,Is.SameAs(f.ExpectedContinuationSource));Assert.That(source,Is.SameAs(f.Read(successor.Intent,"JourneyPermit")));
            Assert.That(snapshot,Is.SameAs(actual));Assert.That(snapshot.Parking.Single(),Is.SameAs(actual.Parking.Single()));
            Assert.That(snapshot,Is.Not.SameAs(planned));Assert.That(f.Read(successor.Intent,"Leg"),Is.SameAs(leg));
            Assert.That(f.Read(successor.Intent,"Request"),Is.SameAs(request));Assert.That(f.ReadLeg(successor.Intent,"Bound"),Is.EqualTo(bound));
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.EqualTo(!bound),"Reading provenance never grants a second Native issue");
            Assert.That(f.Coordinator.QueriesConsumed(successor.Intent),Is.EqualTo(queries));
        }

        [TestCase("source-only")] [TestCase("prepared")] [TestCase("wrong-life")]
        [TestCase("wrong-generation")] [TestCase("wrong-context")] [TestCase("foreign-source-key")]
        public void CommittedLegProvenanceRejectsMissingCommitOrForeignIdentity(string refusal)
        {
            var f=new LegFixture();var key=f.Key;var actor=f.Actor;var generation=1;
            if(refusal=="prepared")
            {
                Assert.That(f.Prepare().Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));f.Coordinator.ProcessReady(f.Frame++);
                Assert.That(f.Coordinator.GetDecision(f.Key).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(MultiClaimFixture.Field(f.Read("Leg"),"Committed"),Is.False);
            }
            else if(refusal!="source-only")
            { f.Start();Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(71,1)),Is.True); }
            else { Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.True);Assert.That(f.Read("Leg"),Is.Null); }
            if(refusal=="wrong-life")actor=new object();
            if(refusal=="wrong-generation")generation=2;
            if(refusal=="wrong-context")key=new TrafficIntentKey(f.Key.Session,f.Key.Epoch,f.Key.ActorId,f.Key.IntentId,f.Key.Generation,f.Key.LayoutRevision,"order.other");
            if(refusal=="foreign-source-key")
            {
                key=Key(f.Key.ActorId,"other-committed-source",2);
                var other=Grant(f.Coordinator,Request(key,Origin,P(6),f.World,frame:f.Frame++,resource:"other-source"));
                Assert.That(other,Is.Not.SameAs(f.Journey));Assert.That(f.Coordinator.TryGetCommittedJourney(key,out var committed),Is.True);
                Assert.That(committed,Is.SameAs(other),"FIXTURE: another real committed source cannot borrow the original strict leg");
            }
            var decision=f.Coordinator.GetDecision(f.Key);var queries=f.Coordinator.QueriesConsumed(f.Key);var request=f.Read("Request");
            Assert.That(f.Coordinator.TryGetCommittedLegProvenance(key,actor,generation,out var source,out var snapshot),Is.False);
            Assert.That(source,Is.Null);Assert.That(snapshot,Is.Null);Assert.That(f.Read("Request"),Is.SameAs(request));
            Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(decision));Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries));
        }

        [TestCase("retired")] [TestCase("completed")] [TestCase("suspended")] [TestCase("stale-snapshot")]
        public void CommittedLegProvenanceRejectsNoLongerCurrentLeg(string lifecycle)
        {
            var f=new LegFixture();f.Start();var stamp=new TrafficNativeStamp(71,1);
            if(lifecycle!="stale-snapshot")Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,stamp),Is.True);
            else Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,1),Is.True);
            if(lifecycle=="retired")f.Coordinator.Retire(f.Key);
            else if(lifecycle=="completed")
            {
                f.World=World(f.World.Version,f.World.BodyVersion+1,new[]{new TrafficBodyFact(f.Key,f.End,.4f,actorLife:f.Actor)},f.World.Parking.ToArray());
                f.Coordinator.SetSnapshot(f.World);Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,stamp,f.End),Is.True);
                Assert.That(MultiClaimFixture.Field(f.Read("Leg"),"Completed"),Is.True);
            }
            else if(lifecycle=="suspended")
            {
                var result=new MovementResult(71,f.Key.ActorId,MovementStatus.LayoutChanged,NavigationFailure.LayoutUnavailable,
                    NavigationFailure.None,NavigationFailure.None,Origin,0);
                Assert.That(f.Coordinator.SuspendLeg(f.Key,f.Actor,stamp,result,f.Key.LayoutRevision),Is.True);
                Assert.That(MultiClaimFixture.Field(f.Read("Leg"),"Suspended"),Is.True);
            }
            else
            {
                f.World=World(f.World.Version+1,f.World.BodyVersion,f.World.Bodies.ToArray(),f.World.Parking.ToArray());f.Coordinator.SetSnapshot(f.World);
                Assert.That(((TrafficRequest)f.Read("Request")).Snapshot,Is.Not.SameAs(f.World));
                Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,1),Is.False,"An unbound stale permit has no current issue authority");
            }
            var request=f.Read("Request");var decision=f.Coordinator.GetDecision(f.Key);var queries=f.Coordinator.QueriesConsumed(f.Key);
            Assert.That(f.Coordinator.TryGetCommittedLegProvenance(f.Key,f.Actor,1,out var source,out var snapshot),Is.False);
            Assert.That(source,Is.Null);Assert.That(snapshot,Is.Null);Assert.That(f.Read("Request"),Is.SameAs(request));
            Assert.That(f.Coordinator.GetDecision(f.Key),Is.SameAs(decision));Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries));
        }

        [Test] public void CommittedLegProvenanceReadPreservesFrozenWaiterAndOriginalBudgets()
        {
            var f=new HandoffFixture();var request=f.Read(f.Owner,"Request");var waiter=f.Coordinator.GetDecision(f.Waiter);
            var waiterRequest=f.Read(f.Waiter,"Request");var frozen=f.Frozen(f.Waiter).ToArray();var remaining=f.Read(f.Waiter,"WaitRemaining");
            var age=f.Read(f.Waiter,"FirstFrame");var ownerQueries=f.Coordinator.QueriesConsumed(f.Owner);var waiterQueries=f.Coordinator.QueriesConsumed(f.Waiter);
            var stamp=f.ReadLeg(f.Owner,"Stamp");var leg=f.Read(f.Owner,"Leg");
            Assert.That(f.SourceSnapshot.Parking,Is.Empty);Assert.That(((TrafficRequest)request).Snapshot.Parking.Single(),Is.SameAs(f.OriginalClaim));
            for(var read=0;read<2;read++)
            {
                Assert.That(f.Coordinator.TryGetCommittedLegProvenance(f.Owner,f.Actor,4,out var source,out var snapshot),Is.True);
                Assert.That(source,Is.SameAs(f.Source));Assert.That(snapshot,Is.SameAs(((TrafficRequest)request).Snapshot));
                Assert.That(snapshot.Parking.Single(),Is.SameAs(f.OriginalClaim));Assert.That(snapshot,Is.Not.SameAs(f.SourceSnapshot));
            }
            Assert.That(f.Read(f.Owner,"Request"),Is.SameAs(request));Assert.That(f.Read(f.Owner,"Leg"),Is.SameAs(leg));Assert.That(f.ReadLeg(f.Owner,"Stamp"),Is.EqualTo(stamp));
            Assert.That(f.Coordinator.HasActiveGrant(f.Owner),Is.True);Assert.That(f.Coordinator.DrainReady(),Is.Empty);
            Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(waiter));Assert.That(f.Read(f.Waiter,"Request"),Is.SameAs(waiterRequest));
            CollectionAssert.AreEquivalent(frozen,f.Frozen(f.Waiter));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(remaining));
            Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(age));Assert.That(f.Coordinator.QueriesConsumed(f.Owner),Is.EqualTo(ownerQueries));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));
        }

        // Pure coordinator contract fixture: a bounded planner really constructs LegEnds around an obstacle.
        // 这里只模拟 Native adapter 的确定性路径输入，不冒称 Unity Native 实际到站证据。
        // Public-Core retained leg enters a real finite wait; reflection below only reads identity/accounting.
        // 真实公开 Core 建立未发腿等候；不写 Entry/Leg/许可，不伪造 Native 结果。
        private static LegFixture FastPendingUnissuedLeg(out TrafficIntentKey blocker,out object blockerLife,
            out CanonicalOwner ownOwner,out TrafficParkingFact ownClaim,FastPendingClaimMarker marker=null)
        {
            var f=new LegFixture();blocker=Key("fast-leg-finite-owner");blockerLife=new object();
            ownOwner=new CanonicalOwner();Assert.That(ownOwner.Prepare().TryApply(out var receipt),Is.True);
            if(marker!=null){marker.Owner=ownOwner;marker.Version=ownOwner.Version;}
            ownClaim=new TrafficParkingFact(f.Key,ownOwner,ownOwner.Version,"fast-own-slot",Origin,.4f,
                businessOwner:f.Journey,releaseObligation:receipt,semanticCheckpoint:marker);
            f.World=World(2,2,new[]{new TrafficBodyFact(f.Key,Origin,.4f,actorLife:f.Actor),
                new TrafficBodyFact(blocker,f.End,.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:blockerLife)},new[]{ownClaim});
            f.Coordinator.SetSnapshot(f.World);
            Assert.That(f.Prepare(generation:9).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(f.Frame++);var waiting=f.Coordinator.GetDecision(f.Key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: genuine finite-owner wait before the behavior under test");
            var expectedBlocker=blocker;
            Assert.That(waiting.Blockers.Any(b=>b.Owner.Equals(expectedBlocker)&&b.ResourceId=="body"),Is.True);
            Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Queued"),Is.False);Assert.That(f.Read("Active"),Is.False);
            foreach(var field in new[]{"Committed","Bound","Completed","Suspended","ReprepareAllowed"})
                Assert.That(D3ReadField(f.Read("Leg"),field),Is.EqualTo(false),field);
            Assert.That(D3ReadField(f.Read("Leg"),"Stamp"),Is.EqualTo(default(TrafficNativeStamp)));
            Assert.That(f.Read("JourneyPermit"),Is.SameAs(f.Journey));return f;
        }

        [TestCase(false,false)]
        [TestCase(false,true)]
        [TestCase(true,false)]
        [TestCase(true,true)]
        public void FastUnissuedLegPollingRetainsOriginalWaitAcrossExternalSnapshotDrift(bool queued,bool canonicalMetadata)
        {
            var f=FastPendingUnissuedLeg(out var blocker,out var life,out var owner,out var claim);
            f.Coordinator.Tick(.25f,false);var waiting=f.Coordinator.GetDecision(f.Key);
            if(queued)f.Coordinator.NotifyChanged(blocker,"body");
            Assert.That(f.Read("Queued"),Is.EqualTo(queued));
            f.World=World(canonicalMetadata?3:2,3,new[]{new TrafficBodyFact(f.Key,Origin,.4f,actorLife:f.Actor),
                new TrafficBodyFact(blocker,f.End+P(.01f),.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:life)},new[]{claim});
            f.Coordinator.SetSnapshot(f.World);
            var identityNames=new[]{"Request","Leg","JourneyPermit","JourneyRequest","FrozenOwners","FrozenResources","WaitingBlockers","Journey","CurrentPath"};
            var identities=identityNames.ToDictionary(name=>name,name=>f.Read(name));
            var entries=(System.Collections.IDictionary)D3ReadField(f.Coordinator,"entries");var originalEntry=entries[f.Key];
            var accounting=D3CaptureAccounting(f.Coordinator,f.Key);var queries=f.Coordinator.QueriesThisFrame;
            for(var poll=0;poll<3;poll++)
            {
                Assert.That(RequeuePreparedLeg(f.Coordinator,f.Journey,"outward",0,f.Actor,9,f.World,Origin,out _),Is.EqualTo("NoOp"),
                    "This is a waiting/queued original candidate, never a second prepared permission");
                var result=f.Prepare(generation:9);
                Assert.That(result,Is.SameAs(waiting),"PRODUCT RED: exact authentic unissued leg must retain its finite wait, not become previous-leg-not-completed");
                Assert.That(entries[f.Key],Is.SameAs(originalEntry));
                foreach(var pair in identities)Assert.That(f.Read(pair.Key),Is.SameAs(pair.Value),"Polling must not replace "+pair.Key);
                D3AssertAccounting(f.Coordinator,f.Key,accounting);Assert.That(f.Coordinator.QueriesThisFrame,Is.EqualTo(queries));
                Assert.That(f.Read("Queued"),Is.EqualTo(queued));Assert.That(f.Read("Prepared"),Is.False);Assert.That(f.Read("Active"),Is.False);
                Assert.That(f.Coordinator.TryCommit(result),Is.False);Assert.That(f.Coordinator.CanIssueLeg(f.Key,f.Actor,9),Is.False);
            }
            // Only real release+Notify may wake the original finite wait; normal batch rechecks full current facts.
            // 真正阻挡者移动后沿原 Notify/ready batch 醒来，保留腿/原余程/原预算，不由polling放行。
            f.World=World(f.World.Version,4,new[]{new TrafficBodyFact(f.Key,Origin,.4f,actorLife:f.Actor),
                new TrafficBodyFact(blocker,P(-20,-20),.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:life)},new[]{claim});
            f.Coordinator.SetSnapshot(f.World);f.Coordinator.NotifyChanged(blocker,"body");
            f.Coordinator.ProcessReady(f.Frame++);var granted=f.Coordinator.GetDecision(f.Key);
            Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(granted,Is.Not.SameAs(waiting));
            Assert.That(f.Read("Leg"),Is.SameAs(identities["Leg"]));Assert.That(f.Read("JourneyPermit"),Is.SameAs(f.Journey));
            D3AssertAccounting(f.Coordinator,f.Key,accounting);
            Assert.That(f.Coordinator.TryCommit(granted),Is.True);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(901,9)),Is.True);
            Assert.That(f.Coordinator.CompleteLeg(f.Key,f.Actor,new TrafficNativeStamp(901,9),f.End),Is.True);
            Assert.That(owner.Applies,Is.EqualTo(1));Assert.That(owner.Rollbacks,Is.Zero);
        }

