        [Test] public void FastUnissuedLegWaitRejectsReentrantClaimRetirementWithoutRestoringOldObjects()
        {
            var marker=new FastPendingClaimMarker();var f=FastPendingUnissuedLeg(out var blocker,out var life,out _,out var claim,marker);
            f.World=World(2,3,new[]{new TrafficBodyFact(f.Key,Origin,.4f,actorLife:f.Actor),
                new TrafficBodyFact(blocker,f.End+P(.01f),.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:life)},new[]{claim});
            f.Coordinator.SetSnapshot(f.World);var queries=f.Coordinator.QueriesConsumed(f.Key);
            marker.DuringCompare=()=>f.Coordinator.Retire(f.Key);
            var result=f.Prepare(generation:9);
            Assert.That(marker.Calls,Is.GreaterThan(0),"PRODUCT: original own-claim checkpoint must actually be consulted");
            Assert.That(result.Kind,Is.EqualTo(TrafficDecisionKind.StaleContext));Assert.That(f.Coordinator.GetDecision(f.Key).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            Assert.That(f.Read("Retired"),Is.True);Assert.That(f.Read("Leg"),Is.Null);Assert.That(f.Read("Request"),Is.Null);
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries));Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.False);
        }
        private sealed class FastPendingClaimMarker:ITrafficClaimCheckpoint
        {
            internal object Owner;internal long Version;internal Action DuringCompare;internal int Calls;
            public object CanonicalOwner=>Owner;public string ResourceId=>"fast-own-slot";public long CapturedOwnerVersion=>Version;
            public bool IsSameCurrentClaim(ITrafficClaimCheckpoint current)
            {Calls++;DuringCompare?.Invoke();return ReferenceEquals(this,current);}
        }

        private sealed class LegFixture
        {
            internal readonly ServiceTrafficCoordinator Coordinator;
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("leg-actor");
            internal readonly object Actor=new object();
            internal TrafficWorldSnapshot World;
            internal readonly TrafficDecision Journey;
            internal readonly TrafficRouteProof Outward,Home;
            internal int Frame=1;
            internal Vector3 End=>Outward.Waypoints[0];
            internal LegFixture(Func<Vector3,Vector3,IReadOnlyList<Vector3>> query=null)
            {
                World=ServiceTrafficCoordinatorTests.World(actors:new[]{new TrafficBodyFact(Key,Origin,.4f,actorLife:Actor)});
                Coordinator=ServiceTrafficCoordinatorTests.Coordinator(World,query:query);
                var requirements=new[]{
                    new TrafficRouteRequirement("outward",Origin,P(4),.8f,new[]{P(2)},selectedJourney:true,avoidProposedParking:false),
                    new TrafficRouteRequirement("home",P(4),P(8),.8f,selectedJourney:true,avoidProposedParking:false),
                    new TrafficRouteRequirement("capability",P(20),P(24),.8f,avoidProposedParking:false)};
                Coordinator.EvaluateParking(Request(Key,Origin,Origin,World,requirements:requirements,resource:"canonical-parking"));
                for(var i=0;i<100;i++)
                {
                    Coordinator.ProcessReady(Frame++);
                    if(Coordinator.GetDecision(Key).Kind!=TrafficDecisionKind.DeferredByBudget)break;
                }
                Journey=Coordinator.GetDecision(Key);
                Assert.That(Journey.Kind,Is.EqualTo(TrafficDecisionKind.Granted),Journey.Reason);
                Assert.That(Coordinator.TryCommit(Journey),Is.True);
                Outward=Journey.ProofRoutes.Single(p=>p.ResourceId=="outward");
                Home=Journey.ProofRoutes.Single(p=>p.ResourceId=="home");
                Assert.That(Outward.LegEnds.Count,Is.GreaterThan(1),"Fixture premise: canonical retained multi-leg proof");
            }
            internal TrafficDecision Prepare(int index=0,int generation=1,Vector3? start=null,float arrivalTolerance=.05f)
            {
                if(index>0)
                {
                    World=ServiceTrafficCoordinatorTests.World(1,World.BodyVersion+1,
                        new[]{new TrafficBodyFact(Key,start??Origin,.4f,actorLife:Actor)});
                    Coordinator.SetSnapshot(World);
                }
                return Coordinator.PrepareLeg(Journey,"outward",index,Actor,generation,World,start??Origin,arrivalTolerance,Frame);
            }
            internal TrafficDecision CommitPrepared()
            {
                Coordinator.ProcessReady(Frame++);var decision=Coordinator.GetDecision(Key);
                Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted),decision.Reason);
                Assert.That(Coordinator.TryCommit(decision),Is.True,"Current leg needs its own committed permission");return decision;
            }
            internal void Start()
            {
                Assert.That(Prepare().Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));CommitPrepared();
            }
            internal object Read(string name)
            {
                const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
                var entries=(System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("entries",flags).GetValue(Coordinator);
                var entry=entries[Key];return entry.GetType().GetField(name,flags).GetValue(entry);
            }
        }

        [TestCase(0)]
        [TestCase(1)]
        public void CompletedMilestoneHoldsExactWakeUntilCommittedFiniteSuccessor(int nativeRetryCount)
        {
            var f=new HandoffFixture();var waiterQueries=f.Coordinator.QueriesConsumed(f.Waiter);
            Assert.That(f.SourceSnapshot.Parking,Is.Empty,"Journey planning precedes actual pickup publication");
            Assert.That(((TrafficRequest)f.Read(f.Owner,"Request")).Snapshot.Parking.Single(),Is.SameAs(f.OriginalClaim),
                "Provenance comes from the actual committed strict leg's stored snapshot");
            var pending=f.Begin(nativeRetryCount);
            Assert.That(f.ConfirmCalls,Is.EqualTo(1));Assert.That(f.LegCompleted,Is.True);
            Assert.That(f.Coordinator.HasActiveGrant(f.Owner),Is.False);Assert.That(f.Frozen(f.Waiter),Does.Contain(f.Owner));
            f.Coordinator.NotifyChanged(f.Owner,f.Resource);f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.DrainReady(),Is.Empty,"No visible wake before the handoff is complete");
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));
            var successor=f.Successor();var publications=0;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>
            {
                publications++;Assert.That(f.Frozen(f.Waiter),Does.Contain(successor.Intent));
                Assert.That(f.Frozen(f.Waiter),Has.No.Member(f.Owner));
                Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.True);
                Assert.That(f.Coordinator.GetDecision(f.Owner).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
                f.PublishSuccessor(successor.Intent);
            }),Is.True,"Only the same owned obligation may atomically hand off to a finite committed successor");
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True,
                "The published ownership-only snapshot must leave the same committed strict leg immediately issuable");
            var saved=((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot;
            Assert.That(saved,Is.SameAs(f.World),"Only the actual publisher snapshot may authenticate the next completion");
            var savedClaim=saved.Parking.Single();Assert.That(savedClaim.Owner,Is.EqualTo(successor.Intent));
            Assert.That(savedClaim.BusinessOwner,Is.SameAs(f.Business));Assert.That(savedClaim.ReleaseObligation,Is.SameAs(f.Obligation));
            Assert.That(savedClaim,Is.SameAs(f.World.Parking.Single()));
            Assert.That(publications,Is.EqualTo(1));Assert.That(f.Coordinator.DrainReady(),Does.Contain(f.Waiter));
            f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Blockers.All(b=>b.Owner.Equals(successor.Intent)),Is.True,
                "The woken waiter rechecks the same physical obligation under its verified successor");
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>publications++),Is.False);
            Assert.That(publications,Is.EqualTo(1));Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False);
        }

        [TestCase("other-body-position")]
        [TestCase("canonical-version")]
        public void HandoffPublicationCannotRebindUnrelatedChangedFacts(string change)
        {
            var f=new HandoffFixture();f.IncludeOtherBody();var pending=f.Begin();var successor=f.Successor();
            var before=((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot;
            var queries=f.Coordinator.QueriesConsumed(successor.Intent);var claimVersion=f.Canonical.Version;
