        }

        [Test] public void VerifiedHandoffPreservesWaiterAgeQueriesBudgetAndStartsNewSuccessorAge()
        {
            var f=new HandoffFixture();var phaseAge=f.Read(f.Waiter,"FirstFrame");var sequence=f.Coordinator.GetDecision(f.Waiter).RequestSequence;
            var queries=f.Coordinator.QueriesConsumed(f.Waiter);var originalBudget=(float)f.Read(f.Waiter,"WaitRemaining");
            var pending=f.Begin();f.Coordinator.Tick(2,false);f.Coordinator.Tick(100,true);f.Coordinator.Tick(0,false);
            Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(originalBudget-2));
            var successor=f.Successor();var successorQueries=f.Coordinator.QueriesConsumed(successor.Intent);
            Assert.That(f.Coordinator.TryGetCommittedJourney(successor.Intent,out var source),Is.True);
            Assert.That(source,Is.SameAs(f.ExpectedContinuationSource));
            Assert.That(source.ProofRoutes.Single().ExpandedPath.Count,Is.GreaterThan(1));
            Assert.That(f.Receipt().AuthorizesSuccessor(successor.Intent,source,f.CollectionFrame),Is.True);
            Assert.That(f.Receipt().AuthorizesSuccessor(successor.Intent,source,f.CollectionFrame-1),Is.False);
            Assert.That(f.Read(successor.Intent,"FirstFrame"),Is.EqualTo(f.CollectionFrame));
            Assert.That((int)f.Read(successor.Intent,"FirstFrame"),Is.GreaterThan((int)f.Read(f.Owner,"FirstFrame")));
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(phaseAge));
            Assert.That(f.Coordinator.GetDecision(f.Waiter).RequestSequence,Is.EqualTo(sequence));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(queries));
            Assert.That(f.Coordinator.QueriesConsumed(successor.Intent),Is.EqualTo(successorQueries));
            Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(originalBudget-2));
            Assert.That(f.Coordinator.GetDecision(successor.Intent).AcquiredSequence,Is.GreaterThan(f.Source.AcquiredSequence));
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True);
            Assert.That(f.Coordinator.BindLeg(successor.Intent,f.Actor,new TrafficNativeStamp(91,5)),Is.True,
                "Lawful collection-time source reaches a real kernel strict committed/bound leg");
        }

        [TestCase("life")]
        [TestCase("business")]
        [TestCase("release")]
        [TestCase("canonical")]
        [TestCase("resource")]
        [TestCase("copied-original-claim")]
        [TestCase("matching-forged-claims")]
        public void HandoffRejectsForeignActorLifeBusinessOwnerCanonicalOwnerOrResource(string mismatch)
        {
            var f=new HandoffFixture();var pending=f.Begin();var successor=f.Successor();var receipt=f.Receipt();
            if(mismatch=="life")receipt.ActorLife=new object();
            if(mismatch=="business")receipt.BusinessOwner=new object();
            if(mismatch=="release")receipt.ReleaseObligation=new object();
            if(mismatch=="canonical")receipt.CurrentClaim=f.Claim(canonical:new object());
            if(mismatch=="resource")receipt.CurrentClaim=f.Claim(resource:"unrelated-resource");
            if(mismatch=="copied-original-claim")receipt.OriginalClaim=f.Claim(version:f.OriginalClaim.OwnerVersion);
            if(mismatch=="matching-forged-claims")
            {
                var inventedBusiness=new object();var inventedRelease=new object();var inventedOwner=new object();
                receipt.BusinessOwner=inventedBusiness;receipt.ReleaseObligation=inventedRelease;
                receipt.OriginalClaim=receipt.CurrentClaim=f.Claim(canonical:inventedOwner,business:inventedBusiness,release:inventedRelease);
            }
            // Even an adapter claiming currentness cannot replace provenance already stored with the real leg.
            receipt.TrustCurrent=true;var published=false;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,receipt,publish:()=>published=true),Is.False);
            Assert.That(published,Is.False);Assert.That(f.Frozen(f.Waiter),Does.Contain(f.Owner));
            Assert.That(f.Frozen(f.Waiter),Has.No.Member(successor.Intent));Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.False);
            Assert.That(f.Canonical.Value,Is.EqualTo(2));Assert.That(f.CurrentBodyPresent,Is.True);
        }

        [TestCase("stale-then-fresh")]
        [TestCase("session")]
        [TestCase("epoch")]
        [TestCase("layout")]
        [TestCase("not-collected")]
        [TestCase("wrong-request")]
        [TestCase("wrong-generation")]
        [TestCase("wrong-actor")]
        [TestCase("not-arrived")]
        [TestCase("wrong-endpoint")]
        [TestCase("mutation-failed")]
        [TestCase("mutation-threw")]
        public void HandoffRejectsStaleVersionContextOrUncompletedMilestone(string mismatch)
        {
            var f=new HandoffFixture();
            if(mismatch=="wrong-request" || mismatch=="wrong-generation" || mismatch=="wrong-actor" ||
                mismatch=="not-arrived" || mismatch=="wrong-endpoint")
            {
                f.ArriveBody();var called=false;var stamp=mismatch=="wrong-request"?new TrafficNativeStamp(72,4):
                    mismatch=="wrong-generation"?new TrafficNativeStamp(71,5):f.Stamp;
                var original=new MovementResult(71,mismatch=="wrong-actor"?"foreign-actor":f.Owner.ActorId,
                    mismatch=="not-arrived"?MovementStatus.Failed:MovementStatus.Arrived,NavigationFailure.None,
                    NavigationFailure.None,NavigationFailure.None,mismatch=="wrong-endpoint"?P(20):f.End,0);
                Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,stamp,original,
                    ()=>{called=true;return f.Confirm();},out var rejected),Is.False);
                Assert.That(called,Is.False);Assert.That(rejected,Is.Null);Assert.That(f.LegCompleted,Is.False);return;
            }
            if(mismatch.StartsWith("mutation-",StringComparison.Ordinal))
            {
                f.ArriveBody();var calls=0;
                Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
                {
                    calls++;f.Confirm(); // A true canonical write and Native arrival cannot be fabricated away on later failure.
                    if(mismatch=="mutation-threw")throw new InvalidOperationException("milestone read failed after actual arrival");
                    return null;
                },out var rejected),Is.False);
                Assert.That(calls,Is.EqualTo(1));Assert.That(rejected,Is.Null);Assert.That(f.LegCompleted,Is.True);
                Assert.That(f.Canonical.Value,Is.EqualTo(1));Assert.That(f.CurrentBodyPresent,Is.True);
                Assert.That(f.Coordinator.HasActiveGrant(f.Owner),Is.False);
                Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));return;
            }
            var pending=f.Begin();var successor=f.Successor(contextMismatch:mismatch);var receipt=f.Receipt();
            if(mismatch=="not-collected")f.Canonical.Value=1;
            if(mismatch=="stale-then-fresh")f.Canonical.ExternalChange();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,receipt),Is.False);
            Assert.That(f.Frozen(f.Waiter),Does.Contain(f.Owner));
            if(mismatch=="stale-then-fresh")
            {
                // A fresh projection rechecks the same owned claim; it cannot merely overwrite an old receipt's version.
                var firstFrame=f.Read(successor.Intent,"FirstFrame");
                var sequence=successor.RequestSequence;var acquired=successor.AcquiredSequence;var queries=f.Coordinator.QueriesConsumed(successor.Intent);
                Assert.That(f.Coordinator.TryGetCommittedJourney(successor.Intent,out var originalSource),Is.True);
                var originalProof=originalSource.ProofRoutes.Single(p=>p.ResourceId==f.Resource);
                Assert.That(f.Coordinator.DiscardPrepared(successor.Intent),Is.True);f.Refresh();
                var frame=f.Frame++;
                Assert.That(f.Coordinator.PrepareLeg(originalSource,f.Resource,0,f.Actor,5,f.World,f.End,.05f,frame).Kind,
                    Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"Explicit unissued-leg reprepare retains the acquired primary source");
                f.Coordinator.ProcessReady(frame);successor=f.Coordinator.GetDecision(successor.Intent);
                Assert.That(successor.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Read(successor.Intent,"FirstFrame"),Is.EqualTo(firstFrame));
                Assert.That(f.Coordinator.TryGetCommittedJourney(successor.Intent,out var retainedSource),Is.True);Assert.That(retainedSource,Is.SameAs(originalSource));
                Assert.That(retainedSource.ProofRoutes.Single(p=>p.ResourceId==f.Resource),Is.SameAs(originalProof));
                Assert.That(successor.RequestSequence,Is.EqualTo(sequence));Assert.That(successor.AcquiredSequence,Is.EqualTo(acquired));
                Assert.That(f.Coordinator.QueriesConsumed(successor.Intent),Is.EqualTo(queries),"Same actual pose reuses the retained Native-model proof");
                Assert.That(f.ReadLeg(successor.Intent,"Committed"),Is.False);Assert.That(f.ReadLeg(successor.Intent,"Bound"),Is.False);
                var fresh=f.Receipt();Assert.That(receipt.IsCurrent,Is.False);Assert.That(fresh.IsCurrent,Is.True);
                Assert.That(fresh.CurrentClaim,Is.Not.SameAs(receipt.CurrentClaim));
                Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,fresh,publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            }
        }

        [TestCase("non-finite")]
