        [Test] public void HandoffTransfersOnlyExistingDependenciesAndLeavesTerminalWaitersTerminal()
        {
            var f=new HandoffFixture();var expired=Key("short-waiter");
            f.AddWaiter(expired,1);var pending=f.Begin();f.Coordinator.Tick(2,false);
            var terminal=f.Coordinator.GetDecision(expired);Assert.That(terminal.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            var late=Key("late-waiter");f.AddWaiter(late,8,false);
            Assert.That(f.Coordinator.GetDecision(late).Kind,Is.Not.EqualTo(TrafficDecisionKind.WaitingForTraffic),"Pending handoff cannot recruit another waiter");
            Assert.That(f.Coordinator.GetDecision(late).Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted),"The same actual body/claim still blocks late arrival");
            var successor=f.Successor();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{successor.Intent}));
            Assert.That(f.Coordinator.GetDecision(expired),Is.SameAs(terminal));
            var ready=f.Coordinator.DrainReady();Assert.That(ready,Has.No.Member(expired));Assert.That(ready,Has.No.Member(late));
        }

        [TestCase("deadline")]
        [TestCase("disable")]
        [TestCase("epoch")]
        [TestCase("abort")]
        public void PendingHandoffExpiresWithinOriginalBudgetAndAbortsOnLifecycleChange(string change)
        {
            var f=new HandoffFixture();var pending=f.Begin();var successor=f.Successor();
            var before=(float)f.Read(f.Waiter,"WaitRemaining");f.Coordinator.Tick(100,true);
            Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(before));f.Coordinator.Tick(0,false);
            if(change=="deadline")f.Coordinator.Tick(before+.01f,false);
            if(change=="disable"){f.Enabled=false;f.Refresh();f.Coordinator.NotifyChanged(f.Owner,f.Resource);f.Coordinator.ProcessReady(f.Frame++);}
            if(change=="epoch")f.Coordinator.ResetLayout(2,8,World(9,9));
            if(change=="abort")f.Coordinator.AbortPhaseHandoff(pending,"actual canonical phase cancelled");
            var decision=f.Coordinator.GetDecision(f.Waiter);
            Assert.That(decision.Kind,Is.EqualTo(change=="epoch"?TrafficDecisionKind.Cancelled:TrafficDecisionKind.PlanningFailed));
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt()),Is.False);
            Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False);
            Assert.That(f.Canonical.Value,Is.EqualTo(2),"Aborting navigation continuity does not undo collection");
            if(change!="epoch")Assert.That(f.CurrentBodyPresent,Is.True,"Disabled or blocked physical bodies remain facts");
        }

        [Test] public void CompletedHandoffSurvivesSameRevisionNavUnavailable()
        {
            var f=new HandoffFixture();var pending=f.Begin();var state=f.Read(f.Owner,"PendingHandoff");
            var originalRequest=f.Read(f.Owner,"Request");var waiter=f.Coordinator.GetDecision(f.Waiter);
            var frozen=f.Frozen(f.Waiter).ToArray();var age=f.Read(f.Waiter,"FirstFrame");
            var budget=f.Read(f.Waiter,"WaitRemaining");var queries=f.Coordinator.QueriesConsumed(f.Waiter);
            Assert.That(f.ReadLeg(f.Owner,"Completed"),Is.True);Assert.That(f.Canonical.Value,Is.EqualTo(1));
            f.NavAvailable=false;f.Refresh();var body=f.World.Bodies.Single();
            Assert.That(body.Enabled,Is.False);Assert.That(body.ActorActive,Is.True);Assert.That(body.ActorLife,Is.SameAs(f.Actor));
            Assert.That(body.Owner,Is.EqualTo(f.Owner));Assert.That(f.CurrentBodyPresent,Is.True);
            Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.SameAs(state),"PRODUCT: a completed canonical phase survives a temporary same-revision Nav gap");
            Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(waiter));Assert.That(f.Read(f.Owner,"Request"),Is.SameAs(originalRequest));
            CollectionAssert.AreEquivalent(frozen,f.Frozen(f.Waiter));f.Coordinator.NotifyChanged(f.Owner,f.Resource);
            Assert.That(f.Coordinator.DrainReady(),Is.Empty,"Existing exact frozen edges remain held during the bounded gap");
            Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(age));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(queries));
            f.NavAvailable=true;f.Refresh();var successor=f.Successor();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{successor.Intent}));
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True);
            Assert.That(f.Coordinator.BindLeg(successor.Intent,f.Actor,new TrafficNativeStamp(91,5)),Is.True);
            Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(age));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(budget));
        }

