            Assert.That(source,Is.Null);Assert.That(snapshot,Is.Null);Assert.That(f.Coordinator.BindLeg(f.Key,f.Actor,new TrafficNativeStamp(91,1)),Is.False);
            Assert.That(MultiClaimFixture.Field(f.Read("Leg"),"Bound"),Is.False);

            // An ownership-only publication cannot silently rewrite the independent lifecycle fact.
