            var h=new HandoffFixture();var pending=h.Begin();var successor=h.Successor();
            var preparedSnapshot=((TrafficRequest)h.Read(successor.Intent,"Request")).Snapshot;
            Assert.That(h.Coordinator.TryCommitPhaseHandoff(pending,successor,h.Receipt(),publish:()=>
            {
                h.PublishSuccessor(successor.Intent);var published=h.World;var current=published.Bodies.Single();
                h.World=World(published.Version,published.BodyVersion+1,new[]{new TrafficBodyFact(current.Owner,current.Position,current.Radius,
                    current.Enabled,current.IndependentlyProgressing,current.RemainingSeconds,current.SafetyMargin,current.ActorLife,actorActive:false)},published.Parking.ToArray());
                h.Coordinator.SetSnapshot(h.World);
            }),Is.True);
            Assert.That(h.World.Bodies.Single().Enabled,Is.True);Assert.That(h.World.Bodies.Single().ActorActive,Is.False);
            Assert.That(((TrafficRequest)h.Read(successor.Intent,"Request")).Snapshot,Is.SameAs(preparedSnapshot),
                "PRODUCT: verified ownership-only equality includes ActorActive");
            Assert.That(h.Coordinator.CanIssueLeg(successor.Intent,h.Actor,5),Is.False);
            Assert.That(h.Coordinator.TryGetCommittedLegProvenance(successor.Intent,h.Actor,5,out source,out snapshot),Is.False);
            Assert.That(source,Is.Null);Assert.That(snapshot,Is.Null);Assert.That(h.Coordinator.BindLeg(successor.Intent,h.Actor,new TrafficNativeStamp(92,5)),Is.False);
        }

        [Test] public void NavUnavailablePendingPausePreservesAndThenExhaustsOriginalBudget()
        {
            var f=new HandoffFixture();var pending=f.Begin();var state=f.Read(f.Owner,"PendingHandoff");
            var remaining=(float)MultiClaimFixture.Field(state,"Remaining");var waiterBudget=(float)f.Read(f.Waiter,"WaitRemaining");
            var age=f.Read(f.Owner,"FirstFrame");var waiterAge=f.Read(f.Waiter,"FirstFrame");
            var queries=f.Coordinator.QueriesConsumed(f.Owner);var waiterQueries=f.Coordinator.QueriesConsumed(f.Waiter);
            f.NavAvailable=false;f.Refresh();f.Coordinator.Tick(100,true);
