            Assert.That(MultiClaimFixture.Field(state,"Remaining"),Is.EqualTo(remaining));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(waiterBudget));
            Assert.That(f.Read(f.Owner,"FirstFrame"),Is.EqualTo(age));Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(waiterAge));
            Assert.That(f.Coordinator.QueriesConsumed(f.Owner),Is.EqualTo(queries));Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));
            f.NavAvailable=true;f.Refresh();f.Coordinator.Tick(2,false);
            Assert.That(MultiClaimFixture.Field(state,"Remaining"),Is.EqualTo(remaining-2));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(waiterBudget-2));
            f.Coordinator.Tick(Math.Max(remaining,waiterBudget),false);
            Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.Null);var terminal=f.Coordinator.GetDecision(f.Waiter);
            Assert.That(terminal.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));Assert.That(f.Canonical.Value,Is.EqualTo(1));
            f.NavAvailable=false;f.Refresh();f.NavAvailable=true;f.Refresh();
            Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(terminal));Assert.That(f.Coordinator.DrainReady(),Is.Empty);
            Assert.That(f.Read(f.Owner,"FirstFrame"),Is.EqualTo(age));Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(waiterAge));
            Assert.That(f.Coordinator.QueriesConsumed(f.Owner),Is.EqualTo(queries));Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,null,f.Receipt()),Is.False);
        }

        [Test]
        public void HandoffMigratesOnlyCapturedPickupEligibilityAfterOriginalWaiterBecomesBound()
        {
            // The captured edge is pickup/current-conflict, not body. First and second Native legs remain separate.
