            var stamp=new TrafficNativeStamp(181,6);var f=new HandoffFixture(additionalBody:new TrafficBodyFact(key,start,.4f,actorLife:actor));
            var request=Request(key,start,corner,f.World,frame:f.Frame++,resource:"b-primary",seconds:8,
                requirements:new[]{new TrafficRouteRequirement("b-suffix",corner,goal,.8f,selectedJourney:true,avoidProposedParking:false)});
            f.Coordinator.EvaluateMovement(request);f.Coordinator.ProcessReady(request.RequestedFrame);var waiting=f.Coordinator.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(waiting.Blockers.Count,Is.EqualTo(1));Assert.That(waiting.Blockers[0].Owner,Is.EqualTo(f.Owner));
            Assert.That(waiting.Blockers[0].ResourceId,Is.EqualTo(f.Resource));Assert.That(waiting.Blockers[0].Proof,Is.EqualTo("current-conflict-segment"));
            Assert.That(f.Frozen(key),Is.EquivalentTo(new[]{f.Owner}));var entries=(System.Collections.IDictionary)D3ReadField(f.Coordinator,"entries");var originalEntry=entries[key];
            var pending=f.Begin();var state=f.Read(f.Owner,"PendingHandoff");var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");
            Assert.That(dependencies.Contains(originalEntry),Is.True,"PREMISE: this exact Entry was unresolved at the actual canonical completion");
            CollectionAssert.AreEquivalent(new[]{f.Resource},(HashSet<string>)dependencies[originalEntry]);
            Assert.That(f.Read(key,"Queued"),Is.False);f.Coordinator.Tick(.25f,false);f.Coordinator.NotifyChanged(f.Owner,"body");
            Assert.That(f.Read(key,"Queued"),Is.True,"PREMISE: actual completed-body checkpoint wakes the original captured current-segment edge");
            Assert.That(f.Coordinator.DrainReady(),Does.Contain(key));f.Coordinator.ProcessReady(f.Frame++);var source=f.Coordinator.GetDecision(key);
            Assert.That(source.Kind,Is.EqualTo(TrafficDecisionKind.Granted),source.Reason);Assert.That(f.Coordinator.TryCommit(source),Is.True);
            Assert.That(f.Coordinator.PrepareLeg(source,"b-primary",0,actor,6,f.World,start,.05f,f.Frame).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(f.Frame++);var strict=f.Coordinator.GetDecision(key);Assert.That(strict.Kind,Is.EqualTo(TrafficDecisionKind.Granted),strict.Reason);
            Assert.That(f.Coordinator.TryCommit(strict),Is.True);Assert.That(f.Coordinator.BindLeg(key,actor,stamp),Is.True);
            f.SetAdditionalBodyPosition(start,true);Assert.That(entries[key],Is.SameAs(originalEntry));Assert.That(dependencies.Contains(originalEntry),Is.True);
            Assert.That(((System.Collections.IEnumerable)D3ReadField(state,"CompletedBodyWakeups")).Cast<object>().Count(value=>ReferenceEquals(value,originalEntry)),Is.EqualTo(1),
                "PREMISE: this exact Entry consumed the real completion checkpoint, not a later inserted ordering edge");
            CollectionAssert.AreEquivalent(new[]{f.Resource},(HashSet<string>)dependencies[originalEntry]);
            Assert.That(f.Read(key,"Active"),Is.True);Assert.That(f.ReadLeg(key,"Bound"),Is.True);Assert.That(f.ReadLeg(key,"Completed"),Is.False);
            Assert.That(f.ReadLeg(key,"Stamp"),Is.EqualTo(stamp));Assert.That(f.ReadLeg(key,"ActorLife"),Is.SameAs(actor));
            Assert.That(D3InvokeBool(f.Coordinator,"HoldsHandoffDependency",originalEntry,f.Owner,f.Resource),Is.False,
                "PREMISE: current-wait filtering stops recognizing B once its independently clear first Native leg is Bound");
            f.Collect();var successor=f.PrepareSuccessorLeg(f.LawfulSuccessorKey,f.CollectionFrame,target:f.End+P(0,4));
            Assert.That(successor.Kind,Is.EqualTo(TrafficDecisionKind.Granted),successor.Reason);
            var originalDecision=f.Coordinator.GetDecision(key);var originalRequest=f.Read(key,"Request");var originalLeg=f.Read(key,"Leg");
            var accounting=D3CaptureAccounting(f.Coordinator,key);var frozen=f.Read(key,"FrozenOwners");var resources=f.Read(key,"FrozenResources");
            var queryCount=f.Coordinator.QueriesConsumed(key);f.Coordinator.DrainReady();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            Assert.That(entries[key],Is.SameAs(originalEntry));Assert.That(f.Coordinator.GetDecision(key),Is.SameAs(originalDecision));
            Assert.That(f.Read(key,"Request"),Is.SameAs(originalRequest));Assert.That(f.Read(key,"Leg"),Is.SameAs(originalLeg));
            Assert.That(f.ReadLeg(key,"Stamp"),Is.EqualTo(stamp));Assert.That(f.ReadLeg(key,"ActorLife"),Is.SameAs(actor));
            Assert.That(f.Read(key,"Active"),Is.True);Assert.That(f.ReadLeg(key,"Bound"),Is.True);Assert.That(f.ReadLeg(key,"Completed"),Is.False);
            Assert.That(f.Read(key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(f.Read(key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(f.Frozen(key),Is.EquivalentTo(new[]{successor.Intent}),
                "FEATURE RED: only a same-Entry release dependency actually captured at Begin follows its authenticated successor, even after B became Bound");
            var actualResources=(Dictionary<TrafficIntentKey,HashSet<string>>)resources;
            CollectionAssert.AreEquivalent(new[]{f.Resource},actualResources[successor.Intent]);Assert.That(actualResources[successor.Intent].Contains("body"),Is.False,
                "Migrating the captured pickup resource cannot fabricate a captured body resource");
            var expectedAccounting=accounting.ToDictionary(pair=>pair.Key,pair=>pair.Value);
            expectedAccounting["FrozenOwners"]=new[]{successor.Intent};
            expectedAccounting["FrozenResources"]=new Dictionary<TrafficIntentKey,string[]>{{successor.Intent,new[]{f.Resource}}};
            D3AssertAccounting(f.Coordinator,key,expectedAccounting);
            Assert.That(f.Coordinator.QueriesConsumed(key),Is.EqualTo(queryCount));Assert.That(f.Coordinator.DrainReady(),Has.No.Member(key));
            var exitStamp=new TrafficNativeStamp(182,5);Assert.That(f.Coordinator.BindLeg(successor.Intent,f.Actor,exitStamp),Is.True);
            f.SetAdditionalBodyPosition(corner,true);Assert.That(f.Coordinator.CompleteLeg(key,actor,stamp,corner),Is.True);
            f.SetAdditionalBodyPosition(corner,false);f.SetActualOwnerPosition(f.End+P(0,2));
            Assert.That(f.Coordinator.PrepareLeg(source,"b-suffix",0,actor,7,f.World,corner,.05f,f.Frame).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Coordinator.ProcessReady(f.Frame++);var next=f.Coordinator.GetDecision(key);
            Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),next.Reason);Assert.That(next.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(next.Blockers.Any(b=>b.Owner.Equals(successor.Intent)&&b.ResourceId=="body"),Is.True,
                "The new body conflict still undergoes the ordinary fresh physical/finite/cycle checks");
            Assert.That(f.Coordinator.TryCommit(next),Is.False);Assert.That(f.Read(key,"FirstFrame"),Is.EqualTo(accounting["FirstFrame"]));
            Assert.That(f.Read(key,"RequestSequence"),Is.EqualTo(accounting["RequestSequence"]));Assert.That(f.Read(key,"FiniteLimit"),Is.EqualTo(accounting["FiniteLimit"]));
            Assert.That(f.Read(key,"WaitRemaining"),Is.EqualTo(accounting["WaitRemaining"]));Assert.That(f.Coordinator.QueriesConsumed(key),Is.GreaterThanOrEqualTo(queryCount));
        }

        [Test]
        public void HandoffDoesNotMigrateIndependentBoundHistoryThatWasNeverCapturedAtBegin()
        {
            var f=new HandoffFixture("bound");var entries=(System.Collections.IDictionary)D3ReadField(f.Coordinator,"entries");var entry=entries[f.Waiter];
            var decision=f.Coordinator.GetDecision(f.Waiter);var request=f.Read(f.Waiter,"Request");var leg=f.Read(f.Waiter,"Leg");var accounting=D3CaptureAccounting(f.Coordinator,f.Waiter);
            Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.ReadLeg(f.Waiter,"Bound"),Is.True);Assert.That(decision.Blockers,Is.Empty);
            var pending=f.Begin();var state=f.Read(f.Owner,"PendingHandoff");var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");
            Assert.That(dependencies.Contains(entry),Is.False,"PREMISE: a prior independently Granted/Bound candidate has no captured current release edge");
            var successor=f.Successor();Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            Assert.That(entries[f.Waiter],Is.SameAs(entry));Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(decision));
            Assert.That(f.Read(f.Waiter,"Request"),Is.SameAs(request));Assert.That(f.Read(f.Waiter,"Leg"),Is.SameAs(leg));D3AssertAccounting(f.Coordinator,f.Waiter,accounting);
            Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}));Assert.That(f.ReadLeg(f.Waiter,"Stamp"),Is.EqualTo(f.WaiterStamp));
            Assert.That(f.ReadLeg(f.Waiter,"Completed"),Is.False);Assert.That(f.Coordinator.DrainReady(),Has.No.Member(f.Waiter));
        }

        [TestCase("source-ready","complete")]
        [TestCase("source-ready","abort")]
        [TestCase("strict-ready","complete")]
        [TestCase("strict-ready","abort")]
        [TestCase("bound","complete")]
        [TestCase("bound","abort")]
        public void HistoricalWaitingCandidateIsUnaffectedByPredecessorHandoff(string stage,string outcome)
        {
            var f=new HandoffFixture(stage);var original=f.Coordinator.GetDecision(f.Waiter);
            var request=f.Read(f.Waiter,"Request");var leg=f.Read(f.Waiter,"Leg");var active=f.Read(f.Waiter,"Active");
            var prepared=f.Read(f.Waiter,"Prepared");var firstFrame=f.Read(f.Waiter,"FirstFrame");
            var queries=f.Coordinator.QueriesConsumed(f.Waiter);var budget=f.Read(f.Waiter,"WaitRemaining");
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(original.Blockers,Is.Empty);
            Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}),"Real prior waiting history must remain frozen");
            Assert.That(f.Read(f.Waiter,"Queued"),Is.False);
            if(stage=="bound")
            {
                Assert.That(active,Is.True);Assert.That(f.ReadLeg(f.Waiter,"Committed"),Is.True);
                Assert.That(f.ReadLeg(f.Waiter,"Bound"),Is.True);Assert.That(f.ReadLeg(f.Waiter,"Stamp"),Is.EqualTo(f.WaiterStamp));
                Assert.That(f.ReadLeg(f.Waiter,"ActorLife"),Is.SameAs(f.WaiterActor));
            }
            var pending=f.Begin();
            if(outcome=="complete")
            {
                var successor=f.Successor();
                Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            }
            else f.Coordinator.AbortPhaseHandoff(pending,"original phase cancelled");
            Assert.That(f.Read(f.Waiter,"Queued"),Is.False,"PRODUCT: historical eligibility is not a current waiting edge");
            Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(original),"A predecessor handoff cannot replace an independent current decision");
            Assert.That(f.Read(f.Waiter,"Request"),Is.SameAs(request));Assert.That(f.Read(f.Waiter,"Leg"),Is.SameAs(leg));
            Assert.That(f.Read(f.Waiter,"Active"),Is.EqualTo(active));Assert.That(f.Read(f.Waiter,"Prepared"),Is.EqualTo(prepared));
            Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}));Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(firstFrame));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(queries));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That(f.Coordinator.DrainReady(),Has.No.Member(f.Waiter));
            if(stage=="bound")
            {
                Assert.That(f.ReadLeg(f.Waiter,"Committed"),Is.True);Assert.That(f.ReadLeg(f.Waiter,"Bound"),Is.True);
                Assert.That(f.ReadLeg(f.Waiter,"Completed"),Is.False);Assert.That(f.ReadLeg(f.Waiter,"Suspended"),Is.False);
                Assert.That(f.ReadLeg(f.Waiter,"Stamp"),Is.EqualTo(f.WaiterStamp));Assert.That(f.ReadLeg(f.Waiter,"ActorLife"),Is.SameAs(f.WaiterActor));
                f.Coordinator.ProcessReady(f.Frame++);
                Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(original));
                Assert.That(f.Coordinator.CompleteLeg(f.Waiter,f.WaiterActor,f.WaiterStamp,Origin),Is.True,
                    "The already bound Native authority still accepts its own original completion");
            }
        }

        [TestCase("new-order")]
        [TestCase("context")]
        [TestCase("generation")]
        [TestCase("source-replacement")]
        [TestCase("source-copy")]
        [TestCase("early-phase")]
        public void HandoffRejectsUnauthorisedSpecificSuccessor(string mismatch)
        {
            var f=new HandoffFixture();var pending=f.Begin();TrafficDecision candidate;HandoffMilestone receipt;
            if(mismatch=="early-phase")
            {
                f.Refresh();candidate=f.PrepareSuccessorLeg(f.LawfulSuccessorKey,f.Frame++,authorize:false);
                Assert.That(candidate.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
                Assert.That(f.Coordinator.TryGetCommittedJourney(candidate.Intent,out var earlySource),Is.True);
                var originalFrame=f.Read(candidate.Intent,"FirstFrame");f.Collect();
                // Canonical collection now selects this exact key/source, but cannot retroactively change its birth.
                f.SelectContinuationSource(earlySource);
                Assert.That(f.Coordinator.DiscardPrepared(candidate.Intent),Is.True);
                Assert.That(f.Coordinator.PrepareLeg(earlySource,f.Resource,0,f.Actor,5,f.World,f.End,.05f,f.Frame).Kind,
                    Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                f.Coordinator.ProcessReady(f.Frame++);candidate=f.Coordinator.GetDecision(candidate.Intent);receipt=f.Receipt();
                Assert.That(f.Read(candidate.Intent,"FirstFrame"),Is.EqualTo(originalFrame));
                Assert.That((int)originalFrame,Is.LessThan(f.CollectionFrame));
                Assert.That(((TrafficRequest)f.Read(candidate.Intent,"Request")).RequestedFrame,Is.GreaterThan(f.CollectionFrame));
                Assert.That(receipt.AuthorizesSuccessor(candidate.Intent,earlySource,f.CollectionFrame),Is.True,
                    "Fixture isolates original FirstFrame: passing the later strict-leg frame would launder the phase age");
            }
            else
            {
                var lawful=f.Successor();receipt=f.Receipt();var key=lawful.Intent;
                if(mismatch=="source-copy")
                {
                    var copy=CopyDecision(f.ExpectedContinuationSource);
                    Assert.That(receipt.IsCurrent,Is.True);
                    Assert.That(receipt.AuthorizesSuccessor(lawful.Intent,f.ExpectedContinuationSource,f.CollectionFrame),Is.True);
                    Assert.That(receipt.AuthorizesSuccessor(lawful.Intent,copy,f.CollectionFrame),Is.False);
                    Assert.That(f.Coordinator.PrepareLeg(copy,f.Resource,0,f.Actor,5,f.World,f.End,.05f,f.Frame).Kind,
                        Is.EqualTo(TrafficDecisionKind.StaleContext),"A copied retained source cannot prepare a strict leg");
                    var copiedPublication=false;
                    Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,CopyDecision(lawful),receipt,publish:()=>copiedPublication=true),Is.False);
                    Assert.That(copiedPublication,Is.False);Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}));
                    Assert.That(f.ReadLeg(lawful.Intent,"Committed"),Is.False);return;
                }
                else if(mismatch=="source-replacement")
                {
                    var originalSource=f.ExpectedContinuationSource;var firstFrame=f.Read(key,"FirstFrame");
                    var originalQueries=f.Coordinator.QueriesConsumed(key);var originalBudget=f.Read(key,"WaitRemaining");
                    var originalWaiter=f.Coordinator.GetDecision(f.Waiter);var waiterQueries=f.Coordinator.QueriesConsumed(f.Waiter);
                    var waiterBudget=f.Read(f.Waiter,"WaitRemaining");var originalClaim=f.World.Parking.Single();
                    var waiterAge=f.Read(f.Waiter,"FirstFrame");var frozenOwners=f.Frozen(f.Waiter).ToArray();
                    var waitingEdges=((IReadOnlyList<TrafficBlocker>)f.Read(f.Waiter,"WaitingBlockers")).Select(b=>new{b.Owner,b.ResourceId}).ToArray();
                    var originalBody=f.World.Bodies.Single(b=>ReferenceEquals(b.ActorLife,f.Actor));
                    Assert.That(f.Coordinator.DiscardPrepared(key),Is.True);
                    var discarded=f.Coordinator.GetDecision(key);var frame=f.Frame++;
                    // Discard has its own notification; finish that authorized pump before the target-swap attack.
                    // 授权 discard 的通知先正常处理，不能把这次重评估归因于后续伪造请求。
                    f.Coordinator.ProcessReady(frame);var beforeTargetSwap=f.Coordinator.GetDecision(f.Waiter);
                    var refused=f.Coordinator.EvaluateMovement(Request(key,f.End,f.End+P(4),f.World,frame:frame,resource:f.Resource,seconds:8));
                    Assert.That(refused,Is.SameAs(discarded),"Ordinary Submit cannot replace the committed source or its target");
                    f.Coordinator.ProcessReady(frame);Assert.That(f.Coordinator.TryCommit(f.Coordinator.GetDecision(key)),Is.False);
                    Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(beforeTargetSwap),"Rejected target swap cannot mutate the waiter");
                    Assert.That(f.Coordinator.TryGetCommittedJourney(key,out var retained),Is.True);Assert.That(retained,Is.SameAs(originalSource));
                    Assert.That(f.Read(key,"FirstFrame"),Is.EqualTo(firstFrame));Assert.That(f.Coordinator.QueriesConsumed(key),Is.EqualTo(originalQueries));
                    Assert.That(f.Read(key,"WaitRemaining"),Is.EqualTo(originalBudget));
                    Assert.That(f.Read(key,"FirstFrame"),Is.EqualTo(f.CollectionFrame));
                    // Restore only the legitimate unissued leg, then challenge live authority with copied proofs.
                    // 先经正常 ready batch 恢复原合法腿，避免仅靠没有 Prepared 候选让伪造来源测试通过。
                    frame=f.Frame++;
                    Assert.That(f.Coordinator.PrepareLeg(originalSource,f.Resource,0,f.Actor,5,f.World,f.End,.05f,frame).Kind,
                        Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                    f.Coordinator.ProcessReady(frame);var ready=f.Coordinator.GetDecision(key);
                    Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Read(key,"Prepared"),Is.True);Assert.That(f.Read(key,"Active"),Is.False);
                    Assert.That(f.ReadLeg(key,"Committed"),Is.False);Assert.That(f.ReadLeg(key,"Bound"),Is.False);Assert.That(f.ReadLeg(key,"ActorLife"),Is.SameAs(f.Actor));
                    Assert.That(receipt.IsCurrent,Is.True);Assert.That(receipt.AuthorizesSuccessor(key,originalSource,f.CollectionFrame),Is.True);
                    var afterPump=f.Coordinator.GetDecision(f.Waiter);
                    string WaiterOwnerLabel(TrafficIntentKey value)=>value.Session+"/e"+value.Epoch+"/"+value.ActorId+"/"+value.IntentId+
                        "/g"+value.Generation+"/r"+value.LayoutRevision+"/"+value.Context;
                    TestContext.WriteLine("D1_SOURCE_REPLACEMENT_WAITER old="+originalWaiter.Kind+"/"+originalWaiter.Reason+
                        " new="+afterPump.Kind+"/"+afterPump.Reason+
                        " oldBlockers="+string.Join(";",originalWaiter.Blockers.Select(b=>WaiterOwnerLabel(b.Owner)+"/resource="+b.ResourceId))+
                        " newBlockers="+string.Join(";",afterPump.Blockers.Select(b=>WaiterOwnerLabel(b.Owner)+"/resource="+b.ResourceId))+
                        " oldEdges="+string.Join(";",waitingEdges.Select(b=>WaiterOwnerLabel(b.Owner)+"/resource="+b.ResourceId))+
                        " newEdges="+string.Join(";",((IReadOnlyList<TrafficBlocker>)f.Read(f.Waiter,"WaitingBlockers")).Select(b=>WaiterOwnerLabel(b.Owner)+"/resource="+b.ResourceId))+
                        " oldWait="+waiterBudget+" newWait="+f.Read(f.Waiter,"WaitRemaining")+
                        " oldQueries="+waiterQueries+" newQueries="+f.Coordinator.QueriesConsumed(f.Waiter)+
                        " oldFirstFrame="+waiterAge+" newFirstFrame="+f.Read(f.Waiter,"FirstFrame")+" queued="+f.Read(f.Waiter,"Queued"));
                    Assert.That(afterPump.Kind,Is.EqualTo(originalWaiter.Kind),"Authorized unissued reprepare cannot fail or grant the original waiter");
                    Assert.That(afterPump.Reason,Is.EqualTo(originalWaiter.Reason));
                    Assert.That(afterPump.Blockers.Select(b=>new{b.Owner,b.ResourceId}),Is.EquivalentTo(originalWaiter.Blockers.Select(b=>new{b.Owner,b.ResourceId})));
                    Assert.That(afterPump.RequestSequence,Is.EqualTo(originalWaiter.RequestSequence));Assert.That(afterPump.AcquiredSequence,Is.EqualTo(originalWaiter.AcquiredSequence));
                    Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(waiterAge));Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(frozenOwners));
                    Assert.That(((IReadOnlyList<TrafficBlocker>)f.Read(f.Waiter,"WaitingBlockers")).Select(b=>new{b.Owner,b.ResourceId}),Is.EquivalentTo(waitingEdges));
                    Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(waiterBudget));
                    Assert.That(f.Coordinator.HasActiveGrant(f.Waiter),Is.False);Assert.That(f.World.Parking.Single(),Is.SameAs(originalClaim));
                    Assert.That(f.World.Bodies.Single(b=>ReferenceEquals(b.ActorLife,f.Actor)),Is.SameAs(originalBody));
                    var copiedSource=CopyDecision(originalSource);
                    Assert.That(receipt.AuthorizesSuccessor(key,copiedSource,f.CollectionFrame),Is.False);
                    var attackWaiter=f.Coordinator.GetDecision(f.Waiter); // Exact-reference boundary for the unauthorized proof attacks.
                    Assert.That(f.Coordinator.PrepareLeg(copiedSource,f.Resource,0,f.Actor,5,f.World,f.End,.05f,f.Frame).Kind,
                        Is.EqualTo(TrafficDecisionKind.StaleContext));
                    var copiedPublished=false;
                    Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,CopyDecision(ready),receipt,publish:()=>copiedPublished=true),Is.False);
                    Assert.That(copiedPublished,Is.False);Assert.That(f.Coordinator.GetDecision(key),Is.SameAs(ready));
                    var currentSnapshot=((TrafficRequest)f.Read(key,"Request")).Snapshot;
                    Assert.That(currentSnapshot,Is.SameAs(f.World));Assert.That(currentSnapshot.Parking.Single(),Is.SameAs(originalClaim));
                    Assert.That(originalClaim.Owner,Is.EqualTo(f.Owner));Assert.That(originalClaim.CanonicalOwner,Is.SameAs(f.Canonical));
                    Assert.That(originalClaim.BusinessOwner,Is.SameAs(f.Business));Assert.That(originalClaim.ReleaseObligation,Is.SameAs(f.Obligation));
                    Assert.That(originalClaim.OwnerVersion,Is.EqualTo(receipt.CurrentClaim.OwnerVersion));
                    Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(attackWaiter));Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}));
                    Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(waiterBudget));
                    Assert.That(f.Coordinator.QueriesConsumed(key),Is.EqualTo(originalQueries));Assert.That(f.Read(key,"WaitRemaining"),Is.EqualTo(originalBudget));
                    Assert.That(f.Coordinator.HasActiveGrant(key),Is.False);Assert.That(f.ReadLeg(key,"Committed"),Is.False);Assert.That(f.ReadLeg(key,"Bound"),Is.False);
                    Assert.That(f.Canonical.Value,Is.EqualTo(2));Assert.That(f.LegCompleted,Is.True);Assert.That(f.CurrentBodyPresent,Is.True);return;
                }
                else
                {
                    key=new TrafficIntentKey(key.Session,key.Epoch,key.ActorId,key.IntentId,
                        mismatch=="context"?key.Generation:key.Generation+1,key.LayoutRevision,
                        mismatch=="new-order"?"order.2/collection/1":mismatch=="context"?"order.1/collection/2":key.Context);
                    candidate=f.PrepareSuccessorLeg(key,f.Frame++,authorize:false);
                }
            }
            Assert.That(candidate.Kind,Is.EqualTo(TrafficDecisionKind.Granted),candidate.Reason);
            Assert.That(f.Read(candidate.Intent,"Prepared"),Is.True);Assert.That(f.Read(candidate.Intent,"Active"),Is.False);
            Assert.That(f.ReadLeg(candidate.Intent,"Committed"),Is.False);Assert.That(f.ReadLeg(candidate.Intent,"Bound"),Is.False);
            Assert.That(f.ReadLeg(candidate.Intent,"ActorLife"),Is.SameAs(f.Actor));Assert.That(receipt.IsCurrent,Is.True);
            var saved=((TrafficRequest)f.Read(candidate.Intent,"Request")).Snapshot;
            Assert.That(saved,Is.SameAs(f.World));var oldClaim=saved.Parking.Single();
            Assert.That(oldClaim.Owner,Is.EqualTo(f.Owner));Assert.That(oldClaim.CanonicalOwner,Is.SameAs(f.Canonical));
            Assert.That(oldClaim.BusinessOwner,Is.SameAs(f.Business));Assert.That(oldClaim.ReleaseObligation,Is.SameAs(f.Obligation));
            Assert.That(oldClaim.OwnerVersion,Is.EqualTo(receipt.CurrentClaim.OwnerVersion));
            Assert.That(f.Coordinator.TryGetCommittedJourney(candidate.Intent,out var actualSource),Is.True);
            Assert.That(receipt.AuthorizesSuccessor(candidate.Intent,actualSource,(int)f.Read(candidate.Intent,"FirstFrame")),Is.False);
            var waiter=f.Coordinator.GetDecision(f.Waiter);var queries=f.Coordinator.QueriesConsumed(f.Waiter);
            var budget=f.Read(f.Waiter,"WaitRemaining");var published=false;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,candidate,receipt,publish:()=>published=true),Is.False,
                "PRODUCT: a current predecessor receipt/global claim cannot authorize another continuation source or phase age");
            Assert.That(published,Is.False);Assert.That(f.World.Parking.Single(),Is.SameAs(oldClaim));
            Assert.That(f.Coordinator.GetDecision(f.Waiter),Is.SameAs(waiter));Assert.That(f.Frozen(f.Waiter),Is.EquivalentTo(new[]{f.Owner}));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(queries));Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That(f.Coordinator.HasActiveGrant(candidate.Intent),Is.False);Assert.That(f.ReadLeg(candidate.Intent,"Committed"),Is.False);
            Assert.That(f.Canonical.Value,Is.EqualTo(2));Assert.That(f.LegCompleted,Is.True);Assert.That(f.CurrentBodyPresent,Is.True);
        }

        private static TrafficDecision CopyDecision(TrafficDecision value)=>new TrafficDecision(value.Intent,value.Kind,value.Reason,
            value.Permit,value.RequestSequence,value.AcquiredSequence,value.Blockers,value.Route,value.ProofRoutes);

        // Real coordinator and planner; the small port models canonical owner reads, not Unity Native arrival.
        [Test] public void MultiClaimMilestoneCapturesEveryExistingResourceInOneHandle()
        {
            var f=new MultiClaimFixture();var pending=f.Begin();
            Assert.That(f.PendingResources(pending),Is.EquivalentTo(f.AllResources),
                "PRODUCT: one completion must retain Counter/Pickup/service plus the existing body/current-leg edges");
            Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.Not.Null);Assert.That(f.ConfirmCalls,Is.EqualTo(1));
            var successor=f.Successor();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.Publish(successor.Intent)),Is.True);
            f.AssertTransferred(successor.Intent,f.AllResources);
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,8),Is.True);
            Assert.That(f.Coordinator.BindLeg(successor.Intent,f.Actor,new TrafficNativeStamp(202,8)),Is.True);
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt()),Is.False);
            Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False);
        }

        [TestCase("omitted")] [TestCase("copied-source")] [TestCase("foreign-canonical")]
        [TestCase("same-business-foreign-entry")] [TestCase("replaced-entry")] [TestCase("removed-service-still-held")]
        public void MultiClaimMilestoneRejectsUnauthorisedSecondaryClaim(string fault)
        {
            var f=new MultiClaimFixture();f.Arrive();MultiClaimMilestone receipt=null;
            var accepted=f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
            {
                f.Confirm();f.ApplySecondaryFault(fault);receipt=f.Receipt(fault);
                Assert.That(receipt.IsCurrent,Is.True,"FIXTURE: valid original primary milestone and business/release/life remain unchanged");
                Assert.That(receipt.ReadClaim(f.Originals[0],out var primary),Is.EqualTo(TrafficPhaseClaimState.Held));
                Assert.That(primary.CanonicalOwner,Is.SameAs(f.Counter));
                var index=fault=="removed-service-still-held"?2:1;
                var state=receipt.ReadClaim(f.Originals[index],out var current);
                if(fault=="foreign-canonical")
                { Assert.That(state,Is.EqualTo(TrafficPhaseClaimState.Held));Assert.That(current.CanonicalOwner,Is.Not.SameAs(f.Pickup)); }
                else Assert.That(state,Is.EqualTo(TrafficPhaseClaimState.Invalid),"FIXTURE: secondary authority fails independently of the valid primary");
                return receipt;
            },out var pending);
            Assert.That(f.Completed,Is.True);Assert.That(f.ConfirmCalls,Is.EqualTo(1));Assert.That(f.CanonicalMarked,Is.True);
            Assert.That(accepted,Is.False,"PRODUCT: a valid primary/same Visit+Admission cannot authorize an invalid secondary obligation");
            Assert.That(pending,Is.Null);Assert.That(f.Coordinator.HasActiveGrant(f.Owner),Is.False);
            Assert.That(f.World.Bodies.Single().ActorLife,Is.SameAs(f.Actor));
