            {
                f.Confirm();f.Release("counter");f.Release("service");f.Release("pickup");var receipt=f.Receipt();
                foreach(var original in f.Originals)
                { Assert.That(receipt.ReadClaim(original,out var current),Is.EqualTo(TrafficPhaseClaimState.Released));Assert.That(current,Is.Null); }
                return receipt;
            },out var pending),Is.True,"PRODUCT: accepted actual completion/canonical milestone returns true even when no gap is needed");
