            Assert.That(f.Completed,Is.True);Assert.That(f.Read(f.Owner,"Active"),Is.False);Assert.That(f.Read(f.Owner,"Retired"),Is.False);
            Assert.That(f.Coordinator.GetDecision(f.Owner).Kind,Is.Not.EqualTo(TrafficDecisionKind.PlanningFailed));
