            Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>{repeated=true;return f.Receipt();},out _),Is.False);
            Assert.That(repeated,Is.False);Assert.That(f.World.Bodies.Single().ActorLife,Is.SameAs(f.Actor));
        }

        [Test] public void MultiClaimNewParkingCannotGiveGapBornWaiterOriginalEligibility()
        {
            var f=new MultiClaimFixture();var pending=f.Begin();f.AddParking();
            var late=Key("multi-gap-born");f.Coordinator.EvaluateMovement(Request(late,P(8,-3),P(8),f.World,frame:f.Frame,seconds:8));
            f.Coordinator.ProcessReady(f.Frame++);var failed=f.Coordinator.GetDecision(late);
            Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"FIXTURE: no old frozen eligibility for the newly acquired parking");
            var successor=f.Successor();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.Publish(successor.Intent)),Is.True);
            Assert.That(f.Coordinator.GetDecision(late),Is.SameAs(failed),"A true gap-born failure cannot be revived by an added claim");
            Assert.That(f.Coordinator.DrainReady(),Has.No.Member(late));f.AssertTransferred(successor.Intent,f.AllResources);
            Assert.That(f.Read(successor.Intent,"Request"),Is.TypeOf<TrafficRequest>());
            Assert.That(((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot.Parking.Any(p=>p.ResourceId==f.NewResource && p.Owner.Equals(successor.Intent)),Is.True);
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,8),Is.True);
        }

        [Test] public void MultiClaimNewParkingNeedsItsOwnCurrentCanonicalAuthority()
        {
            var f=new MultiClaimFixture();var pending=f.Begin();f.AddParking();var successor=f.Successor();
            var sourceFact=f.SuccessorSnapshot.Parking.Single(p=>p.ResourceId==f.NewResource);
