        [Test] public void MultiClaimPausePreservesOriginalAgeAndChargesEachBudgetOnlyOnce()
        {
            var f=new MultiClaimFixture();var ages=f.Waiters.ToDictionary(w=>w,w=>f.Read(w,"FirstFrame"));
            var sequences=f.Waiters.ToDictionary(w=>w,w=>f.Coordinator.GetDecision(w).RequestSequence);
            var queries=f.Waiters.ToDictionary(w=>w,w=>f.Coordinator.QueriesConsumed(w));var pending=f.Begin();
            var state=f.Read(f.Owner,"PendingHandoff");var before=(float)MultiClaimFixture.Field(state,"Remaining");
            f.Coordinator.Tick(2,false);f.Coordinator.Tick(100,true);f.Coordinator.Tick(0,false);
            Assert.That(MultiClaimFixture.Field(state,"Remaining"),Is.EqualTo(before-2));
            foreach(var waiter in f.Waiters)
            { Assert.That(f.Read(waiter,"WaitRemaining"),Is.EqualTo(6f));Assert.That(f.Read(waiter,"FirstFrame"),Is.EqualTo(ages[waiter])); }
            var successor=f.Successor();Assert.That(f.Read(successor.Intent,"FirstFrame"),Is.EqualTo(f.CollectionFrame));
            Assert.That((int)f.Read(successor.Intent,"FirstFrame"),Is.GreaterThan((int)f.Read(f.Owner,"FirstFrame")));
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.Publish(successor.Intent)),Is.True);
            f.AssertTransferred(successor.Intent,f.AllResources);
            foreach(var waiter in f.Waiters)
            {
                Assert.That(f.Read(waiter,"FirstFrame"),Is.EqualTo(ages[waiter]));Assert.That(f.Coordinator.GetDecision(waiter).RequestSequence,Is.EqualTo(sequences[waiter]));
                Assert.That(f.Coordinator.QueriesConsumed(waiter),Is.EqualTo(queries[waiter]));Assert.That(f.Read(waiter,"WaitRemaining"),Is.EqualTo(6f));
            }
        }

