            internal readonly TrafficIntentKey[] Waiters={Key("multi-counter"),Key("multi-pickup-service"),Key("multi-body"),Key("multi-movement")};
            internal readonly ServiceTrafficCoordinator Coordinator;internal readonly TrafficDecision Source;
            internal readonly TrafficParkingFact[] Originals;internal readonly TrafficWorldSnapshot Saved;
            internal readonly CounterQueueService.AssignmentClaim CounterClaim;
            internal readonly PickupQueueService.ReservationClaim PickupClaim;
            internal CounterQueueService AddedParking;internal CounterQueueService.AssignmentClaim AddedClaim;
            internal PickupQueueService ForeignPickup;internal PickupQueueService.ReservationClaim ForeignClaim;
            internal TrafficWorldSnapshot World,SuccessorSnapshot;internal int Frame=3,CollectionFrame,ConfirmCalls;
            internal bool CanonicalMarked,Collected,Enabled=true;
            private TrafficIntentKey bodyOwner;private Vector3 position=Origin;private bool progressing=true;private long version=1;
            private readonly object originalLeg;private TrafficDecision expectedSource;
            internal string CounterResource=>"counter/"+Owner.ActorId;
            internal string PickupResource=>"pickup/"+Owner.ActorId;
            internal string ServiceResource=>"service/"+Owner.ActorId;
            internal string MovementResource=>"strict-movement/"+Owner.ActorId;
            internal string NewResource=>"new-parking/"+Owner.ActorId;
            internal string[] AllResources=>new[]{CounterResource,PickupResource,ServiceResource,"body",MovementResource};
            internal TrafficIntentKey SuccessorKey=>new TrafficIntentKey("scene",1,Owner.ActorId,"actual-exit",12,7,"order.1/collection/1");
            internal MultiClaimFixture(bool duplicate=false)
            {
                bodyOwner=Owner;
                Assert.That(Counter.TryJoin(Owner.ActorId),Is.True);Assert.That(Counter.Complete(Owner.ActorId,1),Is.True);
                Assert.That(Pickup.TryReserve(Owner.ActorId,out _),Is.True);Assert.That(Pickup.TryBeginTransfer(Owner.ActorId,out var wait),Is.True);
                Assert.That(Pickup.MarkArrived(Owner.ActorId,wait.Generation),Is.True);
                Assert.That(Pickup.TryAcquireCollection(Owner.ActorId,End),Is.True);
                Assert.That(Counter.TryCaptureAssignment(Owner.ActorId,out CounterClaim),Is.True);
                Assert.That(Pickup.TryCaptureReservation(Owner.ActorId,out PickupClaim),Is.True);Assert.That(PickupClaim.IsCurrentCollectionLease,Is.True);
                World=ServiceTrafficCoordinatorTests.World(1,1,new[]{Body()});Coordinator=ServiceTrafficCoordinatorTests.Coordinator(World);
                Source=Grant(Coordinator,Request(Owner,Origin,End,World,resource:MovementResource,seconds:8));
                Assert.That(((TrafficRequest)Read(Owner,"Request")).Snapshot.Parking,Is.Empty,"FIXTURE: source acquisition precedes actual claim publication");
                var originals=ActualFacts().ToList();if(duplicate)originals.Add(Copy(originals[1]));Originals=originals.ToArray();
                Refresh(Originals);
                Assert.That(Coordinator.PrepareLeg(Source,MovementResource,0,Actor,7,World,Origin,.05f,2).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Coordinator.ProcessReady(2);Assert.That(Coordinator.TryCommit(Coordinator.GetDecision(Owner)),Is.True);
                Assert.That(Coordinator.BindLeg(Owner,Actor,Stamp),Is.True);originalLeg=Read(Owner,"Leg");Saved=((TrafficRequest)Read(Owner,"Request")).Snapshot;
                Assert.That(Saved,Is.SameAs(World));Assert.That(Saved.Parking.Select((p,i)=>ReferenceEquals(p,Originals[i])).All(v=>v),Is.True);
                var starts=new[]{P(-4,-3),P(4,-3),P(0,-3),P(2,-3)};var targets=new[]{P(-4),End,Origin,P(2,3)};
                for(var i=0;i<Waiters.Length;i++)
                {
                    Coordinator.EvaluateMovement(Request(Waiters[i],starts[i],targets[i],World,frame:Frame,seconds:8));Coordinator.ProcessReady(Frame++);
                    Assert.That(Coordinator.GetDecision(Waiters[i]).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: real ordinary kernel wait "+i);
                    Assert.That(Coordinator.GetDecision(Waiters[i]).Blockers.All(b=>b.Owner.Equals(Owner)),Is.True);
                    Assert.That(Coordinator.GetDecision(Waiters[i]).Blockers.Select(b=>b.ResourceId),Is.EquivalentTo(Resources(i)));
                }
                Assert.That(Coordinator.DrainReady(),Is.Empty);
            }
            private string[] Resources(int waiter)=>waiter==0?new[]{CounterResource}:waiter==1?new[]{PickupResource,ServiceResource}:
                waiter==2?new[]{"body"}:new[]{MovementResource};
            private TrafficBodyFact Body()=>new TrafficBodyFact(bodyOwner,position,.4f,Enabled,progressing,progressing?8:0,actorLife:Actor);
            internal static object Field(object instance,string name)=>instance.GetType().GetField(name,
                System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public).GetValue(instance);
            internal object Read(TrafficIntentKey key,string name)=>Field(((System.Collections.IDictionary)Field(Coordinator,"entries"))[key],name);
            internal bool Completed=>(bool)Field(originalLeg,"Completed");
            internal static TrafficParkingFact Copy(TrafficParkingFact fact,object canonical=null)=>new TrafficParkingFact(fact.Owner,canonical??fact.CanonicalOwner,
                fact.OwnerVersion,fact.ResourceId,fact.Position,fact.Radius,fact.SafetyMargin,fact.BusinessOwner,fact.ReleaseObligation);
            private TrafficParkingFact Fact(object canonical,long ownerVersion,string resource,Vector3 point)=>
                new TrafficParkingFact(bodyOwner,canonical,ownerVersion,resource,point,.4f,businessOwner:Business,releaseObligation:Obligation);
            private IEnumerable<TrafficParkingFact> ActualFacts()
            {
                var counter=Counter.Snapshot.SingleOrDefault(a=>a.VisitId==Owner.ActorId);
                if(counter.VisitId!=null)yield return Fact(Counter,Counter.Version,CounterResource,counter.Position);
                if(Pickup.TryGetReservation(Owner.ActorId,out var pickup))yield return Fact(Pickup,Pickup.Version,PickupResource,pickup.Position);
                if(Pickup.TryGetServiceLease(Owner.ActorId,out var service))yield return Fact(Pickup,Pickup.Version,ServiceResource,service);
                if(AddedParking!=null)
                {
                    var added=AddedParking.Snapshot.SingleOrDefault(a=>a.VisitId==Owner.ActorId);
                    if(added.VisitId!=null)yield return Fact(AddedParking,AddedParking.Version,NewResource,added.Position);
                }
            }
            internal void Refresh(TrafficParkingFact[] facts=null)
            { World=ServiceTrafficCoordinatorTests.World(++version,version,new[]{Body()},facts??ActualFacts().ToArray());Coordinator.SetSnapshot(World); }
            internal TrafficPhaseClaimState ReadCanonical(string resource,out TrafficParkingFact current)
            {
                current=null;
                if(resource==CounterResource || resource==NewResource)
                {
                    var owner=resource==CounterResource?Counter:AddedParking;var original=resource==CounterResource?CounterClaim:AddedClaim;
                    if(owner==null)return TrafficPhaseClaimState.Invalid;
                    if(!owner.TryCaptureAssignment(Owner.ActorId,out var now))return TrafficPhaseClaimState.Released;
                    if(original==null || !original.IsSameReservation(now))return TrafficPhaseClaimState.Invalid;
                    current=Fact(owner,owner.Version,resource,now.Assignment.Position);return TrafficPhaseClaimState.Held;
                }
                if(resource==PickupResource)
                {
                    if(!Pickup.TryGetReservation(Owner.ActorId,out _))return TrafficPhaseClaimState.Released;
                    if(!Pickup.TryCaptureReservation(Owner.ActorId,out var now) || !PickupClaim.IsSameReservation(now))return TrafficPhaseClaimState.Invalid;
                    current=Fact(Pickup,Pickup.Version,resource,now.Assignment.Position);return TrafficPhaseClaimState.Held;
                }
                if(resource==ServiceResource)
                {
                    if(!Pickup.TryGetServiceLease(Owner.ActorId,out var point))return TrafficPhaseClaimState.Released;
                    if(!PickupClaim.IsCurrentCollectionLease)return TrafficPhaseClaimState.Invalid;
                    current=Fact(Pickup,Pickup.Version,resource,point);return TrafficPhaseClaimState.Held;
                }
                return TrafficPhaseClaimState.Invalid;
            }
            internal void Arrive(){position=End;progressing=false;Refresh();}
            internal MovementResult Arrival()=>new MovementResult(201,Owner.ActorId,MovementStatus.Arrived,NavigationFailure.None,
                NavigationFailure.None,NavigationFailure.None,End,0);
            internal MultiClaimMilestone Confirm()
            {
                ConfirmCalls++;Assert.That(Pickup.TryGetReservation(Owner.ActorId,out var assignment),Is.True);
                Assert.That(Pickup.MarkArrived(Owner.ActorId,assignment.Generation),Is.True);
                Assert.That(Pickup.TryGetReservation(Owner.ActorId,out var arrived),Is.True);Assert.That(arrived.Arrived,Is.True);
                CanonicalMarked=true;return Receipt();
            }
            internal TrafficPhaseHandoff Begin()
            {
                Arrive();Assert.That(Coordinator.CompleteLegAndBeginHandoff(Owner,Actor,Stamp,Arrival(),Confirm,out var pending),Is.True,
                    "PRODUCT: matching real kernel completion/canonical Mark must accept every valid original obligation");
                Assert.That(pending,Is.Not.Null);return pending;
            }
            internal MultiClaimMilestone Receipt(string fault=null)=>new MultiClaimMilestone(this,expectedSource,fault);
            internal void Release(string resource)
            {
                if(resource=="counter")Assert.That(Counter.Remove(Owner.ActorId),Is.True);
                else if(resource=="pickup")Assert.That(Pickup.Remove(Owner.ActorId),Is.True);
                else { Assert.That(Pickup.TryGetServiceLease(Owner.ActorId,out _),Is.True);Pickup.ReleaseServicePosition(Owner.ActorId);Assert.That(Pickup.TryGetServiceLease(Owner.ActorId,out _),Is.False); }
            }
            internal void ApplySecondaryFault(string fault)
            {
                if(fault=="removed-service-still-held")
                { Assert.That(Pickup.Remove(Owner.ActorId),Is.True);Assert.That(Pickup.TryGetServiceLease(Owner.ActorId,out _),Is.True);return; }
                if(fault=="replaced-entry")
                {
                    Pickup.ReleaseServicePosition(Owner.ActorId);Assert.That(Pickup.Remove(Owner.ActorId),Is.True);
                    Assert.That(Pickup.TryReserve(Owner.ActorId,out _),Is.True);Assert.That(Pickup.TryBeginTransfer(Owner.ActorId,out var wait),Is.True);
                    Assert.That(Pickup.MarkArrived(Owner.ActorId,wait.Generation),Is.True);Assert.That(Pickup.TryAcquireCollection(Owner.ActorId,End),Is.True);
                    Assert.That(Pickup.TryGetReservation(Owner.ActorId,out var service),Is.True);Assert.That(Pickup.MarkArrived(Owner.ActorId,service.Generation),Is.True);
                    Assert.That(Pickup.TryCaptureReservation(Owner.ActorId,out var replacement),Is.True);Assert.That(PickupClaim.IsSameReservation(replacement),Is.False);
                }
                if(fault=="foreign-canonical" || fault=="same-business-foreign-entry")
                {
                    ForeignPickup=new PickupQueueService(new[]{P(4,4)},new[]{End,P(6)});
                    Assert.That(ForeignPickup.TryReserve(Owner.ActorId,out _),Is.True);Assert.That(ForeignPickup.TryBeginTransfer(Owner.ActorId,out var wait),Is.True);
                    Assert.That(ForeignPickup.MarkArrived(Owner.ActorId,wait.Generation),Is.True);Assert.That(ForeignPickup.TryAcquireCollection(Owner.ActorId,End),Is.True);
                    Assert.That(ForeignPickup.TryCaptureReservation(Owner.ActorId,out ForeignClaim),Is.True);Assert.That(PickupClaim.IsSameReservation(ForeignClaim),Is.False);
                }
            }
            internal void AddParking()
            {
                AddedParking=new CounterQueueService(new[]{P(8)});Assert.That(AddedParking.TryJoin(Owner.ActorId),Is.True);
                Assert.That(AddedParking.TryCaptureAssignment(Owner.ActorId,out AddedClaim),Is.True);Refresh();
            }
            internal TrafficDecision Successor()
            {
                Assert.That(CanonicalMarked,Is.True);Collected=true;CollectionFrame=Frame++;Refresh();
                var source=Grant(Coordinator,Request(SuccessorKey,End,End+P(2),World,frame:CollectionFrame,resource:MovementResource,seconds:8));
                expectedSource=source; // Only the current canonical collection selects this actually committed new source.
                Assert.That(Coordinator.PrepareLeg(source,MovementResource,0,Actor,8,World,End,.05f,Frame).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Coordinator.ProcessReady(Frame++);var decision=Coordinator.GetDecision(SuccessorKey);
                Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FIXTURE: READY STRICT successor, not primary-only");
                SuccessorSnapshot=((TrafficRequest)Read(SuccessorKey,"Request")).Snapshot;return decision;
            }
            internal void Publish(TrafficIntentKey successor,string change=null)
            {
                bodyOwner=successor;
                if(change=="position") { Pickup.ReleaseServicePosition(Owner.ActorId);Assert.That(Pickup.TryAcquireCollection(Owner.ActorId,P(6)),Is.True); }
                if(change=="version")Assert.That(Pickup.TryReserve("unrelated-canonical-tail",out _),Is.True);
                Refresh();
            }
            internal string[] PendingResources(TrafficPhaseHandoff handle)
            {
                var state=Read(Owner,"PendingHandoff");Assert.That(Field(state,"Handle"),Is.SameAs(handle));
                return ((System.Collections.IDictionary)Field(state,"Dependencies")).Values.Cast<HashSet<string>>().SelectMany(v=>v).Distinct().ToArray();
            }
            internal void AssertTransferred(TrafficIntentKey owner,IEnumerable<string> expected)
            {
                var held=new HashSet<string>(expected);
                for(var i=0;i<Waiters.Length;i++)
                {
                    var actual=(IReadOnlyList<TrafficBlocker>)Read(Waiters[i],"WaitingBlockers");
                    foreach(var resource in Resources(i))Assert.That(actual.Any(b=>b.Owner.Equals(owner) && b.ResourceId==resource),Is.EqualTo(held.Contains(resource)),
                        "PRODUCT: exact original resource transfer "+resource+" waiter="+Waiters[i].ActorId);
                }
            }
        }
        private sealed class MultiClaimMilestone : ITrafficPhaseMilestone
        {
            private readonly MultiClaimFixture fixture;private readonly TrafficDecision successorSource;private readonly string fault;
            private readonly TrafficParkingFact secondarySource;
            internal MultiClaimMilestone(MultiClaimFixture fixture,TrafficDecision successorSource,string fault)
            {
                this.fixture=fixture;this.successorSource=successorSource;this.fault=fault;
                secondarySource=fault=="copied-source"?MultiClaimFixture.Copy(fixture.Originals[1]):fixture.Originals[1];
                fixture.ReadCanonical(fixture.CounterResource,out var primary);CurrentClaim=primary;
            }
            public TrafficDecision SourcePermit=>fixture.Source;
            public TrafficParkingFact OriginalClaim=>fixture.Originals[0];
            public TrafficParkingFact CurrentClaim { get; }
            public object ActorLife=>fixture.Actor;
            public object BusinessOwner=>fixture.Business;
            public object ReleaseObligation=>fixture.Obligation;
            public TrafficPhaseMilestoneKind Kind=>fixture.Collected?TrafficPhaseMilestoneKind.Collected:TrafficPhaseMilestoneKind.Arrived;
            public bool IsCurrent=>fixture.Enabled && fixture.CanonicalMarked;
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)
            {
                current=null;
                if(!IsCurrent || captured==null || !fixture.Originals.Any(p=>ReferenceEquals(p,captured)) &&
                    (fixture.SuccessorSnapshot==null || !fixture.SuccessorSnapshot.Parking.Any(p=>ReferenceEquals(p,captured))))return TrafficPhaseClaimState.Invalid;
                if(captured.ResourceId==fixture.PickupResource && (fault=="omitted" ||
                    ReferenceEquals(captured,fixture.Originals[1]) && !ReferenceEquals(captured,secondarySource)))return TrafficPhaseClaimState.Invalid;
                if(captured.ResourceId==fixture.PickupResource && fault=="same-business-foreign-entry" &&
                    !fixture.PickupClaim.IsSameReservation(fixture.ForeignClaim))return TrafficPhaseClaimState.Invalid;
                var state=fixture.ReadCanonical(captured.ResourceId,out current);
                if(state==TrafficPhaseClaimState.Held && captured.ResourceId==fixture.PickupResource && fault=="foreign-canonical")
                    current=MultiClaimFixture.Copy(current,fixture.ForeignPickup);
                return state;
            }
            public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision sourcePermit,int firstFrame)=>IsCurrent && fixture.Collected &&
                successor.Equals(fixture.SuccessorKey) && firstFrame==fixture.CollectionFrame && successorSource!=null &&
                ReferenceEquals(sourcePermit,successorSource) && sourcePermit.Intent.Equals(successor);
        }

        // Public-Core/PQS model: a real stamped Arrived checkpoint may park without an active transaction.
        // 真实停车不消耗事务预算；真实后继 request 出现后仍使用原剩余量，不重置 deadline。
        [Test] public void IdleArrivedParkingPreservesTheSameCheckpointPastFiniteSecondsAndStillCompletes()
        {
            var f=new CanonicalSuccessorPreparationFixture();var handle=f.Begin();
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");var request=D1Read(f.Core,f.Owner,"Request");
            var leg=D1Read(f.Core,f.Owner,"Leg");var decision=f.Core.GetDecision(f.Owner);
            Assert.That(((System.Collections.IDictionary)D3ReadField(state,"Dependencies")).Count,Is.Zero);
            Assert.That(D3ReadField(state,"PreparedSuccessor"),Is.Null);Assert.That(D3ReadField(state,"PreparationRequest"),Is.Null);
            Assert.That(D3ReadField(leg,"Bound"),Is.True);Assert.That(D3ReadField(leg,"Completed"),Is.True);
            Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);Assert.That(f.World.Bodies.Single().Position,Is.EqualTo(f.End));
            var accounting=D3CaptureAccounting(f.Core,f.Owner);var queries=f.Core.QueriesConsumed(f.Owner);var version=f.Pickup.Version;
            f.Core.DrainReady();f.Core.Tick(61,false);f.Core.Tick(100,true);f.Core.Tick(0,false);
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state),
                "RED: an idle authenticated Arrived parking checkpoint must survive more than its 30-second transaction budget");
            Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(30f));Assert.That(f.Core.GetDecision(f.Owner),Is.SameAs(decision));
            Assert.That(D1Read(f.Core,f.Owner,"Request"),Is.SameAs(request));Assert.That(D1Read(f.Core,f.Owner,"Leg"),Is.SameAs(leg));
            D3AssertAccounting(f.Core,f.Owner,accounting);Assert.That(f.Core.QueriesConsumed(f.Owner),Is.EqualTo(queries));
            Assert.That(f.Pickup.Version,Is.EqualTo(version));Assert.That(f.Core.DrainReady(),Is.Empty);
            Assert.That(f.Core.HasActiveGrant(f.Owner),Is.False);Assert.That(f.Core.CanIssueLeg(f.Owner,f.Actor,7),Is.False);
            Assert.That(D3InvokeBool(f.Core,"IsCurrentPhaseHandoff",handle,f.ServiceSource,f.Actor),Is.True);
            f.Collect();var source=f.SubmitExit();Assert.That(f.Bind(handle,source),Is.True);f.Core.ProcessReady(20);
            var ready=f.Core.GetDecision(f.Exit);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            f.CommitExit(handle,ready);f.FinishExit();Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False);
        }

