        [TestCase("expired")] [TestCase("foreign-handle")] [TestCase("wrong-source")]
        [TestCase("wrong-actor")] [TestCase("replaced-body-life")] [TestCase("foreign-session")]
        public void ExactHandoffPreflightRejectsExpiredOrMismatchedActualIdentityWithoutSideEffects(string change)
        {
            var f=new HandoffFixture();var handle=f.Begin();var coordinator=f.Coordinator;var source=f.Source;object actor=f.Actor;
            if(change=="expired")
            {
                f.Coordinator.Tick(9,false);
                Assert.That(f.Coordinator.GetDecision(f.Owner).Reason,Does.Contain("original-budget-exhausted"));
            }
            if(change=="foreign-handle"){var other=new HandoffFixture();handle=other.Begin();}
            if(change=="wrong-source")
            {
                source=f.Coordinator.GetDecision(f.Owner);
                Assert.That(source.Intent,Is.EqualTo(f.Source.Intent));Assert.That(source,Is.Not.SameAs(f.Source));
            }
            if(change=="wrong-actor")actor=new object();
            if(change=="replaced-body-life")
            {
                var bodies=f.World.Bodies.Select(body=>new TrafficBodyFact(body.Owner,body.Position,body.Radius,body.Enabled,
                    body.IndependentlyProgressing,body.RemainingSeconds,body.SafetyMargin,
                    ReferenceEquals(body.ActorLife,f.Actor)?new object():body.ActorLife,body.ActorActive)).ToArray();
                f.Coordinator.SetSnapshot(World(f.World.Version,f.World.BodyVersion+1,bodies,f.World.Parking.ToArray()));
                Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.Null,"Actual public snapshot replacement invalidates old ActorLife");
            }
            if(change=="foreign-session")coordinator=new ServiceTrafficCoordinator("other-scene",1,7,World(),(from,to)=>new[]{from,to});
            var decision=f.Coordinator.GetDecision(f.Owner);var state=f.Read(f.Owner,"PendingHandoff");
            var remaining=state==null?null:D3ReadField(state,"Remaining");var queryFrame=coordinator.QueriesThisFrame;
            var ownerQueries=f.Coordinator.QueriesConsumed(f.Owner);var waiterQueries=f.Coordinator.QueriesConsumed(f.Waiter);
            var version=f.Canonical.Version;f.Coordinator.DrainReady();
            for(var i=0;i<3;i++)Assert.That(D3InvokeBool(coordinator,"IsCurrentPhaseHandoff",handle,source,actor),Is.False,change);
            Assert.That(f.Coordinator.GetDecision(f.Owner),Is.SameAs(decision));Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.SameAs(state));
            if(state!=null)Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(remaining));
            Assert.That(coordinator.QueriesThisFrame,Is.EqualTo(queryFrame));Assert.That(f.Coordinator.QueriesConsumed(f.Owner),Is.EqualTo(ownerQueries));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));Assert.That(f.Canonical.Version,Is.EqualTo(version));
            Assert.That(f.Coordinator.DrainReady(),Is.Empty);
        }

        // Public-Core model only: a stamped owner arrives while its canonical target stays far from this waiter.
        // No Native reproduction/receipt is claimed; no private Entry/Leg mutation or fabricated release.
        private static HandoffFixture VacatingHandoffModel(bool currentLeg,out TrafficIntentKey waiter,out TrafficDecision waiting)
        {
            var f=new HandoffFixture();waiter=Key("vacated-transient-waiter",currentLeg?"leg-alias-wait":"body-wait",20);
            var start=currentLeg?P(1,-3):P(0,-3);var goal=currentLeg?P(1,3):Origin;
            Assert.That(Mathf.Abs(f.End.x-goal.x),Is.GreaterThan(.8f),"FIXTURE: held endpoint is farther than pair clearance from the entire vertical waiter path");
            f.Coordinator.EvaluateMovement(Request(waiter,start,goal,f.World,frame:f.Frame,resource:"transient-only",seconds:8));
            f.Coordinator.ProcessReady(f.Frame++);waiting=f.Coordinator.GetDecision(waiter);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: genuine independent owner blocks this request before actual completion");
            Assert.That(waiting.Blockers.All(block=>block.Owner.Equals(f.Owner)),Is.True);
            Assert.That(waiting.Blockers.Any(block=>block.ResourceId==(currentLeg?f.Resource:"body")),Is.True);
            Assert.That(waiting.Blockers.All(block=>block.Proof!="canonical-parking-on-current-leg" && block.Proof!="canonical-parking-at-target"),Is.True,
                "FIXTURE: wait is for physical motion/body, not the far held canonical target");
            Assert.That(f.Frozen(waiter),Is.EquivalentTo(new[]{f.Owner}));return f;
        }

        [TestCase(false)]
        [TestCase(true)]
        public void CompletedOwnerVacatingTransientConflictAllowsOriginalWaiterSafeReproofWhileFarCanonicalClaimRemainsHeld(bool currentLeg)
        {
            var f=VacatingHandoffModel(currentLeg,out var waiter,out var waiting);
            var first=f.Read(waiter,"FirstFrame");var sequence=f.Read(waiter,"RequestSequence");var budget=f.Read(waiter,"WaitRemaining");
            var frozen=f.Read(waiter,"FrozenOwners");var frozenResources=f.Read(waiter,"FrozenResources");var queries=f.Coordinator.QueriesConsumed(waiter);
            var pending=f.Begin();Assert.That(f.LegCompleted,Is.True);Assert.That(pending,Is.Not.Null);
            var receipt=f.Receipt();Assert.That(receipt.ReadClaim(f.OriginalClaim,out var held),Is.EqualTo(TrafficPhaseClaimState.Held));
            Assert.That(held.Position,Is.EqualTo(f.End));Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.Not.Null);
            // Same producer checkpoint: publish actual completed body/claims, then notify; callback itself cannot wake.
            f.Refresh();f.Coordinator.NotifyChanged(f.Owner,"body");
            Assert.That(f.Coordinator.DrainReady(),Does.Contain(waiter),
                "PRODUCT RED: a vacated transient body/current-leg alias must not stay asleep solely because a far canonical claim remains held");
            f.Coordinator.ProcessReady(f.Frame++);var prepared=f.Coordinator.GetDecision(waiter);
            Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"Ordinary complete current-facts proof must establish safety; notification grants nothing");
            Assert.That(prepared,Is.Not.SameAs(waiting));Assert.That(f.Read(waiter,"FirstFrame"),Is.EqualTo(first));
            Assert.That(f.Read(waiter,"RequestSequence"),Is.EqualTo(sequence));Assert.That(f.Read(waiter,"WaitRemaining"),Is.EqualTo(budget));
            Assert.That(f.Read(waiter,"FrozenOwners"),Is.SameAs(frozen));Assert.That(f.Read(waiter,"FrozenResources"),Is.SameAs(frozenResources));
            Assert.That(f.Coordinator.QueriesConsumed(waiter),Is.GreaterThanOrEqualTo(queries),"Proof retains the original accounting");
            Assert.That(f.Coordinator.TryCommit(prepared),Is.True);
            Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.Not.Null,"Far canonical obligation and original handoff remain real");
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),
                "Independent control: original waiter at actual held endpoint must still wait");
            Assert.That(f.Canonical.Applies,Is.Zero);Assert.That(f.Canonical.Rollbacks,Is.Zero);
        }

        [TestCase("canonical-near")]
        [TestCase("disabled-body")]
        [TestCase("owner-retired")]
        [TestCase("actor-life-ABA")]
        [TestCase("layout")]
        public void TransientHandoffReproofCannotInventReleaseForHeldNearbyOrInvalidatedOwner(string change)
        {
            var f=VacatingHandoffModel(false,out var transient,out _);f.Begin();
            var key=change=="canonical-near"?f.Waiter:transient;
            if(change=="disabled-body"){f.Enabled=false;f.Refresh();}
            else if(change=="owner-retired")f.Coordinator.Retire(f.Owner);
            else if(change=="actor-life-ABA")
            {
                var saved=f.World;
                f.World=World(saved.Version+1,saved.BodyVersion+1,new[]{new TrafficBodyFact(f.Owner,f.End,.4f,actorLife:new object())},saved.Parking.ToArray());
                f.Coordinator.SetSnapshot(f.World);
                f.World=World(saved.Version+2,saved.BodyVersion+2,saved.Bodies.ToArray(),saved.Parking.ToArray());
                f.Coordinator.SetSnapshot(f.World); // Old instance return cannot revive the consumed original handoff.
            }
            else if(change=="layout")f.Coordinator.ResetLayout(2,8,World(20,20));
            else f.Refresh();
            f.Coordinator.NotifyChanged(f.Owner,"body");f.Coordinator.ProcessReady(f.Frame++);
            var outcome=f.Coordinator.GetDecision(key);Assert.That(outcome.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Coordinator.TryCommit(outcome),Is.False);Assert.That(f.Coordinator.HasActiveGrant(key),Is.False);
            f.Coordinator.Tick(100,false);outcome=f.Coordinator.GetDecision(key);
            Assert.That(outcome.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(outcome.Kind,Is.Not.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(f.Coordinator.TryCommit(outcome),Is.False,"Same finite wait cannot auto recover/grant after expiry or lifecycle loss");
        }

        [Test] public void CompletedTransientBodyCheckpointReproofIsOnceOnlyAndRetirementReleasesItsRecordedWaiter()
        {
            var f=VacatingHandoffModel(false,out var waiter,out _);f.Begin();f.Refresh();
            var state=f.Read(f.Owner,"PendingHandoff");var queries=f.Coordinator.QueriesConsumed(waiter);
            var remaining=f.Read(waiter,"WaitRemaining");var first=f.Read(waiter,"FirstFrame");
            var frozen=f.Read(waiter,"FrozenOwners");var frozenResources=f.Read(waiter,"FrozenResources");
            var entries=(System.Collections.IDictionary)D3ReadField(f.Coordinator,"entries");var originalEntry=entries[waiter];
            f.Coordinator.NotifyChanged(f.Owner,"body");
            Assert.That(f.Read(waiter,"Queued"),Is.True,"PRODUCT RED: actual completed body checkpoint queues the original transient-only wait");
            var request=f.Read(waiter,"Request");
            var consumed=(System.Collections.IEnumerable)D3ReadField(state,"CompletedBodyWakeups");
            Assert.That(consumed.Cast<object>().Count(value=>ReferenceEquals(value,originalEntry)),Is.EqualTo(1));
            var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");
            Assert.That(dependencies.Contains(originalEntry),Is.True,"Scheduling reproof does not claim canonical release");
            for(var duplicate=0;duplicate<8;duplicate++)
            {
                f.Coordinator.NotifyChanged(f.Owner,"body");Assert.That(f.Read(waiter,"Request"),Is.SameAs(request));
                Assert.That(f.Coordinator.QueriesConsumed(waiter),Is.EqualTo(queries));Assert.That(f.Read(waiter,"WaitRemaining"),Is.EqualTo(remaining));
                Assert.That(f.Read(waiter,"FrozenOwners"),Is.SameAs(frozen));Assert.That(f.Read(waiter,"FrozenResources"),Is.SameAs(frozenResources));
            }
            Assert.That(f.Coordinator.DrainReady().Count(key=>key.Equals(waiter)),Is.EqualTo(1));
            f.Coordinator.ProcessReady(f.Frame++);var prepared=f.Coordinator.GetDecision(waiter);
            Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Coordinator.QueriesConsumed(waiter),Is.EqualTo(queries+1),"One ordinary complete proof consumes only the original query budget");
            for(var duplicate=0;duplicate<8;duplicate++)f.Coordinator.NotifyChanged(f.Owner,"body");
            f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(waiter),Is.SameAs(prepared));Assert.That(f.Coordinator.QueriesConsumed(waiter),Is.EqualTo(queries+1));
            Assert.That(f.Read(waiter,"WaitRemaining"),Is.EqualTo(remaining));Assert.That(f.Read(waiter,"FirstFrame"),Is.EqualTo(first));
            Assert.That(dependencies.Contains(originalEntry),Is.True);Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.SameAs(state));
            f.Coordinator.Retire(waiter);
            Assert.That(dependencies.Contains(originalEntry),Is.False);Assert.That(consumed.Cast<object>().Any(value=>ReferenceEquals(value,originalEntry)),Is.False,
                "Actual waiter retirement removes its extra Entry reference from the still-live handoff state");
            Assert.That(f.Read(waiter,"Request"),Is.Null);Assert.That(f.Read(waiter,"Leg"),Is.Null);Assert.That(f.Coordinator.TryCommit(prepared),Is.False);
        }

        // Native CFC constructs pickup-wait with PlanPrimaryRoute=true; the generic Request test helper defaults false.
        // Explicit primary approach is essential: capability requirements alone never create current-path conflicts.
        private static TrafficRequest UnbornParkingPrimaryRequest(TrafficIntentKey key,TrafficWorldSnapshot world,int frame=2)
            =>new TrafficRequest(key,frame,world,P(0,-3),P(0,3),.4f,"unborn-pickup",finiteSeconds:8,planPrimaryRoute:true);
        private static ServiceTrafficCoordinator UnbornParkingWaitModel(out TrafficIntentKey moving,out TrafficIntentKey parking,
            out object actor,out TrafficDecision journey,out TrafficWorldSnapshot first)
        {
            moving=Key("temporary-owner","actual-exit",11);parking=Key("unborn-parking","pickup-wait",12);actor=new object();
            first=World(actors:new[]{new TrafficBodyFact(moving,Origin,.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:actor)});
            var core=Coordinator(first,frameBudget:256,intentBudget:256);
            journey=Grant(core,Request(moving,Origin,P(4),first,resource:"owned-actual-route",seconds:8));
            core.EvaluateParking(UnbornParkingPrimaryRequest(parking,first));core.ProcessReady(2);
            var waiting=core.GetDecision(parking);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),
                "FIXTURE: explicit primary parking approach genuinely crosses the committed independent owner's actual route");
            var movingKey=moving;Assert.That(waiting.Blockers.All(block=>block.Owner.Equals(movingKey)),Is.True);
            Assert.That(waiting.Blockers.Any(block=>block.Proof=="current-conflict-segment"),Is.True);
            Assert.That(D1Read(core,parking,"Parking"),Is.EqualTo(true));Assert.That(D1Read(core,parking,"Leg"),Is.Null);
            Assert.That(D1Read(core,parking,"EverCanonicalAttempt"),Is.EqualTo(false));Assert.That(D1Read(core,parking,"AcquiredSequence"),Is.EqualTo(0));
            Assert.That((Vector3[])D1Read(core,parking,"Journey"),Is.Empty);
            var original=(TrafficRequest)D1Read(core,parking,"Request");Assert.That(original.PlanPrimaryRoute,Is.True);Assert.That(original.SelectedJourney,Is.Empty);
            core.Tick(.5f,false);return core;
        }

        [Test] public void UnbornParkingOwnerTemporaryWaitCanReproveAroundActualStationaryBodyWithoutRenewingItsOriginalIntent()
        {
            // Public-Core model, not Unity Native receipt: committed journey -> real original strict leg waits for another independent body.
            var core=UnbornParkingWaitModel(out var moving,out var parking,out var actor,out var journey,out _);
            var entries=(System.Collections.IDictionary)D3ReadField(core,"entries");var originalEntry=entries[parking];
            var accounting=D3CaptureAccounting(core,parking);var frozen=D1Read(core,parking,"FrozenOwners");var resources=D1Read(core,parking,"FrozenResources");
            var blocker=Key("independent-next-leg-blocker");var current=World(1,2,new[]{
                new TrafficBodyFact(moving,Origin,.4f,actorLife:actor),
                new TrafficBodyFact(blocker,P(3),.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:new object())});
            // Independent public-Core control proves the exact current static-body detour; it never authorizes the main original candidate.
            var control=Coordinator(current,frameBudget:256,intentBudget:256);var proofKey=Key("geometry-control");
            control.EvaluateParking(UnbornParkingPrimaryRequest(proofKey,current,1));control.ProcessReady(1);
            var proof=control.GetDecision(proofKey);Assert.That(proof.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FIXTURE: full current-facts primary planning has a safe detour");
            var path=proof.ProofRoutes.Single().ExpandedPath;Assert.That(path.Count,Is.GreaterThan(2));
            Assert.That(CustomerRoutePlanner.IsClear(path,new[]{Origin,P(3)},.8f),Is.True,"FIXTURE: all actual bodies remain present");
            core.SetSnapshot(current);Assert.That(core.PrepareLeg(journey,"owned-actual-route",0,actor,7,current,Origin,.05f,3).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));core.ProcessReady(3);
            Assert.That(core.GetDecision(moving).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(core.GetDecision(moving).Blockers.All(block=>block.Owner.Equals(blocker)),Is.True);
            Assert.That(D1Read(core,moving,"JourneyPermit"),Is.SameAs(journey));
            var pending=core.GetDecision(parking);
            Assert.That(pending.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None),
                "PROPOSED CONTRACT RED: unborn parking gets original-budget full reproof at actual owner temporary wait, not a dead Terminal anchor");
            Assert.That(D1Read(core,parking,"Queued"),Is.EqualTo(true));Assert.That(entries[parking],Is.SameAs(originalEntry));
            D3AssertAccounting(core,parking,accounting);Assert.That(D1Read(core,parking,"FrozenOwners"),Is.SameAs(frozen));
            Assert.That(D1Read(core,parking,"FrozenResources"),Is.SameAs(resources));
            core.ProcessReady(4);var prepared=core.GetDecision(parking);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(CustomerRoutePlanner.IsClear(prepared.ProofRoutes.Single().ExpandedPath,new[]{Origin,P(3)},.8f),Is.True);
            Assert.That(D1Read(core,parking,"FirstFrame"),Is.EqualTo(accounting["FirstFrame"]));
            Assert.That(D1Read(core,parking,"WaitRemaining"),Is.EqualTo(accounting["WaitRemaining"]));
            Assert.That(core.QueriesConsumed(parking),Is.GreaterThan((int)accounting["Queries"]));Assert.That(core.QueriesConsumed(parking),Is.LessThanOrEqualTo(256));
            Assert.That(core.TryCommit(prepared),Is.True);Assert.That(core.GetDecision(moving).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
        }

        [Test] public void RetiredMovingOwnerCanAllowSafeDetourButItsOriginalSourceCannotRevive()
        {
            var core=UnbornParkingWaitModel(out var moving,out var parking,out var actor,out var journey,out _);
            var stationary=World(1,2,new[]{new TrafficBodyFact(moving,Origin,.4f,actorLife:actor)});
            core.SetSnapshot(stationary);core.Retire(moving);var retired=core.GetDecision(moving);
            Assert.That(retired.Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));Assert.That(core.TryCommit(journey),Is.False);
            core.ProcessReady(3);var reproof=core.GetDecision(parking);
            Assert.That(reproof.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"Original Retire notification may allow safe ordinary detour; it does not erase the body");
            Assert.That(CustomerRoutePlanner.IsClear(reproof.ProofRoutes.Single().ExpandedPath,new[]{Origin},.8f),Is.True);
            Assert.That(stationary.Bodies.Single().ActorLife,Is.SameAs(actor));Assert.That(core.GetDecision(moving),Is.SameAs(retired));
        }
