        [Test] public void CanonicalSuccessorPreparationBindsWithoutGrantQueryOrDeadlineRenewal()
        {
            var f=new CanonicalSuccessorPreparationFixture();var handle=f.Begin();f.Collect();var source=f.SubmitExit();
            var request=D1Read(f.Core,f.Exit,"Request");var accounting=D3CaptureAccounting(f.Core,f.Exit);
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");f.Core.Tick(1,false);
            var remaining=D3ReadField(state,"Remaining");var queries=f.Core.QueriesConsumed(f.Exit);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var actualLease),Is.True);
            Assert.That(actualLease,Is.EqualTo(f.End));Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Bound"),Is.True);
            Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Completed"),Is.True);
            Assert.That(f.Bind(handle,source),Is.True,"FEATURE: bind a real collected canonical successor, without issuing it");
            Assert.That(f.Bind(handle,source),Is.True,"Same original preparation binding is idempotent");
            Assert.That(f.Core.GetDecision(f.Exit),Is.SameAs(source));Assert.That(f.Core.HasActiveGrant(f.Exit),Is.False);
            Assert.That(D1Read(f.Core,f.Exit,"Request"),Is.SameAs(request));D3AssertAccounting(f.Core,f.Exit,accounting);
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.EqualTo(queries));Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(remaining));
            Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);Assert.That(D1Read(f.Core,f.Exit,"JourneyPermit"),Is.Null);
        }

        [Test] public void LaterMovementCannotOvertakeEarlierBoundCanonicalSuccessorPreparation()
        {
            var f=new CanonicalSuccessorPreparationFixture();var handle=f.Begin();f.StartCrossing();f.Collect();
            var initial=f.SubmitExit();var bound=f.Bind(handle,initial);f.Core.ProcessReady(20);
            var waiting=f.Core.GetDecision(f.Exit);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(waiting.Blockers.All(b=>b.Owner.Equals(f.Crossing)),Is.True);
            var frozen=D1Read(f.Core,f.Exit,"FrozenOwners");var first=D1Read(f.Core,f.Exit,"FirstFrame");
            Assert.That(first,Is.EqualTo(20));Assert.That(waiting.AcquiredSequence,Is.Zero);
            f.SubmitLater();var later=f.Core.GetDecision(f.Later);
            Assert.That(D1Read(f.Core,f.Later,"FirstFrame"),Is.EqualTo(21));
            Assert.That(later.RequestSequence,Is.GreaterThan(waiting.RequestSequence),"PREMISE: same sequence counter confirms real later processing");
            // Preserve the old product path as evidence: if it grants the later move, legally commit/bind that exact leg.
            // 不是私写Active；旧路径真实公开发腿后，原C仍由匹配stamp真实完成。
            if(later.Kind==TrafficDecisionKind.Granted)f.IssueLater(later);
            f.CompleteCrossing();f.Core.ProcessReady(23);var exit=f.Core.GetDecision(f.Exit);
            TestContext.WriteLine("CANONICAL_SUCCESSOR_ORDER bound="+bound+" later="+later.Kind+" earlier="+exit.Kind+":"+exit.Reason);
            Assert.That(later.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FEATURE: a true later move must wait for this bounded canonical handoff");
            Assert.That(bound,Is.True);Assert.That(exit.Kind,Is.EqualTo(TrafficDecisionKind.Granted),exit.Reason);
            Assert.That(D1Read(f.Core,f.Exit,"FrozenOwners"),Is.SameAs(frozen));
            CollectionAssert.AreEquivalent(new[]{f.Crossing},(HashSet<TrafficIntentKey>)frozen);
            Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(first));Assert.That(exit.RequestSequence,Is.EqualTo(waiting.RequestSequence));
            Assert.That(later.AcquiredSequence,Is.Zero);var laterWait=(float)D1Read(f.Core,f.Later,"WaitRemaining");
            Assert.That(laterWait,Is.GreaterThan(0));Assert.That(laterWait,Is.LessThanOrEqualTo(30f));
            f.Core.Tick(1,false);Assert.That((float)D1Read(f.Core,f.Later,"WaitRemaining"),Is.EqualTo(laterWait-1).Within(.0001f));
            f.CommitExit(handle,exit);f.FinishExit();f.Core.ProcessReady(26);
            var next=f.Core.GetDecision(f.Later);Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.Granted),next.Reason);
            Assert.That(next.RequestSequence,Is.EqualTo(later.RequestSequence));Assert.That(D1Read(f.Core,f.Later,"FirstFrame"),Is.EqualTo(21));
            Assert.That(f.Core.TryCommit(next),Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False);
        }

        [TestCase("no-handle")] [TestCase("foreign-actor")] [TestCase("false-completion")] [TestCase("claim-changed")]
        [TestCase("expired")] [TestCase("epoch")] [TestCase("aba")] [TestCase("collection")]
        public void CanonicalSuccessorPreparationRejectsUnownedOrExpiredActualSource(string change)
        {
            var f=new CanonicalSuccessorPreparationFixture();TrafficPhaseHandoff handle=null;
            if(change=="false-completion")
            {
                Assert.That(f.Core.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,
                    new MovementResult(f.Stamp.RequestId+1,f.Owner.ActorId,MovementStatus.Arrived,NavigationFailure.None,
                        NavigationFailure.None,NavigationFailure.None,f.End,0),f.Confirm,out handle),Is.False);
                Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Completed"),Is.False);
            }
            else handle=f.Begin();
            f.Collect();var source=f.SubmitExit(change=="foreign-actor"?Key("foreign-preparation","actual-exit",14):(TrafficIntentKey?)null);
            if(change=="no-handle")handle=null;
            if(change=="claim-changed" || change=="aba"){f.ReplaceClaim(change=="aba");source=f.SubmitExit();}
            if(change=="expired")
            {f.Core.Tick(31,false);Assert.That(f.Core.GetDecision(f.Owner).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));}
            if(change=="epoch")f.Core.ResetLayout(2,7,f.World);
            if(change=="collection")f.CollectionSequence++;
            var key=source.Intent;var registered=D3ContainsIntent(f.Core,key);
            var current=f.Core.GetDecision(key);var request=registered?D1Read(f.Core,key,"Request"):null;
            var queries=f.Core.QueriesConsumed(key);var version=f.Pickup.Version;var frameQueries=f.Core.QueriesThisFrame;
            f.Core.DrainReady();
            Assert.That(f.Bind(handle,source),Is.False,change);
            Assert.That(f.Core.HasActiveGrant(key),Is.False);Assert.That(D3ContainsIntent(f.Core,key),Is.EqualTo(registered));
            if(registered){Assert.That(f.Core.GetDecision(key),Is.SameAs(current));Assert.That(D1Read(f.Core,key,"Request"),Is.SameAs(request));}
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo(queries));Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(frameQueries));
            Assert.That(f.Pickup.Version,Is.EqualTo(version));Assert.That(f.Core.DrainReady(),Is.Empty);
        }

        // Real canonical Pickup lease + public stamped Core lifecycle; this is a model, not a Native receipt.
        // service使用真实旧collection lease读取；不借reservation checkpoint冒充service授权。
        [Test] public void BoundCanonicalSuccessorSurvivesSameLifeNavigationGapWithoutGrantOrRenewal()
        {
            var f=new CanonicalSuccessorPreparationFixture();var handle=f.Begin();f.Collect();var initial=f.SubmitExit();
            Assert.That(f.Bind(handle,initial),Is.True,"PREMISE: real completed/bound service with authenticated original collection lease");
            var pending=D1Read(f.Core,f.Owner,"PendingHandoff");var binding=D3ReadField(pending,"PreparedSuccessor");
            var descriptor=D3ReadField(pending,"PreparationRequest");var remaining=D3ReadField(pending,"Remaining");
            var phase=f.Core.GetDecision(f.Owner);var queries=f.Core.QueriesConsumed(f.Exit);var version=f.Pickup.Version;
            TrafficWorldSnapshot Navigation(bool enabled)=>World(f.World.Version,f.World.BodyVersion+1,
                f.World.Bodies.Select(b=>new TrafficBodyFact(b.Owner,b.Position,b.Radius,enabled,b.IndependentlyProgressing,
                    b.RemainingSeconds,b.SafetyMargin,b.ActorLife,b.ActorActive)).ToArray(),f.World.Parking.ToArray());
            f.World=Navigation(false);f.Core.SetSnapshot(f.World);
            Assert.That(f.World.Bodies.Single().Enabled,Is.False);Assert.That(f.World.Bodies.Single().ActorActive,Is.True);
            Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True,"PREMISE: no release, ABA, pose or canonical claim change");
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(pending),"FEATURE: Nav-only unavailability cannot abort the completed canonical gap");
            Assert.That(D3ReadField(pending,"PreparedSuccessor"),Is.SameAs(binding));Assert.That(D3ReadField(pending,"PreparationRequest"),Is.SameAs(descriptor));
            Assert.That(D3ReadField(pending,"Remaining"),Is.EqualTo(remaining));Assert.That(f.Core.GetDecision(f.Owner),Is.SameAs(phase));
            Assert.That(f.Core.GetDecision(f.Exit),Is.SameAs(initial));Assert.That(f.Core.HasActiveGrant(f.Exit),Is.False);
            Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);Assert.That(D1Read(f.Core,f.Exit,"JourneyPermit"),Is.Null);
            Assert.That(f.Core.CanIssueLeg(f.Exit,f.Actor,8),Is.False);Assert.That(f.Core.TryCommit(initial),Is.False);
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.EqualTo(queries));Assert.That(f.Pickup.Version,Is.EqualTo(version));
            f.World=Navigation(true);f.Core.SetSnapshot(f.World);
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(pending));Assert.That(D3ReadField(pending,"PreparedSuccessor"),Is.SameAs(binding));
            Assert.That(D3ReadField(pending,"Remaining"),Is.EqualTo(remaining));f.Core.ProcessReady(20);
            var ready=f.Core.GetDecision(f.Exit);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(f.Core.TryCommit(ready),Is.True,"Restored same Entry may continue its ordinary current-world primary proof");
            Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(20));Assert.That(D3ReadField(pending,"PreparedSuccessor"),Is.SameAs(binding));
            Assert.That(f.Core.CanIssueLeg(f.Exit,f.Actor,8),Is.False,"Primary proof is still not a strict Native issue permission");
        }

