            Assert.That(f.Core.TryCommit(primary),Is.True);Assert.That(primary.AcquiredSequence,Is.GreaterThan(0));
            Assert.That(D1Read(f.Core,f.Exit,"JourneyPermit"),Is.SameAs(primary));Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);
            f.Milestone.SelectedSource=primary;TrafficDecision firstLater=null;var laterFrame=laterBeforeStrictLeg?21:23;
            void SubmitLaterAtActualFrame()
            {
                firstLater=f.Core.EvaluateMovement(Request(f.Later,P(3,-2),P(3,2),f.World,frame:laterFrame,resource:"paid-movement",seconds:30));
                Assert.That(firstLater.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Assert.That(D1Read(f.Core,f.Later,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(D1Read(f.Core,f.Later,"Leg"),Is.Null);
                Assert.That(D1Read(f.Core,f.Later,"FrozenOwners"),Is.Null,"PREMISE: the later preparation has not frozen any dependency");
                f.Core.ProcessReady(laterFrame);firstLater=f.Core.GetDecision(f.Later);
            }
            if(laterBeforeStrictLeg)SubmitLaterAtActualFrame();
            f.PrepareCrossingApproachContinuation(crossingSource); // Publish C's actual completed approach before either queued input is captured.
            Assert.That(f.Core.PrepareLeg(primary,f.PickupResource,0,f.Actor,8,f.World,f.End,.05f,22).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            f.Core.ProcessReady(22);f.CommitCrossingApproachContinuation(); // Same snapshot; true birth10 C is evaluated before birth20 A.
            var waiting=f.Core.GetDecision(f.Exit);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(waiting.Blockers.All(blocker=>blocker.Owner.Equals(f.Crossing)),Is.True);
            var frozen=D1Read(f.Core,f.Exit,"FrozenOwners");CollectionAssert.AreEquivalent(new[]{f.Crossing},(HashSet<TrafficIntentKey>)frozen);
            var leg=D1Read(f.Core,f.Exit,"Leg");Assert.That(D3ReadField(leg,"Committed"),Is.EqualTo(false));
            Assert.That(D3ReadField(leg,"Bound"),Is.EqualTo(false));Assert.That(D3ReadField(leg,"Stamp"),Is.EqualTo(default(TrafficNativeStamp)));
            Assert.That(D1Read(f.Core,f.Exit,"AcquiredSequence"),Is.EqualTo(primary.AcquiredSequence));
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(handoff));Assert.That(D3ReadField(handoff,"PreparedSuccessor"),Is.SameAs(binding));
            Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var held),Is.True);
            Assert.That(held,Is.EqualTo(f.End));Assert.That(f.Core.CanIssueLeg(f.Exit,f.Actor,8),Is.False);
            Assert.That(D1Read(f.Core,f.Crossing,"FirstFrame"),Is.EqualTo(10));Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(20));
            var accounting=D3CaptureAccounting(f.Core,f.Exit);var age=D1Read(f.Core,f.Exit,"FirstFrame");
            if(!laterBeforeStrictLeg)SubmitLaterAtActualFrame();
            var later=f.Core.GetDecision(f.Later);
            Assert.That(D1Read(f.Core,f.Later,"FirstFrame"),Is.EqualTo(laterFrame));Assert.That(later.RequestSequence,Is.EqualTo(firstLater.RequestSequence));
            Assert.That(D1Read(f.Core,f.Later,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(D1Read(f.Core,f.Later,"Leg"),Is.Null);
            Assert.That(later.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FEATURE RED: a later route must keep the original bounded canonical ordering across primary acquisition and the first strict wait");
            Assert.That(later.Reason,Is.EqualTo("bounded-phase-handoff"));Assert.That(later.Blockers.All(blocker=>blocker.Owner.Equals(f.Owner)),Is.True);
            CollectionAssert.AreEquivalent(new[]{f.Owner},(HashSet<TrafficIntentKey>)D1Read(f.Core,f.Later,"FrozenOwners"));
            Assert.That(f.Core.TryCommit(later),Is.False);Assert.That(D1Read(f.Core,f.Exit,"FrozenOwners"),Is.SameAs(frozen));
            Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(age));D3AssertAccounting(f.Core,f.Exit,accounting);
            var remaining=(float)D1Read(f.Core,f.Later,"WaitRemaining");Assert.That(remaining,Is.GreaterThan(0));Assert.That(remaining,Is.LessThanOrEqualTo(30));
            f.Core.Tick(.25f,false);Assert.That((float)D1Read(f.Core,f.Later,"WaitRemaining"),Is.EqualTo(remaining-.25f).Within(.0001f));
            f.CompleteCrossingApproachRemainder();f.Core.ProcessReady(24);var ready=f.Core.GetDecision(f.Exit);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            f.CommitAlreadyPreparedExit(handle,ready);f.FinishExit();f.Core.ProcessReady(26);
            var resumed=f.Core.GetDecision(f.Later);Assert.That(resumed.Kind,Is.EqualTo(TrafficDecisionKind.Granted),resumed.Reason);
            Assert.That(D1Read(f.Core,f.Later,"FirstFrame"),Is.EqualTo(laterFrame));Assert.That(resumed.RequestSequence,Is.EqualTo(firstLater.RequestSequence));
            Assert.That(f.Core.TryCommit(resumed),Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False);
        }

        [TestCase("unbound")]
        [TestCase("lease-ABA")]
        public void AcquiredSuccessorOrderingNeedsItsStillAuthenticOriginalCanonicalBinding(string authority)
        {
            var f=new CanonicalSuccessorPreparationFixture();var crossingSource=f.StartCrossingApproach();
            var handle=f.Begin();f.Collect();var initial=f.SubmitExit();
            if(authority!="unbound")Assert.That(f.Bind(handle,initial),Is.True,"PREMISE: the ABA control first binds a genuine original lease while successor acquired0");
            f.Core.ProcessReady(20);var primary=f.Core.GetDecision(f.Exit);Assert.That(primary.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Core.TryCommit(primary),Is.True);Assert.That(primary.AcquiredSequence,Is.GreaterThan(0));f.Milestone.SelectedSource=primary;
            f.PrepareCrossingApproachContinuation(crossingSource);
