            CollectionAssert.AreEquivalent(new[]{f.Crossing},(HashSet<TrafficIntentKey>)D1Read(f.Core,f.Exit,"FrozenOwners"));
            if(authority=="lease-ABA")
            {
                f.ReplaceClaim(true);Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var actual),Is.True);
                Assert.That(f.OriginalLease.IsSameReservation(actual),Is.False);Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.False);
                Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var retained),Is.True);Assert.That(retained,Is.EqualTo(f.End));
                Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null,"PREMISE: actual original Entry/lease retirement aborts the old canonical binding, despite same geometry");
            }
            else
            {
                var pending=D1Read(f.Core,f.Owner,"PendingHandoff");Assert.That(pending,Is.Not.Null);
                Assert.That(D3ReadField(pending,"PreparedSuccessor"),Is.Null,"PREMISE: generic acquired/unissued waiting route has no canonical preparation authorization");
                Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            }
            var initialLater=f.Core.EvaluateMovement(Request(f.Later,P(3,-2),P(3,2),f.World,frame:23,resource:"paid-movement",seconds:30));
            Assert.That(initialLater.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
            Assert.That(D1Read(f.Core,f.Later,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(D1Read(f.Core,f.Later,"FrozenOwners"),Is.Null);
            f.Core.ProcessReady(23);var later=f.Core.GetDecision(f.Later);
            Assert.That(later.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"Absent a current authenticated binding, original generic policy remains: no global sleeping-route priority");
            Assert.That(D1Read(f.Core,f.Later,"FrozenOwners"),Is.Null);Assert.That(D1Read(f.Core,f.Later,"Leg"),Is.Null);
            Assert.That(D1Read(f.Core,f.Later,"FirstFrame"),Is.EqualTo(23));Assert.That(f.Core.TryCommit(later),Is.True);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var kept),Is.True);Assert.That(kept,Is.EqualTo(f.End));
        }

        [Test]
        public void BoundCanonicalExitEndpointWaitRetainsOnlyItsAuthenticCapabilityOrderingBeforeAnyNewPathQuery()
        {
            var f=new CanonicalSuccessorPreparationFixture();
            var originalRequest=(TrafficRequest)D1Read(f.Core,f.Owner,"JourneyRequest");
            var requirement=originalRequest.Requirements.Single(proof=>proof.ResourceId=="collection-exit-capability");
            var capability=f.ServiceSource.ProofRoutes.Single(proof=>proof.ResourceId==requirement.ResourceId);
            Assert.That(requirement.SelectedJourney,Is.False,"PREMISE: the completed service certifies capability, not a selected/issued exit journey");
            Assert.That(requirement.Start,Is.EqualTo(f.End));Assert.That(requirement.Goal,Is.EqualTo(f.Goal));
            CollectionAssert.AreEqual(new[]{f.End,f.Goal},capability.ExpandedPath,"PREMISE: original public query really completed this model capability before C occupied the endpoint");
            var sourceQueries=f.Core.QueriesConsumed(f.Owner);Assert.That(sourceQueries,Is.GreaterThanOrEqualTo(2));
            var handle=f.Begin();Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Bound"),Is.EqualTo(true));
            Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Completed"),Is.EqualTo(true));
            f.StartExitEndpointCrossing();f.Collect();
            f.Candidate=new TrafficRequest(f.Exit,20,f.World,f.ActualPosition,f.Goal,.4f,f.PickupResource,
                independentlyProgressing:true,finiteSeconds:30,planPrimaryRoute:true);
            var initial=f.Core.EvaluateMovement(f.Candidate);f.Milestone=new CanonicalPreparationMilestone(f,f.Candidate,initial);
            Assert.That(f.Candidate.Intent.Session,Is.EqualTo(f.ServiceSource.Intent.Session));Assert.That(f.Candidate.Intent.Epoch,Is.EqualTo(f.ServiceSource.Intent.Epoch));
            Assert.That(f.Candidate.Intent.LayoutRevision,Is.EqualTo(f.ServiceSource.Intent.LayoutRevision));
            Assert.That(f.Bind(handle,initial),Is.True,"PREMISE: real held collection lease and stamped-completed predecessor bind the authentic unacquired exit");
            f.Core.ProcessReady(20);var waiting=f.Core.GetDecision(f.Exit);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(waiting.Blockers.All(blocker=>blocker.Owner.Equals(f.Crossing)&&blocker.ResourceId=="body"&&blocker.Proof=="live-body-checkpoint"),Is.True);
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero,"PREMISE: the original endpoint branch runs before any new exit query");
            Assert.That(((System.Collections.ICollection)D1Read(f.Core,f.Exit,"Jobs")).Count,Is.Zero);
            Assert.That(D1Read(f.Core,f.Exit,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);
            Assert.That(D1Read(f.Core,f.Exit,"JourneyPermit"),Is.Null);Assert.That(f.Core.CanIssueLeg(f.Exit,f.Actor,8),Is.False);
            var frozen=D1Read(f.Core,f.Exit,"FrozenOwners");CollectionAssert.AreEquivalent(new[]{f.Crossing},(HashSet<TrafficIntentKey>)frozen);
            Assert.That(D1Read(f.Core,f.Crossing,"FirstFrame"),Is.EqualTo(10));Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(20));
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,f.Exit);var first=D1Read(f.Core,f.Exit,"FirstFrame");
            var initialLater=f.Core.EvaluateMovement(Request(f.Later,P(3,-2),P(3,2),f.World,frame:21,resource:"paid-movement",seconds:30));
            Assert.That(initialLater.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(D1Read(f.Core,f.Later,"FrozenOwners"),Is.Null);
            Assert.That(D1Read(f.Core,f.Later,"AcquiredSequence"),Is.EqualTo(0L));f.Core.ProcessReady(21);var later=f.Core.GetDecision(f.Later);
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero);Assert.That(f.Core.QueriesConsumed(f.Owner),Is.EqualTo(sourceQueries));
            Assert.That(((System.Collections.ICollection)D1Read(f.Core,f.Exit,"Jobs")).Count,Is.Zero);D3AssertAccounting(f.Core,f.Exit,accounting);
            Assert.That(later.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FEATURE RED: missing new exit geometry cannot erase this bounded authenticated original capability ordering");
            Assert.That(later.Reason,Is.EqualTo("bounded-phase-handoff"));Assert.That(later.Blockers.All(blocker=>blocker.Owner.Equals(f.Owner)),Is.True);
            CollectionAssert.AreEquivalent(new[]{f.Owner},(HashSet<TrafficIntentKey>)D1Read(f.Core,f.Later,"FrozenOwners"));
            Assert.That(later.AcquiredSequence,Is.Zero);Assert.That(f.Core.TryCommit(later),Is.False);Assert.That(f.Core.CanIssueLeg(f.Exit,f.Actor,8),Is.False);
            Assert.That(D1Read(f.Core,f.Exit,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(first));
            var sequence=later.RequestSequence;var remaining=(float)D1Read(f.Core,f.Later,"WaitRemaining");Assert.That(remaining,Is.GreaterThan(0));
            Assert.That(remaining,Is.LessThanOrEqualTo(29.75f));f.Core.Tick(.25f,false);
            Assert.That((float)D1Read(f.Core,f.Later,"WaitRemaining"),Is.EqualTo(remaining-.25f).Within(.0001f));
            f.CompleteExitEndpointCrossing();f.Core.ProcessReady(23);var ready=f.Core.GetDecision(f.Exit);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);Assert.That(f.Core.QueriesConsumed(f.Exit),Is.GreaterThan(0),"Ordinary fresh exit proof is still required after C really releases");
            f.CommitExit(handle,ready);f.FinishExit();f.Core.ProcessReady(26);var resumed=f.Core.GetDecision(f.Later);
            Assert.That(resumed.Kind,Is.EqualTo(TrafficDecisionKind.Granted),resumed.Reason);Assert.That(resumed.RequestSequence,Is.EqualTo(sequence));
            Assert.That(D1Read(f.Core,f.Later,"FirstFrame"),Is.EqualTo(21));Assert.That(f.Core.TryCommit(resumed),Is.True);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False);
        }

        [TestCase("no-proof")]
        [TestCase("wrong-start")]
        [TestCase("wrong-goal")]
        [TestCase("unbound")]
        [TestCase("expired")]
        [TestCase("lease-ABA")]
        public void ZeroQueryCanonicalOrderingNeedsItsOriginalMatchingCapabilityAndLiveAuthority(string guard)
        {
            var mode=guard=="no-proof"?"none":guard=="wrong-start"?"wrong-start":guard=="wrong-goal"?"wrong-goal":"valid";
            var f=new CanonicalSuccessorPreparationFixture(mode);var source=(TrafficRequest)D1Read(f.Core,f.Owner,"JourneyRequest");
            if(mode=="none")Assert.That(f.ServiceSource.ProofRoutes.Any(proof=>proof.ResourceId=="collection-exit-capability"),Is.False);
            else
            {
                var requirement=source.Requirements.Single(proof=>proof.ResourceId=="collection-exit-capability");
                var capability=f.ServiceSource.ProofRoutes.Single(proof=>proof.ResourceId==requirement.ResourceId);
                Assert.That(requirement.SelectedJourney,Is.False);Assert.That(capability.ExpandedPath.Count,Is.GreaterThan(1));
                if(mode=="wrong-start")Assert.That(requirement.Start.Equals(f.End),Is.False);
                if(mode=="wrong-goal")Assert.That(requirement.Goal.Equals(f.Goal),Is.False);
                // Both malformed-role certificates still geometrically cross B's x=3, z=-2..2 corridor.
                // 否定依据必须是真实role/端点不匹配，而不是碰巧不相交。
                Assert.That(capability.ExpandedPath[0].x,Is.EqualTo(0));Assert.That(capability.ExpandedPath[capability.ExpandedPath.Count-1].x,Is.EqualTo(4));
                Assert.That(capability.ExpandedPath.All(point=>point.z>=0 && point.z<=1),Is.True);
            }
            var handle=f.Begin();f.StartExitEndpointCrossing();f.Collect();
            f.Candidate=new TrafficRequest(f.Exit,20,f.World,f.ActualPosition,f.Goal,.4f,f.PickupResource,
                independentlyProgressing:true,finiteSeconds:30,planPrimaryRoute:true);
            var initial=f.Core.EvaluateMovement(f.Candidate);f.Milestone=new CanonicalPreparationMilestone(f,f.Candidate,initial);
            if(guard!="unbound")Assert.That(f.Bind(handle,initial),Is.True,"PREMISE: these controls first authenticate a real held completed canonical phase");
            f.Core.ProcessReady(20);Assert.That(f.Core.GetDecision(f.Exit).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero);Assert.That(((System.Collections.ICollection)D1Read(f.Core,f.Exit,"Jobs")).Count,Is.Zero);
            if(guard=="expired")
            {
                f.Core.Tick(31,false);Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
                Assert.That(f.Core.GetDecision(f.Exit).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                f.Core.Retire(f.Crossing); // Retired actual source is not claimed as finite progress after the controlled expiry.
            }
            else if(guard=="lease-ABA")
            {
                f.ReplaceClaim(true);Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var actual),Is.True);
                Assert.That(f.OriginalLease.IsSameReservation(actual),Is.False);Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.False);
                Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
            }
            else if(guard=="unbound")Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"PendingHandoff"),"PreparedSuccessor"),Is.Null);
            var first=f.Core.EvaluateMovement(Request(f.Later,P(3,-2),P(3,2),f.World,frame:21,resource:"paid-movement",seconds:30));
            Assert.That(first.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(D1Read(f.Core,f.Later,"FrozenOwners"),Is.Null);
            f.Core.ProcessReady(21);var later=f.Core.GetDecision(f.Later);
            Assert.That(later.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"Missing original role or live authority must retain ordinary policy, never manufacture unknown-path priority");
            Assert.That(D1Read(f.Core,f.Later,"FrozenOwners"),Is.Null);Assert.That(D1Read(f.Core,f.Later,"Leg"),Is.Null);
            Assert.That(f.Core.TryCommit(later),Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var held),Is.True);
            Assert.That(held,Is.EqualTo(f.End),"Ordering proof cannot release even an expired or replaced real physical lease");
        }

        [Test]
        public void MovedUnacquiredCanonicalAnchorKeepsItsExistingFullyBoundedHandoffAsleepUntilRealTransfer()
        {
            var f=new CanonicalSuccessorPreparationFixture();var key=Key("moved-unborn-admission","counter-admission",41);
            var start=P(-3,-1);var oldTarget=P(3,-1);var resource="counter/"+key.ActorId;
            var request=new TrafficRequest(key,10,f.World,start,oldTarget,.4f,resource,finiteSeconds:30,planPrimaryRoute:true);
            Assert.That(ParkingEndpointHint(f.Core,request),Is.True,"PREMISE: the original incoming endpoint is genuinely available before Submit");
            f.Core.EvaluateParking(request);f.Core.ProcessReady(10);var original=f.Core.GetDecision(key);
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),original.Reason);
            Assert.That(original.Blockers,Is.Not.Empty);
            Assert.That(original.Blockers.All(b=>b.Owner.Equals(f.Owner)&&b.ResourceId==f.PickupResource&&b.Proof=="current-conflict-segment"),Is.True,
                "PREMISE: real primary approach crosses the earlier issued service segment, while both canonical endpoints are clear");
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));Assert.That(D1Read(f.Core,key,"Leg"),Is.Null);
            Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(f.Core.DrainReady(),Is.Empty);
            var handle=f.Begin();var waiting=f.Core.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false),"PREMISE: real final stamped completion captures this still sleeping waiter without Notify");
            var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");Assert.That(state,Is.Not.Null);
            var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");Assert.That(dependencies.Contains(entry),Is.True);
            var eligible=(HashSet<string>)dependencies[entry];Assert.That(eligible,Does.Contain(f.PickupResource));
            foreach(var blocker in waiting.Blockers)
                Assert.That(D3InvokeBool(f.Core,"HoldsHandoffDependency",entry,blocker.Owner,blocker.ResourceId),Is.True,
                    "PREMISE: every exact original edge is covered by the actual bounded completed-phase handle");
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,key);var queries=f.Core.QueriesThisFrame;
            var frozen=D1Read(f.Core,key,"FrozenOwners");var frozenResources=D1Read(f.Core,key,"FrozenResources");var edges=D1Read(f.Core,key,"WaitingBlockers");
            Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);Assert.That((float)D3ReadField(state,"Remaining"),Is.GreaterThan(0));
            var moved=new TrafficRequest(key,10,f.World,start,f.End,.4f,resource,finiteSeconds:30,planPrimaryRoute:true);
            Assert.That(moved.Target.Equals(request.Target),Is.False);
            Assert.That(CfcReprepare(f.Core,waiting,moved,out var refreshed),Is.True,"The existing API must still accept the authentic same-anchor metadata refresh");
            Assert.That(((TrafficRequest)D1Read(f.Core,key,"Request")).Target,Is.EqualTo(f.End),"Metadata adopts the true new queue target without granting its geometry");
            Assert.That(refreshed,Is.SameAs(waiting),"FEATURE RED: moved metadata cannot wake a real fully covered sleeping handoff dependency before the sole strict transfer");
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));
            Assert.That(entries[key],Is.SameAs(entry));Assert.That(D1Read(f.Core,key,"FrozenOwners"),Is.SameAs(frozen));
            Assert.That(D1Read(f.Core,key,"FrozenResources"),Is.SameAs(frozenResources));Assert.That(D1Read(f.Core,key,"WaitingBlockers"),Is.SameAs(edges));
            D3AssertAccounting(f.Core,key,accounting);Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(queries));
            Assert.That(f.Core.TryCommit(refreshed),Is.False);Assert.That(f.Core.CanIssueLeg(key,new object(),1),Is.False);
            Assert.That(f.Core.DrainReady(),Is.Empty);Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state));
            f.Core.Tick(.25f,false);Assert.That((float)D1Read(f.Core,key,"WaitRemaining"),Is.EqualTo((float)accounting["WaitRemaining"]-.25f).Within(.0001f));
            f.Core.ProcessReady(11);Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo((int)accounting["Queries"]));
            // A model Arrived receipt/real queue lease, never an alias or early primary permission, owns this transfer.
            // 只有原 strict handoff 接续和真实 lease 释放后，旧有限 waiter 才重新验证新目标的几何。
            f.Collect();var initial=f.SubmitExit();Assert.That(f.Bind(handle,initial),Is.True);f.Core.ProcessReady(20);
            var exit=f.Core.GetDecision(f.Exit);Assert.That(exit.Kind,Is.EqualTo(TrafficDecisionKind.Granted),exit.Reason);
            f.CommitExit(handle,exit);Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
            Assert.That(((HashSet<TrafficIntentKey>)D1Read(f.Core,key,"FrozenOwners")),Does.Contain(f.Exit));
            Assert.That(((HashSet<TrafficIntentKey>)D1Read(f.Core,key,"FrozenOwners")).Contains(f.Owner),Is.False);
            f.FinishExit();f.Core.ProcessReady(26);var resumed=f.Core.GetDecision(key);
            Assert.That(resumed.Kind,Is.EqualTo(TrafficDecisionKind.Granted),resumed.Reason);
            Assert.That(resumed.RequestSequence,Is.EqualTo(waiting.RequestSequence));Assert.That(D1Read(f.Core,key,"FirstFrame"),Is.EqualTo(10));
            Assert.That(f.Core.QueriesConsumed(key),Is.GreaterThan((int)accounting["Queries"]),"New target still requires ordinary fresh route proof after actual release");
            Assert.That(resumed.Route.Last(),Is.EqualTo(f.End));Assert.That(f.Core.TryCommit(resumed),Is.True);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False);
        }

        [TestCase("ordinary-owner")]
        [TestCase("mixed-owner")]
        [TestCase("notified-transfer")]
        [TestCase("expired")]
        public void MovedCanonicalAnchorCannotSuppressOrdinaryWakeUncoveredOwnersOrOriginalExpiry(string guard)
        {
            var f=new CanonicalSuccessorPreparationFixture();var key=Key("moved-anchor-guard","counter-admission",42);
            var second=Key("second-original-owner","finite-crossing",6);var start=P(-3,-1);var target=P(3,-1);var resource="counter/"+key.ActorId;
            if(guard=="mixed-owner")
            {
                // Independent public Core movement owner, not a forged private dependency or Native receipt.
                // 第二个既有有限owner由公开query+commit取得；不伪造Native或写私有Entry。
                f.Core.EvaluateMovement(Request(second,P(-1,-2),P(-1,0),f.World,frame:3,resource:"second-crossing",seconds:30));
                f.Core.ProcessReady(3);var other=f.Core.GetDecision(second);
                Assert.That(other.Kind,Is.EqualTo(TrafficDecisionKind.Granted),other.Reason);
                Assert.That(f.Core.TryCommit(other),Is.True);Assert.That(f.Core.HasActiveGrant(second),Is.True);
            }
            var request=new TrafficRequest(key,10,f.World,start,target,.4f,resource,finiteSeconds:30,planPrimaryRoute:true);
            Assert.That(ParkingEndpointHint(f.Core,request),Is.True);f.Core.EvaluateParking(request);f.Core.ProcessReady(10);
            var waiting=f.Core.GetDecision(key);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));Assert.That(waiting.Blockers.Any(b=>b.Owner.Equals(f.Owner)),Is.True);
            TrafficPhaseHandoff handle=null;
            if(guard!="ordinary-owner")
            {
                handle=f.Begin();waiting=f.Core.GetDecision(key);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Not.Null);
                var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var state=D1Read(f.Core,f.Owner,"PendingHandoff");
                var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");Assert.That(dependencies.Contains(entries[key]),Is.True);
                if(guard=="mixed-owner")
                {
                    Assert.That(waiting.Blockers.Any(b=>b.Owner.Equals(second)),Is.True,"PREMISE: both original finite owners genuinely blocked this primary approach");
                    Assert.That(waiting.Blockers.Any(b=>!D3InvokeBool(f.Core,"HoldsHandoffDependency",entries[key],b.Owner,b.ResourceId)),Is.True,
                        "PREMISE: the first real completed-phase handle covers only part of the original wait");
                }
                if(guard=="notified-transfer")
                {
                    f.Collect();var initial=f.SubmitExit();Assert.That(f.Bind(handle,initial),Is.True);f.Core.ProcessReady(20);
                    var exit=f.Core.GetDecision(f.Exit);Assert.That(exit.Kind,Is.EqualTo(TrafficDecisionKind.Granted),exit.Reason);f.CommitExit(handle,exit);
                    waiting=f.Core.GetDecision(key);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                    Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true),"PREMISE: sole real strict handoff has actually transferred and queued this dependency");
                    Assert.That(((HashSet<TrafficIntentKey>)D1Read(f.Core,key,"FrozenOwners")),Does.Contain(f.Exit));
                    Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);Assert.That(f.Core.DrainReady(),Does.Contain(key));
                }
                if(guard=="expired")
                {
                    f.Core.Tick(31,false);waiting=f.Core.GetDecision(key);
                    Assert.That(waiting.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
                }
            }
            var accounting=D3CaptureAccounting(f.Core,key);var source=D1Read(f.Core,key,"Request");var queries=f.Core.QueriesThisFrame;
            var moved=new TrafficRequest(key,10,f.World,start,f.End,.4f,resource,finiteSeconds:30,planPrimaryRoute:true);
            if(guard=="expired")
            {
                Assert.That(CfcReprepare(f.Core,waiting,moved,out var rejected),Is.False);Assert.That(rejected,Is.Null);
                Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));Assert.That(D1Read(f.Core,key,"Request"),Is.SameAs(source));
            }
            else
            {
                Assert.That(CfcReprepare(f.Core,waiting,moved,out var next),Is.True);
                Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"CONTROL: metadata with no full sleeping handoff authority keeps the original ordinary reproof scheduling");
                Assert.That(next,Is.Not.SameAs(waiting));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true));
                Assert.That(f.Core.TryCommit(waiting),Is.False);Assert.That(f.Core.TryCommit(next),Is.False);
                Assert.That(((TrafficRequest)D1Read(f.Core,key,"Request")).Target,Is.EqualTo(f.End));
            }
            D3AssertAccounting(f.Core,key,accounting);Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(queries));
        }

        [Test]
        public void BoundCollectedInitialExitRefreshesItsOriginalSnapshotBeforeTheOrdinaryReadyQuery()
        {
            var f=new CanonicalSuccessorPreparationFixture();var handle=f.Begin();f.Collect();
