            var foreign=Key("foreign-counter-arrival","counter-admission",71);var point=P(20,4);var life=new object();
            var counter=new CounterQueueService(new[]{point});var business=new object();var obligation=new object();
            Assert.That(counter.TryJoin(foreign.ActorId),Is.True);Assert.That(counter.TryCaptureAssignment(foreign.ActorId,out var beforeClaim),Is.True);
            Assert.That(beforeClaim.IsCurrent,Is.True);Assert.That(beforeClaim.Assignment.Arrived,Is.False);
            TrafficParkingFact ForeignFact(CounterQueueService.AssignmentClaim claim)=>new TrafficParkingFact(foreign,counter,claim.CapturedOwnerVersion,
                "counter/"+foreign.ActorId,claim.Assignment.Position,.4f,businessOwner:business,releaseObligation:obligation,semanticCheckpoint:claim);
            var originalWorld=f.World;
            var foreignBefore=new TrafficBodyFact(foreign,point,.4f,true,true,8,actorLife:life);
            f.World=World(originalWorld.Version+1,originalWorld.BodyVersion+1,originalWorld.Bodies.Concat(new[]{foreignBefore}).ToArray(),
                originalWorld.Parking.Concat(new[]{ForeignFact(beforeClaim)}).ToArray());f.Core.SetSnapshot(f.World);
            f.Candidate=new TrafficRequest(f.Exit,20,f.World,f.ActualPosition,f.Goal,.4f,f.PickupResource,
                requirements:Array.Empty<TrafficRouteRequirement>(),finiteSeconds:30,planPrimaryRoute:true);
            var original=f.Core.EvaluateMovement(f.Candidate);f.Milestone=new CanonicalPreparationMilestone(f,f.Candidate,original);
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(original.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(f.Bind(handle,original),Is.True,"PREMISE: original collected milestone binds the real queued successor before any route query");
            var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[f.Exit];
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");var oldRequest=(TrafficRequest)D1Read(f.Core,f.Exit,"Request");
            Assert.That(D3ReadField(state,"PreparedSuccessor"),Is.SameAs(entry));Assert.That(D3ReadField(state,"PreparationMilestone"),Is.SameAs(f.Milestone));
            Assert.That(D1Read(f.Core,f.Exit,"Queued"),Is.EqualTo(true));Assert.That(D1Read(f.Core,f.Exit,"Parking"),Is.EqualTo(false));
            Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);Assert.That(D1Read(f.Core,f.Exit,"JourneyPermit"),Is.Null);Assert.That(D1Read(f.Core,f.Exit,"JourneyRequest"),Is.Null);
            Assert.That(D1Read(f.Core,f.Exit,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero);
            Assert.That(oldRequest.PlanPrimaryRoute,Is.True);Assert.That(oldRequest.SelectedJourney,Is.Empty);Assert.That(oldRequest.Requirements,Is.Empty);
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,f.Exit);var remaining=(float)D3ReadField(state,"Remaining");
            var ownBody=f.World.Bodies.Single(b=>b.Owner.ActorId==f.Owner.ActorId);var ownClaims=f.World.Parking.Where(p=>p.Owner.ActorId==f.Owner.ActorId).ToArray();
            var previous=f.World;var pickupVersion=f.Pickup.Version;var counterVersion=counter.Version;
            // Public Queue completion models an unrelated arrival checkpoint; this is not a Native movement receipt.
            // 外部Queue真实Complete只改变别人的metadata/进度；本Exit的原actor、held claims和角色描述均不改变。
            Assert.That(counter.Complete(foreign.ActorId,beforeClaim.Assignment.Generation),Is.True);
            Assert.That(counter.Version,Is.GreaterThan(counterVersion));Assert.That(counter.TryCaptureAssignment(foreign.ActorId,out var afterClaim),Is.True);
            Assert.That(afterClaim.Assignment.Arrived,Is.True);Assert.That(beforeClaim.IsSameReservation(afterClaim),Is.True);
            var foreignAfter=new TrafficBodyFact(foreign,point,.4f,true,false,0,actorLife:life);
            f.World=World(previous.Version+1,previous.BodyVersion+1,previous.Bodies.Select(b=>b.Owner.Equals(foreign)?foreignAfter:b).ToArray(),
                previous.Parking.Where(p=>!p.Owner.Equals(foreign)).Concat(new[]{ForeignFact(afterClaim)}).ToArray());f.Core.SetSnapshot(f.World);
            Assert.That(f.World.Version,Is.GreaterThan(oldRequest.Snapshot.Version));Assert.That(f.World.Bodies.Single(b=>b.Owner.ActorId==f.Owner.ActorId),Is.SameAs(ownBody));
            CollectionAssert.AreEqual(ownClaims,f.World.Parking.Where(p=>p.Owner.ActorId==f.Owner.ActorId));
            Assert.That(D3InvokeBool(f.Core,"IsCurrentPhaseHandoff",handle,f.ServiceSource,f.Actor),Is.True,"PREMISE: the real logical handoff survives this foreign world-version change");
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state));Assert.That(D3ReadField(state,"PreparedSuccessor"),Is.SameAs(entry));
            Assert.That(D3ReadField(state,"PreparationMilestone"),Is.SameAs(f.Milestone));Assert.That(f.Core.GetDecision(f.Exit),Is.SameAs(original));
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero);Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            f.Core.ProcessReady(21);var ready=f.Core.GetDecision(f.Exit);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),
                "FEATURE RED: a real bound queued collected Exit needs authenticated current-world preparation before the ordinary first query; "+ready.Reason);
            Assert.That(((TrafficRequest)D1Read(f.Core,f.Exit,"Request")).Snapshot,Is.SameAs(f.World));
            Assert.That(ready.ProofRoutes.Count,Is.EqualTo(1));Assert.That(ready.ProofRoutes.Single().ResourceId,Is.EqualTo(f.PickupResource));
            Assert.That(ready.Route.Last(),Is.EqualTo(f.Goal));Assert.That(f.Core.QueriesConsumed(f.Exit),Is.EqualTo(1));
            var retained=accounting.Where(pair=>pair.Key!="Queries"&&pair.Key!="RequestSequence").ToDictionary(pair=>pair.Key,pair=>pair.Value);D3AssertAccounting(f.Core,f.Exit,retained);
            Assert.That(ready.RequestSequence,Is.GreaterThan(0));Assert.That(D1Read(f.Core,f.Exit,"RequestSequence"),Is.EqualTo(ready.RequestSequence));
            Assert.That(D1Read(f.Core,f.Exit,"FirstFrame"),Is.EqualTo(20));Assert.That((float)D3ReadField(state,"Remaining"),Is.EqualTo(remaining));
            Assert.That(f.Pickup.Version,Is.EqualTo(pickupVersion));Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var held),Is.True);Assert.That(held,Is.EqualTo(f.End));
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state));Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);
            Assert.That(f.Core.CanIssueLeg(f.Exit,f.Actor,8),Is.False,"Prepared primary proof is not a strict handoff, Native arrival or employee delivery acceptance");
        }

