            Assert.That(refused.Reason,Is.EqualTo("snapshot-changed"));Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero);
            Assert.That(D1Read(f.Core,f.Exit,"Request"),Is.SameAs(originalRequest));Assert.That(((TrafficRequest)originalRequest).Snapshot,Is.SameAs(oldWorld));
