        private static TrafficDecision BindInitialExitPreparationProbe(CanonicalSuccessorPreparationFixture f,TrafficPhaseHandoff handle,out InitialExitMilestoneProbe probe)
        {
            f.Candidate=new TrafficRequest(f.Exit,20,f.World,f.ActualPosition,f.Goal,.4f,f.PickupResource,
                requirements:Array.Empty<TrafficRouteRequirement>(),finiteSeconds:30,planPrimaryRoute:true);
            var original=f.Core.EvaluateMovement(f.Candidate);f.Milestone=new CanonicalPreparationMilestone(f,f.Candidate,original);
            probe=new InitialExitMilestoneProbe(f.Milestone);
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(original.AcquiredSequence,Is.Zero);
            Assert.That(D3InvokeBool(f.Core,"TryBindPhaseHandoffSuccessorPreparation",handle,original,f.Candidate,probe),Is.True);
            Assert.That(D1Read(f.Core,f.Exit,"Queued"),Is.EqualTo(true));Assert.That(D1Read(f.Core,f.Exit,"Leg"),Is.Null);
            Assert.That(f.Core.QueriesConsumed(f.Exit),Is.Zero);return original;
        }
        private static void AdvanceInitialExitPreparationWorld(CanonicalSuccessorPreparationFixture f)
        {
            // Legal immutable snapshot metadata; original bodies and every real Queue claim are retained.
            // 模型只发布新world版本；不伪造业务完成、Native到达或私有Entry状态。
            f.World=World(f.World.Version+1,f.World.BodyVersion+1,f.World.Bodies.ToArray(),f.World.Parking.ToArray());f.Core.SetSnapshot(f.World);
        }
        private sealed class InitialExitMilestoneProbe:ITrafficPhaseMilestone
        {
            private readonly ITrafficPhaseMilestone inner;internal int Authorizations;internal Action OnAuthorize;
            internal InitialExitMilestoneProbe(ITrafficPhaseMilestone inner){this.inner=inner;}
            public TrafficDecision SourcePermit=>inner.SourcePermit;public TrafficParkingFact OriginalClaim=>inner.OriginalClaim;
            public TrafficParkingFact CurrentClaim=>inner.CurrentClaim;public object ActorLife=>inner.ActorLife;
            public object BusinessOwner=>inner.BusinessOwner;public object ReleaseObligation=>inner.ReleaseObligation;
            public TrafficPhaseMilestoneKind Kind=>inner.Kind;public bool IsCurrent=>inner.IsCurrent;
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)=>inner.ReadClaim(captured,out current);
            public bool AuthorizesSuccessor(TrafficIntentKey key,TrafficDecision source,int first)
            {Authorizations++;var action=OnAuthorize;OnAuthorize=null;action?.Invoke();return inner.AuthorizesSuccessor(key,source,first);}
        }

        // Public analytic model of the Native-shape delivery proposal, not a replay of the Native middle frame.
        // 真实PQS持有停车位；公开Bind/Complete提供完成证据，不写Core Entry或伪造资源释放。
        private static CanonicalSuccessorPreparationFixture PaidWaitParkingCompletionModel(bool selectedHome,
            out TrafficIntentKey key,out TrafficDecision waiting)
        {
            key=Key("paid-wait-completion-proposal",selectedHome?"employee-pickup-journey":"counter-admission",61);
            var work=P(-3,-2);var target=P(3,-2);var life=new object();
            var f=new CanonicalSuccessorPreparationFixture(new TrafficBodyFact(Key(key.ActorId,"body",2),work,.4f,actorLife:life),paidWaitOnly:true);
            var requirements=selectedHome?new[]{new TrafficRouteRequirement("selected-home",target,work,.8f,selectedJourney:true,avoidProposedParking:false)}:Array.Empty<TrafficRouteRequirement>();
            var request=new TrafficRequest(key,10,f.World,work,target,.4f,"pickup/"+key.ActorId,
                requirements:requirements,finiteSeconds:30,planPrimaryRoute:true);
            f.Core.EvaluateParking(request);f.Core.ProcessReady(10);waiting=f.Core.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"PREMISE: actual unissued proposal waits: "+waiting.Reason);
            Assert.That(waiting.Blockers.Count,Is.EqualTo(2));
            Assert.That(waiting.Blockers.Count(b=>b.Owner.Equals(f.Owner)&&b.ResourceId=="body"&&b.Proof=="live-body-checkpoint"),Is.EqualTo(1));
            Assert.That(waiting.Blockers.Count(b=>b.Owner.Equals(f.Owner)&&b.ResourceId==f.PickupResource&&b.Proof=="current-conflict-segment"),Is.EqualTo(1));
            Assert.That(D1Read(f.Core,key,"Parking"),Is.EqualTo(true));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));
            Assert.That(D1Read(f.Core,key,"Leg"),Is.Null);Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));
            Assert.That(D1Read(f.Core,key,"JourneyPermit"),Is.Null);Assert.That(D1Read(f.Core,key,"JourneyRequest"),Is.Null);
            Assert.That(((TrafficRequest)D1Read(f.Core,key,"Request")).Requirements.Count(r=>r.SelectedJourney),Is.EqualTo(selectedHome?1:0));
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo(selectedHome?2:1));
            var ownerLeg=D1Read(f.Core,f.Owner,"Leg");Assert.That(D3ReadField(ownerLeg,"Bound"),Is.EqualTo(true));
            Assert.That(D3ReadField(ownerLeg,"Completed"),Is.EqualTo(false));Assert.That(D3ReadField(ownerLeg,"Stamp"),Is.EqualTo(f.Stamp));
            Assert.That(f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner)).IndependentlyProgressing,Is.True);
            Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var claim),Is.True);Assert.That(claim.IsCurrent,Is.True);
            Assert.That(claim.Assignment.Position,Is.EqualTo(f.End));Assert.That(claim.Assignment.Arrived,Is.False);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False,"PREMISE: this is a paid wait arrival, not a collected/service lease fixture");
            var jobs=(System.Collections.IList)D1Read(f.Core,key,"Jobs");Assert.That(jobs.Count,Is.EqualTo(selectedHome?2:1));
            foreach(var job in jobs)
            {
                var path=(Vector3[])D3ReadField(job,"<ExpandedPath>k__BackingField");
                Assert.That(path.Length,Is.GreaterThanOrEqualTo(2));
                Assert.That(CustomerRoutePlanner.IsClear(path,new[]{f.End},.8f),Is.True,"PREMISE: after actual arrival the held pickup point is clear of every original selected route");
                Assert.That(CustomerRoutePlanner.IsClear(path,new[]{f.Start},.8f),Is.False,"PREMISE: before arrival the actual moving body occupies these routes");
            }
            return f;
        }

        [Test]
        public void CompletedPaidPickupReproofAcceptsOneCornerCompleteStationaryPreservationRequirement()
        {
            // Unity may return one valid corner for start==goal; this nonselected capability is not movement authority.
            // 公开query只对真实同点返回一个corner；不写Job/Entry，不把能力proof当Native移动。
            var key=Key("single-corner-paid-wait-proposal","employee-pickup-journey",62);var work=P(-3,-2);var target=P(3,-2);var preserve=P(5,3);var actor=new object();
            var f=new CanonicalSuccessorPreparationFixture(new TrafficBodyFact(Key(key.ActorId,"body",2),work,.4f,actorLife:actor),paidWaitOnly:true,singletonStationaryQuery:true);
            var requirements=new[]{new TrafficRouteRequirement("preserve-current-goal",preserve,preserve,.8f),
                new TrafficRouteRequirement("selected-home",target,work,.8f,selectedJourney:true,avoidProposedParking:false)};
            f.Core.EvaluateParking(new TrafficRequest(key,10,f.World,work,target,.4f,"pickup/"+key.ActorId,
                requirements:requirements,finiteSeconds:30,planPrimaryRoute:true));f.Core.ProcessReady(10);var waiting=f.Core.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"PREMISE: all jobs completed before finite wait: "+waiting.Reason);
            Assert.That(waiting.Blockers.Count,Is.EqualTo(2));Assert.That(waiting.Blockers.Count(b=>b.Owner.Equals(f.Owner)&&b.ResourceId=="body"&&b.Proof=="live-body-checkpoint"),Is.EqualTo(1));
            Assert.That(waiting.Blockers.Count(b=>b.Owner.Equals(f.Owner)&&b.ResourceId==f.PickupResource&&b.Proof=="current-conflict-segment"),Is.EqualTo(1));
            var jobs=(System.Collections.IList)D1Read(f.Core,key,"Jobs");Assert.That(jobs.Count,Is.EqualTo(3));Assert.That(D1Read(f.Core,key,"JobIndex"),Is.EqualTo(3));
            var zero=jobs[1];Assert.That(D3ReadField(zero,"start"),Is.EqualTo(preserve));Assert.That(D3ReadField(zero,"goal"),Is.EqualTo(preserve));
            CollectionAssert.AreEqual(new[]{preserve},(Vector3[])D3ReadField(zero,"<ExpandedPath>k__BackingField"));
            CollectionAssert.AreEqual(new[]{preserve},(Vector3[])D3ReadField(zero,"<Waypoints>k__BackingField"));
            CollectionAssert.AreEqual(new[]{0},(int[])D3ReadField(zero,"<LegEnds>k__BackingField"));
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo(3));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));
            Assert.That(D1Read(f.Core,key,"Leg"),Is.Null);Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));
            Assert.That(D1Read(f.Core,key,"JourneyPermit"),Is.Null);Assert.That(D1Read(f.Core,key,"JourneyRequest"),Is.Null);
            var before=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(before.IndependentlyProgressing,Is.True);
            var ownerLeg=D1Read(f.Core,f.Owner,"Leg");Assert.That(D3ReadField(ownerLeg,"Bound"),Is.EqualTo(true));Assert.That(D3ReadField(ownerLeg,"Completed"),Is.EqualTo(false));
            f.Core.Tick(.5f,false);Assert.That(f.BeginPaidWait(),Is.Not.Null);
            var after=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(after.Owner,Is.EqualTo(before.Owner));Assert.That(after.ActorLife,Is.SameAs(before.ActorLife));
            Assert.That(after.IndependentlyProgressing,Is.False);Assert.That(after.Position,Is.EqualTo(f.End));
            Assert.That(D1Read(f.Core,f.Owner,"Leg"),Is.SameAs(ownerLeg));Assert.That(D3ReadField(ownerLeg,"Completed"),Is.EqualTo(true));Assert.That(D3ReadField(ownerLeg,"Stamp"),Is.EqualTo(f.Stamp));
            Assert.That((Vector3[])D1Read(f.Core,f.Owner,"CurrentPath"),Is.Empty);Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var held),Is.True);
            Assert.That(held.IsCurrent&&held.Assignment.Arrived&&f.OriginalLease.IsSameReservation(held),Is.True);
            foreach(var job in jobs)Assert.That(CustomerRoutePlanner.IsClear((Vector3[])D3ReadField(job,"<ExpandedPath>k__BackingField"),new[]{f.End},.8f),Is.True,
                "PREMISE: all original complete route geometry, including the single stationary corner, is clear of the actual parked owner");
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];
            var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");Assert.That(dependencies.Contains(entry),Is.True);
            CollectionAssert.AreEquivalent(new[]{"body",f.PickupResource},(HashSet<string>)dependencies[entry]);
            var accounting=D3CaptureAccounting(f.Core,key);var version=f.Pickup.Version;var q=f.Core.QueriesThisFrame;
            var frozen=D1Read(f.Core,key,"FrozenOwners");var resources=D1Read(f.Core,key,"FrozenResources");
            f.Core.NotifyChanged(f.Owner,"body");
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true),
                "FEATURE RED: an actually complete one-corner stationary requirement cannot turn the original selected continuation into an incomplete-job wait");
            Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));Assert.That(f.Core.TryCommit(waiting),Is.False);D3AssertAccounting(f.Core,key,accounting);Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(q));
            var refreshed=D1Read(f.Core,key,"Request");for(var duplicate=0;duplicate<5;duplicate++)
            {f.Core.NotifyChanged(f.Owner,"body");Assert.That(D1Read(f.Core,key,"Request"),Is.SameAs(refreshed));D3AssertAccounting(f.Core,key,accounting);}
            Assert.That(f.Core.DrainReady().Count(k=>k.Equals(key)),Is.EqualTo(1));f.Core.ProcessReady(11);var ready=f.Core.GetDecision(key);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            CollectionAssert.AreEqual(new[]{"pickup/"+key.ActorId,"preserve-current-goal","selected-home"},ready.ProofRoutes.Select(proof=>proof.ResourceId).ToArray());
            var preserved=ready.ProofRoutes.Single(proof=>proof.ResourceId=="preserve-current-goal");CollectionAssert.AreEqual(new[]{preserve},preserved.ExpandedPath);
            CollectionAssert.AreEqual(new[]{preserve},preserved.Waypoints);CollectionAssert.AreEqual(new[]{0},preserved.LegEnds);
            foreach(var proof in ready.ProofRoutes)Assert.That(CustomerRoutePlanner.IsClear(proof.ExpandedPath,new[]{f.End},.8f),Is.True);
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo((int)accounting["Queries"]+3));
            D3AssertAccounting(f.Core,key,accounting.Where(pair=>pair.Key!="Queries").ToDictionary(pair=>pair.Key,pair=>pair.Value));
            Assert.That(D1Read(f.Core,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(f.Pickup.Version,Is.EqualTo(version));Assert.That(held.IsCurrent,Is.True);Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state));
            Assert.That(D3ReadField(ownerLeg,"Stamp"),Is.EqualTo(f.Stamp));Assert.That(f.Core.HasActiveGrant(key),Is.False);Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));
        }

        [Test]
        public void CompletedPaidPickupArrivalQueuesOriginalOutwardAndSelectedHomeForOneBoundedReproof()
        {
            var f=PaidWaitParkingCompletionModel(true,out var key,out var waiting);var before=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));
            f.Core.Tick(.5f,false);var handle=f.BeginPaidWait();Assert.That(handle,Is.Not.Null);
            var after=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(after.Owner,Is.EqualTo(before.Owner));
            Assert.That(after.ActorLife,Is.SameAs(before.ActorLife));Assert.That(after.IndependentlyProgressing,Is.False);Assert.That(after.Position,Is.EqualTo(f.End));
            var ownerLeg=D1Read(f.Core,f.Owner,"Leg");Assert.That(D3ReadField(ownerLeg,"Bound"),Is.EqualTo(true));
            Assert.That(D3ReadField(ownerLeg,"Completed"),Is.EqualTo(true));Assert.That(D3ReadField(ownerLeg,"Stamp"),Is.EqualTo(f.Stamp));
            Assert.That((Vector3[])D1Read(f.Core,f.Owner,"CurrentPath"),Is.Empty);
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];
            var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");Assert.That(dependencies.Contains(entry),Is.True);
            CollectionAssert.AreEquivalent(new[]{"body",f.PickupResource},(HashSet<string>)dependencies[entry]);
            Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var held),Is.True);Assert.That(f.OriginalLease.IsSameReservation(held),Is.True);
            Assert.That(held.IsCurrent&&held.Assignment.Arrived,Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.False);
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,key);var version=f.Pickup.Version;var q=f.Core.QueriesThisFrame;
            var frozen=D1Read(f.Core,key,"FrozenOwners");var resources=D1Read(f.Core,key,"FrozenResources");
            // Same true->false body checkpoint emitted by CFC after public stamped completion; no invented Native authority.
            f.Core.NotifyChanged(f.Owner,"body");
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true),
                "FEATURE RED: completed paid arrival must queue one full physical reproof for its original unacquired outward+selected-home proposal");
            Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));D3AssertAccounting(f.Core,key,accounting);
            Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(q));Assert.That(f.Core.TryCommit(waiting),Is.False);
            var refreshed=D1Read(f.Core,key,"Request");var consumed=(System.Collections.IEnumerable)D3ReadField(state,"CompletedBodyWakeups");
            Assert.That(consumed.Cast<object>().Count(value=>ReferenceEquals(value,entry)),Is.EqualTo(1));
            for(var repeat=0;repeat<6;repeat++)
            {f.Core.NotifyChanged(f.Owner,"body");Assert.That(D1Read(f.Core,key,"Request"),Is.SameAs(refreshed));D3AssertAccounting(f.Core,key,accounting);}
            Assert.That(f.Core.DrainReady().Count(k=>k.Equals(key)),Is.EqualTo(1));f.Core.ProcessReady(11);
            var proof=f.Core.GetDecision(key);Assert.That(proof.Kind,Is.EqualTo(TrafficDecisionKind.Granted),proof.Reason);
            CollectionAssert.AreEqual(new[]{"pickup/"+key.ActorId,"selected-home"},proof.ProofRoutes.Select(route=>route.ResourceId).ToArray());
            foreach(var route in proof.ProofRoutes)Assert.That(CustomerRoutePlanner.IsClear(route.ExpandedPath,new[]{f.End},.8f),Is.True);
            Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo((int)accounting["Queries"]+2));
            D3AssertAccounting(f.Core,key,accounting.Where(pair=>pair.Key!="Queries").ToDictionary(pair=>pair.Key,pair=>pair.Value));
            Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));Assert.That(f.Core.HasActiveGrant(key),Is.False,"Fresh geometric proof is not a joint delivery or Native commit");
            Assert.That(D1Read(f.Core,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(f.Pickup.Version,Is.EqualTo(version));Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var retained),Is.True);
            Assert.That(held.IsSameReservation(retained)&&retained.IsCurrent,Is.True);Assert.That(retained.Assignment,Is.EqualTo(held.Assignment));
            Assert.That(D1Read(f.Core,f.Owner,"Leg"),Is.SameAs(ownerLeg));Assert.That(D3ReadField(ownerLeg,"Stamp"),Is.EqualTo(f.Stamp));
            Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state));Assert.That(dependencies.Contains(entry),Is.True);
            for(var repeat=0;repeat<4;repeat++)f.Core.NotifyChanged(f.Owner,"body");f.Core.ProcessReady(12);
            Assert.That(f.Core.GetDecision(key),Is.SameAs(proof));Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo((int)accounting["Queries"]+2));
        }

