        [TestCase(false)]
        [TestCase(true)]
        public void CompletedPaidPickupReproofCannotReviveTerminalOrGrantThroughActualBlockedGoal(bool blockedGoal)
        {
            var f=PaidWaitParkingCompletionModel(true,out var key,out _);f.BeginPaidWait();
            if(blockedGoal)
            {
                var saved=f.World;f.World=World(saved.Version+1,saved.BodyVersion+1,saved.Bodies.Concat(new[]{
                    new TrafficBodyFact(Key("new-real-static-goal-body","body"),P(3,-2),.4f,actorLife:new object())}).ToArray(),saved.Parking.ToArray());
                f.Core.SetSnapshot(f.World);
            }
            else f.Core.Tick(100,false);
            var original=f.Core.GetDecision(key);var accounting=D3CaptureAccounting(f.Core,key);
            for(var repeat=0;repeat<6;repeat++)f.Core.NotifyChanged(f.Owner,"body");f.Core.ProcessReady(11);
            var outcome=f.Core.GetDecision(key);Assert.That(outcome.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Core.TryCommit(outcome),Is.False);
            Assert.That(f.Core.HasActiveGrant(key),Is.False);Assert.That(f.Pickup.TryCaptureReservation(f.Owner.ActorId,out var held),Is.True);
            Assert.That(held.IsCurrent&&held.Assignment.Arrived&&f.OriginalLease.IsSameReservation(held),Is.True);
            if(!blockedGoal){Assert.That(outcome,Is.SameAs(original));Assert.That(outcome.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));D3AssertAccounting(f.Core,key,accounting);}
            f.Core.Tick(100,false);var terminal=f.Core.GetDecision(key);Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            f.Core.NotifyChanged(f.Owner,"body");f.Core.ProcessReady(12);Assert.That(f.Core.GetDecision(key),Is.SameAs(terminal));Assert.That(f.Core.TryCommit(terminal),Is.False);
        }

        [Test]
        public void CompletedActualPickupJourneyWakesItsOriginalParkingCandidateForOneFreshBoundedProof()
        {
            var key=Key("waiting-delivery","employee-pickup-journey",51);var bodyKey=Key(key.ActorId,"body",2);var actor=new object();
            var work=P(3,-1);var target=P(0,-1);var employee=new TrafficBodyFact(bodyKey,work,.4f,actorLife:actor);
            var f=new CanonicalSuccessorPreparationFixture(extraBody:employee);
            var requirements=new[]{new TrafficRouteRequirement("selected-home",target,work,.8f,new[]{f.Start,f.End},selectedJourney:true,avoidProposedParking:false)};
            var request=new TrafficRequest(key,10,f.World,work,target,.4f,"pickup/"+key.ActorId,requirements:requirements,finiteSeconds:30,planPrimaryRoute:true);
            f.Core.EvaluateParking(request);f.Core.ProcessReady(10);var waiting=f.Core.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(waiting.Blockers,Is.Not.Empty);Assert.That(waiting.Blockers.All(b=>b.Owner.Equals(f.Owner)&&
                b.ResourceId==f.PickupResource&&b.Proof=="selected-journey-parking-protection"),Is.True,
                "PREMISE: only the real previously selected journey protects this candidate endpoint; current bodies/canonical points do not overlap it");
            Assert.That(D1Read(f.Core,key,"Parking"),Is.EqualTo(true));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));
            Assert.That(D1Read(f.Core,key,"Leg"),Is.Null);Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));
            Assert.That(f.Core.QueriesConsumed(key),Is.Zero);Assert.That((System.Collections.IList)D1Read(f.Core,key,"Jobs"),Is.Empty);
            var before=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(before.IndependentlyProgressing,Is.True);
            var beforeEmployee=f.World.Bodies.Single(b=>b.Owner.ActorId==key.ActorId);Assert.That(beforeEmployee.ActorLife,Is.SameAs(actor));
            f.Core.Tick(.5f,false);var handle=f.Begin();Assert.That(handle,Is.Not.Null);
            var after=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(after.Owner,Is.EqualTo(before.Owner));
            Assert.That(after.ActorLife,Is.SameAs(before.ActorLife));Assert.That(after.Enabled&&after.ActorActive,Is.True);
            Assert.That(after.IndependentlyProgressing,Is.False);Assert.That(after.Position,Is.EqualTo(f.End));
            Assert.That(f.World.Bodies.Single(b=>b.Owner.ActorId==key.ActorId).ActorLife,Is.SameAs(actor));
            var leg=D1Read(f.Core,f.Owner,"Leg");Assert.That(D3ReadField(leg,"Bound"),Is.EqualTo(true));
            Assert.That(D3ReadField(leg,"Completed"),Is.EqualTo(true));Assert.That(D3ReadField(leg,"Stamp"),Is.EqualTo(f.Stamp));
            var state=D1Read(f.Core,f.Owner,"PendingHandoff");var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];
            var dependencies=(System.Collections.IDictionary)D3ReadField(state,"Dependencies");Assert.That(dependencies.Contains(entry),Is.True);
            Assert.That(D3InvokeBool(f.Core,"HoldsHandoffDependency",entry,f.Owner,f.PickupResource),Is.True);
            Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var heldService),Is.True);
            Assert.That(heldService,Is.EqualTo(f.End));Assert.That(f.Pickup.TryGetReservation(f.Owner.ActorId,out var heldPickup),Is.True);
            Assert.That(Vector3.Distance(target,heldService),Is.GreaterThan(.8f));Assert.That(Vector3.Distance(target,heldPickup.Position),Is.GreaterThan(.8f));
            Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,key);var queueVersion=f.Pickup.Version;var queries=f.Core.QueriesThisFrame;
            var frozen=D1Read(f.Core,key,"FrozenOwners");var resources=D1Read(f.Core,key,"FrozenResources");
            // Existing CFC RefreshTrafficSnapshot emits this public event on the asserted real progress true->false transition.
            // 这是同真实actor/owner且已完成 stamped Arrived 的公开模型事件；不是额外Native回执或凭空唤醒。
            f.Core.NotifyChanged(f.Owner,"body");
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(true),
                "FEATURE RED: completed selected-journey endpoint protection must schedule one ordinary fresh parking proof while real canonical claims remain held");
            Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));D3AssertAccounting(f.Core,key,accounting);
            Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(queries));Assert.That(f.Core.TryCommit(waiting),Is.False);
            var currentRequest=D1Read(f.Core,key,"Request");var consumed=(System.Collections.IEnumerable)D3ReadField(state,"CompletedBodyWakeups");
            Assert.That(consumed.Cast<object>().Count(value=>ReferenceEquals(value,entry)),Is.EqualTo(1));
            for(var duplicate=0;duplicate<6;duplicate++)
            {f.Core.NotifyChanged(f.Owner,"body");Assert.That(D1Read(f.Core,key,"Request"),Is.SameAs(currentRequest));D3AssertAccounting(f.Core,key,accounting);}
            Assert.That(f.Core.DrainReady().Count(value=>value.Equals(key)),Is.EqualTo(1));f.Core.ProcessReady(11);
            var ready=f.Core.GetDecision(key);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(ready.ProofRoutes.Select(proof=>proof.ResourceId),Is.EquivalentTo(new[]{request.ResourceId,"selected-home"}));
            Assert.That(ready.ProofRoutes.All(proof=>proof.ExpandedPath.Count>=2),Is.True);Assert.That(f.Core.QueriesConsumed(key),Is.EqualTo(2));
            var retained=accounting.Where(pair=>pair.Key!="Queries").ToDictionary(pair=>pair.Key,pair=>pair.Value);D3AssertAccounting(f.Core,key,retained);
            Assert.That(D1Read(f.Core,key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(f.Core,key,"FrozenResources"),Is.SameAs(resources));
            Assert.That(f.Pickup.Version,Is.EqualTo(queueVersion));Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out heldService),Is.True);Assert.That(heldService,Is.EqualTo(f.End));
            Assert.That(f.Pickup.TryGetReservation(f.Owner.ActorId,out heldPickup),Is.True);Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.SameAs(state));
            Assert.That(dependencies.Contains(entry),Is.True,"Reproof schedules old geometry; it never declares its canonical release obligation released");
            Assert.That(f.Core.TryCommit(ready),Is.True,"Kernel permission alone; this model does not claim an employee canonical delivery commit or Native movement");
        }

        [TestCase("held-overlap")]
        [TestCase("not-completed")]
        [TestCase("expired")]
        [TestCase("actor-life-ABA")]
        [TestCase("later-static-body")]
        public void ParkingJourneyCheckpointCannotReleaseRealClaimsSkipActualCompletionOrCrossNewStaticFacts(string guard)
        {
            var key=Key("delivery-checkpoint-guard","employee-pickup-journey",52);var bodyKey=Key(key.ActorId,"body",2);var actor=new object();var work=P(3,-1);
            var f=new CanonicalSuccessorPreparationFixture(extraBody:new TrafficBodyFact(bodyKey,work,.4f,actorLife:actor));
            var target=guard=="held-overlap"?P(0,-.5f):P(0,-1);
            var request=new TrafficRequest(key,10,f.World,work,target,.4f,"pickup/"+key.ActorId,
                requirements:new[]{new TrafficRouteRequirement("selected-home",target,work,.8f,new[]{f.Start,f.End},selectedJourney:true,avoidProposedParking:false)},
                finiteSeconds:30,planPrimaryRoute:true);
            f.Core.EvaluateParking(request);f.Core.ProcessReady(10);var waiting=f.Core.GetDecision(key);
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);Assert.That(D1Read(f.Core,key,"Parking"),Is.EqualTo(true));
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));Assert.That(f.Core.QueriesConsumed(key),Is.Zero);
            if(guard=="held-overlap")
                Assert.That(waiting.Blockers.Any(b=>b.Owner.Equals(f.Owner)&&b.ResourceId==f.ServiceResource&&b.Proof.StartsWith("canonical-parking-version:")),Is.True,
                    "PREMISE: a real held service claim itself overlaps this target; the source movement alias is not its release");
            else Assert.That(waiting.Blockers.All(b=>b.Owner.Equals(f.Owner)&&b.ResourceId==f.PickupResource&&b.Proof=="selected-journey-parking-protection"),Is.True);
            var before=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(before.IndependentlyProgressing,Is.True);
            if(guard!="not-completed")
            {
                Assert.That(f.Begin(),Is.Not.Null);var after=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));
                Assert.That(after.ActorLife,Is.SameAs(before.ActorLife));Assert.That(after.Owner,Is.EqualTo(before.Owner));Assert.That(after.IndependentlyProgressing,Is.False);
                Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Completed"),Is.EqualTo(true));
            }
            else
            {
                Assert.That(D3ReadField(D1Read(f.Core,f.Owner,"Leg"),"Completed"),Is.EqualTo(false));Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
                Assert.That(f.Core.HasActiveGrant(f.Owner),Is.True,"PREMISE: this public Notify below is an adversarial invalid checkpoint, never a claimed real completion event");
            }
            if(guard=="actor-life-ABA")
            {
                var saved=f.World;
                f.World=World(saved.Version+1,saved.BodyVersion+1,saved.Bodies.Select(b=>b.Owner.ActorId==f.Owner.ActorId?
                    new TrafficBodyFact(b.Owner,b.Position,b.Radius,b.Enabled,b.IndependentlyProgressing,b.RemainingSeconds,b.SafetyMargin,new object(),b.ActorActive):b).ToArray(),saved.Parking.ToArray());
                f.Core.SetSnapshot(f.World);Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);
                f.World=World(saved.Version+2,saved.BodyVersion+2,saved.Bodies.ToArray(),saved.Parking.ToArray());f.Core.SetSnapshot(f.World);
            }
            if(guard=="later-static-body")
            {
                f.World=World(f.World.Version+1,f.World.BodyVersion+1,f.World.Bodies.Concat(new[]{new TrafficBodyFact(Key("new-static-parking-blocker"),target,.4f,actorLife:new object())}).ToArray(),f.World.Parking.ToArray());
                f.Core.SetSnapshot(f.World);
            }
            if(guard=="expired")
            {f.Core.Tick(31,false);Assert.That(f.Core.GetDecision(key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(D1Read(f.Core,f.Owner,"PendingHandoff"),Is.Null);}
            else f.Core.Tick(.25f,false);
            var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];var remaining=(float)D1Read(f.Core,key,"WaitRemaining");
            var first=D1Read(f.Core,key,"FirstFrame");var sequence=D1Read(f.Core,key,"RequestSequence");var queueVersion=f.Pickup.Version;
            f.Core.NotifyChanged(f.Owner,"body");Assert.That(f.Core.TryCommit(waiting),Is.False);f.Core.ProcessReady(11);
            var outcome=f.Core.GetDecision(key);Assert.That(outcome.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Core.TryCommit(outcome),Is.False);
            Assert.That(f.Pickup.Version,Is.EqualTo(queueVersion));Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            Assert.That(f.Pickup.TryGetReservation(f.Owner.ActorId,out _),Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out var held),Is.True);
            Assert.That(held,Is.EqualTo(f.End));Assert.That((float)D1Read(f.Core,key,"WaitRemaining"),Is.LessThanOrEqualTo(remaining));
            Assert.That(entries[key],Is.SameAs(entry));Assert.That(D1Read(f.Core,key,"FirstFrame"),Is.EqualTo(first));Assert.That(D1Read(f.Core,key,"RequestSequence"),Is.EqualTo(sequence));
            Assert.That(D1Read(f.Core,key,"AcquiredSequence"),Is.EqualTo(0L));f.Core.Tick(100,false);outcome=f.Core.GetDecision(key);
            Assert.That(outcome.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(f.Core.TryCommit(outcome),Is.False);
            Assert.That(f.Pickup.TryGetReservation(f.Owner.ActorId,out _),Is.True);Assert.That(f.Pickup.TryGetServiceLease(f.Owner.ActorId,out _),Is.True);
        }

        [Test]
        public void CompletedBodyCheckpointCannotWakeUnacquiredParkingWaitingOnItsOriginalCanonicalCurrentSegmentGap()
        {
            var key=Key("protected-admission-gap","counter-admission",53);var actor=new object();var work=P(-3,-1);var target=P(3,-1);
            var f=new CanonicalSuccessorPreparationFixture(extraBody:new TrafficBodyFact(Key(key.ActorId,"body",2),work,.4f,actorLife:actor));
            var request=new TrafficRequest(key,10,f.World,work,target,.4f,"counter/"+key.ActorId,finiteSeconds:30,planPrimaryRoute:true);
            Assert.That(ParkingEndpointHint(f.Core,request),Is.True);f.Core.EvaluateParking(request);f.Core.ProcessReady(10);
            var waiting=f.Core.GetDecision(key);Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),waiting.Reason);
            Assert.That(waiting.Blockers,Is.Not.Empty);Assert.That(waiting.Blockers.All(b=>b.Owner.Equals(f.Owner)&&
                b.ResourceId==f.PickupResource&&b.Proof=="current-conflict-segment"),Is.True,
                "PREMISE: this existing bounded parking gap owns no selected-journey-parking-protection edge");
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));var before=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));
            Assert.That(before.IndependentlyProgressing,Is.True);Assert.That(f.Begin(),Is.Not.Null);
            var after=f.World.Bodies.Single(b=>b.Owner.Equals(f.Owner));Assert.That(after.ActorLife,Is.SameAs(before.ActorLife));
            Assert.That(after.Owner,Is.EqualTo(before.Owner));Assert.That(after.IndependentlyProgressing,Is.False);
            var entries=(System.Collections.IDictionary)D3ReadField(f.Core,"entries");var entry=entries[key];
            Assert.That(D3InvokeBool(f.Core,"HoldsHandoffDependency",entry,f.Owner,f.PickupResource),Is.True);
            f.Core.Tick(.25f,false);var accounting=D3CaptureAccounting(f.Core,key);var queries=f.Core.QueriesThisFrame;
            // The real completion body event cannot reinterpret an existing canonical current-leg parking gap as the new selected-route case.
            // 同一真实完成事件不能把原 bounded canonical gap 借名改成此次新增的 selected-route 停车唤醒。
            f.Core.NotifyChanged(f.Owner,"body");Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));
            Assert.That(f.Core.GetDecision(key),Is.SameAs(waiting));Assert.That(f.Core.DrainReady(),Is.Empty);D3AssertAccounting(f.Core,key,accounting);
            var moved=new TrafficRequest(key,10,f.World,work,f.End,.4f,"counter/"+key.ActorId,finiteSeconds:30,planPrimaryRoute:true);
            Assert.That(CfcReprepare(f.Core,waiting,moved,out var next),Is.True);Assert.That(next,Is.SameAs(waiting));
            Assert.That(D1Read(f.Core,key,"Queued"),Is.EqualTo(false));Assert.That(f.Core.QueriesThisFrame,Is.EqualTo(queries));D3AssertAccounting(f.Core,key,accounting);
            Assert.That(f.Core.TryCommit(next),Is.False);Assert.That(f.OriginalLease.IsCurrentCollectionLease,Is.True);
            f.Core.Tick(100,false);Assert.That(f.Core.GetDecision(key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(f.Core.TryCommit(f.Core.GetDecision(key)),Is.False,"The original finite gap is never an infinite wait or automatic terminal recovery");
        }

