            internal void ReplaceClaim(bool aba)
            {
                Pickup.ReleaseServicePosition(Owner.ActorId);
                if(aba)
                {
                    Assert.That(Pickup.Remove(Owner.ActorId),Is.True);Assert.That(Pickup.TryReserve(Owner.ActorId,out _),Is.True);
                    Assert.That(Pickup.TryBeginTransfer(Owner.ActorId,out var a),Is.True);Assert.That(Pickup.MarkArrived(Owner.ActorId,a.Generation),Is.True);
                }
                Assert.That(Pickup.TryAcquireCollection(Owner.ActorId,aba?End:P(6)),Is.True);
                Assert.That(Pickup.TryCaptureReservation(Owner.ActorId,out var current),Is.True);
                Assert.That(OriginalLease.IsSameReservation(current),Is.EqualTo(!aba));Assert.That(OriginalLease.IsCurrentCollectionLease,Is.False);Refresh();
            }
            internal TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)
            {
                current=null;if(captured==null || !known.Contains(captured) || !ReferenceEquals(captured.CanonicalOwner,Pickup) ||
                    !ReferenceEquals(captured.BusinessOwner,Business) || !ReferenceEquals(captured.ReleaseObligation,Obligation))return TrafficPhaseClaimState.Invalid;
                if(captured.ResourceId==ServiceResource)
                {
                    if(!Pickup.TryGetServiceLease(Owner.ActorId,out var point))return Gone?TrafficPhaseClaimState.Released:TrafficPhaseClaimState.Invalid;
                    if(!OriginalLease.IsCurrentCollectionLease)return TrafficPhaseClaimState.Invalid;
                    current=Fact(captured.Owner,ServiceResource,point);return TrafficPhaseClaimState.Held;
                }
                if(captured.ResourceId!=PickupResource)return TrafficPhaseClaimState.Invalid;
                if(!Pickup.TryCaptureReservation(Owner.ActorId,out var claim))return Gone?TrafficPhaseClaimState.Released:TrafficPhaseClaimState.Invalid;
                if(!OriginalLease.IsSameReservation(claim) || !claim.IsCurrent)return TrafficPhaseClaimState.Invalid;
                current=Fact(captured.Owner,PickupResource,claim.Assignment.Position,claim);return TrafficPhaseClaimState.Held;
            }
        }
        private sealed class PaidWaitArrivalModelMilestone:ITrafficPhaseMilestone
        {
            private readonly CanonicalSuccessorPreparationFixture f;
            internal PaidWaitArrivalModelMilestone(CanonicalSuccessorPreparationFixture value){f=value;}
            public TrafficDecision SourcePermit=>f.ServiceSource;
            public TrafficParkingFact OriginalClaim=>f.OriginalClaims.Single();
            public TrafficParkingFact CurrentClaim=>ReadClaim(OriginalClaim,out var current)==TrafficPhaseClaimState.Held?current:null;
            public object ActorLife=>f.Actor;public object BusinessOwner=>f.Business;public object ReleaseObligation=>f.Obligation;
            public TrafficPhaseMilestoneKind Kind=>TrafficPhaseMilestoneKind.Arrived;
            public bool IsCurrent=>f.Arrived&&!f.Gone;
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)=>f.ReadClaim(captured,out current);
            public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision source,int firstFrame)=>false;
        }
        private sealed class CanonicalPreparationMilestone:ITrafficPhaseMilestone
        {
            private readonly CanonicalSuccessorPreparationFixture f;private readonly TrafficRequest candidate;private readonly TrafficDecision initial;
            private readonly int collection;internal TrafficDecision SelectedSource;
            internal CanonicalPreparationMilestone(CanonicalSuccessorPreparationFixture f,TrafficRequest candidate=null,TrafficDecision initial=null)
            {this.f=f;this.candidate=candidate;this.initial=initial;collection=f.CollectionSequence;}
            public TrafficDecision SourcePermit=>f.ServiceSource;
            public TrafficParkingFact OriginalClaim=>f.OriginalClaims.Single(p=>p.ResourceId==f.ServiceResource);
            public TrafficParkingFact CurrentClaim=>ReadClaim(OriginalClaim,out var current)==TrafficPhaseClaimState.Held?current:null;
            public object ActorLife=>f.Actor;public object BusinessOwner=>f.Business;public object ReleaseObligation=>f.Obligation;
            public TrafficPhaseMilestoneKind Kind=>f.Collected?TrafficPhaseMilestoneKind.Collected:TrafficPhaseMilestoneKind.Arrived;
            public bool IsCurrent=>f.Arrived && !f.Gone && (candidate==null || f.Collected && f.CollectionSequence==collection);
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)=>f.ReadClaim(captured,out current);
            public bool AuthorizesSuccessor(TrafficIntentKey key,TrafficDecision source,int firstFrame)=>IsCurrent && f.Collected && collection==1 &&
                candidate!=null && key.Equals(f.Exit) && candidate.Intent.Equals(key) && candidate.RequestedFrame==20 && firstFrame==20 &&
                candidate.Start==f.ActualPosition && candidate.Target==f.Goal && candidate.ResourceId==f.PickupResource &&
                (ReferenceEquals(source,initial) || SelectedSource!=null && ReferenceEquals(source,SelectedSource));
        }

