            core.EvaluateParking(UnbornParkingPrimaryRequest(consumer,first,1));core.ProcessReady(1);
            var consumerSource=core.GetDecision(consumer);Assert.That(consumerSource.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(core.TryCommit(consumerSource,canonicalAttempt?canonical.Prepare():null),Is.True);
            Assert.That(consumerSource.AcquiredSequence,Is.GreaterThan(0));Assert.That(D1Read(core,consumer,"EverCanonicalAttempt"),Is.EqualTo(canonicalAttempt));
            // Authoritative world facts move an unowned actor before its traffic journey is born; no Native receipt is fabricated.
            var current=World(1,2,new[]{new TrafficBodyFact(moving,Origin,.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:actor),
                new TrafficBodyFact(consumer,start,.4f,actorLife:consumerActor)});core.SetSnapshot(current);
            var movingSource=Grant(core,Request(moving,Origin,P(4),current,frame:2,resource:"guard-move",seconds:8));
            Assert.That(core.PrepareLeg(consumerSource,"unborn-pickup",0,consumerActor,5,current,start,.05f,3).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));core.ProcessReady(3);
            Assert.That(core.GetDecision(consumer).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: owned strict consumer genuinely waits on this moving source");
            var originalLeg=D1Read(core,consumer,"Leg");Assert.That(originalLeg,Is.Not.Null);
            var blocker=Key("guard-next-leg-blocker");current=World(1,3,new[]{new TrafficBodyFact(moving,Origin,.4f,actorLife:actor),
                new TrafficBodyFact(consumer,start,.4f,actorLife:consumerActor),new TrafficBodyFact(blocker,P(3),.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:new object())});
            core.SetSnapshot(current);Assert.That(core.PrepareLeg(movingSource,"guard-move",0,actor,7,current,Origin,.05f,4).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));core.ProcessReady(4);
            Assert.That(core.GetDecision(moving).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            var failed=core.GetDecision(consumer);Assert.That(failed.Reason,Is.EqualTo("owner-no-longer-independent"));
            Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(core.TryCommit(failed),Is.False);
            Assert.That(D1Read(core,consumer,"Leg"),Is.SameAs(originalLeg));Assert.That(D1Read(core,consumer,"EverCanonicalAttempt"),Is.EqualTo(canonicalAttempt));
            Assert.That(canonical.Applies,Is.EqualTo(canonicalAttempt?1:0));Assert.That(canonical.Rollbacks,Is.Zero);
        }

