        // Unborn describes this parking permission only. Its customer already owns an actual Counter entry/body.
        // Public Counter operations establish Arrived; this pure-Core model claims no Unity Native movement receipt.
        private static ServiceTrafficCoordinator UnbornParkingExistingActorModel(out TrafficIntentKey moving,out TrafficIntentKey parking,
            out object ownerActor,out object requestActor,out TrafficDecision journey,out TrafficWorldSnapshot first)
        {
            moving=Key("existing-body-owner","actual-exit",61);parking=Key("existing-body-request","pickup-wait",62);
            ownerActor=new object();requestActor=new object();var start=P(0,-3);
            var counter=new CounterQueueService(new[]{start});Assert.That(counter.TryJoin(parking.ActorId),Is.True);
            Assert.That(counter.Complete(parking.ActorId,counter.Snapshot.Single().Generation),Is.True);
            Assert.That(counter.TryCaptureAssignment(parking.ActorId,out var claim),Is.True);Assert.That(claim.Assignment.Arrived,Is.True);
            var priorBodyOwner=Key(parking.ActorId,"counter-arrived",60);
            var fact=new TrafficParkingFact(priorBodyOwner,counter,counter.Version,"counter/"+parking.ActorId,start,.4f,
                businessOwner:new object(),releaseObligation:new object(),semanticCheckpoint:claim);
            first=World(actors:new[]{new TrafficBodyFact(moving,Origin,.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:ownerActor),
                new TrafficBodyFact(priorBodyOwner,start,.4f,actorLife:requestActor)},parking:new[]{fact});
            var core=Coordinator(first,frameBudget:256,intentBudget:256);
            journey=Grant(core,Request(moving,Origin,P(4),first,resource:"existing-body-move",seconds:8));
            core.EvaluateParking(UnbornParkingPrimaryRequest(parking,first));core.ProcessReady(2);
            Assert.That(core.GetDecision(parking).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            var captured=D1Read(core,parking,"PreparationBody") as TrafficBodyFact;
            Assert.That(captured,Is.Not.Null);Assert.That(captured.ActorLife,Is.SameAs(requestActor));Assert.That(captured.Position,Is.EqualTo(start));
            Assert.That(captured.Owner.Equals(parking),Is.False,"Original Counter body label remains; a new unacquired parking key does not relabel the actor");
            Assert.That(((TrafficParkingFact[])D1Read(core,parking,"PreparationClaims")).Single(),Is.SameAs(fact));
            Assert.That(D1Read(core,parking,"AcquiredSequence"),Is.EqualTo(0));Assert.That(D1Read(core,parking,"EverCanonicalAttempt"),Is.EqualTo(false));
            core.Tick(.5f,false);return core;
        }

        [Test] public void UnbornParkingExistingCounterActorPreservesOriginalBodyAndClaimDuringSafeReproof()
        {
            var core=UnbornParkingExistingActorModel(out var moving,out var parking,out var ownerActor,out var requestActor,out var journey,out var first);
            var body=D1Read(core,parking,"PreparationBody");var claims=D1Read(core,parking,"PreparationClaims");
            var accounting=D3CaptureAccounting(core,parking);var blocker=Key("existing-body-finite-blocker");
            var self=first.Bodies.Single(value=>value.Owner.ActorId==parking.ActorId);
            var current=World(first.Version,first.BodyVersion+1,new[]{new TrafficBodyFact(moving,Origin,.4f,actorLife:ownerActor),self,
                new TrafficBodyFact(blocker,P(3),.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:new object())},first.Parking.ToArray());
            // Same ActorId is essential: the real existing self body/Counter claim remain and are never obstacles against their owner.
            var geometry=Coordinator(current,frameBudget:256,intentBudget:256);
            geometry.EvaluateParking(UnbornParkingPrimaryRequest(parking,current,1));geometry.ProcessReady(1);
            var proof=geometry.GetDecision(parking);Assert.That(proof.Kind,Is.EqualTo(TrafficDecisionKind.Granted),"FIXTURE: existing-body current world has a complete safe detour");
            Assert.That(CustomerRoutePlanner.IsClear(proof.ProofRoutes.Single().ExpandedPath,new[]{Origin,P(3)},.8f),Is.True);
            Assert.That(core.TryCommit(proof),Is.False,"Independent geometry control never supplies authority to the original coordinator");
            core.SetSnapshot(current);Assert.That(core.PrepareLeg(journey,"existing-body-move",0,ownerActor,7,current,Origin,.05f,3).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));core.ProcessReady(3);
            Assert.That(core.GetDecision(moving).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(core.GetDecision(parking).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None),
                "FEATURE RED: existing unchanged customer body does not disqualify this still-unacquired parking preparation");
            Assert.That(D1Read(core,parking,"Queued"),Is.EqualTo(true));Assert.That(D1Read(core,parking,"PreparationBody"),Is.SameAs(body));
            Assert.That(D1Read(core,parking,"PreparationClaims"),Is.SameAs(claims));D3AssertAccounting(core,parking,accounting);
            core.ProcessReady(4);var prepared=core.GetDecision(parking);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(CustomerRoutePlanner.IsClear(prepared.ProofRoutes.Single().ExpandedPath,new[]{Origin,P(3)},.8f),Is.True);
            Assert.That(((TrafficBodyFact)D1Read(core,parking,"PreparationBody")).ActorLife,Is.SameAs(requestActor));
            Assert.That(core.TryCommit(prepared),Is.True);var canonical=(CounterQueueService)first.Parking.Single().CanonicalOwner;
            Assert.That(canonical.Snapshot.Single().VisitId,Is.EqualTo(parking.ActorId));Assert.That(canonical.Snapshot.Single().Arrived,Is.True);
        }

        [TestCase("pose")]
        [TestCase("actor-life")]
        public void UnbornParkingExistingActorCannotAdoptChangedBodyOrActorLife(string drift)
        {
            var core=UnbornParkingExistingActorModel(out var moving,out var parking,out var ownerActor,out var requestActor,out var journey,out var first);
            var before=D1Read(core,parking,"PreparationBody");var queries=core.QueriesConsumed(parking);
            var self=first.Bodies.Single(value=>value.Owner.ActorId==parking.ActorId);var blocker=Key("existing-drift-finite-blocker");
            var altered=new TrafficBodyFact(self.Owner,drift=="pose"?self.Position+P(.1f):self.Position,.4f,
                actorLife:drift=="actor-life"?new object():requestActor);
            var current=World(first.Version,first.BodyVersion+1,new[]{new TrafficBodyFact(moving,Origin,.4f,actorLife:ownerActor),altered,
                new TrafficBodyFact(blocker,P(3),.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:new object())},first.Parking.ToArray());
            core.SetSnapshot(current);Assert.That(core.PrepareLeg(journey,"existing-body-move",0,ownerActor,7,current,Origin,.05f,3).Kind,
                Is.EqualTo(TrafficDecisionKind.DeferredByBudget));core.ProcessReady(3);
            Assert.That(core.GetDecision(moving).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"FIXTURE: only requester's own identity drifted; former owner really reached temporary Waiting");
            var denied=core.GetDecision(parking);Assert.That(denied.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(core.TryCommit(denied),Is.False);Assert.That(D1Read(core,parking,"PreparationBody"),Is.SameAs(before));
            Assert.That(core.QueriesConsumed(parking),Is.EqualTo(queries));
            var restored=World(first.Version,first.BodyVersion+2,new[]{new TrafficBodyFact(moving,Origin,.4f,actorLife:ownerActor),self,
                current.Bodies.Single(value=>value.Owner.Equals(blocker))},first.Parking.ToArray());core.SetSnapshot(restored);
            core.NotifyChanged(moving,"body");core.ProcessReady(4);Assert.That(core.GetDecision(parking),Is.SameAs(denied),"Restoring old facts cannot automatically retry Terminal");
        }

        // Contract witness only: each typed service marker wraps the real public canonical lease evidence.
        // This does not claim CFC currently publishes such markers; its service facts are still null in the Native receipt.
        private sealed class ActualServiceLeaseModelCheckpoint:ITrafficClaimCheckpoint
        {
            internal readonly PickupQueueService Owner;internal readonly string Actor;internal readonly Vector3 Position;
            internal readonly PickupQueueService.ReservationClaim Collection;internal readonly PickupQueueService.DeliveryLeaseClaim Delivery;
            private ActualServiceLeaseModelCheckpoint(PickupQueueService owner,string actor,Vector3 position,
                PickupQueueService.ReservationClaim collection,PickupQueueService.DeliveryLeaseClaim delivery)
            {Owner=owner;Actor=actor;Position=position;Collection=collection;Delivery=delivery;CapturedOwnerVersion=owner.Version;}
            internal static ActualServiceLeaseModelCheckpoint Capture(PickupQueueService owner,string actor)
            {
                if(!owner.TryGetServiceLease(actor,out var position))return null;
                if(owner.TryCaptureReservation(actor,out var collection) && collection.IsCurrentCollectionLease && collection.Assignment.Position==position)
                    return new ActualServiceLeaseModelCheckpoint(owner,actor,position,collection,null);
                if(owner.TryCaptureDeliveryLease(actor,out var delivery) && delivery.IsCurrent && delivery.Position==position)
                    return new ActualServiceLeaseModelCheckpoint(owner,actor,position,null,delivery);
                return null;
            }
            public object CanonicalOwner=>Owner;public string ResourceId=>"service/"+Actor;public long CapturedOwnerVersion{get;}
            public bool IsSameCurrentClaim(ITrafficClaimCheckpoint current)
            {
                if(!(current is ActualServiceLeaseModelCheckpoint other) || !ReferenceEquals(Owner,other.Owner) || Actor!=other.Actor || Position!=other.Position ||
                    CapturedOwnerVersion>other.CapturedOwnerVersion || other.CapturedOwnerVersion!=Owner.Version)return false;
                if(Collection!=null)return other.Collection!=null && Collection.IsCurrentCollectionLease && other.Collection.IsCurrentCollectionLease &&
                    Collection.IsSameCurrentClaim(other.Collection);
                return Delivery!=null && other.Delivery!=null && Delivery.IsCurrent && other.Delivery.IsCurrent && Delivery.IsSameLease(other.Delivery);
            }
        }
        private sealed class StrictServiceBookkeepingModel
        {
            internal readonly LegFixture Flow=new LegFixture();internal readonly PickupQueueService Queue;
            internal readonly string Mode,Marker;internal readonly object Business=new object(),Release=new object(),Opaque=new object(),BlockerLife=new object();
            internal readonly TrafficIntentKey Blocker=Key("service-bookkeeping-finite-blocker");
            internal readonly TrafficDecision Waiting;internal readonly TrafficParkingFact[] OriginalClaims;
            internal readonly ActualServiceLeaseModelCheckpoint OriginalService;
            internal StrictServiceBookkeepingModel(string mode,string marker="typed")
            {
                Mode=mode;Marker=marker;Queue=new PickupQueueService(new[]{P(8,8),P(9,8)},new[]{Origin,P(6)});
                Acquire();OriginalService=ActualServiceLeaseModelCheckpoint.Capture(Queue,Flow.Key.ActorId);Assert.That(OriginalService,Is.Not.Null);
                OriginalClaims=Facts();Flow.World=World(2,2,Bodies(Flow.End),OriginalClaims);Flow.Coordinator.SetSnapshot(Flow.World);
                Assert.That(Flow.Prepare(generation:9).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Flow.Coordinator.ProcessReady(Flow.Frame++);
                Waiting=Flow.Coordinator.GetDecision(Flow.Key);Assert.That(Waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
                Assert.That(D3ReadField(Flow.Read("Leg"),"Committed"),Is.EqualTo(false));Assert.That(D3ReadField(Flow.Read("Leg"),"Stamp"),Is.EqualTo(default(TrafficNativeStamp)));
                Flow.Coordinator.Tick(.25f,false);
            }
            internal void Acquire()
            {
                if(Mode=="delivery"){Assert.That(Queue.TryAcquireDelivery(Flow.Key.ActorId,Origin),Is.True);return;}
                Assert.That(Queue.TryReserve(Flow.Key.ActorId,out _),Is.True);Assert.That(Queue.TryBeginTransfer(Flow.Key.ActorId,out var wait),Is.True);
                Assert.That(Queue.MarkArrived(Flow.Key.ActorId,wait.Generation),Is.True);Assert.That(Queue.TryAcquireCollection(Flow.Key.ActorId,Origin),Is.True);
                Assert.That(Queue.TryCaptureReservation(Flow.Key.ActorId,out var service),Is.True);Assert.That(Queue.MarkArrived(Flow.Key.ActorId,service.Assignment.Generation),Is.True);
            }
            private TrafficBodyFact[] Bodies(Vector3 other)=>new[]{new TrafficBodyFact(Flow.Key,Origin,.4f,actorLife:Flow.Actor),
                new TrafficBodyFact(Blocker,other,.4f,independentlyProgressing:true,remainingSeconds:8,actorLife:BlockerLife)};
            internal TrafficParkingFact[] Facts()
            {
                var facts=new List<TrafficParkingFact>();
                if(Queue.TryCaptureReservation(Flow.Key.ActorId,out var pickup))facts.Add(new TrafficParkingFact(Flow.Key,Queue,Queue.Version,
                    "pickup/"+Flow.Key.ActorId,pickup.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Release,semanticCheckpoint:pickup));
                if(Queue.TryGetServiceLease(Flow.Key.ActorId,out var position))facts.Add(new TrafficParkingFact(Flow.Key,Queue,Queue.Version,
                    "service/"+Flow.Key.ActorId,position,.4f,businessOwner:Business,releaseObligation:Release,
                    semanticCheckpoint:Marker=="typed"?(object)ActualServiceLeaseModelCheckpoint.Capture(Queue,Flow.Key.ActorId):Marker=="opaque"?Opaque:null));
                if(Queue.TryCaptureReservation("service-meta-other",out var other))facts.Add(new TrafficParkingFact(Key("service-meta-other"),Queue,Queue.Version,
                    "pickup/service-meta-other",other.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Release,semanticCheckpoint:other));
                return facts.ToArray();
            }
            internal void Publish(bool releaseBlocker=false)
            {Flow.World=World(Flow.World.Version+1,Flow.World.BodyVersion+1,Bodies(releaseBlocker?P(-20,-20):Flow.End),Facts());Flow.Coordinator.SetSnapshot(Flow.World);}
        }

        [TestCase("collection")]
        [TestCase("delivery")]
        public void StrictWaitingLegRetainsAuthenticServiceLeaseAcrossOnlyOtherReservationBookkeeping(string role)
        {
            var f=new StrictServiceBookkeepingModel(role);var flow=f.Flow;var leg=flow.Read("Leg");var request=flow.Read("Request");
            var accounting=D3CaptureAccounting(flow.Coordinator,flow.Key);var version=f.Queue.Version;
            Assert.That(f.Queue.TryReserve("service-meta-other",out _),Is.True);Assert.That(f.Queue.Version,Is.EqualTo(version+1));
            var fresh=ActualServiceLeaseModelCheckpoint.Capture(f.Queue,flow.Key.ActorId);Assert.That(fresh,Is.Not.Null);
            Assert.That(f.OriginalService.IsSameCurrentClaim(fresh),Is.True,"PRECONDITION: actual same collection Entry/generation or delivery lifetime remains authenticated");
            if(role=="collection")Assert.That(f.OriginalService.Collection.IsSameReservation(fresh.Collection),Is.True);
            else Assert.That(f.OriginalService.Delivery.IsSameLease(fresh.Delivery),Is.True);
            f.Publish();var own=f.OriginalClaims.Where(claim=>claim.Owner.Equals(flow.Key)).ToArray();
            foreach(var old in own)
            {
                var current=flow.World.Parking.Single(claim=>claim.Owner.Equals(flow.Key)&&claim.ResourceId==old.ResourceId);
                Assert.That(old.OwnerVersion,Is.Not.EqualTo(current.OwnerVersion));Assert.That(old.Position,Is.EqualTo(current.Position));
                Assert.That(TrafficClaimCheckpoints.AreSame(old,current),Is.True,"PRECONDITION: real typed authority, not matching coordinates, authenticates unchanged own claim");
            }
            var result=flow.Prepare(generation:9);
            Assert.That(result,Is.SameAs(f.Waiting),"FEATURE RED: only unrelated canonical bookkeeping must not cancel the same authenticated unissued waiting leg");
            Assert.That(flow.Read("Leg"),Is.SameAs(leg));Assert.That(flow.Read("Request"),Is.SameAs(request));D3AssertAccounting(flow.Coordinator,flow.Key,accounting);
            Assert.That(flow.Coordinator.TryCommit(result),Is.False);Assert.That(flow.Coordinator.CanIssueLeg(flow.Key,flow.Actor,9),Is.False);
            f.Publish(true);flow.Coordinator.NotifyChanged(f.Blocker,"body");flow.Coordinator.ProcessReady(flow.Frame++);
            var prepared=flow.Coordinator.GetDecision(flow.Key);Assert.That(prepared.Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(flow.Read("Leg"),Is.SameAs(leg));Assert.That(flow.Coordinator.TryCommit(prepared),Is.True);
        }

        [TestCase("null")]
        [TestCase("opaque")]
        public void StrictWaitingLegNeverIgnoresUnprovedServiceOwnerVersionDrift(string marker)
        {
            var f=new StrictServiceBookkeepingModel("collection",marker);var queries=f.Flow.Coordinator.QueriesConsumed(f.Flow.Key);
            Assert.That(f.Queue.TryReserve("service-meta-other",out _),Is.True);f.Publish();var result=f.Flow.Prepare(generation:9);
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(f.Flow.Coordinator.TryCommit(result),Is.False);
            Assert.That(f.Flow.Coordinator.QueriesConsumed(f.Flow.Key),Is.EqualTo(queries));
        }

        [TestCase("collection","reacquire")]
        [TestCase("collection","entry-ABA")]
        [TestCase("delivery","reacquire")]
        [TestCase("delivery","release")]
        public void StrictWaitingLegRejectsReleasedOrSameGeometryReplacementServiceLease(string role,string change)
        {
            var f=new StrictServiceBookkeepingModel(role);var queries=f.Flow.Coordinator.QueriesConsumed(f.Flow.Key);
            f.Queue.ReleaseServicePosition(f.Flow.Key.ActorId);
            if(change=="entry-ABA"){Assert.That(f.Queue.Remove(f.Flow.Key.ActorId),Is.True);f.Acquire();}
            else if(change=="reacquire")
            {
                if(role=="delivery")Assert.That(f.Queue.TryAcquireDelivery(f.Flow.Key.ActorId,Origin),Is.True);
                else {Assert.That(f.Queue.TryAcquireCollection(f.Flow.Key.ActorId,Origin),Is.True);Assert.That(f.Queue.TryCaptureReservation(f.Flow.Key.ActorId,out var renewed),Is.True);
                    Assert.That(f.Queue.MarkArrived(f.Flow.Key.ActorId,renewed.Assignment.Generation),Is.True);}
            }
            var replacement=ActualServiceLeaseModelCheckpoint.Capture(f.Queue,f.Flow.Key.ActorId);
            Assert.That(replacement==null || !f.OriginalService.IsSameCurrentClaim(replacement),Is.True,"PRECONDITION: real release/new lifetime or Entry/generation invalidates old lease despite same ID/pose");
            if(replacement!=null)Assert.That(replacement.Position,Is.EqualTo(f.OriginalService.Position),"Same geometry cannot authenticate a replacement lease");
            if(role=="delivery")Assert.That(f.OriginalService.Delivery.HasRetiredLifetime,Is.True);
            if(change=="entry-ABA")Assert.That(f.OriginalService.Collection.IsSameReservation(replacement.Collection),Is.False);
            f.Publish();var result=f.Flow.Prepare(generation:9);
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(f.Flow.Coordinator.TryCommit(result),Is.False);
            Assert.That(f.Flow.Coordinator.QueriesConsumed(f.Flow.Key),Is.EqualTo(queries));
        }

        [Test]
        public void StrictWaitingTypedLeaseRejectsEvenUnityApproximatelyEqualFactPositionDrift()
        {
            var f=new StrictServiceBookkeepingModel("collection");var flow=f.Flow;var queries=flow.Coordinator.QueriesConsumed(flow.Key);
            Assert.That(f.Queue.TryReserve("service-meta-other",out _),Is.True);f.Publish();
            var actual=flow.World.Parking.Single(claim=>claim.Owner.Equals(flow.Key)&&claim.ResourceId=="service/"+flow.Key.ActorId);
            var shifted=actual.Position+P(.000001f);
            Assert.That(shifted==actual.Position,Is.True,"PRECONDITION: Unity operator equality regards this nonzero shift as approximately equal");
            Assert.That(shifted.Equals(actual.Position),Is.False,"PRECONDITION: the canonical fact geometry is nevertheless not exactly equal");
            var drifted=new TrafficParkingFact(actual.Owner,actual.CanonicalOwner,actual.OwnerVersion,actual.ResourceId,
                shifted,actual.Radius,actual.SafetyMargin,actual.BusinessOwner,actual.ReleaseObligation,actual.SemanticCheckpoint);
            var original=f.OriginalClaims.Single(claim=>claim.ResourceId==actual.ResourceId);
            Assert.That(TrafficClaimCheckpoints.AreSame(original,drifted),Is.True,"PRECONDITION: real lease authentication cannot authorize an inconsistent DTO position");
            flow.World=World(flow.World.Version+1,flow.World.BodyVersion+1,flow.World.Bodies.ToArray(),
                flow.World.Parking.Select(claim=>ReferenceEquals(claim,actual)?drifted:claim).ToArray());
            flow.Coordinator.SetSnapshot(flow.World);var result=flow.Prepare(generation:9);
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.Granted));Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(result.Kind,Is.Not.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(flow.Coordinator.TryCommit(result),Is.False);
            Assert.That(flow.Coordinator.QueriesConsumed(flow.Key),Is.EqualTo(queries));
        }

