            {
                var pending=Coordinator.EvaluateMovement(Request(key,End,target??End+P(2),World,frame:frame,resource:Resource,independent:independent,seconds:8));
                if(pending.Kind==TrafficDecisionKind.StaleContext)return pending;
                Coordinator.ProcessReady(frame);var source=Coordinator.GetDecision(key);
                if(source.Kind!=TrafficDecisionKind.Granted || primaryOnly)return source;
                Assert.That(Coordinator.TryCommit(source),Is.True,"Successor source has its own collection-time age");
                if(authorize && Canonical.Value==2 && key.Equals(ExpectedContinuationKey))SelectContinuationSource(source);
                Assert.That(Coordinator.PrepareLeg(source,Resource,0,Actor,5,World,End,.05f,Frame).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Coordinator.ProcessReady(Frame++);return Coordinator.GetDecision(key);
            }
