        private sealed class HandoffMilestone : ITrafficPhaseMilestone
        {
            private readonly HandoffFixture fixture;internal bool TrustCurrent;
            private readonly TrafficDecision continuationSource;
            internal HandoffMilestone(HandoffFixture value){fixture=value;continuationSource=value.ExpectedContinuationSource;}
            public TrafficDecision SourcePermit { get; set; }
            public TrafficParkingFact OriginalClaim { get; set; }
            public TrafficParkingFact CurrentClaim { get; set; }
            public object ActorLife { get; set; }
            public object BusinessOwner { get; set; }
            public object ReleaseObligation { get; set; }
            public TrafficPhaseMilestoneKind Kind { get; set; }
            public bool IsCurrent=>TrustCurrent || fixture.Enabled && fixture.Canonical.Version==CurrentClaim.OwnerVersion &&
                ReferenceEquals(CurrentClaim.CanonicalOwner,fixture.Canonical) && ReferenceEquals(BusinessOwner,fixture.Business) &&
                ReferenceEquals(ReleaseObligation,fixture.Obligation) && ReferenceEquals(ActorLife,fixture.Actor) &&
                fixture.Canonical.Value>=(Kind==TrafficPhaseMilestoneKind.Collected?2:1);
            public TrafficPhaseClaimState ReadClaim(TrafficParkingFact captured,out TrafficParkingFact current)
            {
                current=null;if(!ReferenceEquals(captured,OriginalClaim) || !IsCurrent)return TrafficPhaseClaimState.Invalid;
                current=CurrentClaim;return TrafficPhaseClaimState.Held;
            }
            public bool AuthorizesSuccessor(TrafficIntentKey successor,TrafficDecision sourcePermit,int firstFrame)=>
                IsCurrent && Kind==TrafficPhaseMilestoneKind.Collected && fixture.Canonical.Value==2 &&
                ReferenceEquals(BusinessOwner,fixture.Business) && ReferenceEquals(ReleaseObligation,fixture.Obligation) &&
                successor.Equals(fixture.ExpectedContinuationKey) && firstFrame==fixture.CollectionFrame &&
                sourcePermit!=null && sourcePermit.Intent.Equals(successor) &&
                ReferenceEquals(continuationSource,fixture.ExpectedContinuationSource) && ReferenceEquals(sourcePermit,continuationSource);
        }

        // A tiny canonical owner implements the real transaction contract, not Queue policy.
        // Task3 separately proves the actual PickupQueueService adapter against these contracts.
        private sealed class CanonicalOwner
        {
            internal long Version;
            internal int Value, Applies, Rollbacks;
            internal bool FailAfterWrite, ThrowAfterWrite;
            internal void ExternalChange() { Version++; }
            internal IPreparedTrafficMutation Prepare() => new Mutation(this, Version);
            private sealed class Mutation : IPreparedTrafficMutation
            {
                private readonly CanonicalOwner owner; private readonly long preparedVersion;
                internal Mutation(CanonicalOwner owner, long version) { this.owner = owner; preparedVersion = version; }
                public bool IsCurrent => owner.Version == preparedVersion;
                public bool TryApply(out ITrafficMutationReceipt receipt)
                {
                    receipt = null; if (!IsCurrent) return false;
                    owner.Value++; owner.Applies++; owner.Version++;
                    receipt = new Receipt(owner, owner.Version);
                    if (owner.ThrowAfterWrite) throw new InvalidOperationException("Canonical apply failed after its own write.");
                    return !owner.FailAfterWrite;
                }
            }
            private sealed class Receipt : ITrafficMutationReceipt
            {
                private readonly CanonicalOwner owner; private readonly long appliedVersion; private bool retired;
                internal Receipt(CanonicalOwner owner, long version) { this.owner = owner; appliedVersion = version; }
                public bool IsCurrent => !retired && owner.Version == appliedVersion;
                public void RollbackOwnMutation()
                {
                    if (retired) return;
                    if (!IsCurrent) throw new InvalidOperationException("Cannot roll back another owner's mutation.");
                    retired = true; owner.Value--; owner.Rollbacks++; owner.Version++;
                }
            }
        }
        private sealed class FailedCollectionPreparationModel
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("failed-collection","pickup-service"),Held=ServiceTrafficCoordinatorTests.Key("failed-collection","body");
            internal readonly object Actor=new object(),Business=new object(),Obligation=new object();
            internal readonly PickupQueueService Queue=new PickupQueueService(new[]{Origin},new[]{P(4)});
            internal readonly ServiceTrafficCoordinator Core;internal readonly TrafficRequest Request;
            internal TrafficWorldSnapshot World;internal readonly TrafficDecision Source;internal readonly PickupQueueService.ReservationClaim Claim;
            internal FailedCollectionPreparationModel(bool block=true)
            {
                Assert.That(Queue.TryReserve(Key.ActorId,out _),Is.True);Assert.That(Queue.TryBeginTransfer(Key.ActorId,out var paid),Is.True);
                Assert.That(Queue.MarkArrived(Key.ActorId,paid.Generation),Is.True);Assert.That(Queue.TryCaptureReservation(Key.ActorId,out var captured),Is.True);Claim=captured;
                World=Snapshot(block:block);Core=Coordinator(World,query:(x,y)=>new[]{x,y});
                Request=new TrafficRequest(Key,17,World,Origin,P(4),.4f,"pickup/"+Key.ActorId,planPrimaryRoute:true,
                    requirements:new[]{new TrafficRouteRequirement("collection-exit-capability",P(4),P(8),.8f,avoidProposedParking:false)});
                Core.EvaluateParking(Request);Core.ProcessReady(17);Source=Core.GetDecision(Key);
                Assert.That(Source.Kind,Is.EqualTo(block?TrafficDecisionKind.PlanningFailed:TrafficDecisionKind.Granted));
                if(block)Assert.That(Source.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            }
            internal TrafficWorldSnapshot Snapshot(bool block=true,object life=null,Vector3? pose=null,bool omit=false,bool opaque=false,TrafficIntentKey? owner=null)
            {
                var held=owner??Held;Queue.TryCaptureReservation(Key.ActorId,out var current);
                var parking=omit?Array.Empty<TrafficParkingFact>():new[]{new TrafficParkingFact(held,Queue,Queue.Version,"pickup/"+Key.ActorId,
                    Origin,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:opaque?(object)new object():current)};
                return ServiceTrafficCoordinatorTests.World(Queue.Version,World==null?1:World.BodyVersion+1,
                    new[]{new TrafficBodyFact(held,pose??Origin,.4f,actorLife:life??Actor)}.Concat(block?new[]{new TrafficBodyFact(ServiceTrafficCoordinatorTests.Key("static-service-body"),P(4),.4f,actorLife:new object())}:Array.Empty<TrafficBodyFact>()).ToArray(),parking);
            }
            internal bool Retire(TrafficDecision expected=null,object life=null)
            {
                var method=typeof(ServiceTrafficCoordinator).GetMethod("TryRetireFailedCanonicalPreparation",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                Assert.That(method,Is.Not.Null,"TEST-FIRST stub exists; missing port is not the FEATURE RED");
                return (bool)method.Invoke(Core,new object[]{expected??Source,life??Actor});
            }
        }
        [TestCase(false)][TestCase(true)]
        public void ExactFailedUncommittedCollectionRetiresWithoutGrantOrErasingSpent(bool currentBodyPhaseChanged)
        {
            var f=new FailedCollectionPreparationModel();var queries=f.Core.QueriesConsumed(f.Key);var frame=D1Read(f.Core,f.Key,"FirstFrame");
            var seq=f.Source.RequestSequence;var wait=D1Read(f.Core,f.Key,"WaitRemaining");
            if(currentBodyPhaseChanged){f.World=f.Snapshot(owner:ServiceTrafficCoordinatorTests.Key(f.Key.ActorId,"new-stationary-body"));f.Core.SetSnapshot(f.World);}
            Assert.That(f.Queue.TryCaptureReservation(f.Key.ActorId,out var current),Is.True);Assert.That(f.Claim.IsSameCurrentClaim(current),Is.True);
            Assert.That(f.Retire(),Is.True,"FEATURE: only the exact failed uncommitted collection may be retired for an explicit producer-bound new attempt");
            Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(f.Source));Assert.That(f.Core.HasActiveGrant(f.Key),Is.False);
            Assert.That(D1Read(f.Core,f.Key,"Retired"),Is.EqualTo(true));Assert.That(D1Read(f.Core,f.Key,"Request"),Is.Null);
            Assert.That(f.Core.QueriesConsumed(f.Key),Is.EqualTo(queries));Assert.That(D1Read(f.Core,f.Key,"FirstFrame"),Is.EqualTo(frame));
            Assert.That(D1Read(f.Core,f.Key,"WaitRemaining"),Is.EqualTo(wait));Assert.That(f.Core.GetDecision(f.Key).RequestSequence,Is.EqualTo(seq));
            Assert.That(f.Queue.TryCaptureReservation(f.Key.ActorId,out var retained),Is.True);Assert.That(f.Claim.IsSameCurrentClaim(retained),Is.True);
            Assert.That(f.Retire(),Is.False);f.Core.ProcessReady(18);Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(f.Source));
        }
        [TestCase("paused")][TestCase("foreign")][TestCase("life")][TestCase("pose")][TestCase("missing")][TestCase("opaque")][TestCase("ABA")]
        public void FailedCollectionRetirementRejectsUnknownOrChangedActualProducerFacts(string change)
        {
            var f=new FailedCollectionPreparationModel();
            if(change=="paused")f.Core.Tick(0,true);
            if(change=="ABA"){f.Queue.Remove(f.Key.ActorId);Assert.That(f.Queue.TryReserve(f.Key.ActorId,out _),Is.True);Assert.That(f.Queue.TryBeginTransfer(f.Key.ActorId,out var paid),Is.True);Assert.That(f.Queue.MarkArrived(f.Key.ActorId,paid.Generation),Is.True);}
            if(change!="paused" && change!="foreign")
            {f.World=f.Snapshot(life:change=="life"?new object():null,pose:change=="pose"?P(.01f):Origin,omit:change=="missing",opaque:change=="opaque");f.Core.SetSnapshot(f.World);}
            var accounting=D3CaptureAccounting(f.Core,f.Key);
            var expected=change=="foreign"?new TrafficDecision(f.Key,f.Source.Kind,f.Source.Reason,failureDisposition:TrafficFailureDisposition.Terminal):f.Source;
            Assert.That(f.Retire(expected),Is.False);D3AssertAccounting(f.Core,f.Key,accounting);
            Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(f.Source));Assert.That(D1Read(f.Core,f.Key,"Retired"),Is.EqualTo(false));
        }
        [TestCase(false)][TestCase(true)]
        public void FailedCollectionRetirementCannotWithdrawPreparedOrCommittedLease(bool commit)
        {
            var f=new FailedCollectionPreparationModel(false);
            if(commit){Assert.That(f.Queue.TryPrepareMutation(PickupQueueService.MutationKind.CollectionLease,f.Key.ActorId,f.Queue.Version,out var preview,P(4)),Is.True);Assert.That(f.Core.TryCommit(f.Source,preview),Is.True);}
            var accounting=D3CaptureAccounting(f.Core,f.Key);var source=f.Core.GetDecision(f.Key);
            Assert.That(f.Retire(source),Is.False);D3AssertAccounting(f.Core,f.Key,accounting);Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(source));
            if(commit)Assert.That(f.Core.HasActiveGrant(f.Key),Is.True);
        }
        // INSERT into ServiceTrafficCoordinatorTests. Analytic Core model with real Counter/Pickup claims.
        // Actual CFC paid seal + dynamic external role disappearance is proved separately by Native XML1D184B5C.
        // Insert inside ServiceTrafficCoordinatorTests. All movement rights use normal Core APIs;
        // reflection below only reads accounting / lifecycle facts.
        private sealed class PaidReleasedExitDeferModel
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("paid-defer-customer","pickup-paid-movement",30),
                BodyKey=ServiceTrafficCoordinatorTests.Key("paid-defer-customer","counter-advance",29),
                Old=ServiceTrafficCoordinatorTests.Key("paid-defer-old","actual-exit",1),
                New=ServiceTrafficCoordinatorTests.Key("paid-defer-new","pickup-advance",2);
            internal readonly object Actor=new object(),OldLife=new object(),NewLife=new object(),Business=new object(),Obligation=new object();
            internal readonly CounterQueueService Counter=new CounterQueueService(new[]{Origin});
            internal readonly PickupQueueService Pickup=new PickupQueueService(new[]{P(4)},new[]{P(8,4)});
            internal readonly TrafficNativeStamp OldStamp=new TrafficNativeStamp(811,1),NewStamp=new TrafficNativeStamp(812,2);
            internal readonly Vector3 OldStart=P(2),OldEnd=P(2,4),NewStart=P(3,-4),NewEnd=P(3,4);
            internal readonly ServiceTrafficCoordinator Core;internal TrafficWorldSnapshot Snapshot;internal int Calls;
            internal TrafficDecision OriginalWait,Deferred;internal readonly TrafficRequest Initial;
            internal PaidReleasedExitDeferModel()
            {
                Assert.That(Counter.TryJoin(Key.ActorId),Is.True);Assert.That(Counter.Complete(Key.ActorId,1),Is.True);
                Assert.That(Pickup.TryReserve(Key.ActorId,out _),Is.True);
                Snapshot=MakeWorld(1,true,OldStart,NewStart);Core=Coordinator(Snapshot,waitSeconds:30,query:(a,b)=>{Calls++;return new[]{a,b};});
                Bind(Old,OldLife,OldStart,OldEnd,OldStamp,1);
                Initial=Proposal(5);Core.EvaluateMovement(Initial);Core.ProcessReady(5);OriginalWait=Core.GetDecision(Key);
                Assert.That(OriginalWait.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),OriginalWait.Reason);
                Assert.That((IEnumerable<TrafficIntentKey>)D1Read(Core,Key,"FrozenOwners"),Is.EquivalentTo(new[]{Old}));
                Assert.That((float)D1Read(Core,Key,"WaitRemaining"),Is.EqualTo(13f));Core.Tick(2,false);
                Bind(New,NewLife,NewStart,NewEnd,NewStamp,6);
                Snapshot=MakeWorld(2,true,OldEnd,P(3));Core.SetSnapshot(Snapshot);
                Assert.That(Core.CompleteLeg(Old,OldLife,OldStamp,OldEnd),Is.True);
                // Physical departure and explicit retirement happen only after genuine old-leg completion.
                Snapshot=MakeWorld(3,false,OldEnd,P(3));Core.SetSnapshot(Snapshot);Core.Retire(Old);
                Assert.That(D1Read(Core,Old,"Retired"),Is.EqualTo(true));
                var expected=Core.GetDecision(Key);Assert.That(D2Refresh(Core,expected,Proposal(8),out _),Is.True,
                    "PREMISE: unchanged real Counter/PQS identity adopts the published old-body departure");
                Core.ProcessReady(8);Deferred=Core.GetDecision(Key);
            }
            private TrafficWorldSnapshot MakeWorld(long version,bool includeOld,Vector3 oldPose,Vector3 newPose)
            {
                Assert.That(Counter.TryCaptureAssignment(Key.ActorId,out var counter),Is.True);
                Assert.That(counter.Assignment.Arrived,Is.True);Assert.That(Pickup.TryCaptureReservation(Key.ActorId,out var pickup),Is.True);
                var bodies=new List<TrafficBodyFact>{new TrafficBodyFact(BodyKey,Origin,.4f,actorLife:Actor),
                    new TrafficBodyFact(New,newPose,.4f,independentlyProgressing:version<4,remainingSeconds:version<4?13:0,actorLife:NewLife)};
                if(includeOld)bodies.Add(new TrafficBodyFact(Old,oldPose,.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:OldLife));
                return ServiceTrafficCoordinatorTests.World(version,version,bodies.ToArray(),new[]{
                    new TrafficParkingFact(BodyKey,Counter,Counter.Version,"counter/"+Key.ActorId,counter.Assignment.Position,.4f,
                        businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:counter),
                    new TrafficParkingFact(BodyKey,Pickup,Pickup.Version,"pickup/"+Key.ActorId,pickup.Assignment.Position,.4f,
                        businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:pickup)});
            }
            private void Bind(TrafficIntentKey key,object life,Vector3 start,Vector3 end,TrafficNativeStamp stamp,int frame)
            {
                var resource="pickup/"+key.ActorId;
                var source=Grant(Core,ServiceTrafficCoordinatorTests.Request(key,start,end,Snapshot,frame:frame,resource:resource,seconds:13));
                Core.PrepareLeg(source,resource,0,life,stamp.LegGeneration,Snapshot,start,.08f,frame+1);Core.ProcessReady(frame+1);
                Assert.That(Core.TryCommit(Core.GetDecision(key)),Is.True);Assert.That(Core.BindLeg(key,life,stamp),Is.True);
            }
            internal TrafficRequest Proposal(int frame)=>new TrafficRequest(Key,frame,Snapshot,Origin,P(4),.4f,"pickup/"+Key.ActorId,
                finiteSeconds:20,planPrimaryRoute:true);
            internal void FinishNew()
            {
                Snapshot=MakeWorld(4,false,OldEnd,NewEnd);Core.SetSnapshot(Snapshot);
                Assert.That(Core.CompleteLeg(New,NewLife,NewStamp,NewEnd),Is.True);
                var expected=Core.GetDecision(Key);Assert.That(D2Refresh(Core,expected,Proposal(13),out _),Is.True,
                    "Same original fixed target and both original typed claims must survive the actual new-owner arrival");
                Core.ProcessReady(13);
            }
        }
        [TestCase(false)][TestCase(true)]
        public void PaidPreparationAfterActualExitReleaseDefersOnlyWithinItsOriginalDebtAndReprovesFixedTarget(bool expire)
        {
            var f=new PaidReleasedExitDeferModel();var core=f.Core;var deferred=f.Deferred;
            Assert.That(deferred.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget),
                "Original Native RED: a newly Bound owner cannot become new Frozen debt; preparation remains unacquired and finite");
            Assert.That(deferred.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));
            Assert.That(deferred.Blockers.Any(b=>b.Owner.Equals(f.New)&&b.ResourceId=="body"&&b.Proof=="live-body-checkpoint"),Is.True);
            Assert.That(deferred.AcquiredSequence,Is.Zero);Assert.That(core.TryCommit(deferred),Is.False);Assert.That(core.HasActiveGrant(f.Key),Is.False);
            Assert.That(D1Read(core,f.Key,"Queued"),Is.EqualTo(true));Assert.That(D1Read(core,f.Key,"Leg"),Is.Null);
            Assert.That((IEnumerable<TrafficIntentKey>)D1Read(core,f.Key,"FrozenOwners"),Is.EquivalentTo(new[]{f.Old}));
            Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(11f));
            var queries=core.QueriesConsumed(f.Key);var calls=f.Calls;var sequence=deferred.RequestSequence;var age=D1Read(core,f.Key,"FirstFrame");
            for(var frame=9;frame<=12;frame++)core.ProcessReady(frame);
            Assert.That(core.QueriesConsumed(f.Key),Is.EqualTo(queries));Assert.That(f.Calls,Is.EqualTo(calls),"Unchanged completed jobs do not query again");
            core.Tick(100,true);Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(11f));core.Tick(0,false);
            if(expire)
            {
                core.Tick(11,false);var terminal=core.GetDecision(f.Key);
                Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(terminal.Reason,Is.EqualTo("wait-budget-exhausted"));
                Assert.That(core.TryCommit(terminal),Is.False);Assert.That(D2Refresh(core,terminal,f.Proposal(13),out _),Is.False);
                Assert.That(core.QueriesConsumed(f.Key),Is.EqualTo(queries));return;
            }
            f.FinishNew();var ready=core.GetDecision(f.Key);
            Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);Assert.That(ready.RequestSequence,Is.EqualTo(sequence));
            Assert.That(D1Read(core,f.Key,"FirstFrame"),Is.EqualTo(age));Assert.That(((TrafficRequest)D1Read(core,f.Key,"Request")).Target,Is.EqualTo(P(4)));
            Assert.That((float)D1Read(core,f.Key,"WaitRemaining"),Is.EqualTo(11f));
            Assert.That((IEnumerable<TrafficIntentKey>)D1Read(core,f.Key,"FrozenOwners"),Is.EquivalentTo(new[]{f.Old}));
            Assert.That(core.QueriesConsumed(f.Key),Is.GreaterThan(queries),"The changed real Native body checkpoint requires full current proof");
            Assert.That(core.TryCommit(ready),Is.True);
        }

        private sealed class QueuedPaidRoleFixture
        {
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("paid-role-owner","pickup-paid-movement",70);
            internal readonly TrafficIntentKey BodyKey=ServiceTrafficCoordinatorTests.Key("paid-role-owner","counter-advance",64);
            internal readonly TrafficIntentKey OtherOne=ServiceTrafficCoordinatorTests.Key("paid-role-one","pickup-paid-movement",1);
            internal readonly TrafficIntentKey OtherTwo=ServiceTrafficCoordinatorTests.Key("paid-role-two","pickup-paid-movement",2);
            internal readonly TrafficIntentKey OtherThree=ServiceTrafficCoordinatorTests.Key("paid-role-three","pickup-paid-movement",3);
            internal readonly TrafficIntentKey Blocker=ServiceTrafficCoordinatorTests.Key("paid-role-blocker");
            internal readonly object Actor=new object(),OneLife=new object(),TwoLife=new object(),ThreeLife=new object(),BlockerLife=new object(),Business=new object(),Obligation=new object();
            internal readonly CounterQueueService Counter=new CounterQueueService(new[]{Origin});
            internal readonly PickupQueueService Pickup=new PickupQueueService(new[]{P(4),P(8,4),P(10,4),P(12,4)},new[]{P(14,4)});
            internal readonly ServiceTrafficCoordinator Core;internal readonly TrafficRequest Initial;
            internal TrafficWorldSnapshot World;internal int Calls;private readonly bool blocker;
            internal QueuedPaidRoleFixture(bool finiteBlocker=false)
            {
                blocker=finiteBlocker;
                Assert.That(Counter.TryJoin(Key.ActorId),Is.True);Assert.That(Counter.Complete(Key.ActorId,1),Is.True);
                Assert.That(Pickup.TryReserve(Key.ActorId,out _),Is.True);Assert.That(Pickup.TryReserve(OtherOne.ActorId,out _),Is.True);Assert.That(Pickup.TryReserve(OtherTwo.ActorId,out _),Is.True);
                World=BuildWorld(1);Core=Coordinator(World,frameBudget:1,query:(a,b)=>{Calls++;return new[]{a,b};});
                Initial=new TrafficRequest(Key,11,World,Origin,P(4),.4f,"pickup/"+Key.ActorId,requirements:Roles(),finiteSeconds:20,planPrimaryRoute:true);
                Core.EvaluateMovement(Initial);Core.ProcessReady(11);
                Assert.That(Core.GetDecision(Key).Kind,Is.EqualTo(blocker?TrafficDecisionKind.WaitingForTraffic:TrafficDecisionKind.DeferredByBudget));
                Assert.That(Core.QueriesConsumed(Key),Is.EqualTo(blocker?0:1));Assert.That(D1Read(Core,Key,"JourneyPermit"),Is.Null);Assert.That(D1Read(Core,Key,"Leg"),Is.Null);
            }
            internal object Entry=>((System.Collections.IDictionary)D3ReadField(Core,"entries"))[Key];
            internal TrafficWorldSnapshot BuildWorld(long version,Vector3? ownPose=null,object ownLife=null)
            {
                Assert.That(Counter.TryCaptureAssignment(Key.ActorId,out var counter),Is.True);Assert.That(Pickup.TryCaptureReservation(Key.ActorId,out var own),Is.True);
                var actors=new List<TrafficBodyFact>{new TrafficBodyFact(BodyKey,ownPose??Origin,.4f,actorLife:ownLife??Actor),
                    new TrafficBodyFact(OtherOne,P(8,4),.4f,actorLife:OneLife),new TrafficBodyFact(OtherTwo,P(10,4),.4f,actorLife:TwoLife)};
                var claims=new List<TrafficParkingFact>{new TrafficParkingFact(BodyKey,Counter,Counter.Version,"counter/"+Key.ActorId,counter.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:counter),
                    new TrafficParkingFact(BodyKey,Pickup,Pickup.Version,"pickup/"+Key.ActorId,own.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:own)};
                foreach(var other in new[]{OtherOne,OtherTwo,OtherThree})if(Pickup.TryCaptureReservation(other.ActorId,out var held))
                {
                    claims.Add(new TrafficParkingFact(other,Pickup,Pickup.Version,"pickup/"+other.ActorId,held.Assignment.Position,.4f,businessOwner:Business,releaseObligation:Obligation,semanticCheckpoint:held));
                    if(other.Equals(OtherThree))actors.Add(new TrafficBodyFact(other,held.Assignment.Position,.4f,actorLife:ThreeLife));
                }
                if(blocker)actors.Add(new TrafficBodyFact(Blocker,P(4),.4f,true,true,8,actorLife:BlockerLife));
                return ServiceTrafficCoordinatorTests.World(version,version,actors.ToArray(),claims.ToArray());
            }
            private TrafficRouteRequirement[] Roles()=>new[]{OtherOne,OtherTwo,OtherThree}.Where(key=>Pickup.TryGetReservation(key.ActorId,out _)).Select(key=>
            {
                Pickup.TryGetReservation(key.ActorId,out var assignment);
                return new TrafficRouteRequirement("existing-goal/"+key.ActorId,assignment.Position,assignment.Position,.8f);
            }).ToArray();
            internal TrafficRequest ChangeRoles(string mode="remove",Vector3? ownPose=null,object ownLife=null)
            {
                if(mode=="add")Assert.That(Pickup.TryReserve(OtherThree.ActorId,out _),Is.True);else Assert.That(Pickup.Remove(OtherTwo.ActorId),Is.True);
                World=BuildWorld(2,ownPose,ownLife);Core.SetSnapshot(World);return D2FreshRequest(Initial,World,requirements:Roles());
            }
        }
        private static bool ResubmitPaidRoles(ServiceTrafficCoordinator core,TrafficDecision expected,TrafficRequest request,Func<bool> current,out TrafficDecision next)
        {
            var port=typeof(ServiceTrafficCoordinator).GetMethod("TryResubmitQueuedPaidPickupPreparation",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(port,Is.Not.Null,"FEATURE: exact-shape-only refresh strands an unchanged original paid producer when another visit changes external role");
            var args=new object[]{expected,request,current,null};var ok=(bool)port.Invoke(core,args);next=(TrafficDecision)args[3];return ok;
        }
        [TestCase("remove")][TestCase("add")]
        public void QueuedPaidRoleShapeChangeKeepsOriginalAccountingAndReprovesEveryCurrentRole(string mode)
        {
            var f=new QueuedPaidRoleFixture();var request=f.ChangeRoles(mode);var expected=f.Core.GetDecision(f.Key);
            var accounting=D3CaptureAccounting(f.Core,f.Key);var entry=f.Entry;var before=f.Calls;
            Assert.That(D2Refresh(f.Core,expected,request,out _),Is.False,"Original exact-shape API remains unchanged");
            Assert.That(ResubmitPaidRoles(f.Core,expected,request,()=>true,out var next),Is.True);
            Assert.That(f.Entry,Is.SameAs(entry));D3AssertAccounting(f.Core,f.Key,accounting);Assert.That(f.Calls,Is.EqualTo(before));
            Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(next.AcquiredSequence,Is.Zero);Assert.That(f.Core.TryCommit(next),Is.False);
            Assert.That(D1Read(f.Core,f.Key,"Jobs"),Is.Empty);Assert.That(D1Read(f.Core,f.Key,"CurrentPath"),Is.Empty);
            var retained=(TrafficRequest)D1Read(f.Core,f.Key,"Request");Assert.That(retained.RequestedFrame,Is.EqualTo(11));Assert.That(retained.Snapshot,Is.SameAs(f.World));
            Assert.That(retained.Intent,Is.EqualTo(f.Key));Assert.That(retained.Requirements.Select(r=>r.ResourceId),Is.EqualTo(request.Requirements.Select(r=>r.ResourceId)));
            for(var frame=12;frame<18 && f.Core.GetDecision(f.Key).Kind!=TrafficDecisionKind.Granted;frame++)f.Core.ProcessReady(frame);
            var ready=f.Core.GetDecision(f.Key);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(ready.ProofRoutes.Select(p=>p.ResourceId),Is.EquivalentTo(new[]{request.ResourceId}.Concat(request.Requirements.Select(p=>p.ResourceId))));
            Assert.That(f.Core.QueriesConsumed(f.Key),Is.EqualTo((int)accounting["Queries"]+1+request.Requirements.Count),"Old queries are spent; original primary AND all current external roles are queried again");
            D3AssertAccounting(f.Core,f.Key,accounting.Where(x=>x.Key!="Queries").ToDictionary(x=>x.Key,x=>x.Value));Assert.That(f.Core.CanIssueLeg(f.Key,f.Actor,1),Is.False);
        }
        [TestCase(false)][TestCase(true)]
        public void QueuedPaidRoleReproofAcceptsOnlyNonselectedOwnedGoalExitCapability(bool selected)
        {
            var f=new QueuedPaidRoleFixture();var changed=f.ChangeRoles();
            var exits=changed.Requirements.Select(role=>new TrafficRouteRequirement(role.ResourceId+"/exit-capability",role.Goal,
                role.Goal+P(0,2),role.Clearance,role.Obstacles,selectedJourney:selected,avoidProposedParking:true));
            var requirements=changed.Requirements.Concat(exits).ToArray();
            var request=D2FreshRequest(changed,f.World,requirements:requirements);var expected=f.Core.GetDecision(f.Key);
            var accounting=D3CaptureAccounting(f.Core,f.Key);var entry=f.Entry;var calls=f.Calls;
            var accepted=ResubmitPaidRoles(f.Core,expected,request,()=>true,out var next);
            Assert.That(accepted,Is.EqualTo(!selected),"The existing-goal prefix accepts a capability obligation, never a selected exclusive future route");
            Assert.That(f.Entry,Is.SameAs(entry));D3AssertAccounting(f.Core,f.Key,accounting);Assert.That(f.Calls,Is.EqualTo(calls));
            if(selected){Assert.That(next,Is.Null);Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(expected));return;}
            Assert.That(next.Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));Assert.That(next.AcquiredSequence,Is.Zero);
            Assert.That(f.Core.TryCommit(next),Is.False);Assert.That(D1Read(f.Core,f.Key,"Jobs"),Is.Empty);
            for(var frame=12;frame<20 && f.Core.GetDecision(f.Key).Kind!=TrafficDecisionKind.Granted;frame++)f.Core.ProcessReady(frame);
            var ready=f.Core.GetDecision(f.Key);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
            Assert.That(ready.ProofRoutes.Select(p=>p.ResourceId),Is.EquivalentTo(new[]{request.ResourceId}.Concat(requirements.Select(r=>r.ResourceId))));
            Assert.That(f.Core.QueriesConsumed(f.Key),Is.EqualTo((int)accounting["Queries"]+1+requirements.Length));
            D3AssertAccounting(f.Core,f.Key,accounting.Where(pair=>pair.Key!="Queries").ToDictionary(pair=>pair.Key,pair=>pair.Value));
            Assert.That(f.Core.CanIssueLeg(f.Key,f.Actor,1),Is.False,"Full capability proof still cannot issue a Native leg without a real commit");
        }
        [Test]
        public void QueuedPaidRoleReproofPreservesTheSpentFiniteWaitAndOriginalFrozenOwners()
        {
            var f=new QueuedPaidRoleFixture(true);f.Core.Tick(2,false);f.Core.NotifyChanged(f.Blocker,"body");var request=f.ChangeRoles();var expected=f.Core.GetDecision(f.Key);
            var accounting=D3CaptureAccounting(f.Core,f.Key);var frozen=D1Read(f.Core,f.Key,"FrozenOwners");Assert.That((float)accounting["WaitRemaining"],Is.EqualTo(6).Within(.001));
            Assert.That(ResubmitPaidRoles(f.Core,expected,request,()=>true,out var next),Is.True);D3AssertAccounting(f.Core,f.Key,accounting);
            Assert.That(D1Read(f.Core,f.Key,"FrozenOwners"),Is.SameAs(frozen));Assert.That(next.AcquiredSequence,Is.Zero);
            f.Core.ProcessReady(12);Assert.That(f.Core.GetDecision(f.Key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That((float)D1Read(f.Core,f.Key,"WaitRemaining"),Is.EqualTo(6).Within(.001));Assert.That(f.Core.QueriesConsumed(f.Key),Is.Zero);
        }
        [TestCase("producer-false")][TestCase("producer-throws")][TestCase("producer-reentry")]
        [TestCase("terminal")][TestCase("acquired")][TestCase("counter-aba")][TestCase("pickup-aba")]
        [TestCase("start")][TestCase("target")][TestCase("resource")][TestCase("finite")][TestCase("selected-role")][TestCase("static-role")][TestCase("paused")][TestCase("body-life")][TestCase("stale-source")]
        public void QueuedPaidRoleReproofCannotBorrowInvalidOrOwnedAuthority(string scenario)
        {
            var f=new QueuedPaidRoleFixture();
            if(scenario=="acquired")
            {f.Core.ProcessReady(12);f.Core.ProcessReady(13);var granted=f.Core.GetDecision(f.Key);Assert.That(granted.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Core.TryCommit(granted),Is.True);}
            if(scenario=="counter-aba"){Assert.That(f.Counter.Remove(f.Key.ActorId),Is.True);Assert.That(f.Counter.TryJoin(f.Key.ActorId),Is.True);Assert.That(f.Counter.Complete(f.Key.ActorId,1),Is.True);}
            if(scenario=="pickup-aba"){foreach(var id in new[]{f.OtherTwo.ActorId,f.OtherOne.ActorId,f.Key.ActorId})Assert.That(f.Pickup.Remove(id),Is.True);foreach(var id in new[]{f.Key.ActorId,f.OtherOne.ActorId,f.OtherTwo.ActorId})Assert.That(f.Pickup.TryReserve(id,out _),Is.True);}
            var request=f.ChangeRoles(ownLife:scenario=="body-life"?new object():null);var expected=f.Core.GetDecision(f.Key);
            if(scenario=="start")request=new TrafficRequest(f.Key,99,f.World,P(.1f),P(4),.4f,request.ResourceId,requirements:request.Requirements,finiteSeconds:20,planPrimaryRoute:true);
            if(scenario=="target")request=D2FreshRequest(request,f.World,target:P(5));
            if(scenario=="resource")request=D2FreshRequest(request,f.World,resource:"pickup/foreign-owner");
            if(scenario=="finite")request=D2FreshRequest(request,f.World,finite:21);
            if(scenario=="selected-role")request=D2FreshRequest(request,f.World,requirements:new[]{new TrafficRouteRequirement("existing-goal/paid-role-one",P(8,4),P(8,4),.8f,selectedJourney:true)});
            if(scenario=="static-role")request=D2FreshRequest(request,f.World,requirements:new[]{new TrafficRouteRequirement("fixed-exit-proof",P(8,4),P(8,4),.8f)});
            if(scenario=="paused")f.Core.Tick(0,true);
            if(scenario=="terminal"){f.Core.Retire(f.Key);expected=f.Core.GetDecision(f.Key);}
            if(scenario=="stale-source")expected=new TrafficDecision(f.Key,TrafficDecisionKind.DeferredByBudget,"foreign-same-key-decision");
            var accounting=D3CaptureAccounting(f.Core,f.Key);var oldRequest=D1Read(f.Core,f.Key,"Request");var entry=f.Entry;var before=f.Calls;var decision=f.Core.GetDecision(f.Key);
            Func<bool> current=()=>true;
            if(scenario=="producer-false")current=()=>false;
            if(scenario=="producer-throws")current=()=>throw new InvalidOperationException("readonly producer failed");
            if(scenario=="producer-reentry")current=()=>{f.Core.Retire(f.Key);return true;};
            Assert.That(ResubmitPaidRoles(f.Core,expected,request,current,out var rejected),Is.False,scenario);Assert.That(rejected,Is.Null);
            Assert.That(f.Entry,Is.SameAs(entry));Assert.That(f.Calls,Is.EqualTo(before));D3AssertAccounting(f.Core,f.Key,accounting);
            if(scenario=="producer-reentry")Assert.That(f.Core.GetDecision(f.Key).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            else{Assert.That(f.Core.GetDecision(f.Key),Is.SameAs(decision));Assert.That(D1Read(f.Core,f.Key,"Request"),Is.SameAs(oldRequest));}
        }
    }
